insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الصِّيَامُ جُنَّةٌ، فَلَا يَرْفُثْ وَلَا يَجْهَلْ، وَإِنِ امْرُؤٌ قَاتَلَهُ أَوْ شَاتَمَهُ فَلْيَقُلْ: إِنِّي صَائِمٌ، مَرَّتَيْنِ، وَالَّذِي نَفْسِي بِيَدِهِ لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ تَعَالَى مِنْ رِيحِ الْمِسْكِ، يَتْرُكُ طَعَامَهُ وَشَرَابَهُ وَشَهْوَتَهُ مِنْ أَجْلِي، الصِّيَامُ لِي وَأَنَا أَجْزِي بِهِ، وَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നോമ്പ് പരിചയാണ്. നോമ്പുകാരൻ തെറ്റായ പ്രവൃത്തികൾ ചെയ്യുകയോ സംസ്കാരമില്ലാത്ത വാക്കുകൾ പറയുകയോ ചെയ്യരുത്. വല്ലവനും അവനോടു ശണ്ഠ കൂടുകയോ അവനെ ശകാരിക്കുകയോ ചെയ്തെങ്കിൽ ഞാൻ നോമ്പുകാരനാണെന്നു രണ്ടു തവണ അവൻ പറയട്ടെ. എന്റെ ആത്മാവിനെ നിയന്ത്രിക്കുന്ന അല്ലാഹുവാണെ! നോമ്പുകാരന്റെ വായയുടെ വാസന അല്ലാഹുവിന്റെ അടുക്കൽ കസ്തൂരിയേക്കാൾ സുഗന്ധമുള്ളതാണ്. അവൻ ഭക്ഷണ പാനീയങ്ങളും ദേഹേച്ഛയും എനിക്കു വേണ്ടിയാണ് ഉപേക്ഷിക്കുന്നത്. നോമ്പ് എനിക്കുള്ളതാണ്. ഞാൻ തന്നെയാണ് അതിന് പ്രതിഫലം നൽകുന്നത്. ഓരോ സൽകർമ്മത്തിനും പത്തിരട്ടിയാണ് ഞാൻ പ്രതിഫലം നൽകുക." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 49, 49, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ رَضِيَ اللهُ عَنْهُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الصِّيَامُ جُنَّةٌ مِنَ النَّارِ، كَجُنَّةِ أَحَدِكُمْ مِنَ الْقِتَالِ". (ن,جه)', 'ഉസ്മാനുബ്നു അബിൽആസ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "യുദ്ധത്തിൽ നിങ്ങളുടെ പരിച പോലെ നരകത്തിൽ നിന്നുള്ള പരിചയാണ് നോമ്പ്." (ന,ജ)', 'عُثْمَانَ بْنِ أَبِي الْعَاصِ', 'ഉസ്മാനുബ്നു അബിൽആസ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 49, 49, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ فِي الْجَنَّةِ بَابًا يُقَالُ لَهُ الرَّيَّانُ، يُدْعَى يَوْمَ الْقِيَامَةِ، يُقَالُ: أَيْنَ الصَّائِمُونَ؟ فَمَنْ كَانَ مِنَ الصَّائِمِينَ دَخَلَهُ، وَمَنْ دَخَلَهُ لَمْ يَظْمَأْ أَبَدًا". (ت,جه)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം സ്വർഗ്ഗത്തിൽ ''റയ്യാൻ'' എന്നു വിളിക്കപ്പെടുന്ന ഒരു വാതിലുണ്ട്. അന്ത്യനാളിൽ വിളിക്കപ്പെടും: നോമ്പുകാരെവിടെ? അപ്പോൾ നോമ്പുകാർ അതിലൂടെ പ്രവേശിക്കും. അതിൽ പ്രവേശിച്ചവന് ഒരിക്കലും ദാഹമുണ്ടാകുകയില്ല." (തു,ജ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 49, 49, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَنْفَقَ زَوْجَيْنِ فِي سَبِيلِ اللَّهِ نُودِيَ مِنْ أَبْوَابِ الْجَنَّةِ: يَا عَبْدَ اللَّهِ هَذَا خَيْرٌ، فَمَنْ كَانَ مِنْ أَهْلِ الصَّلَاةِ دُعِيَ مِنْ بَابِ الصَّلَاةِ، وَمَنْ كَانَ مِنْ أَهْلِ الْجِهَادِ دُعِيَ مِنْ بَابِ الْجِهَادِ، وَمَنْ كَانَ مِنْ أَهْلِ الصِّيَامِ دُعِيَ مِنْ بَابِ الرَّيَّانِ، وَمَنْ كَانَ مِنْ أَهْلِ الصَّدَقَةِ دُعِيَ مِنْ بَابِ الصَّدَقَةِ". فَقَالَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ: بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ مَا عَلَى مَنْ دُعِيَ مِنْ تِلْكَ الْأَبْوَابِ مِنْ ضَرُورَةٍ، فَهَلْ يُدْعَى أَحَدٌ مِنْ تِلْكَ الْأَبْوَابِ كُلِّهَا؟ قَالَ: "نَعَمْ، وَأَرْجُو أَنْ تَكُونَ مِنْهُمْ". (خ,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "വല്ലവരും ഒരു ജോടി (കുതിരകളെ) അല്ലാഹുവിന്റെ മാർഗത്തിൽ ചെലവഴിച്ചാൽ സ്വർഗ്ഗത്തിന്റെ വാതിലുകളിൽ നിന്ന് വിളിച്ചു പറയപ്പെടും: അല്ലാഹുവിന്റെ ദാസാ, ഈ വാതിലാണ് നിങ്ങൾക്കു നല്ലത്. നിസ്കാരക്കാരെ നിസ്കാരത്തിന്റെ വാതിലിൽ നിന്നും, അല്ലാഹുവിന്റെ മാർഗത്തിൽ യുദ്ധം ചെയ്തവരെ ജിഹാദിന്റെ വാതിലിൽ നിന്നും, നോമ്പുകാരെ ''റയ്യാൻ'' എന്നു പേരുള്ള വാതിലിൽ നിന്നും, ദാനധർമ്മങ്ങൾ നൽകിയവരെ സ്വദഖയുടെ വാതിലിൽ നിന്നും വിളിക്കപ്പെടും". അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: എന്റെ മാതാപിതാക്കൾ അങ്ങേക്ക് ദണ്ഡമാണ് നബിയേ, ഈ വാതിലുകളിൽ നിന്നേതെങ്കിലും ഒന്നിൽ നിന്ന് ആരെങ്കിലും വിളിക്കപ്പെട്ടാൽ അവനു സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കാൻ പ്രയാസമേതുമില്ല. എന്നാൽ മുഴുവൻ വാതിലുകളിൽ നിന്നും ഒരാൾ വിളിക്കപ്പെടുമോ? നബി(സ) പ്രതിവചിച്ചു: "അതേ, നിങ്ങൾ അവരിലൊരാൾ ആകണമെന്നാണ് എന്റെ ആഗ്രഹം". (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 49, 50, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَالَ اللَّهُ: كُلُّ عَمَلِ ابْنِ آدَمَ لَهُ، إِلَّا الصِّيَامَ فَإِنَّهُ لِي وَأَنَا أَجْزِي بِهِ، وَالصِّيَامُ جُنَّةٌ، فَإِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلَا يَرْفُثْ يَوْمَئِذٍ وَلَا يَسْخَبْ، فَإِنْ سَابَّهُ أَحَدٌ أَوْ قَاتَلَهُ فَلْيَقُلْ: إِنِّي امْرُؤٌ صَائِمٌ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ، لِلصَّائِمِ فَرْحَتَانِ يَفْرَحُهُمَا: إِذَا أَفْطَرَ فَرِحَ بِفِطْرِهِ، وَإِذَا لَقِيَ رَبَّهُ فَرِحَ بِصَوْمِهِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) അരുൾചെയ്തു: "അല്ലാഹു പറഞ്ഞു: ആദം സന്തതികളുടെ നോമ്പൊഴികെയുള്ള മുഴുവൻ ആരാധനകളും അവർക്കുതന്നെയാണ്. നോമ്പെനിക്കുള്ളതാണ്. അതിനു പ്രതിഫലം നൽകുന്നതും ഞാൻ തന്നെ. നോമ്പു പരിചയാണ്. നിങ്ങളിലൊരാൾ നോമ്പെടുത്താൽ അന്നേ ദിവസം അവൻ തെറ്റായ പ്രവർത്തനങ്ങൾ ചെയ്യാതിരിക്കുകയും ബഹളമുണ്ടാക്കാതിരിക്കുകയും ചെയ്യട്ടെ. വല്ലവരും അവനെ ആക്ഷേപിക്കുകയോ അവനോട് ശണ്ഠകൂടുകയോ ചെയ്താൽ ഞാൻ നോമ്പുകാരനാണെന്ന് അവൻ പറയട്ടെ. എന്റെ ആത്മാവ് ആരുടെ നിയന്ത്രണത്തിലാണോ അവൻ തന്നെയാണ്! നിശ്ചയം നോമ്പുകാരന്റെ വായയുടെ ഗന്ധം അന്ത്യനാളിൽ അല്ലാഹുവിന്റെയടുക്കൽ കസ്തൂരിയേക്കാൾ സുഗന്ധമുള്ളതാണ്. നോമ്പുകാരനു രണ്ട് ആനന്ദമുണ്ട്. നോമ്പുതുറക്കുന്ന സമയത്തും മറ്റൊന്ന് അല്ലാഹുവിനെ കണ്ടുമുട്ടുന്ന സമയത്തും. ആ സമയത്ത് അവന്റെ നോമ്പുകൊണ്ടവൻ ആനന്ദിക്കുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 50, 50, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ رَبَّكُمْ يَقُولُ: كُلُّ حَسَنَةٍ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِ مِائَةِ ضِعْفٍ، وَالصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ، الصَّوْمُ جُنَّةٌ مِنَ النَّارِ، وَلَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ، وَإِنْ جَهِلَ عَلَى أَحَدِكُمْ جَاهِلٌ وَهُوَ صَائِمٌ فَلْيَقُلْ: إِنِّي صَائِمٌ". حَسَنٌ غَرِيبٌ (خ,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ രക്ഷിതാവ് പറയുന്നു: ഓരോ നന്മക്കും പത്തിരട്ടി മുതൽ എഴുന്നൂറിരട്ടിവരെയാണു പ്രതിഫലം. നോമ്പ് എനിക്കുള്ളതും, ഞാൻ അതിനു പ്രതിഫലം നൽകുന്നതുമാണ്. വ്രതം നരകാഗ്നിയിൽ നിന്നുള്ള രക്ഷാകവചമാണ്. നിശ്ചയം നോമ്പുകാരന്റെ വായയുടെ ഗന്ധത്തിന് അല്ലാഹുവിന്റെയടുക്കൽ കസ്തൂരിയേക്കാൾ സുഗന്ധമുണ്ട്. നിങ്ങൾ നോമ്പുകാരനായിരിക്കെ വല്ലവരും നിങ്ങളോട് അറിവില്ലായ്മ പ്രവർത്തിച്ചാൽ നിങ്ങൾ ഞാൻ നോമ്പുകാരനാണ് എന്നു പറയുക." (ബു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 50, 50, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: مُرْنِي بِأَمْرٍ آخُذُهُ عَنْكَ. قَالَ: "عَلَيْكَ بِالصَّوْمِ، فَإِنَّهُ لَا مِثْلَ لَهُ". وَفِي رِوَايَةٍ: قُلْتُ: يَا رَسُولَ اللَّهِ، مُرْنِي بِأَمْرٍ يَنْفَعُنِي اللَّهُ بِهِ. قَالَ: "عَلَيْكَ بِالصَّوْمِ، فَإِنَّهُ لَا مِثْلَ لَهُ". وَفِي رِوَايَةٍ: أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الْعَمَلِ أَفْضَلُ؟ قَالَ: "عَلَيْكَ بِالصَّوْمِ، فَإِنَّهُ لَا عِدْلَ لَهُ". وَفِي رِوَايَةٍ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، مُرْنِي بِعَمَلٍ. قَالَ: "عَلَيْكَ بِالصَّوْمِ، فَإِنَّهُ لَا عَدْلَ لَهُ". (ن)', 'അബൂഉമാമ(റ): ഞാൻ റസൂൽ(സ)യുടെ അടുത്തുചെന്നു ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്നോടു വല്ലതും കൽപിക്കുക. അങ്ങയിൽനിന്നു ഞാനതു സ്വീകരിച്ചോട്ടേ. അവിടന്ന് പറഞ്ഞു: "നീ നോമ്പനുഷ്ഠിക്കുക. അതിനോടു സദൃശ്യമായ മറ്റൊന്നുമില്ല."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=7), 1, 'وَفِي رِوَايَةٍ: قُلْتُ: يَا رَسُولَ اللَّهِ، مُرْنِي بِأَمْرٍ يَنْفَعُنِي اللَّهُ بِهِ. قَالَ: "عَلَيْكَ بِالصَّوْمِ، فَإِنَّهُ لَا مِثْلَ لَهُ".', 'മറ്റൊരു നിവേദനം: ഞാൻ പറഞ്ഞു: എനിക്കല്ലാഹു ഉപകാരം ചെയ്യുന്ന ഒരു കാര്യം അല്ലാഹുവിന്റെ റസൂലേ, എന്നോടു കൽപിക്കുക. അവിടന്ന് പറഞ്ഞു: "നോമ്പനുഷ്ഠിക്കുക. അതിനോടു സദൃശ്യമായ മറ്റൊന്നില്ലതന്നെ."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=7), 2, 'وَفِي رِوَايَةٍ: أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الْعَمَلِ أَفْضَلُ؟ قَالَ: "عَلَيْكَ بِالصَّوْمِ، فَإِنَّهُ لَا عِدْلَ لَهُ".', 'മറ്റൊരു നിവേദനം: അദ്ദേഹം റസൂൽ(സ)യോട് ചോദിച്ചു: ഏറ്റവും ശ്രേഷ്ഠമായ ആരാധനയേതാണ്? നബി(സ) പ്രതിവചിച്ചു: "നോമ്പനുഷ്ഠിക്കുക, നിശ്ചയം അതിന് തുല്യമായ മറ്റൊന്നില്ല."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=7), 3, 'وَفِي رِوَايَةٍ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، مُرْنِي بِعَمَلٍ. قَالَ: "عَلَيْكَ بِالصَّوْمِ، فَإِنَّهُ لَا عَدْلَ لَهُ". (ن)', 'മറ്റൊരു നിവേദനം: ഞാൻ പറഞ്ഞു: റസൂലേ, എനിക്ക് ഒരു കർമ്മം പറഞ്ഞു തരിക. അവിടന്ന് പറഞ്ഞു: "നീ നോമ്പനുഷ്ഠിക്കുക, അതിനോട് തുല്യമായ ഒന്നുമില്ല." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي عُبَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الصَّوْمُ جُنَّةٌ، مَا لَمْ يَخْرِقْهَا". (ن)', 'അബൂഉബൈദ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നോമ്പു പരിചയാണ്, അതു പൊളിച്ചുകളയാത്ത കാലത്തോളം." (ന)', 'أَبِي عُبَيْدَةَ', 'അബൂഉബൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 51, 51, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لِلصَّائِمِينَ بَابٌ فِي الْجَنَّةِ يُقَالُ لَهُ الرَّيَّانُ، لَا يَدْخُلُ فِيهِ أَحَدٌ غَيْرُهُمْ، فَإِذَا دَخَلَ آخِرُهُمْ أُغْلِقَ. مَنْ دَخَلَ فِيهِ شَرِبَ، وَمَنْ شَرِبَ لَمْ يَظْمَأْ أَبَدًا". (ن)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): നബി(സ) പറഞ്ഞു: "സ്വർഗ്ഗത്തിൽ നോമ്പുകാർക്ക് ''റയ്യാൻ'' എന്ന് പേരുള്ള ഒരു കവാടമുണ്ട്, നോമ്പുകാരല്ലാതെ മറ്റാരാളും അതിലൂടെ പ്രവേശിക്കുകയില്ല. അവരിൽ അവസാനത്തെയാൾ അതിലൂടെ പ്രവേശിച്ചാൽ വാതിൽ അടക്കപ്പെടും. അതിൽ പ്രവേശിച്ചവർ കുടിക്കുന്നു. കുടിച്ചവന്ന് പിന്നീട് ദാഹിക്കുകയില്ല."(ന)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 51, 51, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ شَبَابٌ لَا نَقْدِرُ عَلَى شَيْءٍ، قَالَ: "يَا مَعْشَرَ الشَّبَابِ عَلَيْكُمْ بِالْبَاءَةِ، فَإِنَّهُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ. وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ، فَإِنَّهُ لَهُ وِجَاءٌ". (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. ഒരു കാര്യത്തിനും കഴിവില്ലാത്ത യുവാക്കളായിരുന്നു ഞങ്ങൾ. (വിവാഹം പോലെയുള്ള കാര്യങ്ങൾക്ക് സാധിക്കുന്നവരായിരുന്നില്ലെന്ന് സൂചിപ്പിക്കപ്പെടുന്നു). നബി(സ) പറഞ്ഞു: "ഓ യുവാക്കളെ, നിങ്ങൾ വിവാഹം കഴിക്കുക, തീർച്ചയായും അത് കണ്ണുകളെ കീഴ്പ്പോട്ടാക്കുകയും ഗുഹ്യസ്ഥാനങ്ങളെ നിയന്ത്രിക്കുകയും ചെയ്യും. വിവാഹത്തിന് കഴിയാത്തവർ നോമ്പനുഷ്ഠിച്ചു കൊള്ളട്ടെ. അതവർക്ക് വികാര നിയന്ത്രണത്തിനുതകും." (ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 51, 51, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عَلْقَمَةَ: أَنَّ ابْنَ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ لَقِيَ عُثْمَانَ رَضِيَ اللهُ عَنْهُ بِعَرَفَاتٍ فَخَلَا بِهِ فَحَدَّثَهُ، وَأَنَّ عُثْمَانَ قَالَ لِابْنِ مَسْعُودٍ: هَلْ لَكَ فِي فَتَاةٍ أُزَوِّجُكَهَا؟ فَدَعَا عَبْدُ اللَّهِ عَلْقَمَةَ فَحَدَّثَهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ اسْتَطَاعَ مِنْكُمُ الْبَاءَةَ فَلْيَتَزَوَّجْ، فَإِنَّهُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ، وَمَنْ لَمْ يَسْتَطِعْ فَلْيَصُمْ، فَإِنَّ الصَّوْمَ لَهُ وِجَاءٌ". (ن)', 'അൽഖമ(റ): ഇബ്നുമസ്ഊദ്(റ) അറഫയിൽവെച്ച് ഉസ്മാൻ(റ)നെ കണ്ടുമുട്ടി. അദ്ദേഹത്തെ തനിച്ചു ലഭിച്ചപ്പോൾ അദ്ദേഹത്തോട് ഒത്തിരി സംസാരിച്ചു. ഉസ്മാൻ(റ) ഇബ്നുമസ്ഊദ്(റ)നോട് ചോദിച്ചു: നിങ്ങൾക്കു വല്ല യുവതികളിലും താൽപര്യമുണ്ടോ? ഞാൻ വിവാഹം കഴിപ്പിച്ചുതരാം. അപ്പോൾ അബ്ദുല്ല(റ) അൽഖമ(റ)നെ വിളിച്ച് പറഞ്ഞു: നിശ്ചയം നബി(സ) പറഞ്ഞിട്ടുണ്ട്: "നിങ്ങളിൽ സാധിക്കുന്നവർ വിവാഹിതരാവട്ടെ. നിശ്ചയം അതു കണ്ണുകളെ താഴ്ത്തുകയും ഗുഹ്യസ്ഥാനങ്ങളെ നിയന്ത്രിക്കുകയും ചെയ്യും. വിവാഹത്തിനു സാധിക്കാത്തവൻ നോമ്പെടുത്തുകൊള്ളട്ടെ. നിശ്ചയം നോമ്പ് അവനു വികാരശമനോപാധിയാണ്." (ന)', 'عَلْقَمَةَ', 'അൽഖമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 51, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ قَالَ: دَخَلْنَا عَلَى عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، وَمَعَنَا عَلْقَمَةُ وَالْأَسْوَدُ وَجَمَاعَةٌ، فَحَدَّثَنَا بِحَدِيثٍ مَا رَأَيْتُهُ حَدَّثَ بِهِ الْقَوْمَ إِلَّا مِنْ أَجْلِي، لِأَنِّي كُنْتُ أَحْدَثَهُمْ سِنًّا، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا مَعْشَرَ الشَّبَابِ، مَنِ اسْتَطَاعَ مِنْكُمُ الْبَاءَةَ فَلْيَتَزَوَّجْ، فَإِنَّهُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ". (ن)', 'അബ്ദുറഹ്മാനുബ്നു യസീദ്(റ): ഞങ്ങൾ അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)വിന്റെ അടുത്തു ചെന്നു. തദവസരം അൽഖമ(റ)യും അസ്വദ്(റ)വും മറ്റൊരു വിഭാഗവും ഞങ്ങളോടൊപ്പമുണ്ട്. അബ്ദുല്ല(റ) ഞങ്ങളോടൊരു ഹദീസ് പറഞ്ഞു. ഞാനുണ്ടായതു കൊണ്ടാണ് അവരത് പറഞ്ഞു തന്നതെന്നാണ് ഞാൻ മനസ്സിലാക്കുന്നത്, കാരണം ഞാനായിരുന്നു അവരിൽ ഏറ്റവും പ്രായം കുറഞ്ഞ വ്യക്തി. അദ്ദേഹം പറയുന്നു: റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "ഓ യുവാക്കളേ, നിങ്ങളിൽ കഴിവുള്ളവർ വിവാഹിതരാവട്ടെ. കാരണം, അതു കണ്ണിനെ താഴ്ത്തുകയും ഗുഹ്യസ്ഥാനങ്ങളെ നിയന്ത്രിക്കുകയും ചെയ്യും.." (ന).', 'عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ قَالَ', 'അബ്ദുറഹ്മാനുബ്നു യസീദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 52, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ الْحَسَنِ بْنِ عَلِيٍّ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تُحْفَةُ الصَّائِمِ الدُّهْنُ وَالْمِجْمَرُ". (ت)', 'ഹസനുബ്നു അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "നോമ്പുകാരനുള്ള സമ്മാനം (അവന്റെ ക്ഷീണം ഇല്ലാതാക്കുന്ന വസ്തുക്കൾ) എണ്ണയും ഉലുവാനുമാണ്. (തു)', 'الْحَسَنِ بْنِ عَلِيٍّ', 'ഹസനുബ്നു അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 52, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ عَبْدٍ يَصُومُ يَوْمًا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ إِلَّا بَعَّدَ اللَّهُ عَزَّ وَجَلَّ بِذَلِكَ الْيَوْمِ وَجْهَهُ عَنِ النَّارِ سَبْعِينَ خَرِيفًا". وَفِي رِوَايَةٍ: "مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ بَاعَدَهُ اللَّهُ- وَفِي رِوَايَةٍ: بَاعَدَ اللَّهُ وَجْهَهُ- عَنِ النَّارِ سَبْعِينَ خَرِيفًا". (ن)', 'അബൂസഈദ്(റ): റസൂൽ(സ) പറയുന്നു: "ഒരടിമ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരു ദിവസം നോമ്പനുഷ്ഠിച്ചാൽ എഴുപത് വർഷത്തെ വിദൂരം നരകത്തിൽ നിന്നും അവന്റെ മുഖത്തെ അല്ലാഹു അകറ്റും." മറ്റൊരു നിവേദനത്തിൽ: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരുത്തൻ ഒരു നോമ്പ് അനുഷ്ഠിച്ചാൽ നരകത്തെ തൊട്ട് അല്ലാഹു അവനെ എഴുപത് വർഷം വിദൂരത്താക്കുന്നതാണ്." (ന)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 52, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=14), 1, 'وَفِي رِوَايَةٍ: "مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ بَاعَدَهُ اللَّهُ-', 'മറ്റൊരു നിവേദനത്തിൽ: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരുത്തൻ ഒരു നോമ്പ് അനുഷ്ഠിച്ചാൽ നരകത്തെ തൊട്ട് അല്ലാഹു അവനെ എഴുപത് വർഷം വിദൂരത്താക്കുന്നതാണ്." (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=14), 2, 'وَفِي رِوَايَةٍ: بَاعَدَ اللَّهُ وَجْهَهُ- عَنِ النَّارِ سَبْعِينَ خَرِيفًا". (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ بَاعَدَ اللَّهُ مِنْهُ جَهَنَّمَ مَسِيرَةَ مِائَةِ عَامٍ". (ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരു ദിനം നോമ്പെടുത്താൽ അവനും നരകത്തിനുമിടക്ക് നൂറുവർഷത്തെ ദൂരം അല്ലാഹു സൃഷ്ടിക്കും." (ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 52, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لِكُلِّ شَيْءٍ زَكَاةٌ، وَزَكَاةُ الْجِسْمِ الصَّوْمُ". وَفِي رِوَايَةٍ: وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الصِّيَامُ نِصْفُ الصَّبْرِ". [ز: في سنده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "എല്ലാ വസ്തുവിനും നിർബന്ധദാനമുണ്ട്. ശരീരത്തിന്റെ നിർബന്ധദാനം വ്രതമത്രെ." മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറയുന്നു: "വ്രതം ക്ഷമയുടെ പകുതിഭാഗമത്രെ." (പരമ്പരയിൽ ദുർബലനുണ്ട്) (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', 'പരമ്പരയിൽ ദുർബലനുണ്ട്', 52, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=16), 1, 'وَفِي رِوَايَةٍ: وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الصِّيَامُ نِصْفُ الصَّبْرِ". [ز: في سنده ضعيف] (جه)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറയുന്നു: "വ്രതം ക്ഷമയുടെ പകുതിഭാഗമത്രെ." (പരമ്പരയിൽ ദുർബലനുണ്ട്) (ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثَةٌ لَا تُرَدُّ دَعْوَتُهُمْ: الْإِمَامُ الْعَادِلُ، وَالصَّائِمُ حَتَّى يُفْطِرَ، وَدَعْوَةُ الْمَظْلُومِ: يَرْفَعُهَا اللَّهُ دُونَ الْغَمَامِ يَوْمَ الْقِيَامَةِ، وَتُفْتَحُ لَهَا أَبْوَابُ السَّمَاءِ، وَيَقُولُ: بِعِزَّتِي لَأَنْصُرَنَّكِ وَلَوْ بَعْدَ حِينٍ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) അരുളി: "മൂന്നുപേരുടെ പ്രാർത്ഥന തള്ളപ്പെടുകയില്ല: നീതിമാനായ ഭരണാധിപൻ, നോമ്പുകാരൻ നോമ്പു മുറിക്കുന്നതുവരെ, അക്രമിക്കപ്പെട്ടവന്റെ പ്രാർത്ഥന. അന്ത്യദിനത്തിൽ മറകൂടാതെ അവ ഉയർത്തപ്പെടുന്നു. ആകാശ കവാടങ്ങൾ അവക്കുവേണ്ടി തുറക്കപ്പെടും. അല്ലാഹു പറയും: എന്റെ ഔന്നിത്യം തന്നെ സത്യം, പിന്നീടെങ്കിലും നിന്നെ ഞാൻ സഹായിക്കുമെന്നതു തീർച്ച." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 52, 53, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ لِلصَّائِمِ عِنْدَ فِطْرِهِ لَدَعْوَةً مَا تُرَدُّ". (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): തിരുമേനി(സ) പറയുന്നു: "നോമ്പുകാരൻ നോമ്പ് അവസാനിപ്പിക്കുന്ന അവസരത്തിൽ തള്ളപ്പെടാത്തൊരു പ്രാർത്ഥനയുമുണ്ട്. (ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 53, 53, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا كَانَ أَوَّلُ لَيْلَةٍ مِنْ شَهْرِ رَمَضَانَ صُفِّدَتِ الشَّيَاطِينُ وَمَرَدَةُ الْجِنِّ، وَغُلِّقَتْ أَبْوَابُ النَّارِ فَلَمْ يُفْتَحْ مِنْهَا بَابٌ، وَفُتِّحَتْ أَبْوَابُ الْجَنَّةِ فَلَمْ يُغْلَقْ مِنْهَا بَابٌ، وَيُنَادِي مُنَادٍ: يَا بَاغِيَ الْخَيْرِ أَقْبِلْ، وَيَا بَاغِيَ الشَّرِّ أَقْصِرْ، وَلِلَّهِ عُتَقَاءُ مِنَ النَّارِ. وَذَلِكَ كُلَّ لَيْلَةٍ". (م,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "റമളാനിന്റെ ആദ്യരാത്രിയായാൽ പിശാചുക്കളും അഹങ്കാരികളായ ജിന്നുകളും ചങ്ങലകളിൽ ബന്ധിക്കപ്പെടും. നരകത്തിന്റെ വാതിലുകൾ കൊട്ടിയടക്കപ്പെടും. അവയിലൊരു വാതിലും തുറക്കപ്പെടുകയില്ല. സ്വർഗ്ഗവാതിലുകൾ തുറക്കപ്പെടും. അവയിലൊരു വാതിലും അടക്കപ്പെടുകയില്ല. പിന്നെ, വിളിച്ചു പറയുന്ന ഒരാൾ വിളിച്ചു പറയും: നൻമേച്ഛുക്കളേ മുന്നിടൂ. തിന്മ കൊതിക്കുന്നവരേ തെറ്റുനിറുത്തുക. അല്ലാഹുവിന് നരകത്തിൽനിന്ന് മോചിപ്പിക്കപ്പെടുന്ന കുറെ അടിമകളുണ്ട്. ഇത് (റമളാനിലെ) എല്ലാ രാത്രികളിലുമുണ്ട്." (മു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 53, 53, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عَرْفَجَةَ بْنِ عَبْدِ اللَّهِ الثَّقَفِيِّ قَالَ: عُدْنَا عُتْبَةَ بْنَ فَرْقَدٍ رَضِيَ اللهُ عَنْهُ، فَتَذَاكَرْنَا شَهْرَ رَمَضَانَ، فَقَالَ: مَا تَذْكُرُونَ؟ قُلْنَا: شَهْرُ رَمَضَانَ. قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "تُفْتَحُ فِيهِ أَبْوَابُ الْجَنَّةِ، وَتُغْلَقُ فِيهِ أَبْوَابُ النَّارِ، وَتُغَلُّ فِيهِ الشَّيَاطِينُ، وَيُنَادِي مُنَادٍ كُلَّ لَيْلَةٍ: يَا بَاغِيَ الْخَيْرِ هَلُمَّ، وَيَا بَاغِيَ الشَّرِّ أَقْصِرْ". وَفِي رِوَايَةٍ قَالَ: كُنْتُ فِي بَيْتٍ فِيهِ عُتْبَةُ بْنُ فَرْقَدٍ رَضِيَ اللهُ عَنْهُ، فَأَرَدْتُ أَنْ أُحَدِّثَ بِحَدِيثٍ، وَكَانَ رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَأَنَّهُ أَوْلَى بِالْحَدِيثِ مِنِّي، فَحَدَّثَ الرَّجُلُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي رَمَضَانَ: "تُفْتَحُ فِيهِ أَبْوَابُ السَّمَاءِ، وَتُغْلَقُ فِيهِ أَبْوَابُ النَّارِ، وَيُصَفَّدُ فِيهِ كُلُّ شَيْطَانٍ مَرِيدٍ، وَيُنَادِي مُنَادٍ كُلَّ لَيْلَةٍ: يَا طَالِبَ الْخَيْرِ هَلُمَّ، وَيَا طَالِبَ الشَّرِّ أَمْسِكْ". (ن)', 'അർഫജതുബ്നു അബ്ദില്ല(റ): ഞങ്ങൾ ഉത്ബതുബ്നു ഫർഖദ്(റ)വിനെ സന്ദർശിച്ചു. തദവസരത്തിൽ റമളാൻ മാസത്തെക്കുറിച്ച് ഞങ്ങൾ സംസാരിച്ചു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: എന്തിനെക്കുറിച്ചാണ് നിങ്ങൾ സംസാരിക്കുന്നത്? റമളാനെക്കുറിച്ചാണെന്ന് ഞങ്ങൾ പറഞ്ഞു. തുടർന്ന് അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "റമളാനിൽ സ്വർഗ്ഗവാതിലുകൾ തുറക്കപ്പെടും. നരകവാതിലുകൾ അടക്കപ്പെടും. പിശാചുക്കൾ ബന്ധിക്കപ്പെടും. എല്ലാ രാത്രിയിലും ഒരാൾ വിളിച്ചുപറഞ്ഞുകൊണ്ടിരിക്കും: നന്മ ആഗ്രഹിക്കുന്നവനേ, മുന്നോട്ട് വരിക. തിന്മയാഗ്രഹിക്കുന്നവനേ, അതിൽ നിന്നും പിന്തിരിയുക."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=20), 1, 'وَفِي رِوَايَةٍ قَالَ: كُنْتُ فِي بَيْتٍ فِيهِ عُتْبَةُ بْنُ فَرْقَدٍ رَضِيَ اللهُ عَنْهُ، فَأَرَدْتُ أَنْ أُحَدِّثَ بِحَدِيثٍ، وَكَانَ رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَأَنَّهُ أَوْلَى بِالْحَدِيثِ مِنِّي، فَحَدَّثَ الرَّجُلُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي رَمَضَانَ: "تُفْتَحُ فِيهِ أَبْوَابُ السَّمَاءِ، وَتُغْلَقُ فِيهِ أَبْوَابُ النَّارِ، وَيُصَفَّدُ فِيهِ كُلُّ شَيْطَانٍ مَرِيدٍ، وَيُنَادِي مُنَادٍ كُلَّ لَيْلَةٍ: يَا طَالِبَ الْخَيْرِ هَلُمَّ، وَيَا طَالِبَ الشَّرِّ أَمْسِكْ". (ن)', 'മറ്റൊരു നിവേദനം: ഞാൻ ഉത്ബതുബ്നു ഫർഖദ്(റ) ഉണ്ടായിരുന്ന ഒരു വീട്ടിലായിരുന്നു. അന്നേരം ഞാൻ ഒരു ഹദീസ് പറയാനുദ്ദേശിച്ചു. എന്നേക്കാൾ ഹദീസിനെക്കുറിച്ച് പറയാനർഹനായ, നബി(സ)യുടെ അനുചരൻമാരിൽപ്പെട്ട ഒരാളുണ്ടായിരുന്നു അവിടെ. റമളാനിനെക്കുറിച്ച് നബി(സ) പറഞ്ഞതായി അദ്ദേഹം പറഞ്ഞു: "അതിൽ ആകാശവാതിലുകൾ തുറക്കപ്പെടും, നരകവാതിലുകൾ അടക്കപ്പെടും, അക്രമകാരികളായ പിശാചുക്കളെല്ലാം തളക്കപ്പെടും. എല്ലാ രാത്രിയിലും ഒരാൾ വിളിച്ചുപറയും: നന്മ ആഗ്രഹിക്കുന്നവനേ, മുന്നോട്ട് വരിക, തിന്മ ആഗ്രഹിക്കുന്നവനേ, മാറിനിൽക്ക്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ لِلَّهِ عِنْدَ كُلِّ فِطْرٍ عُتَقَاءَ، وَذَلِكَ فِي كُلِّ لَيْلَةٍ". (جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ നോമ്പുതുറ സമയത്തും നരകമോചനം നൽകപ്പെടുന്ന കുറെ അടിമകളുണ്ട് അല്ലാഹുവിന്. ഇത് എല്ലാ രാത്രികളിലും ഉണ്ട്." (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 54, 54, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَامَ رَمَضَانَ- إِيمَانًا وَاحْتِسَابًا- غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (خ,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "വിശ്വസിച്ചും പ്രതിഫലമാഗ്രഹിച്ചും ആരെങ്കിലും റമളാനിൽ നോമ്പനുഷ്ഠിച്ചാൽ അവരുടെ മുൻകഴിഞ്ഞ ദോഷങ്ങൾ പൊറുക്കപ്പെടും." (ബു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], null, null, 54, 54, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ رَمَضَانُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ هَذَا الشَّهْرَ قَدْ حَضَرَكُمْ، وَفِيهِ لَيْلَةٌ خَيْرٌ مِنْ أَلْفِ شَهْرٍ، مَنْ حُرِمَهَا فَقَدْ حُرِمَ الْخَيْرَ كُلَّهُ، وَلَا يُحْرَمُ خَيْرَهَا إِلَّا مَحْرُومٌ". (ن)', 'അനസ്(റ): റമളാൻ ആഗതമായ സന്ദർഭം റസൂൽ(സ) അരുളി: "നിശ്ചയം ഈ മാസം നിങ്ങൾക്ക് ആഗതമായിരിക്കുന്നു. അതിൽ ആയിരം മാസത്തേക്കാൾ പുണ്യമുള്ള ഒരു രാത്രിയുണ്ട്. ആ രാത്രി തടയപ്പെട്ടവർക്ക് മുഴുവൻ നന്മയും തടയപ്പെട്ടു, നിർഭാഗ്യവാന്മാർക്കല്ലാതെ ആ ഗുണം തടയപ്പെടുകയില്ല." (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 54, 54, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِامْرَأَةٍ مِنَ الْأَنْصَارِ: "إِذَا كَانَ رَمَضَانُ فَاعْتَمِرِي فِيهِ، فَإِنَّ عُمْرَةً فِيهِ تَعْدِلُ حَجَّةً". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഒരു അൻസാരി സ്ത്രീയോട് പറഞ്ഞു: "റമളാൻ ആഗതമായാൽ അതിൽ നീ ഉംറ നിർവ്വഹിക്കുക. റമളാനിലെ ഉംറ ഹജ്ജിന് തുല്യമാണ്." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 54, 54, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: {يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ} [البقرة:١٨٣] فَكَانَ النَّاسُ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّوُا الْعَتَمَةَ حَرُمَ عَلَيْهِمُ الطَّعَامُ وَالشَّرَابُ وَالنِّسَاءُ، وَصَامُوا إِلَى الْقَابِلَةِ، فَاخْتَانَ رَجُلٌ نَفْسَهُ، فَجَامَعَ امْرَأَتَهُ وَقَدْ صَلَّى الْعِشَاءَ وَلَمْ يُفْطِرْ، فَأَرَادَ اللَّهُ عَزَّ وَجَلَّ أَنْ يَجْعَلَ ذَلِكَ يُسْرًا لِمَنْ بَقِيَ وَرُخْصَةً وَمَنْفَعَةً، فَقَالَ سُبْحَانَهُ: {عَلِمَ اللَّهُ أَنَّكُمْ كُنْتُمْ تَخْتَانُونَ أَنْفُسَكُمْ} [البقرة:١٨٧] الْآيَةَ. وَكَانَ هَذَا مِمَّا نَفَعَ اللَّهُ بِهِ النَّاسَ وَرَخَّصَ لَهُمْ وَيَسَّرَ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''സത്യവിശ്വാസികളേ, നിങ്ങളുടെ മുൻഗാമികൾക്കു നോമ്പു നിർബന്ധമാക്കപ്പെട്ടതുപോലെ നിങ്ങൾക്കും നോമ്പ് നിർബന്ധമാക്കപ്പെട്ടിരിക്കുന്നു.'' (അൽബഖറ: 183) നബി(സ)യുടെ കാലത്ത് രാത്രി നിസ്കാരശേഷം ജനങ്ങൾക്ക് അന്നപാനീയങ്ങളും ഭാര്യമാരും വിലക്കപ്പെടുകയും ആ സമയത്ത് തന്നെ അടുത്ത നോമ്പ് ആരംഭിക്കുകയും ചെയ്യുമായിരുന്നു. ആത്മവഞ്ചനയിലകപ്പെട്ട ഒരാൾ ''ഇശാ''നിസ്കരിച്ച് ഭാര്യയുമായി ബന്ധപ്പെടുകയും നോമ്പ് തുടരുകയും ചെയ്തു. ഇത് മറ്റുള്ളവർക്കു കൂടി ഇളവും സൗകര്യവും ഉപകാരപ്രദവുമാകാൻ അല്ലാഹു ഉദ്ദേശിച്ചു. അങ്ങനെ അല്ലാഹു പറഞ്ഞു: ''നിങ്ങൾ ആത്മവഞ്ചനയിലകപ്പെടുകയായിരുന്നുവെന്ന് അല്ലാഹു അറിഞ്ഞിരിക്കുന്നു.'' (അൽബഖറ: 187) ഇത് അല്ലാഹു ജനങ്ങൾക്ക് നൽകിയ ഉപകാരവും വിട്ടുവീഴ്ചയും സൗകര്യവുമായിരുന്നു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'البقرة:١٨٧', null, 54, 55, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ أَصْحَابُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ الرَّجُلُ صَائِمًا فَحَضَرَ الْإِفْطَارُ فَنَامَ قَبْلَ أَنْ يُفْطِرَ لَمْ يَأْكُلْ لَيْلَتَهُ وَلَا يَوْمَهُ حَتَّى يُمْسِيَ، وَإِنَّ قَيْسَ بْنَ صِرْمَةَ الْأَنْصَارِيَّ كَانَ صَائِمًا فَلَمَّا حَضَرَ الْإِفْطَارُ أَتَى امْرَأَتَهُ فَقَالَ لَهَا: أَعِنْدَكِ طَعَامٌ؟ قَالَتْ: لَا، وَلَكِنْ أَنْطَلِقُ فَأَطْلُبُ لَكَ وَكَانَ يَوْمَهُ يَعْمَلُ فَغَلَبَتْهُ عَيْنَاهُ فَجَاءَتْهُ امْرَأَتُهُ، فَلَمَّا رَأَتْهُ قَالَتْ: خَيْبَةً لَكَ، فَلَمَّا انْتَصَفَ النَّهَارُ غُشِيَ عَلَيْهِ فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَزَلَتْ هَذِهِ الْآيَةُ: {أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَى نِسَائِكُمْ} فَفَرِحُوا بِهَا فَرَحًا شَدِيدًا، وَنَزَلَتْ: {وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ}. (خ,د,ت,ن)', 'ബറാഅ്(റ): മുഹമ്മദ്(സ)യുടെ അനുയായികൾ; അവരിൽ ഒരാൾ നോമ്പനുഷ്ഠിച്ചു. തുറക്കുന്ന സമയമായെങ്കിലും നോമ്പ് തുറക്കുംമുമ്പ് അദ്ദേഹം ഉറങ്ങിപ്പോയി. ആ രാത്രിയും അടുത്ത പകലും അയാൾ ഒന്നും തന്നെ ഭക്ഷിച്ചില്ല. വൈകുവോളം കാത്തിരുന്നു. ഖൈസുബ്നു സ്വിർമത് നോമ്പുകാരനായിരുന്നു. നോമ്പു തുറക്കുവാനുള്ള സമയമായപ്പോൾ അദ്ദേഹം തന്റെ ഭാര്യയുടെ അടുത്തുചെന്നു ചോദിച്ചു: നിന്റെയടുത്ത് ഭക്ഷണം വല്ലതുമുണ്ടോ? അവർ പറഞ്ഞു: ഇല്ല, എങ്കിലും ഞാൻ നിങ്ങൾക്ക് വേണ്ടി അന്വേഷിക്കാം. അന്നു പകൽ മുഴുവനും അദ്ദേഹം ജോലിയെടുത്തിരുന്നു. അതുമൂലം അയാൾ ഉറങ്ങിപ്പോയി. ഭാര്യ തിരിച്ചുവന്നു. അദ്ദേഹം ഉറങ്ങുന്നതുകണ്ടപ്പോൾ അവർ പറഞ്ഞു: താങ്കളുടെ ദൗർഭാഗ്യം! പിറ്റേന്ന് ഉച്ചസമയത്ത് അദ്ദേഹം ബോധരഹിതനായി. വിഷയം നബി(സ)യെ ധരിപ്പിച്ചു. അപ്പോൾ സൂക്തമിറങ്ങി: ''നോമ്പിന്റെ രാത്രി ഭാര്യമാരുമായി സഹവസിക്കൽ നിങ്ങൾക്ക് അനുവദിക്കപ്പെട്ടിരിക്കുന്നു.'' ഈ വിധിയിൽ അവർ വളരെയധികം സന്തോഷിച്ചു. ഈ സൂക്തവുമിറങ്ങി: ''വെളുത്ത നൂലിഴകളിൽനിന്ന് കറുത്ത നൂലിഴകൾ നിങ്ങൾക്ക് വെളിവാകുന്നതുവരെ നിങ്ങൾ തിന്നുകയും കുടിക്കുകയും ചെയ്യുക.'' (2: 187) (ബു,ദ,തു,ന)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 55, 55, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ: أَنَّ أَعْرَابِيًّا جَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَائِرَ الرَّأْسِ، فَقَالَ: يَا رَسُولَ اللَّهِ، أَخْبِرْنِي مَاذَا فَرَضَ اللَّهُ عَلَيَّ مِنَ الصَّلَاةِ؟ قَالَ: "الصَّلَوَاتُ الْخَمْسُ إِلَّا أَنْ تَطَوَّعَ شَيْئًا". قَالَ: أَخْبِرْنِي بِمَا افْتَرَضَ اللَّهُ عَلَيَّ مِنَ الصِّيَامِ؟ قَالَ: "صِيَامُ شَهْرِ رَمَضَانَ إِلَّا أَنْ تَطَوَّعَ شَيْئًا". قَالَ: أَخْبِرْنِي بِمَا افْتَرَضَ اللَّهُ عَلَيَّ مِنَ الزَّكَاةِ: فَأَخْبَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَرَائِعِ الْإِسْلَامِ، فَقَالَ: وَالَّذِي أَكْرَمَكَ لَا أَتَطَوَّعُ شَيْئًا، لَا أَنْقُصُ مِمَّا فَرَضَ اللَّهُ عَلَيَّ شَيْئًا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَفْلَحَ إِنْ صَدَقَ. أَوْ: دَخَلَ الْجَنَّةَ إِنْ صَدَقَ". (ن)', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ): ഒരു അഅ്റാബി മുടിയും പറത്തി റസൂൽ(സ)യുടെ സന്നിധിയിലെത്തി. എന്നിട്ടു പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹു എന്റെ മേൽ നിർബന്ധമാക്കിയ നിസ്കാരങ്ങൾ ഏതൊക്കെയെന്ന് എനിക്ക് പറഞ്ഞുതന്നാലും. അവിടന്ന് പറഞ്ഞു: "അഞ്ചുനേരത്തെ നിസ്കാരം, നീ സുന്നത്ത് അനുഷ്ഠിക്കുന്നതൊഴികെ." അഅ്റാബി ചോദിച്ചു: എനിക്ക് നിർബന്ധമായ നോമ്പിനെക്കുറിച്ചു പറഞ്ഞുതരു. റസൂൽ(സ) പറഞ്ഞു: "റമളാൻ മാസം വ്രതമനുഷ്ഠിക്കുക, പിന്നെ സുന്നത്തുകളും അനുഷ്ഠിക്കാം." അഅ്റാബി ചോദിച്ചു: സകാത്തിൽനിന്ന് എനിക്ക് നിർബന്ധമാക്കിയതിനെക്കുറിച്ച് പറഞ്ഞുതരൂ. അപ്പോൾ റസൂൽ(സ) ഇസ്ലാമിക നിയമങ്ങൾ പറഞ്ഞുകൊടുത്തു. തദവസരം അഅ്റാബി പറഞ്ഞു: അങ്ങയെ ആദരിച്ചവനാണു സത്യം! സുന്നത്തുകളൊന്നും ഞാൻ ചെയ്യില്ല. എന്റെ മേൽ നിർബന്ധമായതിൽ നിന്നൊന്നും തന്നെ ഞാൻ ചുരുക്കുകയുമില്ല. തൽക്ഷണം റസൂൽ(സ) പ്രതിവചിച്ചു: "പറഞ്ഞത് സത്യമെങ്കിൽ അദ്ദേഹം വിജയിച്ചു." അല്ലെങ്കിൽ "പറഞ്ഞത് സത്യമെങ്കിൽ അദ്ദേഹം സ്വർഗ്ഗത്തിൽ പ്രവേശിച്ചു." (ന)', 'طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 55, 56, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: نُهِينَا فِي الْقُرْآنِ أَنْ نَسْأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ شَيْءٍ، فَكَانَ يُعْجِبُنَا أَنْ يَجِيءَ الرَّجُلُ الْعَاقِلُ مِنْ أَهْلِ الْبَادِيَةِ فَيَسْأَلَهُ، فَجَاءَ رَجُلٌ مِنْ أَهْلِ الْبَادِيَةِ فَقَالَ: يَا مُحَمَّدُ، أَتَانَا رَسُولُكَ فَأَخْبَرَنَا أَنَّكَ تَزْعُمُ: أَنَّ اللَّهَ عَزَّ وَجَلَّ أَرْسَلَكَ؟ قَالَ: "صَدَقَ". قَالَ: فَمَنْ خَلَقَ السَّمَاءَ؟ قَالَ: "اللَّهُ". قَالَ: فَمَنْ خَلَقَ الْأَرْضَ؟ قَالَ: "اللَّهُ". قَالَ: فَمَنْ نَصَبَ فِيهَا الْجِبَالَ: قَالَ: "اللَّهُ". قَالَ: فَمَنْ جَعَلَ فِيهَا الْمَنَافِعَ؟ قَالَ: "اللَّهُ". قَالَ: فَبِالَّذِي خَلَقَ السَّمَاءَ وَالْأَرْضَ وَنَصَبَ فِيهَا الْجِبَالَ وَجَعَلَ فِيهَا الْمَنَافِعَ، آللَّهُ أَرْسَلَكَ؟ قَالَ: "نَعَمْ". قَالَ: وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا خَمْسَ صَلَوَاتٍ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ؟ قَالَ: "صَدَقَ". قَالَ: فَبِالَّذِي أَرْسَلَكَ، آللَّهُ أَمَرَكَ بِهَذَا؟ قَالَ: "نَعَمْ". قَالَ: وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا زَكَاةَ أَمْوَالِنَا؟ قَالَ: "صَدَقَ". قَالَ: فَبِالَّذِي أَرْسَلَكَ، آللَّهُ أَمَرَكَ بِهَذَا؟ قَالَ: "نَعَمْ". قَالَ: وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا صَوْمَ شَهْرِ رَمَضَانَ فِي كُلِّ سَنَةٍ؟ قَالَ: "صَدَقَ". قَالَ: فَبِالَّذِي أَرْسَلَكَ، آللَّهُ أَمَرَكَ بِهَذَا؟ قَالَ: "نَعَمْ". قَالَ: وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا الْحَجَّ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا؟ قَالَ: "صَدَقَ". قَالَ: فَبِالَّذِي أَرْسَلَكَ، آللَّهُ أَمَرَكَ بِهَذَا؟ قَالَ: "نَعَمْ". قَالَ: فَوَالَّذِي بَعَثَكَ بِالْحَقِّ لَا أَزِيدَنَّ عَلَيْهِنَّ شَيْئًا وَلَا أَنْقُصُ. فَلَمَّا وَلَّى قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَئِنْ صَدَقَ لَيَدْخُلَنَّ الْجَنَّةَ". (ن)', 'അനസ്(റ): നബി(സ)യോട് വല്ലതും ചോദിക്കുന്നതിൽ നിന്ന് ഖുർആൻ ഞങ്ങളെ വിലക്കിയിരുന്നു. എന്നാൽ, ബദവികളിൽപ്പെട്ട ബുദ്ധിമാനായ ഒരാൾ വന്ന് നബി(സ)യോട് ചോദ്യങ്ങൾ ചോദിക്കുന്നത് ഞങ്ങളെ ആശ്ചര്യഭരിതരാക്കിയിരുന്നു. ഒരു ബദവി വന്ന് നബി(സ)യോട് ചോദിച്ചു: മുഹമ്മദേ, താങ്കളെ അല്ലാഹു പ്രവാചകനായി നിയോഗിച്ചെന്ന് താങ്കൾ വാദിക്കുന്നതായി താങ്കളുടെ ഒരു ദൂതൻ ഞങ്ങളോട് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അത് സത്യമാണ്." അദ്ദേഹം ചോദിച്ചു: ആകാശം സൃഷ്ടിച്ചതാരാണ്? അവിടന്ന് പറഞ്ഞു: "അല്ലാഹു." അയാൾ: ഭൂമിയെ സൃഷ്ടിച്ചതാരാണ്? നബി(സ): "അല്ലാഹു." അയാൾ: അതിൽ പർവ്വതങ്ങൾ സ്ഥാപിച്ചതാരാണ്? നബി(സ): "അല്ലാഹു." അയാൾ: ആരാണതിൽ ഉപകാരമുള്ള വസ്തുക്കൾ സൃഷ്ടിച്ചത്? നബി(സ): "അല്ലാഹു." അയാൾ: ആകാശഭൂമികളെ സൃഷ്ടിക്കുകയും അതിൽ പർവ്വതങ്ങൾ സ്ഥാപിക്കുകയും ഉപകാരങ്ങൾ ഉണ്ടാക്കുകയും ചെയ്ത നാഥനാണോ താങ്കളെ നിയോഗിച്ചത്? നബി(സ): "അതെ". താങ്കളുടെ ദൂതൻ രാവിലും പകലിലുമായി അഞ്ചുസമയത്തു നിസ്കാരം നിർബന്ധമാണെന്ന് വാദിച്ചുവല്ലോ? നബി(സ): "സത്യമാണയാൾ പറഞ്ഞത്." അയാൾ: താങ്കളെ നിയോഗിച്ച നാഥനാണ് സത്യം, അല്ലാഹുവാണോ താങ്കളോടിത് കൽപ്പിച്ചത്? റസൂൽ(സ): "അതെ." അയാൾ: നിങ്ങളുടെ ദൂതൻ ഞങ്ങളുടെ സമ്പത്തിൽനിന്ന് നിർബന്ധദാനം നൽകണമെന്ന് വാദിച്ചുവല്ലോ? റസൂൽ(സ): "അത് സത്യമാണ്." അയാൾ: നിങ്ങളെ നിയോഗിച്ചവൻ തന്നെ സത്യം, ഇത് താങ്കളോട് അല്ലാഹു കൽപിച്ചതാണോ? റസൂൽ(സ): "അതെ." അയാൾ: ഓരോ വർഷവും റമളാൻ മാസം നോമ്പനുഷ്ഠിക്കണമെന്ന് നിങ്ങളുടെ ദൂതൻ വാദിച്ചുവല്ലോ? റസൂൽ(സ): "സത്യമാണ് അദ്ദേഹം പറഞ്ഞത്". അയാൾ: താങ്കളുടെ നിയോക്താവാണ് സത്യം, ഇതും നിങ്ങളോടല്ലാഹു കല്പിച്ച കാര്യമാണോ? റസൂൽ(സ): "അതെ." അയാൾ: സാധ്യമെങ്കിൽ ഞങ്ങൾ ഹജ്ജ് ചെയ്യണമെന്ന് നിങ്ങളുടെ ദൂതൻ വാദിച്ചുവല്ലോ? നബി(സ) പറഞ്ഞു: "സത്യമായും." അയാൾ: താങ്കളെ നിയോഗിച്ചവനാണ് സത്യം! താങ്കളോടിതും അല്ലാഹു കൽപിച്ചതാണോ? റസൂൽ(സ): "അതെ." അയാൾ പറഞ്ഞു: സത്യദൂതുമായി താങ്കളെ നിയോഗിച്ച ഒരുവനാണ് സത്യം, ഞാൻ ഇതിൽ ഒന്നും അധികമാക്കുകയോ ചുരുക്കുകയോ ചെയ്യുകയില്ല. അയാൾ പിന്തിരിഞ്ഞപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അയാൾ പറഞ്ഞത് സത്യമെങ്കിൽ അയാൾ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കും." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 56, 57, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: بَيْنَمَا نَحْنُ جُلُوسٌ فِي الْمَسْجِدِ جَاءَ رَجُلٌ عَلَى جَمَلٍ فَأَنَاخَهُ فِي الْمَسْجِدِ ثُمَّ عَقَلَهُ، فَقَالَ لَهُمْ: أَيُّكُمْ مُحَمَّدٌ؟ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُتَّكِئٌ بَيْنَ ظَهْرَانَيْهِمْ، قُلْنَا لَهُ: هَذَا الرَّجُلُ الْأَبْيَضُ الْمُتَّكِئُ. فَقَالَ لَهُ الرَّجُلُ: يَا ابْنَ عَبْدِ الْمُطَّلِبِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَدْ أَجَبْتُكَ". فَقَالَ الرَّجُلُ: إِنِّي سَائِلُكَ يَا مُحَمَّدُ فَمُشَدِّدٌ عَلَيْكَ فِي الْمَسْأَلَةِ، فَلَا تَجِدَنَّ فِي نَفْسِكَ. قَالَ: "سَلْ مَا بَدَا لَكَ". فَقَالَ الرَّجُلُ: نَشَدْتُكَ بِرَبِّكَ وَرَبِّ مَنْ قَبْلَكَ، آللَّهُ أَرْسَلَكَ إِلَى النَّاسِ كُلِّهِمْ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ نَعَمْ". قَالَ: فَأَنْشُدُكَ اللَّهَ، آللَّهُ أَمَرَكَ أَنْ تُصَلِّيَ الصَّلَوَاتِ الْخَمْسَ فِي الْيَوْمِ وَاللَّيْلَةِ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ نَعَمْ". قَالَ: فَأَنْشُدُكَ اللَّهَ، آللَّهُ أَمَرَكَ أَنْ تَصُومَ هَذَا الشَّهْرَ مِنَ السَّنَةِ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ نَعَمْ". قَالَ: فَأَنْشُدُكَ اللَّهَ، آللَّهُ أَمَرَكَ أَنْ تَأْخُذَ هَذِهِ الصَّدَقَةَ مِنْ أَغْنِيَائِنَا فَتَقْسِمَهَا عَلَى فُقَرَائِنَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ نَعَمْ". فَقَالَ الرَّجُلُ: آمَنْتُ بِمَا جِئْتَ بِهِ، وَأَنَا رَسُولُ مَنْ وَرَائِي مِنْ قَوْمِي، وَأَنَا ضِمَامُ بْنُ ثَعْلَبَةَ أَخُو بَنِي سَعْدِ بْنِ بَكْرٍ.(ن)', 'അനസുബ്നു മാലിക്(റ): ഞങ്ങൾ പള്ളിയിൽ ഇരിക്കുമ്പോൾ ഒട്ടകപ്പുറത്ത് ഒരാൾ വന്നിറങ്ങുകയും ഒട്ടകത്തെ ബന്ധിക്കുകയും ചെയ്തു. എന്നിട്ട് ഞങ്ങളോടു ചോദിച്ചു: നിങ്ങളിൽ മുഹമ്മദാരാണ്? തദവസരം റസൂൽ(സ) ഞങ്ങളുടെ ഇടയിൽ ചാരി ഇരിക്കുകയായിരുന്നു. ഞങ്ങൾ പറഞ്ഞു: ഈ ചാരിയിരിക്കുന്ന വെളുത്തയാളാണ്. ആഗതൻ നബി(സ)യോടു പറഞ്ഞു: അബ്ദുൽമുത്തലിബിന്റെ സന്താനമേ. റസൂൽ(സ) അയാളോട് പറഞ്ഞു: "നിങ്ങൾക്ക് ഞാനുത്തരം നൽകി." ആഗതൻ പറഞ്ഞു: മുഹമ്മദേ, ഞാൻ താങ്കളോടു ചോദിക്കുകയാണ്, ചോദിക്കുന്നതിൽ വിഷമം കാണിക്കരുത്. റസൂൽ(സ): "നിങ്ങൾക്ക് വേണ്ടതെല്ലാം ചോദിക്കൂ." ആഗതൻ പറഞ്ഞു: നിങ്ങളുടെയും നിങ്ങളുടെ മുൻകാലക്കാരുടെയും രക്ഷിതാവാണ് സത്യം! ഞാൻ ചോദിക്കുന്നു, അല്ലാഹു നിങ്ങളെ നിയോഗിച്ചത് മുഴുവൻ മനുഷ്യസമൂഹത്തിലേക്കുമായാണോ? റസൂൽ(സ): "അല്ലാഹുവാണ സത്യം! അതെ." ആഗതൻ: അല്ലാഹുവാണ് സത്യം! ഞാനപേക്ഷിക്കുന്നു, രാവും പകലുമായി അഞ്ച് നേരം നിസ്കരിക്കാൻ നിങ്ങളോട് കൽപിച്ചത് അല്ലാഹു തന്നെയോ? റസൂൽ(സ): "അതെ." ആഗതൻ: നാഥനാണെ, ഞാനപേക്ഷിക്കുന്നു, വർഷത്തിൽ ഒരു മാസം നോമ്പനുഷ്ഠിക്കാൻ നിങ്ങളോട് കൽപിച്ചത് നാഥൻ തന്നെയോ? റസൂൽ(സ): അതെ. ആഗതൻ: ഞങ്ങളിലുള്ള ദനാഢ്യരിൽ നിന്നും സ്വദഖ പിടിച്ച് പാവങ്ങൾക്ക് വിതരണം ചെയ്യാൻ നിങ്ങളോട് നാഥൻ കൽപിച്ചുവോ? റസൂൽ(സ): അതെ. ആഗതൻ പറഞ്ഞു: താങ്കൾ കൊണ്ടുവന്നതെല്ലാം ഞാൻ വിശ്വസിച്ചു കഴിഞ്ഞു. എന്റെ സമൂഹത്തിനു (ഗോത്രത്തിന്) ദൂതനാണു ഞാൻ. ഞാൻ ബനൂ സഅ്ദിബ്നി ബക്റിന്റെ സഹോദരൻ ളിമാമുബ്നു സഅ്ലബയാണ്. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 57, 57, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي الْبَخْتَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا لِلْعُمْرَةِ، فَلَمَّا نَزَلْنَا بِبَطْنِ نَخْلَةَ، قَالَ: تَرَاءَيْنَا الْهِلَالَ، فَقَالَ بَعْضُ الْقَوْمِ: هُوَ ابْنُ ثَلَاثٍ. وَقَالَ بَعْضُ الْقَوْمِ: هُوَ ابْنُ لَيْلَتَيْنِ. قَالَ: فَلَقِينَا ابْنَ عَبَّاسٍ فَقُلْنَا: إِنَّا رَأَيْنَا الْهِلَالَ، فَقَالَ بَعْضُ الْقَوْمِ: هُوَ ابْنُ ثَلَاثٍ، وَقَالَ بَعْضُ الْقَوْمِ: هُوَ ابْنُ لَيْلَتَيْنِ. فَقَالَ: أَيَّ لَيْلَةٍ رَأَيْتُمُوهُ؟ قَالَ: قُلْنَا: لَيْلَةَ كَذَا وَكَذَا، فَقَالَ ابْنُ عَبَّاسٍ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ مَدَّهُ لِلرُّؤْيَةِ، فَهُوَ لِلَيْلَةٍ رَأَيْتُمُوهُ". (م)', 'അബുൽ ബഖ്തരി(റ): ഞങ്ങൾ ഉംറക്ക് പുറപ്പെട്ടു. അങ്ങനെ ഞങ്ങൾ ''ബത്നുനഖ്ല''യിൽ ഇറങ്ങിയപ്പോൾ (റമളാൻ) മാസപ്പിറവി ദർശിക്കാനിടയായി. അപ്പോൾ ചിലർ പറഞ്ഞു: ഇത് ഉദിച്ചിട്ട് മൂന്നുദിവസം കഴിഞ്ഞിരിക്കുന്നു. ചിലർ രണ്ടുദിനമെന്നഭിപ്രായപ്പെട്ടു. അങ്ങനെ ഇബ്നുഅബ്ബാസ്(റ)വിനെ കണ്ടപ്പോൾ ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങൾ മാസം ദർശിച്ചിരിക്കുന്നു. എന്നാൽ ചിലർ അത് ഉദിച്ച് രണ്ടുദിവസം കഴിഞ്ഞെന്നും ചിലർ മൂന്നുദിവസമെന്നും അഭിപ്രായപ്പെടുന്നു. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) ചോദിച്ചു: നിങ്ങൾ ഏത് രാത്രിയിലാണ് പിറവി കണ്ടത്. ഇന്ന രാത്രിയിലാണെന്നു ഞങ്ങൾ മറുപടി പറഞ്ഞപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്. "മാസത്തെ നിങ്ങൾ ദർശിക്കുന്നതു (സമയം) വരെ അല്ലാഹു നിങ്ങൾക്ക് നീട്ടിത്തന്നിട്ടുണ്ട്. നിങ്ങൾ കാണുന്ന രാത്രിയേതോ അന്നുനിങ്ങൾ വ്രതം ആരംഭിക്കുക." (മു)', 'أَبِي الْبَخْتَرِيِّ', 'അബുൽ ബഖ്തരി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 57, 58, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ رِبْعِيِّ بْنِ حِرَاشٍ، عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُقَدِّمُوا الشَّهْرَ حَتَّى تَرَوُا الْهِلَالَ قَبْلَهُ، أَوْ تُكْمِلُوا الْعِدَّةَ، ثُمَّ صُومُوا حَتَّى تَرَوُا الْهِلَالَ أَوْ تُكْمِلُوا الْعِدَّةَ قَبْلَهُ". (ن)', 'രിബ്ഇയ്യുബ്നു ഹിറാശ്(റ), ഹുദൈഫത്തുബ്നുൽയമാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "റമളാനിനു മുമ്പ് മാസം കാണുന്നത് വരെ, അല്ലെങ്കിൽ മാസം പൂർത്തിയാകുന്നതുവരെ നിങ്ങൾ നോമ്പനുഷ്ഠിക്കരുത്, കണ്ടില്ലെങ്കിൽ മാസം പൂർത്തീകരിക്കുക. പിന്നീട് അടുത്ത മാസം കാണുവോളം, അല്ലെങ്കിൽ മാസം പൂർത്തിയാകുന്നതുവരെ നിങ്ങൾ നോമ്പനുഷ്ഠിക്കുക." (ന)', 'رِبْعِيِّ بْنِ حِرَاشٍ، عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ', 'രിബ്ഇയ്യുബ്നു ഹിറാശ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 58, 58, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ، فَإِنْ حَالَ بَيْنَكُمْ وَبَيْنَهُ سَحَابٌ فَأَكْمِلُوا الْعِدَّةَ، وَلَا تَسْتَقْبِلُوا الشَّهْرَ اسْتِقْبَالًا". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മാസപ്പിറവി ദർശിച്ചാൽ നിങ്ങൾ നോമ്പനുഷ്ഠിക്കുക. അതു കണ്ടാൽ നോമ്പ് ഉപേക്ഷിക്കുകയും ചെയ്യുക. മാസപ്പിറവിക്കും നിങ്ങൾക്കുമിടയിൽ മേഘം മറയിട്ടാൽ എണ്ണം (മുപ്പത്) പൂർത്തീകരിക്കുക. റമളാൻ മാസത്തെ (നോമ്പുകാരായി) നിങ്ങൾ വരവേൽക്കരുത്." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 58, 58, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الشَّهْرُ تِسْعٌ وَعِشْرُونَ، فَلَا تَصُومُوا حَتَّى تَرَوْهُ، وَلَا تُفْطِرُوا حَتَّى تَرَوْهُ، فَإِنْ غُمَّ عَلَيْكُمْ فَاقْدُرُوا لَهُ ثَلَاثِينَ". قَالَ: فَكَانَ ابْنُ عُمَرَ إِذَا كَانَ شَعْبَانُ تِسْعًا وَعِشْرِينَ نُظِرَ لَهُ، فَإِنْ رُئِيَ فَذَاكَ، وَإِنْ لَمْ يُرَ وَلَمْ يَحُلْ دُونَ مَنْظَرِهِ سَحَابٌ وَلَا قَتَرَةٌ أَصْبَحَ مُفْطِرًا فَإِنْ حَالَ دُونَ مَنْظَرِهِ سَحَابٌ أَوْ قَتَرَةٌ أَصْبَحَ صَائِمًا (د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മാസം ഇരുപത്തൊമ്പത്(ദിവസം) ആണ്. അത്(ചന്ദ്രനെ) കാണുന്നതുവരെ നിങ്ങൾ നോമ്പനുഷ്ഠിക്കരുത്. അത് കാണുന്നതുവരെ നിങ്ങൾ നോമ്പുപേക്ഷിക്കുകയുമരുത്. മേഘാവൃതമായാൽ മുപ്പത് ദിവസം നിങ്ങൾ എണ്ണിക്കണക്കാക്കുക." നിവേദകൻ പറയുന്നു: ഇബ്നുഉമർ(റ) ശഅ്ബാൻ ഇരുപത്തൊമ്പതായാൽ മാസം നോക്കാറുണ്ടായിരുന്നു. മാസം കണ്ടാൽ അപ്പോൾ നോമ്പുനോൽക്കും. കാണാതിരുന്നാൽ, പൊടിപടലങ്ങളോ മേഘമോ കാഴ്ചക്ക് മറയിട്ടില്ലെങ്കിൽ, നോമ്പില്ലാത്തവരായിരിക്കും. പൊടിപടലങ്ങളോ മേഘമോ മറയിട്ടാൽ അദ്ദേഹം നോമ്പുകാരനുമായിരിക്കും. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 58, 58, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "إِنَّا أُمَّةٌ أُمِّيَّةٌ لَا نَكْتُبُ وَلَا نَحْسُبُ الشَّهْرُ هَكَذَا وَهَكَذَا، يَعْنِي مَرَّةً تِسْعَةً وَعِشْرِينَ، وَمَرَّةً ثَلَاثِينَ". (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "എഴുതുകയോ കണക്കുകൂട്ടുകയോ ചെയ്യാത്ത നിരക്ഷര സമുദായ മാണ് നാം. മാസം ഇപ്രകാരമാണ്, ഇപ്രകാരവുമാണ്. അതായത് ചില സമയത്ത് ഇരുപത്തി ഒൻപതും ചിലപ്പോൾ മുപ്പതും." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 58, 59, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّا أُمَّةٌ أُمِّيَّةٌ، لَا نَكْتُبُ وَلَا نَحْسُبُ، الشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا" ثَلَاثًا، حَتَّى ذَكَرَ تِسْعًا وَعِشْرِينَ. وَفِي رِوَايَةٍ: وَعَقَدَ الْإِبْهَامَ فِي الثَّالِثَةِ: "وَالشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا". تَمَامَ الثَّلَاثِينَ. وَفِي رِوَايَةٍ: وَنَقَصَ فِي الثَّالِثَةِ إِصْبَعًا مِنْ أَصَابِعِ يَدَيْهِ. (م,ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "നാം നിരക്ഷര സമൂഹമാണ്. എഴുതുകയോ കണക്കുകൂട്ടുകയോ ഇല്ല. മാസം ഇപ്രകാരവും ഇപ്രകാരവും ഇപ്രകാരവുമാകുന്നു." മൂന്ന് പ്രാവശ്യം കാണിച്ചു. ഇരുപത്തൊൻപത് ദിവസത്തെയും പരാമർശിച്ചു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=35), 1, 'وَفِي رِوَايَةٍ: وَعَقَدَ الْإِبْهَامَ فِي الثَّالِثَةِ: "وَالشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا". تَمَامَ الثَّلَاثِينَ.', 'മറ്റൊരു നിവേദനം: മൂന്നാം പ്രാവശ്യം കൈകൊണ്ട് ആംഗ്യം കാണിച്ചപ്പോൾ തള്ളവിരൽ മടക്കിപ്പിടിച്ചു: "മാസം ഇപ്രകാരവും, ഇപ്രകാരവും, ഇപ്രകാരവുമാണ്." മുപ്പത് പൂർത്തിയാക്കി കാണിച്ചു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=35), 2, 'وَفِي رِوَايَةٍ: وَنَقَصَ فِي الثَّالِثَةِ إِصْبَعًا مِنْ أَصَابِعِ يَدَيْهِ. (م,ن)', 'മറ്റൊരു നിവേദനം: മൂന്നാം പ്രാവശ്യത്തെ ആംഗ്യത്തിൽ നബി(സ)യുടെ ഇരുകൈകളിൽ നിന്നുള്ള ഒരു വിരലിനെ ചുരുക്കിപ്പിടിച്ചു. (മു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَتَانِي جِبْرِيلُ عَلَيْهِ السَّلَامُ فَقَالَ: الشَّهْرُ تِسْعٌ وَعِشْرُونَ يَوْمًا". وَفِي رِوَايَةٍ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الشَّهْرُ تِسْعٌ وَعِشْرُونَ يَوْمًا". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ജിബ്രീൽ(അ) എന്റെയടുക്കൽ വന്നുപറഞ്ഞു: മാസം ഇരുപത്തൊൻപത് ദിനങ്ങളാകുന്നു."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=36), 1, 'وَفِي رِوَايَةٍ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الشَّهْرُ تِسْعٌ وَعِشْرُونَ يَوْمًا". (ن)', 'മറ്റൊരു നിവേദനം: നബി(സ) അരുളി: "മാസം ഇരുപത്തിയൊമ്പത് ദിനങ്ങളാകുന്നു." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَمْ مَضَى مِنَ الشَّهْرِ". قَالَ: قُلْنَا: اثْنَانِ وَعِشْرُونَ، وَبَقِيَتْ ثَمَانٍ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الشَّهْرُ هَكَذَا، وَالشَّهْرُ هَكَذَا، وَالشَّهْرُ هَكَذَا". ثَلَاثَ مَرَّاتٍ، وَأَمْسَكَ وَاحِدَةً. (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ചോദിച്ചു: "മാസം എത്രയായി?" ഞങ്ങൾ പറഞ്ഞു: ഇരുപത്തിരണ്ട്, എട്ടുദിവസം ശേഷിക്കുന്നു. അപ്പോൾ അവിടന്ന് "മാസം ഇപ്രകാരമാണ്, മാസം ഇപ്രകാരമാണ്, മാസം ഇപ്രകാരമാണ്." എന്ന് മൂന്ന് തവണ പറയുകയും ഒരു വിരൽ മടക്കിപ്പിടിക്കുകയും ചെയ്തു. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 59, 59, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمْ أَزَلْ حَرِيصًا أَنْ أَسْأَلَ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ عَنِ الْمَرْأَتَيْنِ مِنْ أَزْوَاجِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، اللَّتَيْنِ قَالَ اللَّهُ لَهُمَا: {إِنْ تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا} [التحريم:٤]. وَسَاقَ الْحَدِيثَ.. وَقَالَ فِيهِ: فَاعْتَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نِسَاءَهُ- مِنْ أَجْلِ ذَلِكَ الْحَدِيثِ حِينَ أَفْشَتْهُ حَفْصَةُ إِلَى عَائِشَةَ- تِسْعًا وَعِشْرِينَ لَيْلَةً، قَالَتْ عَائِشَةُ: وَكَانَ قَالَ: "مَا أَنَا بِدَاخِلٍ عَلَيْهِنَّ شَهْرًا". مِنْ شِدَّةِ مَوْجِدَتِهِ عَلَيْهِنَّ حِينَ حَدَّثَهُ اللَّهُ عَزَّ وَجَلَّ حَدِيثَهُنَّ، فَلَمَّا مَضَتْ تِسْعٌ وَعِشْرُونَ لَيْلَةً دَخَلَ عَلَى عَائِشَةَ فَبَدَأَ بِهَا، فَقَالَتْ لَهُ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: إِنَّكَ قَدْ كُنْتَ آلَيْتَ- يَا رَسُولَ اللَّهِ- أَنْ لَا تَدْخُلَ عَلَيْنَا شَهْرًا، وَإِنَّا أَصْبَحْنَا مِنْ تِسْعٍ وَعِشْرِينَ لَيْلَةً، نَعُدُّهَا عَدَدًا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الشَّهْرُ تِسْعٌ وَعِشْرُونَ لَيْلَةً". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ''നിങ്ങൾ രണ്ടുപേരും അല്ലാഹുവിലേക്ക് ഖേദിച്ചു മടങ്ങുകയാണെങ്കിൽ, നിങ്ങളുടെ ഹൃദയങ്ങൾ അതിലേക്ക് ചാഞ്ഞിരിക്കുന്നു.'' (തഹ്രീം:4) എന്ന സൂക്തത്തിൽ അല്ലാഹു പ്രദിപാദിച്ച നബി(സ)യുടെ രണ്ട് ഭാര്യമാരെക്കുറിച്ച് ഉമറുബ്നുൽ ഖത്താബ്(റ)വിനോട് ചോദിച്ചറിയണമെന്ന് എനിക്ക് വല്ലാത്ത ആഗ്രഹമുണ്ടായിരുന്നു. അദ്ദേഹം ഹദീസ് പൂർണമായി ഉദ്ധരിക്കുന്നു... അതിൽ അദ്ദേഹം പറയുന്നു: ഹഫ്സ(റ) ആഇശ(റ)യോട് വിവരമറിയിച്ചതനുസരിച്ച് ഹദീസിലെ പരാമർശവിഷയം കാരണം നബി(സ) ഭാര്യമാരിൽ നിന്ന് ഇരുപത്തൊൻപത് ദിവസം ഒഴിഞ്ഞു നിന്നു. ആഇശ(റ) പറയുന്നു: നബി(സ) "ഒരു മാസം, ഞാനവരുടെ അടുത്ത് പോവില്ലെ"ന്ന് പറഞ്ഞിരുന്നു. അവരെക്കുറിച്ച് അല്ലാഹു തആല പറഞ്ഞറിയിച്ചതുമൂലം അവരോട് ഉണ്ടായ ദേഷ്യം കാരണമായിരുന്നു അത്. ഇപ്രകാരം ഇരുപത്തി ഒൻപത് ദിവസം പിന്നിട്ടപ്പോൾ നബി(സ) ആഇശ(റ)യുടെ അടുത്ത് ചെന്നു. അന്നേരം ആഇശ(റ) നബി(സ)യോട് ചോദിച്ചു: തിരുദൂതരേ, നിങ്ങൾ ഞങ്ങളുമായി ഒരു മാസക്കാലം ബന്ധപ്പെടുകയില്ലെന്ന് സത്യം ചെയ്തിരുന്നില്ലേ? ഇന്നേക്ക് ഇരുപത്തൊൻപത് ദിനങ്ങളേ ആയിട്ടുള്ളൂ. ഞങ്ങളത് എണ്ണിക്കൊണ്ടിരിക്കുകയാണ്. അന്നേരം നബി(സ) പറഞ്ഞു: "മാസം ഇരുപത്തൊൻപത് രാവുകളാണ്." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'التحريم:٤', null, 59, 60, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَا صُمْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِسْعًا وَعِشْرِينَ أَكْثَرَ مِمَّا صُمْنَا مَعَهُ ثَلَاثِينَ. (د,ت)', 'ഇബ്നുമസ്ഊദ്(റ): നബി(സ)യോടു കൂടെ ഞങ്ങൾ മുപ്പതു നോമ്പ് അനുഷ്ഠിച്ചതിനേക്കാൾ കൂടുതൽ ഇരുപത്തിയൊൻപത് നോമ്പ് അനുഷ്ഠിച്ചിട്ടില്ല. (ദ,തു)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 60, 60, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "شَهْرَا عِيدٍ لَا يَنْقُصَانِ، رَمَضَانُ وَذُو الْحِجَّةِ". (ق,د,ت,جه)', 'അബൂബക്റ(റ): നബി(സ) പറഞ്ഞു: "പെരുന്നാളിന്റെ രണ്ടുമാസങ്ങളായ റമളാനും ദുൽഹിജ്ജയും ചുരുങ്ങുകയില്ല." (ബു,മു,ദ,തു,ജ)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 60, 60, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ- ذَكَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِ- قَالَ: "وَفِطْرُكُمْ يَوْمَ تُفْطِرُونَ، وَأَضْحَاكُمْ يَوْمَ تُضَحُّونَ، وَكُلُّ عَرَفَةَ مَوْقِفٌ، وَكُلُّ مِنًى مَنْحَرٌ، وَكُلُّ فِجَاجِ مَكَّةَ مَنْحَرٌ، وَكُلُّ جَمْعٍ مَوْقِفٌ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ഈ വിഷയത്തിൽ പറഞ്ഞു: "നിങ്ങൾ നോമ്പു മുറിക്കുന്ന ദിവസമാണു നിങ്ങളുടെ (ഈദുൽ) ഫിത്വ്ർ. നിങ്ങൾ ബലിയറുക്കുന്ന ദിവസംതന്നെയാണ് നിങ്ങളുടെ ബലി പെരുന്നാൾ. അറഫ മുഴുവൻ നിൽക്കാനുള്ള സ്ഥലമാണ്. മിന മുഴുവൻ ബലിസ്ഥലമാണ്. മക്കയിലെ മലമ്പാതകളെല്ലാം ബലിസ്ഥലമാണ്. ജംഅ്(മുസ്ദലിഫ) മുഴുവൻ ജനങ്ങൾക്ക് നിൽക്കാനുള്ളതാണ്." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 60, 60, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ كُرَيْبٍ: أَنَّ أُمَّ الْفَضْلِ ابْنَةَ الْحَارِثِ بَعَثَتْهُ إِلَى مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ بِالشَّامِ، قَالَ: فَقَدِمْتُ الشَّامَ فَقَضَيْتُ حَاجَتَهَا فَاسْتَهَلَّ رَمَضَانُ وَأَنَا بِالشَّامِ، فَرَأَيْنَا الْهِلَالَ لَيْلَةَ الْجُمُعَةِ، ثُمَّ قَدِمْتُ الْمَدِينَةَ فِي آخِرِ الشَّهْرِ، فَسَأَلَنِي ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، ثُمَّ ذَكَرَ الْهِلَالَ، فَقَالَ: مَتَى رَأَيْتُمُ الْهِلَالَ؟ قُلْتُ: رَأَيْتُهُ لَيْلَةَ الْجُمُعَةِ، قَالَ: أَنْتَ رَأَيْتَهُ؟ قُلْتُ: نَعَمْ، وَرَآهُ النَّاسُ، وَصَامُوا وَصَامَ مُعَاوِيَةُ. قَالَ: لَكِنَّا رَأَيْنَاهُ لَيْلَةَ السَّبْتِ، فَلَا نَزَالُ نَصُومُهُ حَتَّى نُكْمِلَ الثَّلَاثِينَ أَوْ نَرَاهُ. فَقُلْتُ: أَفَلَا تَكْتَفِي بِرُؤْيَةِ مُعَاوِيَةَ وَصِيَامِهِ؟ قَالَ: لَا، هَكَذَا أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م,د,ت,ن)', 'കുറൈബ്(റ): ഹാരിസിന്റെ മകൾ ഉമ്മുൽഫള്ൽ(റ) അദ്ദേഹത്തെ ശാമിലുള്ള മുആവിയ(റ)യുടെ അടുത്തേക്കു പറഞ്ഞയച്ചു. നിവേദകൻ പറയുന്നു: ഞാൻ ശാമിൽ പ്രവേശിച്ചു അവരുടെ ആഗ്രഹം നിർവഹിച്ചു. ഞാൻ ശാമിലായിരിക്കെ അവിടെ റമളാൻ പിറ കണ്ടു. ഞങ്ങൾ വെള്ളിയാഴ്ച രാത്രിയാണു മാസപ്പിറവി ദർശിച്ചത്. മാസാവസാനം ഞാൻ മദീനയിലേക്കു വന്നു. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) എന്നോടു കുശലാന്വേഷണങ്ങൾ നടത്തവെ മാസപ്പിറവിയെക്കുറിച്ച് പരാമർശിച്ചു. അദ്ദേഹം ചോദിച്ചു: നിങ്ങൾ എപ്പോഴാണ് മാസപ്പിറവി കണ്ടത്. ഞാൻ പറഞ്ഞു: വെള്ളിയാഴ്ച രാത്രിയിലാണത് കണ്ടത്. അദ്ദേഹം ചോദിച്ചു: താങ്കൾ തന്നെയാണോ അതു കണ്ടത്? ഞാൻ പറഞ്ഞു: അതേ, ജനങ്ങളും അത് കണ്ടിട്ടുണ്ട്. അവരും മുആവിയ(റ)യും നോമ്പെടുക്കുകയും ചെയ്തു. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: എന്നാൽ ഞങ്ങൾ കണ്ടതു ശനിയാഴ്ച രാത്രിയിലായിരുന്നു. അപ്പോൾ ഞങ്ങൾ മാസം കാണുംവരെയോ മുപ്പതു പൂർത്തിയാക്കുംവരെയോ നോമ്പെടുക്കും. അപ്പോൾ ഞാൻ ചോദിച്ചു: മുആവിയ(റ)യുടെ ദർശനവും നോമ്പും താങ്കൾക്ക് മതിയാവുകയില്ലേ? അദ്ദേഹം പറഞ്ഞു: ഇല്ല. ഇങ്ങനെയാണ് റസൂൽ(സ) നമ്മോട് കൽപിച്ചിരിക്കുന്നത്. (മു,ദ,തു,ന)', 'كُرَيْبٍ', 'കുറൈബ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 60, 61, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنِ الْحَسَنِ رَضِيَ اللَّهُ عَنْهُ – فِي رَجُلٍ كَانَ بِمِصْرٍ مِنَ الْأَمْصَارِ فَصَامَ يَوْمَ الِاثْنَيْنِ، وَشَهِدَ رَجُلَانِ أَنَّهُمَا رَأَيَا الْهِلَالَ لَيْلَةَ الْأَحَدِ– فَقَالَ: لَا يَقْضِي ذَلِكَ الْيَوْمَ الرَّجُلُ وَلَا أَهْلُ مِصْرِهِ، إِلَّا أَنْ يَعْلَمُوا أَنَّ أَهْلَ مِصْرٍ مِنْ أَمْصَارِ الْمُسْلِمِينَ قَدْ صَامُوا يَوْمَ الْأَحَدِ، فَيَقْضُونَهُ. (د)', 'ഹസൻ(റ): ഞായറാഴ്ച രാവിൽ മാസപ്പിറവി ദർശിച്ചതായി രണ്ടാളുകൾ സാക്ഷി പറഞ്ഞിരിക്കെ തിങ്കളാഴ്ച നോമ്പെടുത്ത ആ നഗരത്തിലുണ്ടായിരുന്ന ഒരാളെക്കുറിച്ച് പറയുന്നു: മുസ്‌ലിം പട്ടണനിവാസികൾ ഞായറാഴ്ച നോമ്പെടുത്തതായി അവർ അറിഞ്ഞാലല്ലാതെ അയാളോ തന്റെ പട്ടണനിവാസികളോ നോമ്പ് വീണ്ടെടുക്കേണ്ടതില്ല. അവരതറിഞ്ഞാൽ വീണ്ടെടുക്കുകയും വേണം. (ദ)', 'الْحَسَنِ', 'ഹസൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 61, 61, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عِكْرِمَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُمْ شَكُّوا فِي هِلَالِ رَمَضَانَ مَرَّةً، فَأَرَادُوا أَنْ لَا يَقُومُوا وَلَا يَصُومُوا، فَجَاءَ أَعْرَابِيٌّ مِنَ الْحَرَّةِ فَشَهِدَ أَنَّهُ رَأَى الْهِلَالَ، فَأُتِيَ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "أَتَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنِّي رَسُولُ اللَّهِ". قَالَ: نَعَمْ، وَشَهِدَ أَنَّهُ رَأَى الْهِلَالَ، فَأَمَرَ بِلَالًا فَنَادَى فِي النَّاسِ أَنْ يَقُومُوا وَأَنْ يَصُومُوا. (د,ت,ن,جه)', 'ഇക്‌രിമ(റ): ഒരിക്കൽ റമളാൻ മാസപ്പിറവിയിൽ അവർ സംശയിച്ചു. അങ്ങനെ വ്രതവും തറാവീഹും ഉപേക്ഷിക്കാൻ അവരുദ്ദേശിച്ചു. അപ്പോൾ കൽപ്രദേശവാസിയായ ഒരു ഗ്രാമീണൻ വന്നു ചന്ദ്രപ്പിറവി ദർശിച്ചതായി സാക്ഷിനിന്നു. തുടർന്ന് അദ്ദേഹത്തെ നബി(സ)യുടെ അടുക്കൽ കൊണ്ടുവന്നു. നബി(സ) അദ്ദേഹത്തോടു ചോദിച്ചു: "ഞാൻ അല്ലാഹുവിന്റെ ദൂതരാണെന്നും, അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും താങ്കൾ സാക്ഷ്യം വഹിക്കുന്നുവോ?" അദ്ദേഹം മറുപടി പറഞ്ഞു: അതെ. അയാൾ ചന്ദ്രപ്പിറവി ദർശിച്ചെന്ന് സാക്ഷിനിൽക്കുകയും ചെയ്തു. അപ്പോൾ നബി(സ) ജനങ്ങളോടു നോമ്പെടുക്കാനും തറാവീഹ് നിസ്കരിക്കാനും വിളിച്ചുപറയാൻ ബിലാൽ(റ)വിനോട് കൽപിച്ചു. (ദ,തു,ന,ജ)', 'عِكْرِمَةَ', 'ഇക്‌രിമ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 61, 61, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: تَرَاءَى النَّاسُ الْهِلَالَ، فَأَخْبَرْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنِّي رَأَيْتُهُ، فَصَامَهُ وَأَمَرَ النَّاسَ بِصِيَامِهِ. (د)', 'ഇബ്നുഉമർ(റ): ജനങ്ങൾ ചന്ദ്രപ്പിറവി കണ്ടു. അപ്പോൾ ഞാൻ ചന്ദ്രനെ കണ്ടിരിക്കുന്നുവെന്ന് നബി(സ)യെ വിവരമറിയിച്ചു. തുടർന്ന് നബി(സ) വ്രതമെടുക്കുകയും ജനങ്ങളോട് വ്രതമെടുക്കാൻ കൽപ്പിക്കുകയും ചെയ്തു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 61, 62, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَبِي مَالِكٍ الْأَشْجَعِيِّ: حَدَّثَنَا حُسَيْنُ بْنُ الْحَارِثِ الْجَدَلِيُّ: أَنَّ أَمِيرَ مَكَّةَ خَطَبَ ثُمَّ قَالَ: عَهِدَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نَنْسُكَ لِلرُّؤْيَةِ، فَإِنْ لَمْ نَرَهُ وَشَهِدَ شَاهِدَا عَدْلٍ نَسَكْنَا بِشَهَادَتِهِمَا. فَسَأَلْتُ الْحُسَيْنَ بْنَ الْحَارِثِ: مَنْ أَمِيرُ مَكَّةَ؟ قَالَ: لَا أَدْرِي، ثُمَّ لَقِيَنِي بَعْدُ فَقَالَ: هُوَ الْحَارِثُ بْنُ حَاطِبٍ أَخُو مُحَمَّدِ بْنِ حَاطِبٍ. ثُمَّ قَالَ الْأَمِيرُ: إِنَّ فِيكُمْ مَنْ هُوَ أَعْلَمُ بِاللَّهِ وَرَسُولِهِ مِنِّي، وَشَهِدَ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَوْمَأَ بِيَدِهِ إِلَى رَجُلٍ. قَالَ الْحُسَيْنُ: فَقُلْتُ لِشَيْخٍ إِلَى جَنْبِي: مَنْ هَذَا الَّذِي أَوْمَأَ إِلَيْهِ الْأَمِيرُ؟ قَالَ: هَذَا عَبْدُ اللَّهِ بْنُ عُمَرَ، وَصَدَقَ، كَانَ أَعْلَمَ بِاللَّهِ مِنْهُ، فَقَالَ: بِذَلِكَ أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د)', 'അബൂമാലികുൽ അശ്ജഈ(റ): ഹാരിസുൽ ജദ്‌ലിയുടെ മകനായ ഹുസൈൻ(റ) ഞങ്ങൾക്കൊരു സംഭവം വിവരിച്ചു തന്നു: മക്കയുടെ അമീർ ജനങ്ങളെ അഭിസംബോധന ചെയ്തു പറഞ്ഞു: മാസപ്പിറവി കണ്ടാൽ നോമ്പനുഷ്ഠിക്കാൻ റസൂൽ(സ) നമ്മോട് കരാർ ചെയ്തിട്ടുണ്ട്. നമ്മൾ മാസപ്പിറവി ദർശിച്ചില്ലെങ്കിൽ നീതിമാന്മാരായ രണ്ടാളുകൾ മാസപ്പിറവി ദർശിച്ചതായി സാക്ഷിനിന്നാൽ അതുമുഖേന നാം നോമ്പനുഷ്ഠിക്കും. അപ്പോൾ ഞാൻ ഹുസൈനുബ്നു ഹാരിസിനോട് ചോദിച്ചു: ആരാണ് മക്കയുടെ അമീർ? അദ്ദേഹം പറഞ്ഞു: എനിക്കറിയില്ല. പിന്നീട് കാലങ്ങൾക്ക് ശേഷം എന്നെ കണ്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അത് (മക്കയിലെ അമീർ) മുഹമ്മദുബ്നു ഹാത്വിബിന്റെ സഹോദരനായ ഹാരിസുബ്നു ഹാത്വിബ് ആയിരുന്നു. തുടർന്ന് അമീർ (പ്രഭാഷണത്തിൽ) പറഞ്ഞു: നിശ്ചയം നിങ്ങളിൽ എന്നേക്കാൾ കൂടുതൽ അല്ലാഹുവിനെയും അവന്റെ പ്രവാചകനേയും അറിയുന്ന ഒരാളുണ്ട്. അദ്ദേഹം പ്രവാചകരിൽ നിന്ന് ഇതിന് സാക്ഷിയായിട്ടുണ്ട്. അമീർ ഒരാളുടെ നേരെ കൈ ചൂണ്ടി. ഹുസൈൻ പറയുന്നു: അപ്പോൾ ഞാൻ എന്റെ അരികിലുണ്ടായിരുന്ന വൃദ്ധനോട് ചോദിച്ചു: അമീർ കൈ ചൂണ്ടിയ ആൾ ആരാണ്? അദ്ദേഹം പറഞ്ഞു: അത് അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) ആണ്. അമീർ പറഞ്ഞത് സത്യമാണ്. ഇബ്നുഉമർ(റ) അമീറിനേക്കാൾ അല്ലാഹുവിനെക്കുറിച്ച് അറിയുന്നവരാണ്. അപ്പോൾ ഇബ്നുഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരം ചെയ്യാനാണ് നമ്മോട് കൽപിച്ചത്. (ദ)', 'أَبِي مَالِكٍ الْأَشْجَعِيِّ', 'അബൂമാലികുൽ അശ്ജഈ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 62, 62, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ رِبْعِيِّ بْنِ حِرَاشٍ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اخْتَلَفَ النَّاسُ فِي آخِرِ يَوْمٍ مِنْ رَمَضَانَ، فَقَدِمَ أَعْرَابِيَّانِ فَشَهِدَا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّهِ لَأَهَلَّا الْهِلَالَ أَمْسِ عَشِيَّةً، فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّاسَ أَنْ يُفْطِرُوا، وَأَنْ يَغْدُوا إِلَى مُصَلَّاهُمْ. (د)', 'രിബ്ഇയ്യുബ്നു ഹിറാശ്(റ) റസൂൽ(സ)യുടെ അനുചരരിൽ പെട്ട ഒരാളിൽനിന്ന്: റമളാൻ മാസത്തിലെ അവസാനദിനത്തിൽ ജനങ്ങൾ ഭിന്നാഭിപ്രായക്കാരായി. അപ്പോൾ ഗ്രാമീണവാസികളായ രണ്ട് അറബികൾ നബിയുടെ അടുക്കൽ വന്ന് തലേദിവസം വൈകി മാസപ്പിറവി ദർശിച്ചതായി അല്ലാഹുവിന്റെ പേരിൽ സത്യം ചെയ്ത് സാക്ഷിനിന്നു. ഉടനെ റസൂൽ(സ) ജനങ്ങളോട് അവരുടെ നോമ്പ് ഉപേക്ഷിക്കുവാനും പ്രഭാതത്തിൽ (പെരുന്നാൾ) നിസ്കാരസ്ഥലത്തേക്ക് പോകുവാനും കല്പിച്ചു. (ദ)', 'رِبْعِيِّ بْنِ حِرَاشٍ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ', 'രിബ്ഇയ്യുബ്നു ഹിറാശ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 62, 62, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ الْخَطَّابِ: أَنَّهُ خَطَبَ النَّاسَ فِي الْيَوْمِ الَّذِي يُشَكُّ فِيهِ، فَقَالَ: أَلَا، إِنِّي جَالَسْتُ أَصْحَابَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَاءَلْتُهُمْ، وَإِنَّهُمْ حَدَّثُونِي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ، وَانْسُكُوا لَهَا، فَإِنْ غُمَّ عَلَيْكُمْ فَأَكْمِلُوا ثَلَاثِينَ، فَإِنْ شَهِدَ شَاهِدَانِ فَصُومُوا وَأَفْطِرُوا". (ن)', 'അബ്ദുർറഹ്മാനുബ്നു സൈദുബ്നുൽ ഖത്താബ്(റ): (നോമ്പാണോ അല്ലയോ എന്ന്) സംശയിക്കപ്പെട്ട ഒരു ദിനത്തിൽ അദ്ദേഹം ജനങ്ങളോട് പ്രസംഗിച്ചു. (പ്രസംഗത്തിൽ) അദ്ദേഹം പറഞ്ഞു: അറിയുക! ഞാൻ പ്രവാചകരുടെ സ്വഹാബതിന്റെ കൂടെ ഇരിക്കുകയും അവരോടു ചോദിക്കുകയും ചെയ്തിട്ടുണ്ട്. അവർ എന്നോടൊരു ഹദീസ് പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "മാസപ്പിറവി ദർശനത്താൽ നിങ്ങൾ വ്രതമനുഷ്ഠിക്കുകയും മാസപ്പിറവി കണ്ടാൽ നിങ്ങൾ നോമ്പുപേക്ഷിക്കുകയും ചെയ്യുക. മാസപ്പിറവി കണ്ടാൽ നിങ്ങൾ നോമ്പെടുക്കുക. മേഘം മറയിട്ടതിനാൽ മാസപ്പിറവി ദൃശ്യമാവാതെ വന്നാൽ മുപ്പത് ദിവസം നിങ്ങൾ പൂർണ്ണമാക്കുക. രണ്ടുപേർ സാക്ഷിനിന്നാൽ നിങ്ങൾ നോമ്പെടുക്കുകയും ഉപേക്ഷിക്കുകയും ചെയ്യുക." (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ الْخَطَّابِ', 'അബ്ദുർറഹ്മാനുബ്നു സൈദുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 62, 63, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَبِي عُمَيْرِ بْنِ أَنَسِ بْنِ مَالِكٍ قَالَ: حَدَّثَنِي عُمُومَتِي مِنَ الْأَنْصَارِ– مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ– قَالُوا أُغْمِيَ عَلَيْنَا هِلَالُ شَوَّالٍ، فَأَصْبَحْنَا صِيَامًا، فَجَاءَ رَكْبٌ مِنْ آخِرِ النَّهَارِ فَشَهِدُوا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُمْ رَأَوُا الْهِلَالَ بِالْأَمْسِ. فَأَمَرَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُفْطِرُوا، وَأَنْ يَخْرُجُوا إِلَى عِيدِهِمْ مِنَ الْغَدِ. (د,ن,جه)', 'അബൂ ഉമൈറുബ്നു അനസുബ്നു മാലിക്(റ): പ്രവാചകരുടെ സ്വഹാബിമാരിൽപ്പെട്ട അൻസ്വാരികളായ പിതൃസഹോദരിമാർ എന്നോട് പറഞ്ഞു: ഒരിക്കൽ മേഘപടലം കാരണം ശവ്വാൽപിറവി ഞങ്ങൾക്കു കാണാൻ സാധിക്കാതെ വന്നു. പിറ്റേദിനം ഞങ്ങൾ നോമ്പനുഷ്ഠിച്ചു. വൈകുന്നേരസമയത്ത് ഒരു യാത്രാസംഘം നബി(സ)യുടെ അടുക്കൽവന്ന് തലേന്ന് അവർ ചന്ദ്രനെ കണ്ടതായി സാക്ഷിനിന്നു. അപ്പോൾ നബി(സ) അവരോട് നോമ്പ് ഉപേക്ഷിക്കാനും അടുത്ത ദിവസം ''ഈദ്'' ആഘോഷിക്കാനും കൽപിച്ചു. (ദ,ന,ജ)', 'أَبِي عُمَيْرِ بْنِ أَنَسِ بْنِ مَالِكٍ قَالَ', 'അബൂ ഉമൈറുബ്നു അനസുബ്നു മാലിക്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 63, 63, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ صِلَةَ بْنِ زُفَرَ الْعَبْسِيِّ قَالَ: كُنَّا عِنْدَ عَمَّارٍ رَضِيَ اللَّهُ عَنْهُ فَأُتِيَ بِشَاةٍ مَصْلِيَّةٍ، فَقَالَ: كُلُوا. فَتَنَحَّى بَعْضُ الْقَوْمِ قَالَ: إِنِّي صَائِمٌ. فَقَالَ عَمَّارٌ: مَنْ صَامَ الْيَوْمَ الَّذِي يُشَكُّ فِيهِ فَقَدْ عَصَى أَبَا الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ,د,ت,ن)', 'സ്വിലതുബ്നു സുഫറുൽ അബസീ(റ): ഞങ്ങൾ അമ്മാർ(റ)വിന്റെ സമീപത്തായിരിക്കെ വേവിച്ച ഒരാട് കൊണ്ടുവരപ്പെട്ടു. അപ്പോൾ അമ്മാർ(റ) പറഞ്ഞു: നിങ്ങൾ ഭക്ഷിച്ചോളൂ. അന്നേരം, ഒരാൾ നീങ്ങിയിരിക്കുകയും ഞാൻ നോമ്പുകാരനാണെന്ന് പറയുകയും ചെയ്തു. അമ്മാർ(റ) പറഞ്ഞു: (നോമ്പാണോ അല്ലയോ എന്ന്) സംശയാസ്പദമായ ദിവസം നോമ്പനുഷ്ഠിച്ചവൻ അബുൽഖാസിം(സ)യോട് എതിർപ്രവർത്തിച്ചിരിക്കുന്നു. (ബു,ദ,തു,ന)', 'صِلَةَ بْنِ زُفَرَ الْعَبْسِيِّ قَالَ', 'സ്വിലതുബ്നു സുഫറുൽ അബസീ(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 63, 63, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقَدَّمُوا الشَّهْرَ بِصِيَامِ يَوْمٍ أَوْ يَوْمَيْنِ، إِلَّا أَنْ يُوَافِقَ ذَلِكَ يَوْمًا كَانَ يَصُومُهُ أَحَدُكُمْ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ (സ) പറഞ്ഞു: "റമളാനിന് മുമ്പ് ഒന്നോ രണ്ടോ ദിവസം നിങ്ങൾ നോമ്പുമായി മുന്നിടരുത്, നിങ്ങളിലൊരാൾ അന്നേ ദിവസത്തോട് യോജിച്ച് മറ്റുനോമ്പുകൾ നോൽക്കുന്നെങ്കിലൊഴികെ." (ന)', 'ابْنِ عَبَّاسٍ قَالَ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 63, 63, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ عَلَى الْمِنْبَرِ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عَلَى الْمِنْبَرِ، قَبْلَ شَهْرِ رَمَضَانَ: "الصِّيَامُ يَوْمَ كَذَا وَكَذَا، وَنَحْنُ مُتَقَدِّمُونَ، فَمَنْ شَاءَ فَلْيَتَقَدَّمْ وَمَنْ شَاءَ فَلْيَتَأَخَّرْ". (جه)', 'മുആവിയതുബ്നു അബീസുഫ്‌യാൻ(റ): അദ്ദേഹം മിമ്പറിൽ വെച്ച് പറഞ്ഞു: നബി(സ) റമളാൻ മാസത്തിനുമുമ്പു മിമ്പറിൽവെച്ച് പറയാറുണ്ടായിരുന്നു: "ഇത്ര ദിവസങ്ങളാണ് നോമ്പ്. നാം നോമ്പിലേക്കു മുന്നിട്ടുകൊണ്ടിരിക്കുന്നവരാണ്. മുന്നിടീക്കാൻ ആഗ്രഹിക്കുന്നവർ അങ്ങനെയും പിന്തിക്കാൻ ആഗ്രഹിക്കുന്നവർ അങ്ങനെയും ചെയ്യട്ടെ." (ജ)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ', 'മുആവിയതുബ്നു അബീസുഫ്‌യാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 63, 64, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَقُولَنَّ أَحَدُكُمْ: صُمْتُ رَمَضَانَ، وَلَا قُمْتُهُ كُلَّهُ". وَلَا أَدْرِي: أَكَرِهَ التَّزْكِيَةَ، أَوْ قَالَ: "لَا بُدَّ مِنْ غَفْلَةٍ، وَرَقْدَةٍ". (ن)', 'അബൂബക്റ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ആരുംതന്നെ, ഞാൻ റമളാൻ മുഴുവൻ നോമ്പെടുത്തെന്നോ റമളാൻ മുഴുവൻ നിസ്കരിച്ചെന്നോ പറയരുത്." നിവേദകൻ പറയുന്നു: അവിടന്ന് ആത്മപ്രശംസയെ വെറുത്തോ എന്ന് എനിക്കറിയില്ല. അല്ലെങ്കിൽ അവിടന്ന് പറഞ്ഞു: "അശ്രദ്ധയും ഉറക്കുമെല്ലാം ആവശ്യംതന്നെയാണ്." (ന)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 64, 64, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَقُولَنَّ أَحَدُكُمْ إِنِّي صُمْتُ رَمَضَانَ كُلَّهُ، وَقُمْتُهُ كُلَّهُ". فَلَا أَدْرِي أَكَرِهَ التَّزْكِيَةَ؟ أَوْ قَالَ: لَا بُدَّ مِنْ نَوْمَةٍ أَوْ رَقْدَةٍ. (د,ن)', 'അബൂബക്റ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ആരുംതന്നെ, ഞാൻ റമളാൻ മുഴുവൻ നോമ്പെടുത്തെന്നോ റമളാൻ മുഴുവൻ നിസ്കരിച്ചെന്നോ പറയരുത്." നിവേദകൻ പറയുന്നു: അവിടന്ന് ആത്മപ്രശംസയെ വെറുത്തോ എന്ന് എനിക്കറിയില്ല. അല്ലെങ്കിൽ നിവേദകൻ പറഞ്ഞു: ഉറക്കം ആവശ്യംതന്നെയാണ്. (ദ,ന)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 64, 64, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ حَفْصَةَ رَضِيَ اللَّهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ لَمْ يُبَيِّتِ الصِّيَامَ قَبْلَ الْفَجْرِ–وَفِي رِوَايَةٍ: مِنَ اللَّيْلِ– فَلَا صِيَامَ لَهُ". وَفِي رِوَايَةٍ: "مَنْ لَمْ يُجْمِعِ الصِّيَامَ قَبْلَ طُلُوعِ الْفَجْرِ فَلَا يَصُومُ". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) ഹഫ്സ(റ)യിൽ നിന്നും നിവേദനം: നബി(സ) അരുളി: "രാത്രിയുടെ പ്രഭാതത്തിന് (ഫജ്റ്) മുമ്പ് നോമ്പിനെക്കുറിച്ചു മനസ്സിൽ കരുതാത്തവനു നോമ്പില്ല.". മറ്റൊരു നിവേദനം: "പ്രഭാതത്തിനു (ഫജ്റ്) മുമ്പ് നോമ്പിനെ കരുതാത്തവൻ നോമ്പ് അനുഷ്ഠിക്കുന്നില്ല.". (ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 64, 64, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=55), 1, 'وَفِي رِوَايَةٍ: مِنَ اللَّيْلِ– فَلَا صِيَامَ لَهُ".', 'മറ്റൊരു നിവേദനം: "പ്രഭാതത്തിനു (ഫജ്റ്) മുമ്പ് നോമ്പിനെ കരുതാത്തവൻ നോമ്പ് അനുഷ്ഠിക്കുന്നില്ല.". (ദ,തു,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=55), 2, 'وَفِي رِوَايَةٍ: "مَنْ لَمْ يُجْمِعِ الصِّيَامَ قَبْلَ طُلُوعِ الْفَجْرِ فَلَا يَصُومُ". (د,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنِ ابْنِ عُمَرَ، عَنْ حَفْصَةَ– رَضِيَ اللَّهُ عَنْهُمْ– قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا صِيَامَ لِمَنْ لَمْ يَفْرِضْهُ مِنَ اللَّيْلِ". (د,ت,ن,جه)', 'ഹഫ്സ(റ)യിൽനിന്ന് ഇബ്നുഉമർ(റ): മഹതി പറഞ്ഞു: റസൂൽ(സ) അരുളി: "ഫർള് നോമ്പിനെ രാത്രിയിൽ കരുതാത്തവനു നോമ്പില്ല." (ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ، عَنْ حَفْصَةَ–', 'ഹഫ്സ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 64, 64, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ رَجُلًا يُنَادِي فِي النَّاسِ يَوْمَ عَاشُورَاءَ: إِنَّ مَنْ أَكَلَ فَلْيُتِمَّ أَوْ فَلْيَصُمْ، وَمَنْ لَمْ يَأْكُلْ فَلَا يَأْكُلْ. (خ)', 'സലമതുബ്നു അക്‌വഅ്(റ): നബി(സ) ആശുറാഅ് (മുഹറം 10) ദിനത്തിൽ "ഭക്ഷണം കഴിച്ചവർ അതു പൂർത്തീകരിക്കട്ടെ, അല്ലെങ്കിൽ നോമ്പനുഷ്ഠിക്കട്ടെ. ഭക്ഷണം കഴിക്കാത്തവർ കഴിക്കാതിരിക്കുകയും ചെയ്യട്ടെ" എന്ന് ജനങ്ങളോട് വിളിച്ചുപറയാൻ ഒരാളെ അയച്ചു. (ബു)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നു അക്‌വഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 65, 65, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ سَلَمَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِرَجُلٍ: "أَذِّنْ يَوْمَ عَاشُورَاءَ: مَنْ كَانَ أَكَلَ فَلْيُتِمَّ بَقِيَّةَ يَوْمِهِ، وَمَنْ لَمْ يَكُنْ أَكَلَ فَلْيَصُمْ". (ن)', 'സലമ(റ): റസൂൽ(സ) ഒരാളോട് ഇപ്രകാരം പറഞ്ഞു: "ആശൂറാഅ് ദിവസം നീ ഇപ്രകാരം വിളിച്ചുപറയൂ: വല്ലവരും ഭക്ഷണം കഴിച്ചെങ്കിൽ ദിവസത്തിൽ ബാക്കിഭാഗം അവൻ പൂർത്തീകരിക്കട്ടെ. ഭക്ഷണം കഴിക്കാത്തവൻ നോമ്പനുഷ്ഠിച്ചുകൊള്ളട്ടെ." (ന)', 'سَلَمَةَ', 'സലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 65, 65, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ أُمِّ هَانِئٍ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمَّا كَانَ يَوْمُ الْفَتْحِ– فَتْحِ مَكَّةَ– جَاءَتْ فَاطِمَةُ فَجَلَسَتْ عَنْ يَسَارِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأُمُّ هَانِئٍ عَنْ يَمِينِهِ، قَالَتْ: فَجَاءَتِ الْوَلِيدَةُ بِإِنَاءٍ فِيهِ شَرَابٌ فَنَاوَلَتْهُ، فَشَرِبَ مِنْهُ، ثُمَّ نَاوَلَهُ أُمَّ هَانِئٍ، فَشَرِبَتْ مِنْهُ، قَالَتْ: يَا رَسُولَ اللَّهِ، لَقَدْ أَفْطَرْتُ وَكُنْتُ صَائِمَةً؟ فَقَالَ لَهَا: "أَكُنْتِ تَقْضِينَ شَيْئًا". قَالَتْ: لَا، قَالَ: "فَلَا يَضُرُّكِ إِنْ كَانَ تَطَوُّعًا". (د,ت)', 'ഉമ്മുഹാനിഅ്(റ): ഫത്ഹു മക്കാദിനത്തിൽ ഫാത്വിമ(റ) വന്ന് നബി(സ)യുടെ ഇടഭാഗത്തും ഉമ്മു ഹാനിഅ്(റ) വലഭാഗത്തും ഇരുന്നു. ഉമ്മുഹാനിഅ്(റ) പറഞ്ഞു: അപ്പോൾ വലീദത് ഒരു പാത്രത്തിൽ പാനീയവുമായി വന്ന് നബി(സ)യ്ക്ക് കൊടുത്തു. നബി(സ) അതിൽനിന്ന് കുടിച്ചു. പിന്നീട് അത് ഉമ്മുഹാനിഅ്(റ)ന് കൊടുത്തു, അവരും അതിൽനിന്ന് കുടിച്ചു. ശേഷം ഉമ്മുഹാനിഅ്(റ) പറഞ്ഞു: പ്രവാചകരേ, ഞാൻ നോമ്പുകാരിയായിരുന്നു. ഇപ്പോൾ ഞാൻ നോമ്പ് മുറിച്ചിരിക്കുന്നു. അപ്പോൾ നബി(സ) അവളോട് ചോദിച്ചു: "നീ വല്ലതിനേയും ''ഖളാഅ്'' വീട്ടുന്നവളായിരുന്നോ?" അവർ മറുപടി നൽകി: അല്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "സുന്നത് നോമ്പാണെങ്കിൽ നിന്നെ അത് ബുദ്ധിമുട്ടാക്കില്ല." (ദ,തു)', 'أُمِّ هَانِئٍ', 'ഉമ്മുഹാനിഅ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 65, 65, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا فَقَالَ: "هَلْ عِنْدَكُمْ شَيْءٌ". فَقُلْتُ: لَا. قَالَ: "فَإِنِّي صَائِمٌ". ثُمَّ مَرَّ بِي بَعْدَ ذَلِكَ الْيَوْمِ وَقَدْ أُهْدِيَ إِلَيَّ حَيْسٌ، فَخَبَأْتُ لَهُ مِنْهُ، وَكَانَ يُحِبُّ الْحَيْسَ، قَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّهُ أُهْدِيَ لَنَا حَيْسٌ فَخَبَأْتُ لَكَ مِنْهُ؟ قَالَ: "أَدْنِيهِ، أَمَا إِنِّي قَدْ أَصْبَحْتُ وَأَنَا صَائِمٌ". فَأَكَلَ مِنْهُ، ثُمَّ قَالَ: "إِنَّمَا مَثَلُ صَوْمِ الْمُتَطَوِّعِ مَثَلُ الرَّجُلِ يُخْرِجُ مِنْ مَالِهِ الصَّدَقَةَ، فَإِنْ شَاءَ أَمْضَاهَا وَإِنْ شَاءَ حَبَسَهَا". وَفِي رِوَايَةٍ قَالَتْ: دَارَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَوْرَةً، قَالَ: "أَعِنْدَكِ شَيْءٌ". قَالَتْ: لَيْسَ عِنْدِي شَيْءٌ. قَالَ: "فَأَنَا صَائِمٌ". قَالَتْ: ثُمَّ دَارَ عَلَيَّ الثَّانِيَةَ وَقَدْ أُهْدِيَ لَنَا حَيْسٌ فَجِئْتُ بِهِ فَأَكَلَ، فَعَجِبْتُ مِنْهُ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، دَخَلْتَ عَلَيَّ وَأَنْتَ صَائِمٌ، ثُمَّ أَكَلْتَ حَيْسًا؟ قَالَ: "نَعَمْ يَا عَائِشَةُ، إِنَّمَا مَنْزِلَةُ مَنْ صَامَ فِي غَيْرِ رَمَضَانَ– أَوْ: غَيْرِ قَضَاءِ رَمَضَانَ، أَوْ: فِي التَّطَوُّعِ– بِمَنْزِلَةِ رَجُلٍ أَخْرَجَ صَدَقَةَ مَالِهِ، فَجَادَ مِنْهَا بِمَا شَاءَ فَأَمْضَاهُ، وَبَخِلَ مِنْهَا بِمَا بَقِيَ فَأَمْسَكَهُ". (م,د,ت,ن,جه)', 'ആഇശ(റ): ഒരു ദിവസം എന്റെയടുക്കൽ വന്നു റസൂൽ(സ) ചോദിച്ചു. "നിങ്ങളുടെയടുക്കൽ വല്ലതുമുണ്ടോ?" ഇല്ലെന്ന് ഞാൻ പറഞ്ഞു: "എങ്കിൽ ഞാനിന്ന് വ്രതമനുഷ്ഠിക്കുകയാണ്." അവിടന്നരുളി. പിന്നീടൊരുദിനം അവിടന്ന് എന്റെയരികെ നടന്നു. പാരിതോഷികമായി കിട്ടിയ ''ഹൈസ്'' എന്ന പലഹാരം എന്റെ അടുത്തുണ്ടായിരുന്നു. അവിടത്തേക്കതിഷ്ടമായതിനാൽ ഞാനത് കരുതിവെച്ചിരുന്നു. ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, പാരിതോഷികമായി നമുക്ക് ലഭിച്ച ഹൈസ് പലഹാരം അങ്ങേയ്ക്കുവേണ്ടി ഞാൻ കരുതിവെച്ചിരിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "എന്നാൽ കൊണ്ടുവരൂ. പ്രഭാതത്തിൽ ഞാനൊരു നോമ്പുകാരനായിരുന്നു." റസൂൽ(സ) അതിൽനിന്ന് ഭക്ഷിച്ചു. ശേഷം പറഞ്ഞു: "സുന്നത് നോമ്പനുഷ്ഠിക്കുന്നവൻ ദാനം ചെയ്യുന്നവനെപ്പോലെയാണ്. വേണമെങ്കിൽ കൊടുക്കാം. അല്ലെങ്കിൽ തടഞ്ഞുവെക്കാം."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=60), 1, 'وَفِي رِوَايَةٍ قَالَتْ: دَارَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَوْرَةً، قَالَ: "أَعِنْدَكِ شَيْءٌ". قَالَتْ: لَيْسَ عِنْدِي شَيْءٌ. قَالَ: "فَأَنَا صَائِمٌ". قَالَتْ: ثُمَّ دَارَ عَلَيَّ الثَّانِيَةَ وَقَدْ أُهْدِيَ لَنَا حَيْسٌ فَجِئْتُ بِهِ فَأَكَلَ، فَعَجِبْتُ مِنْهُ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، دَخَلْتَ عَلَيَّ وَأَنْتَ صَائِمٌ، ثُمَّ أَكَلْتَ حَيْسًا؟ قَالَ: "نَعَمْ يَا عَائِشَةُ، إِنَّمَا مَنْزِلَةُ مَنْ صَامَ فِي غَيْرِ رَمَضَانَ– أَوْ: غَيْرِ قَضَاءِ رَمَضَانَ، أَوْ: فِي التَّطَوُّعِ– بِمَنْزِلَةِ رَجُلٍ أَخْرَجَ صَدَقَةَ مَالِهِ، فَجَادَ مِنْهَا بِمَا شَاءَ فَأَمْضَاهُ، وَبَخِلَ مِنْهَا بِمَا بَقِيَ فَأَمْسَكَهُ". (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: ആഇശ(റ) പറഞ്ഞു: ഒരു ദിവസം എന്റെയടുക്കൽ വന്ന് നബി(സ) ചോദിച്ചു. "നിങ്ങളുടെയടുക്കൽ വല്ലതുമുണ്ടോ?" എന്റെയടുക്കൽ ഒന്നുമില്ലെന്ന് മഹതി പറഞ്ഞു: "എങ്കിൽ ഞാനിന്ന് നോമ്പുകാരനാ"ണെന്ന് നബി(സ) പറഞ്ഞു. രണ്ടാമതായി ഒരു ദിവസം വന്നു. അന്ന് ഒരു പലഹാരം ദാനമായി ലഭിച്ചിരുന്നു. ഞാൻ അത് കൊണ്ടുവന്നു. അപ്പോൾ അതിൽ നിന്ന് നബി(സ) ഭക്ഷിച്ചു. എനിക്കത്ഭുതമായി. ഞാൻ ചോദിച്ചു: റസൂലേ, നിങ്ങൾ എന്റെയടുക്കൽ നോമ്പുകാരനാണെന്ന് പറഞ്ഞു വന്നിട്ട് ഇപ്പോൾ ഈ പലഹാരം കഴിക്കുന്നോ? നബി(സ) പറഞ്ഞു: "അതേ ആഇശ, ഒരാൾ അനുഷ്ഠിക്കുന്നത് റമളാനിലെ നോമ്പോ റമളാനിലേത് ഖളാഅ് വീട്ടുന്ന നോമ്പോ, സുന്നത് നോമ്പാണ് അനുഷ്ഠിക്കുന്നതെങ്കിൽ അയാൾ ദാനം ചെയ്യുന്നവനെപ്പോലെയാണ്. സമ്പത്തിൽ നിന്നും ഉദ്ദേശിച്ചത് ദാനത്തിന് മാറ്റിവെക്കുകയും ദാനംചെയ്യുകയും, ബാക്കിയുള്ളവ അദ്ദേഹത്തിനായി എടുത്ത് വെക്കുകയും ചെയ്യുന്നു." (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَعَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى السَّحُورِ فِي رَمَضَانَ، فَقَالَ: "هَلُمَّ إِلَى الْغَدَاءِ الْمُبَارَكِ". (د,ن)', 'ഇർബാള്ബ്നു സാരിയ(റ): റമളാനിൽ അത്താഴത്തിനായി റസൂൽ(സ) എന്നെ വിളിച്ചു. എന്നിട്ട് പറഞ്ഞു. "അനുഗൃഹീതമായ ഭക്ഷണത്തിലേക്ക് വരൂ." (ദ,ന)', 'الْعِرْبَاضِ بْنِ سَارِيَةَ', 'ഇർബാള്ബ്നു സാരിയ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 66, 66, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "نِعْمَ سَحُورُ الْمُؤْمِنِ التَّمْرُ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) അരുളി: "വിശ്വാസിക്ക് അത്താഴമായി കാരക്ക വളരെ ഉത്തമം." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 66, 66, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ فَصْلَ مَا بَيْنَ صِيَامِنَا وَصِيَامِ أَهْلِ الْكِتَابِ أَكْلَةُ السَّحَرِ". (م,د,ت,ن)', 'അംറുബ്നു ആസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നമ്മുടെയും പൂർവ്വ വേദക്കാരുടെയും വ്രതത്തിന്നിടയിലെ വ്യത്യാസം അത്താഴഭക്ഷണമാണ്." (മു,ദ,തു,ന)', 'عَمْرِو بْنِ الْعَاصِ', 'അംറുബ്നു ആസ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 66, 66, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تَسَحَّرُوا، فَإِنَّ فِي السَّحُورِ بَرَكَةً". حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'അനസ്(റ): നബി(സ) അരുളി. "അത്താഴം കഴിക്കൂ, തീർച്ചയായും അതിൽ സമൃദ്ധിയുണ്ട്." (ബു,മു,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 66, 66, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَتَسَحَّرُ، فَقَالَ: "إِنَّهَا بَرَكَةٌ أَعْطَاكُمُ اللَّهُ إِيَّاهَا، فَلَا تَدَعُوهُ". (ن)', 'പ്രവാചകാനുചരരിൽ ഒരാളെ ഉദ്ധരിച്ച് അബ്ദുല്ലാഹിബ്നുൽ ഹാരിസ്(റ): അത്താഴം കഴിച്ചുകൊണ്ടിരുന്ന നബി(സ)യുടെ അടുത്ത് ഞാൻ ചെന്നു. അവിടന്നരുളി: "അത്താഴം അല്ലാഹു നിങ്ങൾക്ക് നൽകിയ പുണ്യഭക്ഷണമാണ്. അതിനാൽ നിങ്ങളത് ഉപേക്ഷിക്കരുത്." (ന)', 'عَبْدِ اللَّهِ بْنِ الْحَارِثِ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ', 'പ്രവാചകാനുചരരിൽ ഒരാളെ ഉദ്ധരിച്ച് അബ്ദുല്ലാഹിബ്നുൽ ഹാരിസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 66, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "عَلَيْكُمْ بِغَدَاءِ السُّحُورِ، فَإِنَّهُ هُوَ الْغَدَاءُ الْمُبَارَكُ". (ن)', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ): റസൂൽ(സ) പറഞ്ഞു: "അത്തായഭക്ഷണം നിങ്ങൾ കഴിക്കുക. നിശ്ചയം അതു പുണ്യമുള്ള ഭക്ഷണമാണ്." (ന.)', 'الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 67, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اسْتَعِينُوا بِطَعَامِ السَّحَرِ عَلَى صِيَامِ النَّهَارِ، وَبِالْقَيْلُولَةِ عَلَى قِيَامِ اللَّيْلِ". [ز: في إسناده ضعيف]. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "പകൽ നോമ്പനുഷ്ഠിക്കാൻവേണ്ടി അത്താഴഭക്ഷണംകൊണ്ടും രാത്രി നിസ്കാരത്തിന് വേണ്ടി പകൽ ഉറക്കം (ഖൈലൂലത്) കൊണ്ടും സഹായം തേടുക. (പരമ്പരയിൽ ദുർബലനുണ്ട്). (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'പരമ്പരയിൽ ദുർബലനുണ്ട്', 67, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَغُرَّنَّكُمْ مِنْ سَحُورِكُمْ أَذَانُ بِلَالٍ، وَلَا بَيَاضُ الْأُفُقِ الْمُسْتَطِيلُ هَكَذَا، حَتَّى يَسْتَطِيرَ هَكَذَا". وَحَكَاهُ حَمَّادٌ بِيَدَيْهِ، قَالَ: يَعْنِي مُعْتَرِضًا. (م,د,ت)', 'സമുറതുബ്നു ജുൻദുബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അത്താഴം കഴിക്കുന്നതിൽ നിന്ന് ബിലാൽ(റ)ന്റെ ബാങ്കും ഇപ്രകാരം നീളത്തിൽ നീണ്ടുകിടക്കുന്ന ചക്രവാള ധവളിമയും നിങ്ങളെ ആശയക്കുഴപ്പത്തിലാക്കാതിരിക്കട്ടെ. ഇപ്രകാരം അത് വ്യാപകമാകുന്നതുവരെ." ഇത് ഉദ്ധരിക്കുമ്പോൾ ഹമ്മാദ്(റ) (ഇമാം മുസലിമിന്റെ ഉസ്താദിന്റെ ഉസ്താദ്) തന്റെ കൈകൾ കൊണ്ട് ആംഗ്യരൂപേണ കാണിച്ചിരുന്നു. (മു,ദ,തു)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 67, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَغُرَّنَّكُمْ أَذَانُ بِلَالٍ، وَلَا هَذَا الْبَيَاضُ، حَتَّى يَنْفَجِرَ الْفَجْرُ هَكَذَا وَهَكَذَا" يَعْنِي مُعْتَرِضًا، قَالَ: وَبَسَطَ بِيَدَيْهِ يَمِينًا وَشِمَالًا مَادًّا يَدَيْهِ. (ن)', 'സമുറത്(റ): റസൂൽ(സ) അരുളി. "ബിലാൽ(റ)ന്റെ ബാങ്കും ഈ ധവളപ്രകാശവും നിങ്ങളെ വഞ്ചിക്കരുത്. ഇപ്രകാരവും ഇപ്രകാരവും ഫജ്റുസ്സ്വാദിഖ് പൊട്ടിവിടരുന്നതുവരെ." തിരുനബി(സ) ഉദ്ദേശിച്ചത് പരന്ന് പൊട്ടിവിടരുന്നതിനെയാണ്. സമുറത്(റ) പറയുന്നു: ഇത് പറയുമ്പോൾ തിരുനബി(സ) തന്റെ ഇരുകരവും ഇടത്തും വലത്തും വിടർത്തി നീട്ടിയിരുന്നു. (ന)', 'سَمُرَةَ', 'സമുറത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 67, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُؤَذِّنَانِ: بِلَالٌ، وَابْنُ أُمِّ مَكْتُومٍ الْأَعْمَى، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ بِلَالًا يُؤَذِّنُ بِلَيْلٍ، فَكُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ ابْنُ أُمِّ مَكْتُومٍ". قَالَ: وَلَمْ يَكُنْ بَيْنَهُمَا إِلَّا أَنْ يَنْزِلَ هَذَا وَيَرْقَى هَذَا. (م)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ)ക്കു രണ്ടു മുഅദ്ദിനുമാർ (ബാങ്ക് വിളിക്കുന്നവർ) ഉണ്ടായിരുന്നു, ബിലാൽ(റ)വും അന്ധനായ ഇബ്നു ഉമ്മിമക്തൂം(റ)വും. തിരുനബി(സ) അരുളി: "നിശ്ചയം ബിലാൽ(റ) രാത്രിയിൽ ബാങ്കുകൊടുക്കും, അതിനുശേഷം ഇബ്നു ഉമ്മിമക്തൂം(റ) ബാങ്ക് വിളിമുഴക്കുന്നത് വരെ നിങ്ങൾക്ക് കുടിക്കുകയും തിന്നുകയും ചെയ്യാം." നിവേദകൻ പറയുന്നു: ഒരാൾ ഇറങ്ങുകയും മറ്റെയാൾ കയറുകയും ചെയ്യുന്ന സമയം മാത്രമായിരുന്നു അവ രണ്ടിന്റെയും ഇടയിലുള്ള അന്തരം. (മു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 67, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: [لَمَّا] نَزَلَتْ هَذِهِ الْآيَةُ: {وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ} [البقرة:١٨٧] قَالَ: فَكَانَ الرَّجُلُ إِذَا أَرَادَ الصَّوْمَ رَبَطَ أَحَدُهُمْ فِي رِجْلَيْهِ الْخَيْطَ الْأَسْوَدَ وَالْخَيْطَ الْأَبْيَضَ، فَلَا يَزَالُ يَأْكُلُ وَيَشْرَبُ حَتَّى يَتَبَيَّنَ لَهُ رِئْيُهُمَا، فَأَنْزَلَ اللَّهُ بَعْدَ ذَلِكَ: {مِنَ الْفَجْرِ} فَعَلِمُوا أَنَّمَا يَعْنِي بِذَلِكَ اللَّيْلَ وَالنَّهَارَ. (م)', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ): ''വെളുത്ത നൂലിഴകൾ കറുത്ത ഇഴകളിൽനിന്നും വ്യക്തമായി ദർശിക്കുംവരെ നിങ്ങൾ തിന്നുകയും കുടിക്കുകയും ചെയ്യുക.'' (അൽബഖറ: 187) എന്ന ഖുർആൻ സൂക്തം അവതരിച്ചപ്പോൾ നോമ്പ് ഉദ്ദേശിക്കുന്ന ആളുകൾ ഇരു കാലുകളിലും കറുത്തതും വെളുത്തതുമായ ഇഴകൾ ബന്ധിപ്പിക്കുമായിരുന്നു. അവയുടെ നിറം വ്യക്തമാകുന്നതുവരെ അവർ തിന്നുകയും കുടിക്കുകയും ചെയ്തിരുന്നു. അതിനുശേഷം ''പ്രഭാതത്തിലെ'' എന്ന് അല്ലാഹു സൂക്തമിറക്കി. അതോടെ അല്ലാഹു ഉദ്ദേശിച്ചത് രാവും പകലുമാണെന്ന് അവർ മനസ്സിലാക്കി. (മു)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'البقرة:١٨٧', null, 68, 68, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ: {حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ} [البقرة:١٨٧] قَالَ: أَخَذْتُ عِقَالًا أَبْيَضَ وَعِقَالًا أَسْوَدَ، فَوَضَعْتُهُمَا تَحْتَ وِسَادَتِي، فَنَظَرْتُ فَلَمْ أَتَبَيَّنْ، فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَضَحِكَ، فَقَالَ: "إِنَّ وِسَادَكَ إِذَنْ لَعَرِيضٌ طَوِيلٌ، إِنَّمَا هُوَ اللَّيْلُ وَالنَّهَارُ". وَفِي رِوَايَةٍ: "إِنَّمَا هُوَ سَوَادُ اللَّيْلِ وَبَيَاضُ النَّهَارِ". (خ,د,ت)', 'അദിയ്യുബ്നു ഹാതിം(റ): ''കറുത്തരേഖകളിൽനിന്ന് വെളുത്തരേഖകൾ നിങ്ങൾക്കു തെളിഞ്ഞുകാണുന്നതുവരെ'' എന്ന ഖുർആൻ സൂക്തം അവതരിച്ചപ്പോൾ ഞാൻ വെളുത്തതും കറുത്തതുമായ ഓരോ നൂലുകൾ എടുത്ത് എന്റെ തലയിണക്ക് ചുവട്ടിൽ വെച്ച് ഞാൻ വീക്ഷിച്ചു. പക്ഷേ, അവ രണ്ടും വ്യക്തമായി ദർശിക്കാൻ സാധിച്ചില്ല. ഇത് പ്രവാചകൻ(സ)യെ ധരിപ്പിച്ചപ്പോൾ റസൂൽ(സ) ചിരിച്ചു. ഇങ്ങനെ പറയുകയും ചെയ്തു: "അന്നേരം നിന്റെ തലയിണ വലിയതായിരുന്നു. (അദ്ദേഹത്തിന് പിണഞ്ഞ അബദ്ധത്തെ സൂചിപ്പിച്ചുകൊണ്ടാണ് ഇങ്ങനെ പറഞ്ഞത്), അത് രാവും പകലും മാത്രമാണ്." മറ്റൊരു ഉദ്ധരണിയിൽ: "നിശ്ചയം അത് രാവിന്റെ കറുപ്പും പകലിന്റെ വെളുപ്പുമാണ്." (ബു,ദ,തു)', 'عَدِيِّ بْنِ حَاتِمٍ', 'അദിയ്യുബ്നു ഹാതിം(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], 'البقرة:١٨٧', null, 68, 68, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=72), 1, 'وَفِي رِوَايَةٍ: "إِنَّمَا هُوَ سَوَادُ اللَّيْلِ وَبَيَاضُ النَّهَارِ". (خ,د,ت)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَمْنَعَنَّ أَحَدَكُمْ أَذَانُ بِلَالٍ مِنْ سُحُورِهِ، فَإِنَّهُ يُؤَذِّنُ– أَوْ قَالَ: يُنَادِي– لِيَرْجِعَ قَائِمُكُمْ، وَيَنْتَبِهَ نَائِمُكُمْ، وَلَيْسَ الْفَجْرُ أَنْ يَقُولَ هَكَذَا" وَجَمَعَ كَفَّيْهِ "حَتَّى يَقُولَ هَكَذَا" وَمَدَّ بِأُصْبُعِهِ السَّبَّابَتَيْنِ. (ق,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ബിലാൽ(റ)വിന്റെ ബാങ്ക് അത്താഴം കഴിക്കുന്നതിൽ നിന്ന് നിങ്ങളിലൊരാളെയും തടസ്സപ്പെടുത്താതിരിക്കട്ടെ. അദ്ദേഹം ബാങ്ക്‌വിളിക്കുന്നത് നിങ്ങളെ ഉറക്കിൽനിന്ന് ഉണർത്തുവാനും തഹജ്ജുദ് നിസ്കരിക്കുന്നവന് വിശ്രമിക്കുവാനും വേണ്ടിയാണ്". റസൂൽ(സ) തന്റെ രണ്ട് മുൻകൈകൾ കൂട്ടിപ്പിടിച്ച് പറഞ്ഞു: "ഇപ്രകാരം നീളത്തിൽ നീണ്ടുകിടക്കുന്നതല്ല ശരിയായ പ്രഭാതം." പിന്നെ റസൂൽ(സ) തന്റെ വിരൽ കൊണ്ട് രണ്ട് ചൂണ്ടുവിരലുകൾ നീട്ടി സൂചിപ്പിച്ചു. "ഇപ്രകാരം (വിലങ്ങനെ) നീണ്ടുകിടക്കുന്നതാണ് ശരിയായ പ്രഭാതം". (ബു,ദ,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 68, 68, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ طَلْقٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلُوا وَاشْرَبُوا، وَلَا يَهِيدَنَّكُمُ السَّاطِعُ الْمُصْعِدُ، فَكُلُوا وَاشْرَبُوا حَتَّى يَعْتَرِضَ لَكُمُ الْأَحْمَرُ". (د,ت)', 'ത്വൽഖ്(റ): റസൂൽ(സ) അരുളി: "തിന്നോളൂ, കുടിച്ചോളൂ. നീണ്ട വെളുത്ത പ്രഭ നിങ്ങളെ അതിൽനിന്ന് തടയരുത്. ചക്രവാളത്തിൽ ചുവപ്പ് വരുന്നതുവരെ നിങ്ങൾക്ക് തിന്നുകയും കുടിക്കുകയും ചെയ്യാം." (ദ,തു)', 'طَلْقٍ', 'ത്വൽഖ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 68, 68, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: تَسَحَّرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَزَيْدُ بْنُ ثَابِتٍ، ثُمَّ قَامَا فَدَخَلَا فِي صَلَاةِ الصُّبْحِ. فَقِيلَ لِأَنَسٍ: كَمْ كَانَ بَيْنَ فَرَاغِهِمَا وَدُخُولِهِمَا فِي الصَّلَاةِ؟ قَالَ: قَدْرُ مَا يَقْرَأُ الْإِنْسَانُ خَمْسِينَ آيَةً. (ن)', 'അനസ്(റ): സൈദുബ്നു സാബിത്(റ)വും റസൂൽ(സ)യും അത്താഴം കഴിച്ചു. പിന്നെ രണ്ടുപേരും എഴുന്നേറ്റ് സുബ്ഹി നിസ്കാരം തുടങ്ങി. നിസ്കാരപ്രവേശത്തിനും അത്താഴ വിരാമത്തിനും ഇടയിൽ അവർ എത്ര സമയമെടുത്തു എന്നൊരാൾ അനസ്(റ)വിനോട് ചോദിച്ചു. ഒരു മനുഷ്യന് അമ്പത് സൂക്തങ്ങൾ ഓതാനെടുക്കുന്ന സമയമെന്ന് അദ്ദേഹം മറുപടി പറഞ്ഞു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 69, 69, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَذَلِكَ عِنْدَ السُّحُورِ: "يَا أَنَسُ، إِنِّي أُرِيدُ الصِّيَامَ، أَطْعِمْنِي شَيْئًا". فَأَتَيْتُهُ بِتَمْرٍ وَإِنَاءٍ فِيهِ مَاءٌ، وَذَلِكَ بَعْدَ مَا أَذَّنَ بِلَالٌ، فَقَالَ: "يَا أَنَسُ، انْظُرْ رَجُلًا يَأْكُلُ مَعِي". فَدَعَوْتُ زَيْدَ بْنَ ثَابِتٍ فَجَاءَ، فَقَالَ: إِنِّي قَدْ شَرِبْتُ شَرْبَةَ سَوِيقٍ، وَأَنَا أُرِيدُ الصِّيَامَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَأَنَا أُرِيدُ الصِّيَامَ". فَتَسَحَّرَ مَعَهُ، ثُمَّ قَامَ فَصَلَّى رَكْعَتَيْنِ، ثُمَّ خَرَجَ إِلَى الصَّلَاةِ. (ن)', 'അനസ്(റ): അത്താഴസമയത്ത് റസൂൽ(സ) പറഞ്ഞു: "ഓ അനസ്, ഞാൻ നോമ്പെടുക്കാൻ ഉദ്ദേശിക്കുന്നു. അൽപം ഭക്ഷണം വേണം." അൽപം കാരക്കയും വെള്ളവും ഞാൻ റസൂൽ(സ)ക്കു നൽകി. ബിലാൽ(റ)വിന്റെ ബാങ്കിനു ശേഷമായിരുന്നു അത്. നബി(സ) പറഞ്ഞു: "ഓ അനസ്, എന്റെ കൂടെ ഭക്ഷണം കഴിക്കാവുന്ന ആരെങ്കിലും ഒരാളെ വിളിക്ക്." അപ്പോൾ ഞാൻ സൈദ്ബ്നു സാബിത്(റ)നെ ക്ഷണിച്ചു. ഉടനെ അദ്ദേഹം വന്നു. തുടർന്ന് അദ്ദേഹം പറഞ്ഞു: ഞാൻ പൊടിക്കഞ്ഞി കുടിച്ചിട്ടുണ്ട്. ഞാൻ നോമ്പെടുക്കാൻ ഉദ്ദേശിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "എനിക്കും നോമ്പെടുക്കാൻ താൽപര്യമുണ്ട്." റസൂൽ(സ) സൈദ്(റ)വിനോട് കൂടെ അത്താഴം കഴിച്ചു. ശേഷം എഴുന്നേറ്റ് രണ്ട് റക്അത് നിസ്കരിച്ച് റസൂൽ(സ) സുബ്ഹി നിസ്കരിക്കാൻ പോയി. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 69, 69, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ زِرِّ بْنِ حُبَيْشٍ قَالَ: قُلْنَا لِحُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ: أَيَّ سَاعَةٍ تَسَحَّرْتَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: هُوَ النَّهَارُ، إِلَّا أَنَّ الشَّمْسَ لَمْ تَطْلُعْ. (ن)', 'സിർറുബ്നു ഹുബൈശ്(റ): എപ്പോഴാണു താങ്കൾ നബി(സ)യോടൊപ്പം അത്താഴം കഴിച്ചതെന്ന് ഹുദൈഫ(റ)യോട് ഞങ്ങൾ ചോദിച്ചു. അതു പകൽതന്നെയായിരുന്നു, സൂര്യൻ ഉദിച്ചില്ലെന്നു മാത്രം എന്നദ്ദേഹം മറുപടി പറഞ്ഞു. (ന)', 'زِرِّ بْنِ حُبَيْشٍ قَالَ', 'സിർറുബ്നു ഹുബൈശ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 69, 69, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ زِرِّ بْنِ حُبَيْشٍ قَالَ: تَسَحَّرْتُ مَعَ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ ثُمَّ خَرَجْنَا إِلَى الصَّلَاةِ، فَلَمَّا أَتَيْنَا الْمَسْجِدَ صَلَّيْنَا رَكْعَتَيْنِ وَأُقِيمَتِ الصَّلَاةُ، وَلَيْسَ بَيْنَهُمَا إِلَّا هُنَيْهَةٌ. (ن)', 'സിർറുബ്നു ഹുബൈശ്(റ): ഞാൻ ഹുദൈഫ(റ)യോടൊപ്പം അത്താഴം കഴിച്ചു. ശേഷം ഞങ്ങൾ നിസ്കരിക്കാൻ പോയി. പള്ളിയിൽ ചെന്ന് രണ്ട് റക്അത്ത് നിസ്കരിച്ചപ്പോഴേക്കും നിസ്കാരത്തിന് ഇഖാമത് വിളിച്ചു. അവ രണ്ടിനും ഇടയിൽ ചുരുങ്ങിയ സമയം മാത്രമേ ഉണ്ടായിരുന്നുള്ളൂ." (ന)', 'زِرِّ بْنِ حُبَيْشٍ قَالَ', 'സിർറുബ്നു ഹുബൈശ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 69, 69, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَبِي عَطِيَّةَ قَالَ: قُلْتُ لِعَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: فِينَا رَجُلَانِ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَحَدُهُمَا يُعَجِّلُ الْإِفْطَارَ وَيُؤَخِّرُ السُّحُورَ، وَالْآخَرُ يُؤَخِّرُ الْإِفْطَارَ وَيُعَجِّلُ السُّحُورَ؟ قَالَتْ: أَيُّهُمَا الَّذِي يُعَجِّلُ الْإِفْطَارَ وَيُؤَخِّرُ السُّحُورَ؟ قُلْتُ: عَبْدُ اللَّهِ بْنُ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ. قَالَتْ: هَكَذَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ. (ن)', 'അബൂഅതിയ്യ(റ): ഞാൻ ആഇശ(റ)യോട് പറഞ്ഞു: ഞങ്ങളുടെ കൂട്ടത്തിൽ നബി(സ)യുടെ അനുചരൻമാരിൽപെട്ട രണ്ടാളുകളുണ്ട്. ഒരാൾ നോമ്പുതുറ വേഗത്തിലാക്കുകയും അത്താഴം പിന്തിപ്പിക്കുകയും ചെയ്യുന്നു. മറ്റെയാൾ നോമ്പുതുറ പിന്തിപ്പിക്കുകയും അത്താഴം വേഗത്തിലാക്കുകയും ചെയ്യുന്നു. ആഇശ(റ) ചോദിച്ചു: നോമ്പുതുറ വേഗത്തിലാക്കുകയും അത്താഴം പിന്തിക്കുകയും ചെയ്യുന്നതാരാണ്? ഞാൻ പറഞ്ഞു: അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ). ആഇശ(റ) പറഞ്ഞു: ഇപ്രകാരമായിരുന്നു റസൂൽ(സ) ചെയ്തിരുന്നത്. (ന)', 'أَبِي عَطِيَّةَ قَالَ', 'അബൂഅതിയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 69, 70, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ أَبِي عَطِيَّةَ قَالَ: دَخَلْتُ أَنَا وَمَسْرُوقٌ عَلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، فَقُلْنَا لَهَا: يَا أُمَّ الْمُؤْمِنِينَ، رَجُلَانِ مِنْ أَصْحَابِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَحَدُهُمَا يُعَجِّلُ الْإِفْطَارَ وَيُعَجِّلُ الصَّلَاةَ، وَالْآخَرُ يُؤَخِّرُ الْإِفْطَارَ وَيُؤَخِّرُ الصَّلَاةَ؟ فَقَالَتْ: أَيُّهُمَا يُعَجِّلُ الْإِفْطَارَ وَيُعَجِّلُ الصَّلَاةَ؟ قُلْنَا: عَبْدُ اللَّهِ بْنُ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ. قَالَتْ: هَكَذَا كَانَ يَصْنَعُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْآخَرُ أَبُو مُوسَى رَضِيَ اللَّهُ عَنْهُمَا. (ن)', 'അബൂഅതിയ്യ(റ): ഞാനും മസ്റൂഖ്(റ)വും ആഇശ(റ)യുടെ അടുത്തെത്തി. ഞങ്ങൾ അവരോട് പറഞ്ഞു: ഓ ഉമ്മുൽമുഅ്മിനീൻ, സ്വഹാബികളിൽപെട്ട രണ്ടുപേരിൽ ഒരാൾ നിസ്കാരവും നോമ്പ്തുറയും വേഗത്തിലാക്കും. മറ്റെയാൾ നോമ്പുതുറയും നിസ്കാരവും പിന്തിപ്പിക്കും. നിസ്കാരവും നോമ്പ്തുറയും വേഗത്തിലാക്കുന്നയാൾ ആരാണെന്ന് അവർ ചോദിച്ചു. അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)വാണതെന്ന് ഞങ്ങൾ മറുപടി പറഞ്ഞു. അപ്രകാരമാണ് റസൂൽ(സ) ചെയ്തിരുന്നതെന്ന് അവർ പറഞ്ഞു. അപരൻ അബൂമൂസാ(റ) ആണ്. (ന)', 'أَبِي عَطِيَّةَ قَالَ', 'അബൂഅതിയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 70, 70, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا سَمِعَ أَحَدُكُمُ النِّدَاءَ وَالْإِنَاءُ عَلَى يَدِهِ فَلَا يَضَعْهُ حَتَّى يَقْضِيَ حَاجَتَهُ مِنْهُ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഭക്ഷണപ്പാത്രം കയ്യിലിരിക്കെ നിങ്ങളിലാരെങ്കിലും ബാങ്ക് കേൾക്കാനിടയായാൽ ആവശ്യനിർവ്വഹണത്തിനു ശേഷം മാത്രം അവൻ പാത്രം വെച്ചാൽ മതി." (ബിലാൽ(റ)വിന്റെ അത്താഴബാങ്കാണിത്, സുബ്ഹി ബാങ്ക് അല്ല ഇവിടെ ഉദ്ദേശ്യം). (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 70, 70, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سِرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ صَائِمٌ، فَلَمَّا غَرَبَتِ الشَّمْسُ قَالَ: "يَا بِلَالُ، انْزِلْ فَاجْدَحْ لَنَا". قَالَ: يَا رَسُولَ اللَّهِ، لَوْ أَمْسَيْتَ. قَالَ: "انْزِلْ فَاجْدَحْ لَنَا". قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ عَلَيْكَ نَهَارًا. قَالَ: "انْزِلْ فَاجْدَحْ لَنَا". فَنَزَلَ فَجَدَحَ، فَشَرِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: "إِذَا رَأَيْتُمُ اللَّيْلَ قَدْ أَقْبَلَ مِنْ هَا هُنَا فَقَدْ أَفْطَرَ الصَّائِمُ". وَأَشَارَ بِأُصْبُعِهِ قِبَلَ الْمَشْرِقِ. (ق,د,ت)', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ): നോമ്പുകാരനായിരുന്ന റസൂൽ(സ)യുടെ കൂടെ ഞങ്ങൾ സഞ്ചരിച്ചു. സൂര്യൻ അസ്തമിച്ചപ്പോൾ തിരുനബി(സ) അരുളി. "ഹേ ബിലാൽ, വാഹനമിറങ്ങി ഞങ്ങൾക്ക് പാനീയം തയ്യാറാക്കുക." വൈകുന്നേരമായിക്കോട്ടെ, തിരുദൂതരേ എന്നു ബിലാൽ(റ) തിരിച്ചു പറഞ്ഞു. റസൂൽ(സ) വീണ്ടും അരുളി: "വാഹനമിറങ്ങി പാനീയം പാകംചെയ്തു തരിക." പകൽ ഇനിയുമുണ്ടല്ലോ തിരുദൂതരേ, എന്ന് ബിലാൽ(റ) വീണ്ടും തിരിച്ച് ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "വാഹനമിറങ്ങി പാനീയം പാകം ചെയ്തു തരിക." ബിലാൽ(റ) ഇറങ്ങി ഭക്ഷണം പാകം ചെയ്തു. റസൂൽ(സ) അത് കുടിച്ചു. കിഴക്കിലേക്കു വിരൽചൂണ്ടി റസൂൽ(സ) അരുളി. "ഇവിടെ നിന്നും രാവ് ആരംഭിക്കുന്നതു കണ്ടാൽ നോമ്പുകാരന് നോമ്പു മുറിക്കാം." (ബു,മു,ദ,തു)', 'عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 70, 71, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ: أَفْطَرْنَا يَوْمًا فِي رَمَضَانَ فِي غَيْمٍ، فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ طَلَعَتِ الشَّمْسُ. قِيلَ: أُمِرُوا بِالْقَضَاءِ؟ قِيلَ: وَبُدٌّ مِنْ ذَلِكَ. (خ,د,جه)', 'അസ്മാഉബിൻത് അബീബകർ(റ): തിരുദൂതർ(സ)യുടെ കാലത്ത് മേഘമുള്ള ഒരു റമളാൻ ദിനത്തിൽ ഞങ്ങൾ നോമ്പ്മുറിച്ചു. പിന്നെ സൂര്യൻ വെളിവായി. അതു ഖളാഅ് വീട്ടാൻ കൽപിക്കപ്പെട്ടോ എന്നൊരാൾ ചോദിച്ചു. അത് അനിവാര്യമല്ലല്ലോ എന്ന് മറുപടി നൽകപ്പെട്ടു. (ബു,ദ,ജ)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഉബിൻത് അബീബകർ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 71, 71, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَقْبَلَ اللَّيْلُ وَأَدْبَرَ النَّهَارُ وَغَابَتِ الشَّمْسُ فَقَدْ أَفْطَرْتَ". (ق,د,ت,ن)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): റസൂൽ(സ) അരുളി: "രാത്രി മുന്നിട്ട് വരികയും, പകൽ പിന്നിട്ട് പോവുകയും, സൂര്യൻ അസ്തമിക്കുകയും ചെയ്താൽ നിങ്ങൾ നോമ്പ് മുറിച്ചു." (ബു,മു,ദ,തു,ന)', 'عُمَرَ بْنِ الْخَطَّابِ قَالَ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 71, 71, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَزَالُ النَّاسُ بِخَيْرٍ مَا عَجَّلُوا الْفِطْرَ". (ق,ت,جه)', 'സഹ്‌ലുബ്നു സഅ്ദ് (റ): റസൂൽ(സ) പറഞ്ഞു: "നോമ്പുതുറ വേഗത്തിലാക്കുന്ന കാലത്തോളം ജനങ്ങൾ നന്മയിലായിരിക്കും." (ബു,മു,തു,ജ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്‌ലുബ്നു സഅ്ദ് (റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 71, 71, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَزَالُ الدِّينُ ظَاهِرًا مَا عَجَّلَ النَّاسُ الْفِطْرَ، لِأَنَّ الْيَهُودَ وَالنَّصَارَى يُؤَخِّرُونَ". (د,جه)', 'അബൂഹുറൈറ(റ): തിരുനബി(സ) പറഞ്ഞു: "ജനങ്ങൾ നോമ്പ് തുറക്കുന്നതിൽ ധൃതികാണിക്കുന്ന കാലത്തോളം ദീൻ പരസ്യമായിക്കൊണ്ടേയിരിക്കും. ജൂതരും ക്രിസ്ത്യാനികളും നോമ്പുതുറ പിന്തിക്കുന്നവരാണ്." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 71, 71, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أَبِي عَطِيَّةَ قَالَ: دَخَلْتُ عَلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَا وَمَسْرُوقٌ، فَقُلْنَا: يَا أُمَّ الْمُؤْمِنِينَ، رَجُلَانِ مِنْ أَصْحَابِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَحَدُهُمَا يُعَجِّلُ الْإِفْطَارَ وَيُعَجِّلُ الصَّلَاةَ، وَالْآخَرُ يُؤَخِّرُ الْإِفْطَارَ وَيُؤَخِّرُ الصَّلَاةَ؟ قَالَتْ: أَيُّهُمَا يُعَجِّلُ الْإِفْطَارَ وَيُعَجِّلُ الصَّلَاةَ؟ فَقُلْنَا: عَبْدُ اللَّهِ، قَالَتْ: كَذَلِكَ كَانَ يَصْنَعُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م,د,ت,ن)', 'അബൂഅതിയ്യ(റ): ഞാനും മസ്റൂഖു(റ)ം ആഇശ(റ)യുടെ വീട്ടിൽ ചെന്നു. ഞങ്ങൾ പറഞ്ഞു: ഉമ്മുൽ മുഅ്മിനീൻ, നബി(സ)യുടെ അനുചരരിൽപ്പെട്ട രണ്ടാളുകൾ, ഒരാൾ നോമ്പുതുറയും നിസ്കാരവും വേഗത്തിലാക്കുന്നു. മറ്റെയാൾ നോമ്പുതുറയും നിസ്കാരവും വൈകിക്കുന്നു. ആഇശ(റ) ചോദിച്ചു: നോമ്പുതുറയും നിസ്കാരവും വേഗത്തിൽ ചെയ്യുന്നത് ആരാണ്? ഞങ്ങൾ പറഞ്ഞു: അബ്ദുല്ല. ആഇശ(റ) പറഞ്ഞു: അപ്രകാരമായിരുന്നു നബി(സ) ചെയ്തിരുന്നത്. (മു,ദ,തു,ന)', 'أَبِي عَطِيَّةَ قَالَ', 'അബൂഅതിയ്യ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 71, 71, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَالَ اللَّهُ عَزَّ وَجَلَّ: أَحَبُّ عِبَادِي إِلَيَّ أَعْجَلُهُمْ فِطْرًا". حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു പറയുന്നു: എന്റെ അടിമകളിൽ എനിക്കേറ്റവും സ്നേഹമുള്ളവർ നോമ്പ്തുറക്കുന്നതിൽ ധൃതി കാണിക്കുന്നവരാണ്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 72, 72, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُفْطِرُ عَلَى رُطَبَاتٍ قَبْلَ أَنْ يُصَلِّيَ، فَإِنْ لَمْ تَكُنْ رُطَبَاتٌ فَعَلَى تَمَرَاتٍ، فَإِنْ لَمْ تَكُنْ حَسَا حَسَوَاتٍ مِنْ مَاءٍ. (د,ت)', 'അനസ്(റ): റസൂൽ(സ) നിസ്കരിക്കുന്നതിനു മുമ്പ് ഈത്തപ്പഴങ്ങൾകൊണ്ട് നോമ്പു മുറിക്കാറുണ്ടായിരുന്നു. ഈത്തപ്പഴം ലഭിച്ചില്ലെങ്കിൽ കാരക്ക. കാരക്കയില്ലെങ്കിൽ കുറച്ച് വെള്ളം കുടിക്കും. (ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 72, 72, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أُمِّ هَانِئٍ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كُنْتُ قَاعِدَةً عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأُتِيَ بِشَرَابٍ فَشَرِبَ مِنْهُ، ثُمَّ نَاوَلَنِي فَشَرِبْتُ مِنْهُ. فَقُلْتُ: إِنِّي أَذْنَبْتُ، فَاسْتَغْفِرْ لِي. فَقَالَ: "وَمَا ذَاكِ". قَالَتْ: كُنْتُ صَائِمَةً فَأَفْطَرْتُ. فَقَالَ: "أَمِنْ قَضَاءٍ كُنْتِ تَقْضِينَهُ". قَالَتْ: لَا. قَالَ: "فَلَا يَضُرُّكِ". وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا، فَدَعَى بِشَرَابٍ فَشَرِبَ، ثُمَّ نَاوَلَهَا فَشَرِبَتْ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، أَمَا إِنِّي كُنْتُ صَائِمَةً. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الصَّائِمُ الْمُتَطَوِّعُ أَمِينُ– وَفِي رِوَايَةٍ: أَمِيرُ– نَفْسِهِ، إِنْ شَاءَ صَامَ وَإِنْ شَاءَ أَفْطَرَ". (د,ت)', 'ഉമ്മുഹാനിഅ്(റ): ഞാൻ റസൂൽ(സ)യുടെ അടുത്തിരിക്കെ പാനീയം കൊണ്ടുവരപ്പെടുകയും തിരുനബി(സ) അതിൽനിന്ന് കുടിക്കുകയും ചെയ്തു. പിന്നെ എനിക്ക് തന്നു. ഞാനും കുടിച്ചു. ഞാൻ പറഞ്ഞു: ഞാൻ പാപം ചെയ്തിട്ടുണ്ട്. അതിന് അങ്ങ് എനിക്കുവേണ്ടി മാപ്പിരക്കണം. "അതെന്താണെ"ന്നു തിരുനബി(സ) ചോദിച്ചു. ഞാൻ നോമ്പുമുറിച്ചു എന്നവർ പറഞ്ഞു: "കടമുള്ള നോമ്പായിരുന്നോ നീ നോറ്റത്?" തിരുനബി(സ) വീണ്ടും ചോദിച്ചു. അല്ലെന്ന് അവർ പറഞ്ഞു. റസൂൽ(സ) പറഞ്ഞു "എങ്കിൽ നിനക്കത് ദോഷം ചെയ്യില്ല."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=90), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا، فَدَعَى بِشَرَابٍ فَشَرِبَ، ثُمَّ نَاوَلَهَا فَشَرِبَتْ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، أَمَا إِنِّي كُنْتُ صَائِمَةً. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الصَّائِمُ الْمُتَطَوِّعُ أَمِينُ–', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) അവരുടെ അടുത്ത്ചെന്ന് പാനീയം ആവശ്യപ്പെട്ടു, അങ്ങനെ അത്കുടിച്ചു, പിന്നെ അവർക്ക് നൽകി, അവരും കുടിച്ചു. തുടർന്ന് അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ നോമ്പുകാരി ആയിരുന്നല്ലോ. തിരുനബി(സ) പറഞ്ഞു: "ഐച്ഛിക നോമ്പുകാരൻ നിർഭയനാണ് -');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=90), 2, 'وَفِي رِوَايَةٍ: أَمِيرُ– نَفْسِهِ، إِنْ شَاءَ صَامَ وَإِنْ شَاءَ أَفْطَرَ". (د,ت)', 'മറ്റൊരു നിവേദനം: അവൻ അവന്റെ ദേഹത്തിന്റെ അധിപനാണ് - അവനുദ്ദേശിച്ചാൽ നോമ്പു പിടിക്കാം. ഉദ്ദേശിച്ചാൽ മുറിക്കുകയും ചെയ്യാം." (ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَفْطَرَ أَحَدُكُمْ فَلْيُفْطِرْ عَلَى تَمْرٍ، فَإِنَّهُ بَرَكَةٌ، فَمَنْ لَمْ يَجِدْ فَلْيُفْطِرْ عَلَى مَاءٍ فَإِنَّهُ طَهُورٌ". (د,ت,ن,جه)', 'സൽമാനുബ്നു ആമിരിള്ളബിയ്യ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നോമ്പ് മുറിക്കുന്നെങ്കിൽ കാരക്ക കൊണ്ട് മുറിക്കുക, നിശ്ചയം അതിൽ സമൃദ്ധിയുണ്ട്. കാരക്ക ലഭിക്കാത്തവർ വെള്ളം കൊണ്ട് മുറിക്കുക. നിശ്ചയം അത് ശുദ്ധിയുള്ളതും ശുദ്ധീകരിക്കാൻ ഉതകുന്നതുമാകുന്നു." (ദ,തു,ന,ജ)', 'سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ', 'സൽമാനുബ്നു ആമിരിള്ളബിയ്യ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 72, 72, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: كَانَ يَقْبِضُ عَلَى لِحْيَتِهِ فَيَقْطَعُ مَا زَادَ عَلَى الْكَفِّ، وَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَفْطَرَ قَالَ: "ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ". (د)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം തന്റെ താടിരോമം കൈകൊണ്ടു പിടിക്കുകയും അതിൽ ഒതുങ്ങാത്തത് വെട്ടിനീക്കുകയും ചെയ്യും. അദ്ദേഹം പറയുന്നു: നോമ്പു തുറക്കുന്ന അവസരത്തിൽ റസൂൽ(സ) പറയാറുണ്ടായിരുന്നു: "ദാഹം ശമിച്ചു. ഞരമ്പുകൾ നനഞ്ഞു. അല്ലാഹു നിനച്ചാൽ പ്രതിഫലവും ഉറപ്പായി." (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 73, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ مُعَاذِ بْنِ زُهْرَةَ: أَنَّهُ بَلَغَهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَفْطَرَ قَالَ: "اللَّهُمَّ لَكَ صُمْتُ، وَعَلَى رِزْقِكَ أَفْطَرْتُ". (مرسل) (د)', 'മുആദുബ്നു സുഹ്റ(റ): തിരുനബി(സ) നോമ്പു തുറക്കുമ്പോൾ ഇങ്ങനെ പറയാറുണ്ടായിരുന്നു എന്ന വിവരം അദ്ദേഹത്തിന് ലഭിച്ചു: "അല്ലാഹുവേ, നിനക്കുവേണ്ടി ഞാൻ നോമ്പനുഷ്ടിച്ചു. നിന്റെ ഭക്ഷണം കൊണ്ട് നോമ്പ് തുറക്കുകയും ചെയ്തു." (ദ)', 'مُعَاذِ بْنِ زُهْرَةَ', 'മുആദുബ്നു സുഹ്റ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 73, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ فَطَّرَ صَائِمًا كَانَ لَهُ مِثْلُ أَجْرِهِمْ، مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أُجُورِهِمْ شَيْئًا". (ت,جه)', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനി(റ): റസൂൽ(സ) പറഞ്ഞു: "നോമ്പു തുറക്കുന്നവരുടെ പ്രതിഫലത്തിനു തുല്യമായ പ്രതിഫലം തുറപ്പിക്കുന്നവനും ലഭിക്കും. അവരുടേതിൽനിന്ന് ഒന്നും കുറയാതെത്തന്നെ." (തു,ജ)', 'زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 73, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَفْطَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ سَعْدِ بْنِ مُعَاذٍ، فَقَالَ: "أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ". [ز: في سنده ضعيف] (جه)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): സഅ്ദുബ്നു മുആദ്(റ)ന്റെ അടുത്ത്നിന്ന് റസൂൽ(സ) നോമ്പു തുറന്നു. തുടർന്ന് നബി(സ) അരുളി. "നിങ്ങളുടെ അടുത്തുനിന്ന് നോമ്പുകാർ നോമ്പ് തുറന്നു. ഗുണവാന്മാർ നിങ്ങളുടെ ഭക്ഷണം കഴിച്ചു. മലക്കുകൾ നിങ്ങൾക്കുവേണ്ടി പ്രാർത്ഥിച്ചു." (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ട്) (ജ.)', 'عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ട്', 73, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ سِنَانِ بْنِ سَنَّةَ الْأَسْلَمِيِّ رَضِيَ اللَّهُ عَنْهُ - صَاحِبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الطَّاعِمُ الشَّاكِرُ لَهُ مِثْلُ أَجْرِ الصَّائِمِ الصَّابِرِ". (جه)', 'റസൂൽ(സ)യുടെ അനുചരനായ സിനാനുബ്നു സന്നതൽ അസ്ലമി(റ): റസൂൽ(സ) പറഞ്ഞു: "കഴിച്ച ഭക്ഷണത്തിനു നന്ദിയുള്ളവന് ക്ഷമയുള്ള നോമ്പുകാരന്റെ പ്രതിഫലമുണ്ട്." (ജ)', 'سِنَانِ بْنِ سَنَّةَ الْأَسْلَمِيِّ', 'റസൂൽ(സ)യുടെ അനുചരനായ സിനാനുബ്നു സന്നതൽ അസ്ലമി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 73, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ أُمِّ عُمَارَةَ بِنْتِ كَعْبٍ الْأَنْصَارِيَّةِ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا فَقَدَّمَتْ إِلَيْهِ طَعَامًا، فَقَالَ: "كُلِي". فَقَالَتْ: إِنِّي صَائِمَةٌ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الصَّائِمَ تُصَلِّي عَلَيْهِ الْمَلَائِكَةُ إِذَا أُكِلَ عِنْدَهُ حَتَّى يَفْرُغُوا". وَرُبَّمَا قَالَ: "حَتَّى يَشْبَعُوا". حَسَنٌ صَحِيحٌ. (ت)', 'ഉമ്മുഉമാറ ബിൻത് കഅ്ബുൽ അൻസാരിയ്യ(റ): തിരുനബി(സ) അവരുടെ അടുത്ത് ചെന്നപ്പോൾ അവർ റസൂൽ(സ)ക്ക് ഭക്ഷണം വിളമ്പി. തിരുനബി(സ) പറഞ്ഞു: "നീ ഭക്ഷിക്കൂ." അവർ പറഞ്ഞു: ഞാൻ നോമ്പുകാരിയാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നോമ്പുകാരന്റെ അടുത്തുനിന്ന് ഭക്ഷിച്ചാൽ അവൻ വിരമിക്കും വരെ മലക്കുകൾ നോമ്പുകാരനുവേണ്ടി പ്രാർത്ഥിക്കും." ഒരുപക്ഷേ ഇങ്ങനെയാകും തിരുനബി(സ) പറഞ്ഞത്: "അവന്റെ (ഭക്ഷിക്കുന്നവന്റെ) വയറുനിറയും വരെ." (തു)', 'أُمِّ عُمَارَةَ بِنْتِ كَعْبٍ الْأَنْصَارِيَّةِ', 'ഉമ്മുഉമാറ ബിൻത് കഅ്ബുൽ അൻസാരിയ്യ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 74, 74, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أُمِّ عُمَارَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَرَّبْنَا إِلَيْهِ طَعَامًا، فَكَانَ بَعْضُ مَنْ عِنْدَهُ صَائِمًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الصَّائِمُ إِذَا أُكِلَ عِنْدَهُ الطَّعَامُ صَلَّتْ عَلَيْهِ الْمَلَائِكَةُ". (ت,جه)', 'ഉമ്മുഉമാറ(റ): റസൂൽ(സ) ഞങ്ങളുടെ അടുത്തുവന്നപ്പോൾ അവിടത്തേക്ക് ഞങ്ങൾ ഭക്ഷണം വിളമ്പി. അവിടത്തോടൊപ്പം ചില നോമ്പുകാരും ഉണ്ടായിരുന്നു. അപ്പോൾ തിരുനബി(സ) പറഞ്ഞു: "നോമ്പുകാരന്റെ സമീപത്ത് വെച്ച് ആരെങ്കിലും ഭക്ഷണം കഴിച്ചാൽ നോമ്പുകാരനുവേണ്ടി മലക്കുകൾ പ്രാർത്ഥിക്കും." (തു,ജ)', 'أُمِّ عُمَارَةَ', 'ഉമ്മുഉമാറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 74, 74, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِبِلَالٍ: "الْغَدَاءَ يَا بِلَالُ". فَقَالَ: إِنِّي صَائِمٌ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَأْكُلُ أَرْزَاقَنَا، وَفَضْلُ رِزْقِ بِلَالٍ فِي الْجَنَّةِ. أَشَعَرْتَ - يَا بِلَالُ - أَنَّ الصَّائِمَ تُسَبِّحُ عِظَامُهُ وَتَسْتَغْفِرُ لَهُ الْمَلَائِكَةُ مَا أُكِلَ عِنْدَهُ". [ز: في إسناده راو متفق علي تضعيفه] (جه)', 'ബുറൈദ(റ): റസൂൽ(സ) ബിലാലി(റ)നോട് പറഞ്ഞു: "ബിലാലെ, പ്രഭാതഭക്ഷണം എടുക്കൂ." അദ്ദേഹം പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. റസൂൽ(സ) പറഞ്ഞു: "നമ്മുടെ ഭക്ഷണം നാം കഴിക്കുന്നു. ബിലാലിന്റെ ഭക്ഷണം സ്വർഗത്തിൽ അവശേഷിക്കുന്നു. ബിലാലെ, നിനക്കറിയുമോ, നോമ്പുകാരന്റെ സമീപത്തുവെച്ച് ഭക്ഷണം കഴിച്ച് കൊണ്ടിരിക്കുന്ന സമയത്തോളം, അവന്റെ എല്ലുകൾ തസ്ബീഹ് ചൊല്ലുകയും മലക്കുകൾ അവനുവേണ്ടി മാപ്പിരക്കുകയും ചെയ്യും." (ഇതിന്റെ പരമ്പരയിൽ ഏകോപിതമായി ദൗർബല്യം ആരോപിക്കപ്പെട്ട ഒരു വ്യക്തിയുണ്ട്). (ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده راو متفق علي تضعيفه', null, 74, 74, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا دُعِيَ أَحَدُكُمْ فَلْيُجِبْ، فَإِنْ كَانَ مُفْطِرًا فَلْيَطْعَمْ، وَإِنْ كَانَ صَائِمًا فَلْيُصَلِّ". (م,د,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ സദ്യക്കു ക്ഷണിക്കപ്പെട്ടാൽ ക്ഷണം സ്വീകരിക്കുക. നോമ്പില്ലാത്തവനാണെങ്കിൽ ഭക്ഷണം കഴിക്കുക. നോമ്പുകാരനാണെങ്കിൽ പ്രാർത്ഥിക്കുക." (മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 74, 74, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا دُعِيَ أَحَدُكُمْ وَهُوَ صَائِمٌ فَلْيَقُلْ: إِنِّي صَائِمٌ". حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നോമ്പുകാരൻ സദ്യക്ക് ക്ഷണിക്കപ്പെട്ടാൽ ഞാൻ നോമ്പുകാരനാണെന്ന് അവൻ മറുപടി പറയട്ടെ." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 74, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ دُعِيَ إِلَى طَعَامٍ وَهُوَ صَائِمٌ فَلْيُجِبْ، فَإِنْ شَاءَ طَعِمَ وَإِنْ شَاءَ تَرَكَ". (م,جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "സദ്യക്കുള്ള ക്ഷണം നോമ്പുകാരൻ സ്വീകരിക്കണം. അവനുദ്ദേശിച്ചാൽ ഭക്ഷണം കഴിക്കാം. അല്ലെങ്കിൽ ഉപേക്ഷിക്കാം." (മു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 75, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ حَتَّى نَقُولَ لَا يُفْطِرُ، وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ. وَمَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَكْمَلَ صِيَامَ شَهْرٍ قَطُّ إِلَّا رَمَضَانَ، وَمَا رَأَيْتُهُ فِي شَهْرٍ أَكْثَرَ صِيَامًا مِنْهُ فِي شَعْبَانَ. (خ,د,ن,جه)', 'ആഇശ(റ): തിരുമേനി(സ) ഇനി നോമ്പുപേക്ഷിക്കില്ല എന്ന് ഞങ്ങൾ പറയുംവരെ റസൂൽ(സ) നോമ്പെടുക്കാറുണ്ടായിരുന്നു. ഇനി നോമ്പെടുക്കില്ല എന്ന് ഞങ്ങൾ പറയും വരെ റസൂൽ(സ) നോമ്പ് ഒഴിവാക്കിയിരുന്നു. റമളാനിലൊഴികെ ഒരു മാസം പൂർണമായും റസൂൽ(സ) നോമ്പെടുക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല. ശഅ്ബാനിലേതിനേക്കാൾ കൂടുതലായി മറ്റൊരു മാസത്തിൽ റസൂൽ(സ) നോമ്പെടുക്കുന്നതും ഞാൻ കണ്ടിട്ടില്ല. (ബു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 75, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا فِي رِوَايَةٍ زِيَادَةٌ وَكَانَ يَقُولُ: "خُذُوا مِنَ الْعَمَلِ مَا تُطِيقُونَ، فَإِنَّ اللَّهَ لَا يَمَلُّ حَتَّى تَمَلُّوا". وَأَحَبُّ الصَّلَاةِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا دُووِمَ عَلَيْهِ وَإِنْ قَلَّتْ، وَكَانَ إِذَا صَلَّى صَلَاةً دَاوَمَ عَلَيْهَا. (خ)', 'ആഇശ(റ)യിൽ നിന്നുള്ള മറ്റൊരു റിപ്പോർട്ട്: തിരുമേനി(സ) ഇങ്ങനെ പറയാറുണ്ടായിരുന്നു. "നിങ്ങളുടെ കഴിവിനനുസരിച്ചുള്ള ആരാധനാകർമ്മങ്ങൾ മാത്രം സ്വീകരിക്കുക. നിങ്ങൾക്കു മടുപ്പു തോന്നാത്ത കാലം വരെയും അല്ലാഹുവിനും മടുപ്പു തോന്നുകയില്ല." പതിവായി അനുവർത്തിക്കുന്ന ആരാധനകളാണ് തിരുമേനി(സ)ക്ക് ഇഷ്ടം. അതെത്ര ചുരുങ്ങിയാലും. ഒരു നിസ്കാരം തുടങ്ങിവെച്ചാൽ തിരുമേനി(സ) അതു പതിവാക്കാറുണ്ടായിരുന്നു. (ബു.)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 75, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=104), 1, null, 'മറ്റൊരു നിവേദന്: തിരുമേനി(സ) ഇങ്ങനെ പറയാറുണ്ടായിരുന്നു. "നിങ്ങളുടെ കഴിവിനനുസരിച്ചുള്ള ആരാധനാകർമ്മങ്ങൾ മാത്രം സ്വീകരിക്കുക. നിങ്ങൾക്കു മടുപ്പു തോന്നാത്ത കാലം വരെയും അല്ലാഹുവിനും മടുപ്പു തോന്നുകയില്ല." പതിവായി അനുവർത്തിക്കുന്ന ആരാധനകളാണ് തിരുമേനി(സ)ക്ക് ഇഷ്ടം. അതെത്ര ചുരുങ്ങിയാലും. ഒരു നിസ്കാരം തുടങ്ങിവെച്ചാൽ തിരുമേനി(സ) അതു പതിവാക്കാറുണ്ടായിരുന്നു. (ബു.)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْوِصَالِ فِي الصَّوْمِ، فَقَالَ لَهُ رَجُلٌ مِنَ الْمُسْلِمِينَ: إِنَّكَ تُوَاصِلُ يَا رَسُولَ اللَّهِ، قَالَ: "وَأَيُّكُمْ مِثْلِي إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي وَيَسْقِينِ"، فَلَمَّا أَبَوْا أَنْ يَنْتَهُوا عَنِ الْوِصَالِ وَاصَلَ بِهِمْ يَوْمًا ثُمَّ يَوْمًا ثُمَّ رَأَوُا الْهِلَالَ، فَقَالَ: "لَوْ تَأَخَّرَ لَزِدْتُكُمْ". كَالتَّنْكِيلِ لَهُمْ حِينَ أَبَوْا أَنْ يَنْتَهُوا، وَفِي رِوَايَةٍ عَنْهُ قَالَ لَهُمْ: "فَاكْلَفُوا مِنَ الْعَمَلِ مَا تُطِيقُونَ". (ق)', 'അബൂഹുറൈറ(റ): നോമ്പുമുറിക്കാതെ തുടർച്ചയായി നോമ്പ് അനുഷ്ഠിക്കുന്നത് റസൂൽ(സ) നിരോധിച്ചു. മുസ്ലിംകളിൽപെട്ട ഒരു വ്യക്തി റസൂൽ(സ)യോടു ചോദിച്ചു: ദൈവദൂതരേ, അവിടന്ന് വ്രതങ്ങൾ ചേർത്ത് അനുഷ്ഠിക്കുന്നുല്ലോ. റസൂൽ(സ) പ്രതിവചിച്ചു: "എന്നെപ്പോലെ നിങ്ങളിൽ ആരുണ്ട്? ഞാൻ രാത്രി ഉറങ്ങുമ്പോൾ എന്റെ നാഥൻ എനിക്ക് ആഹാരവും പാനീയവും നൽകുന്നു." അവർക്ക് അതിൽനിന്നു വിരമിക്കാൻ മനസ്സില്ലെന്നു കണ്ടപ്പോൾ അവരെയും കൂട്ടി തിരുമേനി(സ) രണ്ടുദിവസം നോമ്പനുഷ്ഠിച്ചു. പിന്നീടവർ ചന്ദ്രപ്പിറവി കണ്ടു. "മാസപ്പിറവി കാണാൻ വൈകിയിരുന്നെങ്കിൽ ഇതിലുമധികം ദിവസം നിങ്ങൾക്കു ഞാൻ നോമ്പുണ്ടാക്കിത്തരുമായിരുന്നു"വെന്ന് തിരുമേനി(സ) പറഞ്ഞു. ഒരു പകലിലധികം നോമ്പനുഷ്ഠിക്കരുതെന്നു തിരുമേനി(സ) അരുളിയത് അവർ കൂട്ടാക്കാതിരുന്നതിൽ പ്രതിഷേധമെന്ന നിലക്കാണ് റസൂൽ(സ) ഇതു പറഞ്ഞത്. അബൂഹുറൈറ(റ)വിൽനിന്നുള്ള മറ്റൊരു ഉദ്ധരണിയിൽ ഇങ്ങനെ വന്നിട്ടുണ്ട്: "നിങ്ങളുടെ കഴിവനുസരിച്ചുള്ള സൽകർമ്മങ്ങളുടെ ബാധ്യത മാത്രം നിങ്ങളേറ്റെടുക്കുക." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 75, 76, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=105), 1, 'وَفِي رِوَايَةٍ عَنْهُ قَالَ لَهُمْ: "فَاكْلَفُوا مِنَ الْعَمَلِ مَا تُطِيقُونَ". (ق)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِي رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تُوَاصِلُوا، فَأَيُّكُمْ إِذَا أَرَادَ أَنْ يُوَاصِلَ فَلْيُوَاصِلْ حَتَّى السَّحَرِ". قَالُوا: فَإِنَّكَ تُوَاصِلُ؟ قَالَ: "إِنِّي لَسْتُ كَهَيْئَتِكُمْ، إِنَّ لِي مُطْعِمًا يُطْعِمُنِي وَسَاقِيًا يَسْقِينِي". (خ,د)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "നിങ്ങൾ തുടർച്ചയായി നോമ്പനുഷ്ഠിക്കരുത്. ആരെങ്കിലും നോമ്പുമുറിക്കാതെ തുടരാനുദ്ദേശിക്കുകയാണെങ്കിൽ അത്താഴസമയം വരെ അവൻ തുടർന്നുകൊള്ളട്ടെ." അവർ ചോദിച്ചു: അവിടുന്ന് വ്രതം മുറിക്കാതെ തുടരുന്നല്ലോ? തിരുമേനി(സ) മറുപടി പറഞ്ഞു: "ഞാൻ നിങ്ങളെപ്പോലെയല്ല. തീർച്ചയായും എനിക്ക് കുടിപ്പിക്കുന്നവനും ഭക്ഷിപ്പിക്കുന്നവനുമുണ്ട്." (ബു,ദ)', 'أَبِي سَعِيدٍ الْخُدْرِي', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 76, 76, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُوَاصِلُوا". قَالُوا: فَإِنَّكَ تُوَاصِلُ يَا رَسُولَ اللَّهِ، قَالَ: "إِنِّي لَسْتُ كَأَحَدِكُمْ، إِنَّ رَبِّي يُطْعِمُنِي وَيَسْقِينِي". (ق,ت)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ തുടർച്ചയായി നോമ്പനുഷ്ഠിക്കരുത്." അവർ ചോദിച്ചു: റസൂലേ, അങ്ങ് തുടർച്ചയായി നോമ്പനുഷ്ഠിക്കുന്നുവല്ലോ? റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങളെപ്പോലെയല്ല, എന്റെ റബ്ബ് എനിക്ക് ഭക്ഷണവും വെള്ളവും നൽകുന്നു." (ബു,മു,തു,)', 'أَنَسٍ قَالَ', 'അനസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 76, 76, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ شَهْرَيْنِ مُتَتَابِعَيْنِ إِلَّا شَعْبَانَ وَرَمَضَانَ. حَسَنٌ. (د,ت,ن)', 'ഉമ്മുസലമ(റ): റമളാൻ മാസവും ശഅബാൻ മാസവുമൊഴികെ തുടർച്ചയായി രണ്ടുമാസം റസൂൽ(സ) വ്രതമനുഷ്ഠിച്ചതായി ഞാൻ കണ്ടിട്ടില്ല. (ദ,തു,ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 76, 76, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، وَقَدْ سُئِلَتْ عَنْ صِيَامِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَتْ: كَانَ يَصُومُ شَعْبَانَ كُلَّهُ حَتَّى يَصِلَهُ بِرَمَضَانَ. (ت,ن,جه)', 'ആഇശ(റ): പ്രവാചകരു(സ)ടെ വ്രതത്തെ കുറിച്ച് ചോദിക്കപ്പെട്ടപ്പോൾ മഹതി പ്രതിവചിച്ചു. റമളാൻ മാസത്തോട് ചേർക്കുവോളം ശഅബാൻ മുഴുവൻ തിരുമേനി(സ) നോമ്പ് അനുഷ്ഠിച്ചിരുന്നു. (തു,ന,ജ.)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 76, 76, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: آخَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ سَلْمَانَ وَأَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُمَا فَزَارَ سَلْمَانُ أَبَا الدَّرْدَاءِ، فَرَأَى أُمَّ الدَّرْدَاءِ مُتَبَذِّلَةً، فَقَالَ لَهَا: مَا شَأْنُكِ؟ قَالَتْ: أَخُوكَ أَبُو الدَّرْدَاءِ لَيْسَ لَهُ حَاجَةٌ فِي الدُّنْيَا، فَجَاءَ أَبُو الدَّرْدَاءِ فَصَنَعَ لَهُ طَعَامًا، فَقَالَ: كُلْ، قَالَ: فَإِنِّي صَائِمٌ، قَالَ: مَا أَنَا بِآكِلٍ حَتَّى تَأْكُلَ، فَأَكَلَ. فَلَمَّا كَانَ اللَّيْلُ ذَهَبَ أَبُو الدَّرْدَاءِ يَقُومُ، قَالَ: نَمْ فَنَامَ، ثُمَّ ذَهَبَ يَقُومُ، فَقَالَ: نَمْ، فَلَمَّا كَانَ مِنْ آخِرِ اللَّيْلِ قَالَ سَلْمَانُ: قُمِ الْآنَ، فَصَلَّيَا، فَقَالَ لَهُ سَلْمَانُ: إِنَّ لِرَبِّكَ عَلَيْكَ حَقًّا، وَلِنَفْسِكَ عَلَيْكَ حَقًّا، وَلِأَهْلِكَ عَلَيْكَ حَقًّا، فَأَعْطِ كُلَّ ذِي حَقٍّ حَقَّهُ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "صَدَقَ سَلْمَانُ". (خ)', 'അബുജുഹൈഫ(റ): സൽമാൻ(റ), അബുദ്ദർദാഅ്(റ) എന്നിവർക്കിടയിൽ തിരുമേനി(സ) സാഹോദര്യ ബന്ധം സ്ഥാപിച്ചു. സൽമാൻ(റ) അബുദ്ദർദാഅ്(റ)വിനെ സന്ദർശിച്ചു. അപ്പോൾ ഉമ്മുദർദാഅ് മോടിയിലും സൗന്ദര്യത്തിലും ശ്രദ്ധിക്കാത്തതായി അദ്ദേഹം കണ്ടു. നിങ്ങൾക്കെന്തുപറ്റി? അദ്ദേഹം അന്വേഷിച്ചു. താങ്കളുടെ സഹോദരൻ അബുദ്ദർദാഅ്(റ)ന് ഐഹിക കാര്യങ്ങളിൽ യാതൊരു പ്രതിപത്തിയുമില്ല എന്നവർ മറുപടി പറഞ്ഞു. അതിനിടക്ക് അബുദ്ദർദാഅ്(റ) വന്നു. ഉടനെ അദ്ദേഹത്തിനു ഭക്ഷണം തയ്യാറാക്കി. സൽമാൻ(റ) പറഞ്ഞു: നിങ്ങളും കഴിച്ചുകൊള്ളുക. അബുദ്ദർദാഅ്(റ) പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. സൽമാൻ(റ) പറഞ്ഞു: നിങ്ങൾ തിന്നാതെ ഞാൻ തിന്നൂല. അപ്പോൾ അബുദ്ദർദാഅ്(റ) തിന്നു. രാത്രിയായപ്പോൾ അബുദ്ദർദാഅ്(റ) നിസ്കരിക്കാൻ തുടങ്ങി. താങ്കൾ പോയി കിടന്നുറങ്ങുക എന്ന് സൽമാനുപദേശിച്ചു. അപ്പോഴദ്ദേഹം പോയി കിടന്നുറങ്ങി. വീണ്ടും എഴുന്നേറ്റ് നിസ്കരിക്കാൻ തുടങ്ങി. പോയി കിടന്നുറങ്ങുക എന്ന് സൽമാനുപദേശിച്ചു. രാത്രിയുടെ അന്ത്യയാമങ്ങളിൽ അദ്ദേഹം അബുദ്ദർദാഇനെ വിളിച്ചു പറഞ്ഞു: ഇപ്പോൾ എഴുന്നേറ്റു നിസ്കരിക്കുക. അങ്ങനെ അവരൊന്നിച്ചു നിസ്കരിച്ചു. തുടർന്ന് സൽമാൻ(റ) പറഞ്ഞു: നിങ്ങൾക്ക് നിങ്ങളുടെ നാഥനോട് ഒരു കടപ്പാടുണ്ട്. നിങ്ങൾക്ക് നിങ്ങളുടെ ശരീരത്തോട് ഒരു കടപ്പാടുണ്ട്. നിങ്ങൾക്ക് നിങ്ങളുടെ ഭാര്യയോട് ഒരു കടപ്പാടുണ്ട്. അതിനാൽ എല്ലാവരോടുമുള്ള കടപ്പാടുകൾ നിറവേറ്റുക. സൽമാൻ(റ) തിരുമേനി(സ)യുടെ സന്നിധിയിൽ ചെന്ന് വിവരങ്ങൾ പറഞ്ഞു. "സൽമാൻ(റ) പറഞ്ഞത് സത്യമെ"ന്ന് അവിടന്ന് പ്രതികരിച്ചു. (ബു)', 'أَبِي جُحَيْفَةَ', 'അബുജുഹൈഫ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 76, 77, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَلَغَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنِّي أَصُومُ أَسْرُدُ، وَأُصَلِّي اللَّيْلَ، فَإِمَّا أَرْسَلَ إِلَيَّ وَإِمَّا لَقِيتُهُ، فَقَالَ: "أَلَمْ أُخْبَرْ أَنَّكَ تَصُومُ وَلَا تُفْطِرُ وَتُصَلِّي اللَّيْلَ؟ فَلَا تَفْعَلْ، فَإِنَّ لِعَيْنِكَ حَظًّا، وَلِنَفْسِكَ حَظًّا، وَلِأَهْلِكَ حَظًّا. فَصُمْ وَأَفْطِرْ، وَصَلِّ وَنَمْ، وَصُمْ مِنْ كُلِّ عَشَرَةِ أَيَّامٍ يَوْمًا، وَلَكَ أَجْرُ تِسْعَةٍ". قَالَ: إِنِّي أَجِدُنِي أَقْوَى مِنْ ذَلِكَ يَا نَبِيَّ اللَّهِ، قَالَ: "فَصُمْ صِيَامَ دَاوُدَ عَلَيْهِ السَّلَامُ". قَالَ: وَكَيْفَ كَانَ دَاوُدُ يَصُومُ يَا نَبِيَّ اللَّهِ؟ قَالَ: "كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا، وَلَا يَفِرُّ إِذَا لَاقَى". قَالَ: مَنْ لِي بِهَذِهِ يَا نَبِيَّ اللَّهِ؟. قَالَ عَطَاءٌ: فَلَا أَدْرِي كَيْفَ ذَكَرَ صِيَامَ الْأَبَدِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا صَامَ مَنْ صَامَ الْأَبَدَ، لَا صَامَ مَنْ صَامَ الْأَبَدَ". (م,ن)', 'അബ്ദുല്ലാഹിബ്നു അംരിബ്നിൽ ആസ്(റ): ഞാൻ രാത്രിയിൽ നിസ്കരിക്കുകയും തുടർച്ചയായി നോമ്പനുഷ്ഠിക്കുകയും ചെയ്യുന്നകാര്യം നബി(സ) അറിഞ്ഞു. അങ്ങനെയിരിക്കെ എന്റെയടുത്തേക്ക് ആളെ അയച്ചു, അല്ലെങ്കിൽ ഞാനുമായി കണ്ടുമുട്ടി. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ തുടർച്ചയായി മുറിക്കാതെ നോമ്പനുഷ്ഠിക്കുകയും, രാത്രി നിസ്കരിക്കുകയും ചെയ്യുന്നതായി അറിഞ്ഞു. അപ്രകാരം ചെയ്യരുത്. നിങ്ങളുടെ കണ്ണിനും ശരീരത്തിനും കുടുംബത്തിനും ചില കടപ്പാടുകളുണ്ട്. അതുകൊണ്ട് നോമ്പനുഷ്ഠിക്കുകയും മുറിക്കുകയും ചെയ്യുക, നിസ്കരിക്കുകയും ഉറങ്ങുകയും ചെയ്യുക. എല്ലാ പത്ത് ദിവസത്തിലും ഒരു ദിവസം നോമ്പനുഷ്ഠിക്കുക. എന്നാൽ ബാക്കി ഒൻപതിന്റെയും പ്രതിഫലം നിങ്ങൾക്ക് ലഭിക്കും." അബ്ദുല്ലാ(റ) പറഞ്ഞു: എനിക്കതിലേറെ ചെയ്യാൻ കഴിവുണ്ട്, പ്രവാചകരെ. നബി(സ) പറഞ്ഞു: "എന്നാൽ നിങ്ങൾ ദാവൂദ്നബി(അ)ന്റെ നോമ്പനുഷ്ഠിക്കുക." അദ്ദേഹം ചോദിച്ചു. ദാവൂദ്(അ)ന്റെ നോമ്പ് എപ്രകാരമാണ്, പ്രവാചകരെ. നബി(സ) പറഞ്ഞു: "ഒരു ദിവസം നോമ്പനുഷ്ഠിക്കുകയും, അടുത്ത ദിവസം നോമ്പുപേക്ഷിക്കുകയും ചെയ്യും. ശത്രുവിനെ കണ്ടാൽ അദ്ദേഹം പിൻമാറില്ല." അബ്ദുല്ലാ(റ) പറഞ്ഞു: പ്രവാചകരെ, ആരാണ് എനിക്കിതുകൊണ്ട് ജാമ്യം നിൽക്കുക. അത്വാഅ്(റ) പറയുന്നു: കാലം മുഴുവൻ നോമ്പനുഷ്ഠിക്കുന്നതിനെക്കുറിച്ച് റസൂൽ(സ) എന്തുകൊണ്ടാണ് പറഞ്ഞതെന്ന് എനിക്കറിയില്ല. നബി(സ) പറഞ്ഞു: "കാലം മുഴുവൻ നോമ്പനുഷ്ഠിക്കുന്നവർക്ക് നോമ്പില്ല. കാലം മുഴുവൻ നോമ്പനുഷ്ഠിക്കുന്നവർ നോമ്പനുഷ്ഠിച്ചിട്ടില്ല." (മു,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംരിബ്നിൽ ആസ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 77, 77, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ عَبْدِ اللَّهِ بْنِ شَقِيقٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قُلْتُ لِعَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ شَهْرًا كُلَّهُ؟ قَالَتْ: مَا عَلِمْتُهُ صَامَ شَهْرًا كُلَّهُ إِلَّا رَمَضَانَ، وَلَا أَفْطَرَهُ كُلَّهُ حَتَّى يَصُومَ مِنْهُ، حَتَّى مَضَى لِسَبِيلِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م)', 'അബ്ദുല്ലാഹിബ്നു ശഖീഖ്(റ): ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചു: മാസം മുഴുവൻ നബി(സ) നോമ്പ് അനുഷ്ഠിച്ചിരുന്നോ? അവർ മറുപടി നൽകി: റമളാനിലല്ലാതെ നബി(സ) മാസം മുഴുവനും നോമ്പെടുത്തതായി എനിക്കറിയില്ല. ഒരു മാസവും നോമ്പെടുക്കാതിരുന്നിട്ടുമില്ല. വിയോഗം വരെ അങ്ങനെയായിരുന്നു. (മു.)', 'عَبْدِ اللَّهِ بْنِ شَقِيقٍ', 'അബ്ദുല്ലാഹിബ്നു ശഖീഖ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 77, 78, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، كَيْفَ تَصُومُ؟ فَغَضِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ قَوْلِهِ، فَلَمَّا رَأَى ذَلِكَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَضِينَا بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ نَبِيًّا، نَعُوذُ بِاللَّهِ مِنْ غَضَبِ اللَّهِ وَغَضَبِ رَسُولِهِ. فَلَمْ يَزَلْ عُمَرُ رَضِيَ اللَّهُ عَنْهُ يُرَدِّدُهَا حَتَّى سَكَنَ غَضَبُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ، كَيْفَ بِمَنْ يَصُومُ الدَّهْرَ كُلَّهُ؟ قَالَ: "لَا صَامَ وَلَا أَفْطَرَ. أَوْ: لَمْ يَصُمْ وَلَمْ يُفْطِرْ. أَوْ: مَا صَامَ وَلَا أَفْطَرَ". قَالَ: يَا رَسُولَ اللَّهِ، كَيْفَ بِمَنْ يَصُومُ يَوْمَيْنِ وَيُفْطِرُ يَوْمًا؟ قَالَ: "أَوَ يُطِيقُ ذَلِكَ أَحَدٌ". قَالَ: يَا رَسُولَ اللَّهِ، فَكَيْفَ بِمَنْ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا؟ قَالَ: "ذَلِكَ صَوْمُ دَاوُدَ عَلَيْهِ السَّلَامُ". قَالَ: يَا رَسُولَ اللَّهِ، فَكَيْفَ بِمَنْ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمَيْنِ؟ قَالَ: "وَدِدْتُ أَنِّي طُوِّقْتُ ذَلِكَ". ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثٌ مِنْ كُلِّ شَهْرٍ، وَرَمَضَانُ إِلَى رَمَضَانَ، فَهَذَا صِيَامُ الدَّهْرِ كُلِّهِ. وَصِيَامُ عَرَفَةَ: إِنِّي أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ وَالسَّنَةَ الَّتِي بَعْدَهُ. وَصَوْمُ يَوْمِ عَاشُورَاءَ: إِنِّي أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ". وَفِي رِوَايَةٍ: قَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ صَوْمَ يَوْمِ الِاثْنَيْنِ وَيَوْمِ الْخَمِيسِ؟ قَالَ: "فِيهِ وُلِدْتُ، وَفِيهِ أُنْزِلَ عَلَيَّ الْقُرْآنُ". (ق,د,ت,ن,جه)', 'അബൂഖതാദ(റ): ഒരിക്കൽ നബി(സ)യുടെ അടുക്കൽ വന്ന് ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എങ്ങനെയാണ് അവിടന്ന് നോമ്പെടുക്കാറുള്ളത്? അദ്ദേഹത്തിന്റെ ചോദ്യം കാരണം നബി(സ) കോപിച്ചു. നബി(സ) ദേഷ്യപ്പെട്ടതു കണ്ടപ്പോൾ ഉമർ(റ) പറഞ്ഞു: ഞങ്ങൾ അല്ലാഹുവിനെ രക്ഷിതാവായും ഇസ്ലാമിനെ മതമായും മുഹമ്മദ് നബി(സ)യെ നബിയായും തൃപ്തിപ്പെട്ടിരിക്കുന്നു. അല്ലാഹുവിന്റെ കോപത്തിൽനിന്നും അവന്റെ പ്രവാചകന്റെ കോപത്തിൽനിന്നും ഞങ്ങൾ അല്ലാഹുവിങ്കൽ അഭയം തേടുന്നു. നബി(സ)യുടെ കോപം അവസാനിക്കുംവരെ ഉമർ(റ) ഇത് ആവർത്തിച്ചു. ശേഷം ഉമർ(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, കാലാകാലം നോമ്പെടുക്കുന്നവന്റെ അവസ്ഥയെന്താണ്? നബി(സ) പറഞ്ഞു: "അവർ നോമ്പെടുക്കുകയോ, നോമ്പ് തുറക്കുകയോ ചെയ്തിട്ടില്ല. അല്ലെങ്കിൽ നോമ്പനുഷ്ഠിക്കുകയോ മുറിക്കുകയോ ചെയ്തിട്ടില്ല." ഉമർ(റ) ചോദിച്ചു: രണ്ട് ദിവസം നോമ്പെടുക്കുകയും ഒരു ദിവസം നോമ്പെടുക്കാതിരിക്കുകയും ചെയ്യുന്നവന്റെ അവസ്ഥയെന്താണ്? നബി(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും അത് സാധിക്കുമോ?" ഉമർ(റ) ചോദിച്ചു: ഒരു ദിവസം നോമ്പെടുക്കുകയും ഒരു ദിവസം നോമ്പ് എടുക്കാതിരിക്കുകയും ചെയ്യുന്നവന്റെ അവസ്ഥയെന്താണ്? നബി(സ) പറഞ്ഞു: "അതാണ് ദാവൂദ് നബി(അ)യുടെ നോമ്പ്." ഉമർ(റ) ചോദിച്ചു: ഒരു ദിവസം നോമ്പെടുത്ത് രണ്ടു ദിനങ്ങൾ നോമ്പെടുക്കാതിരിക്കുന്നവന്റെ അവസ്ഥയോ? നബി(സ) പറഞ്ഞു: "അങ്ങനെ ചെയ്യാൻ എനിക്ക് സാധിക്കട്ടെ എന്ന് ഞാൻ ആഗ്രഹിക്കുന്നു." തുടർന്ന് നബി(സ) പറഞ്ഞു: "ഓരോ മാസവും മൂന്ന് ദിവസങ്ങളും റമദാൻ മാസവും നോമ്പെടുത്താൽ അത് എല്ലാ കാലത്തും നോമ്പെടുത്തതിന് തുല്യമാണ്. അറഫയുടെ നോമ്പെടുത്താൽ അതിനു മുമ്പും പിമ്പുമുള്ള വർഷങ്ങളിലെ പാപങ്ങൾ അല്ലാഹു പൊറുത്തുകൊടുക്കുമെന്ന് ഞാൻ വിചാരിക്കുന്നു. ആശൂറാഅ് നോമ്പെടുത്താൽ മുമ്പുള്ള ഒരു വർഷത്തെ പാപം അല്ലാഹു പൊറുത്തുകൊടുക്കുമെന്നു ഞാൻ പ്രതീക്ഷിക്കുന്നു."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=113), 1, 'وَفِي رِوَايَةٍ: قَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ صَوْمَ يَوْمِ الِاثْنَيْنِ وَيَوْمِ الْخَمِيسِ؟ قَالَ: "فِيهِ وُلِدْتُ، وَفِيهِ أُنْزِلَ عَلَيَّ الْقُرْآنُ". (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: ഉമർ(റ) ചോദിച്ചു: തിങ്കളാഴ്ചയിലെയും വ്യാഴാഴ്ചയിലെയും നോമ്പിനെപ്പറ്റി അവിടന്ന് എന്തുപറയുന്നു? നബി(സ) പറഞ്ഞു: "അന്നേദിവസമാണ് ഞാൻ ജനിച്ചത്. എനിക്ക് ഖുർആൻ അവതരിച്ചതും അന്നാണ്." (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَقِيَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "أَلَمْ أُحَدَّثْ أَنَّكَ تَقُولُ: لَأَقُومَنَّ اللَّيْلَ، وَلَأَصُومَنَّ النَّهَارَ". قَالَ: نَعَمْ يَا رَسُولَ اللَّهِ، قَدْ قُلْتُ ذَاكَ. قَالَ: "قُمْ وَنَمْ، وَصُمْ وَأَفْطِرْ، وَصُمْ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ، وَذَاكَ مِثْلُ صِيَامِ الدَّهْرِ". قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ؟ قَالَ: "فَصُمْ يَوْمًا وَأَفْطِرْ يَوْمَيْنِ". قَالَ: فَقُلْتُ: إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ؟ قَالَ: "فَصُمْ يَوْمًا وَأَفْطِرْ يَوْمًا، وَهُوَ أَعْدَلُ الصِّيَامِ، وَهُوَ صِيَامُ دَاوُدَ". قُلْتُ: إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا أَفْضَلَ مِنْ ذَلِكَ". (ق,د,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) എന്നെ കണ്ടുമുട്ടിയപ്പോൾ ചോദിച്ചു: "രാത്രിമുഴുവൻ നിസ്കരിക്കുമെന്നും പകൽമുഴുവൻ നോമ്പെടുക്കുമെന്നും നിങ്ങൾ പറഞ്ഞതായി എനിക്ക് വിവരം കിട്ടിയല്ലോ?" അദ്ദേഹം പറഞ്ഞു: അതെ, റസൂലെ, ഞാനങ്ങനെ പറഞ്ഞിരുന്നു. നബി(സ) പറഞ്ഞു: "നിസ്കരിക്കുകയും ഉറങ്ങുകയും ചെയ്യുക. നോമ്പെടുക്കുകയും നോമ്പെടുക്കാതിരിക്കുകയും ചെയ്യുക. മാസത്തിൽ മൂന്ന് ദിവസം നോമ്പെടുക്കുക. അതു കാലം മുഴുവൻ നോമ്പെടുത്തതുപോലെയാണ്." അദ്ദേഹം പറയുന്നു: ഞാൻ പറഞ്ഞു: റസൂലെ, അതിനേക്കാൾ ചെയ്യാൻ എനിക്കാവും. നബി(സ) പറഞ്ഞു: "ഒരുദിവസം നോമ്പെടുത്ത് രണ്ടുദിവസം നോമ്പെടുക്കാതിരിക്കുക." അദ്ദേഹം പറയുന്നു: ഞാൻ പറഞ്ഞു: അതിനേക്കാൾ ചെയ്യാൻ എനിക്കാവും? നബി(സ) പറഞ്ഞു: "ഒരുദിവസം നോമ്പെടുത്ത് ഒരുദിവസം നോമ്പെടുക്കാതിരിക്കുക. അതാണ് മിതമായ നോമ്പ്. ദാവൂദ്(അ)മിന്റെ നോമ്പത്രെ അത്." ഞാൻ പറഞ്ഞു: അതിനേക്കാൾ ചെയ്യാൻ എനിക്കാവും? നബി(സ) പറഞ്ഞു: "അതിനേക്കാൾ ശ്രേഷ്ഠമായി ഒന്നുമില്ല." (ബു,മു,ദ,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 78, 79, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'وَقَالَ فِي هَذِهِ الرِّوَايَةِ، فَكَانَ عَبْدُ اللَّهِ يَقُولُ بَعْدَ مَا كَبِرَ: يَا لَيْتَنِي قَبِلْتُ رُخْصَةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ഈ നിവേദനത്തിൽ നിവേദകൻ പറയുന്നു: തിരുമേനി(സ)യുടെ ഇളവ് സ്വീകരിച്ചിരുന്നുവെങ്കിൽ എത്ര നന്നായിരുന്നു എന്ന് വാർദ്ധക്യം പ്രാപിച്ചശേഷം അബ്ദുല്ല(റ) പറയാറുണ്ടായിരുന്നു. (ബു.)', null, 'ഈ നിവേദനത്തിൽ നിവേദകൻ പറയുന്നു', null, null, array['خ']::text[], array['ബു']::text[], null, null, 79, 79, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "صُمْ يَوْمًا، وَلَكَ أَجْرُ مَا بَقِيَ". قَالَ: إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ. قَالَ: "صُمْ يَوْمَيْنِ، وَلَكَ أَجْرُ مَا بَقِيَ". قَالَ: إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ. قَالَ: "صُمْ ثَلَاثَةَ أَيَّامٍ، وَلَكَ أَجْرُ مَا بَقِيَ". قَالَ: إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ. قَالَ: "صُمْ أَرْبَعَةَ أَيَّامٍ، وَلَكَ أَجْرُ مَا بَقِيَ". قَالَ: إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ. قَالَ: "صُمْ أَفْضَلَ الصِّيَامِ عِنْدَ اللَّهِ، صَوْمَ دَاوُدَ عَلَيْهِ السَّلَامُ: كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "നീ ഒരു ദിവസം നോമ്പെടുക്കുക. ബാക്കിയുള്ളതിന്റെ കൂലി നിനക്കുകിട്ടും." അദ്ദേഹം പറഞ്ഞു: എനിക്ക് അതിനേക്കാൾ കഴിയും." നബി(സ) പറഞ്ഞു: "നീ രണ്ടുദിവസം നോമ്പെടുക്കുക, ബാക്കിയുള്ളതിന്റെ കൂലി നിനക്കുണ്ട്." അദ്ദേഹം പറഞ്ഞു: എനിക്ക് അതിനേക്കാൾ കഴിയും. നബി(സ) പറഞ്ഞു: "മൂന്നുദിവസം നോമ്പെടുക്കുക, ബാക്കിയുള്ളതിന്റെ പ്രതിഫലം നിനക്ക് കിട്ടും." അദ്ദേഹം പറഞ്ഞു: എനിക്ക് അതിനേക്കാളും കഴിയുമല്ലോ. നബി(സ) പറഞ്ഞു: "എന്നാൽ നാലുദിവസം നോമ്പെടുക്കുക, ബാക്കിയുള്ളതിന്റെ കൂലി കിട്ടും." അദ്ദേഹം പറഞ്ഞു: അതിനേക്കാൾ എനിക്കു കഴിയും. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിങ്കൽ ഏറ്റവും ശ്രേഷ്ഠമായ നോമ്പെടുക്കുക. അഥവാ, ദാവൂദ് നബി(അ)ന്റെ നോമ്പ്. അദ്ദേഹം ഒരുദിവസം നോമ്പെടുക്കുകയും ഒരു ദിവസം നോമ്പെടുക്കാതിരിക്കുകയുമായിരുന്നു പതിവ്." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 79, 79, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ حَمْزَةَ بْنَ عَمْرٍو الْأَسْلَمِيَّ - رَضِيَ اللَّهُ عَنْهُ - سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي رَجُلٌ أَسْرُدُ الصَّوْمَ، أَفَأَصُومُ فِي السَّفَرِ؟ قَالَ: "صُمْ إِنْ شِئْتَ، أَوْ أَفْطِرْ إِنْ شِئْتَ". (ن)', 'ആഇശ(റ): ഹംസതുബ്നു അംറുൽ അസ്ലമി(റ) നബി(സ)യോട് ചോദിച്ചു: പ്രവാചകരേ ഞാൻ എന്നും നോമ്പനുഷ്ഠിക്കുന്നവനാണ്. യാത്രയിലും ഞാൻ നോമ്പെടുക്കണോ? നബി(സ) പറഞ്ഞു: "നീ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ നോമ്പെടുക്കുക അല്ലെങ്കിൽ നോമ്പെടുക്കാതിരിക്കുക." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 79, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: ذَكَرْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّوْمَ، فَقَالَ: "صُمْ مِنْ كُلِّ عَشَرَةِ أَيَّامٍ يَوْمًا، وَلَكَ أَجْرُ تِلْكَ التِّسْعَةِ". فَقُلْتُ: إِنِّي أَقْوَى مِنْ ذَلِكَ. قَالَ: "صُمْ مِنْ كُلِّ تِسْعَةِ أَيَّامٍ يَوْمًا، وَلَكَ أَجْرُ تِلْكَ الثَّمَانِيَةِ". قُلْتُ: إِنِّي أَقْوَى مِنْ ذَلِكَ. قَالَ: "فَصُمْ مِنْ كُلِّ ثَمَانِيَةِ أَيَّامٍ يَوْمًا، وَلَكَ أَجْرُ تِلْكَ السَّبْعَةِ". قُلْتُ: إِنِّي أَقْوَى مِنْ ذَلِكَ. قَالَ: فَلَمْ يَزَلْ حَتَّى قَالَ: "صُمْ يَوْمًا وَأَفْطِرْ يَوْمًا". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ)യോട് വ്രതത്തെക്കുറിച്ച് ഞാൻ സംസാരിച്ചു. അവിടന്ന് അരുളി: "ഓരോ പത്തിലും ഒരു ദിവസം നീ വ്രതമെടുക്കുക, നിനക്കു ബാക്കി ഒമ്പതു ദിവസത്തിന്റെയും പ്രതിഫലം ലഭിക്കും." അപ്പോൾ ഞാൻ പറഞ്ഞു: ഞാൻ അതിനേക്കാൾ ശക്തനാണ്. നബി(സ) അരുളി: "ഒമ്പതിൽ ഒരു ദിവസം വ്രതമെടുക്കുക. ബാക്കി എട്ടിന്റെയും പ്രതിഫലം നിനക്കുണ്ട്." ഞാൻ പറഞ്ഞു: ഞാൻ അതിനേക്കാൾ കഴിവുള്ളവനാണ്. നബി(സ) അരുളി: "ഓരോ എട്ടിലും ഒരു ദിവസം വ്രതമെടുക്കുക, ബാക്കി ഏഴിന്റെയും പ്രതിഫലം നിനക്കുണ്ട്." ഞാൻ പറഞ്ഞു: ഞാൻ അതിനേക്കാളും കഴിവുള്ളവനാണ്. "ഒരുദിവസം നോമ്പെടുക്കുകയും അടുത്ത ഒരു ദിവസം നോമ്പു മുറിക്കുകയും ചെയ്യുക" എന്ന് തിരുമേനി(സ) പറയുന്നതുവരെ അദ്ദേഹം ഇപ്രകാരം പറഞ്ഞുകൊണ്ടേയിരുന്നു. (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 80, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "صُمْ يَوْمًا، وَلَكَ أَجْرُ عَشَرَةٍ". فَقُلْتُ: زِدْنِي. فَقَالَ: "صُمْ يَوْمَيْنِ، وَلَكَ أَجْرُ تِسْعَةٍ". قُلْتُ: زِدْنِي. قَالَ: "صُمْ ثَلَاثَةَ أَيَّامٍ، وَلَكَ أَجْرُ ثَمَانِيَةٍ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) എന്നോടു പറഞ്ഞു: "ഒരു ദിവസം നീ വ്രതമനുഷ്ഠിക്കുക. നിനക്കു പത്തു ദിവസത്തെ പ്രതിഫലമുണ്ട്." ഞാൻ പറഞ്ഞു: എനിക്കു കൂടുതലാക്കിത്തരണം. അപ്പോൾ നബി(സ) അരുളി: "നീ രണ്ടുദിവസം വ്രതമെടുക്കുക. നിനക്ക് ഒമ്പതു ദിവസത്തെ (നോമ്പെടുത്ത) പ്രതിഫലമുണ്ട്." ഞാൻ പറഞ്ഞു: എനിക്കു കൂടുതലാക്കിത്തരണം. അവിടന്നു പറഞ്ഞു: "നീ മൂന്നുദിവസം വ്രതമെടുക്കുക. നിനക്ക് എട്ടുദിവസത്തെ പ്രതിഫലമുണ്ട്." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 80, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ عِمْرَانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ، إِنَّ فُلَانًا لَا يُفْطِرُ نَهَارًا الدَّهْرَ؟ قَالَ: "لَا صَامَ وَلَا أَفْطَرَ". (ن)', 'ഇംറാൻ(റ): റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, ഒരാൾ ഒരുകാലത്തും പകലിൽ നോമ്പു മുറിക്കുന്നേ ഇല്ല? (അദ്ദേഹത്തിന്റെ അവസ്ഥയെന്താണ്?) റസൂൽ(സ) പ്രതിവചിച്ചു. "അയാൾ നോമ്പെടുത്തിട്ടില്ല; മുറിച്ചിട്ടുമില്ല." (ന)', 'عِمْرَانَ', 'ഇംറാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 80, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَرَرْنَا بِرَجُلٍ، فَقَالُوا: يَا نَبِيَّ اللَّهِ، هَذَا لَا يُفْطِرُ مُنْذُ كَذَا وَكَذَا. فَقَالَ: "لَا صَامَ وَلَا أَفْطَرَ". (ن)', 'ഉമർ(റ): ഞങ്ങൾ അല്ലാഹുവിന്റെ റസൂൽ(സ)യുടെ കൂടെ ഒരു വ്യക്തിയുടെ അരികിലൂടെ നീങ്ങുമ്പോൾ അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, ആ മനുഷ്യൻ ഇന്ന ദിവസം തൊട്ടു നോമ്പു മുറിച്ചിട്ടില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അയാൾ നോമ്പെടുത്തിട്ടില്ല; മുറിച്ചിട്ടുമില്ല." (ന)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 80, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَحَبَّ الصِّيَامِ إِلَى اللَّهِ صِيَامُ دَاوُدَ، وَأَحَبَّ الصَّلَاةِ إِلَى اللَّهِ صَلَاةُ دَاوُدَ عَلَيْهِ السَّلَامُ: كَانَ يَنَامُ نِصْفَ اللَّيْلِ، وَيَقُومُ ثُلُثَهُ، وَيَنَامُ سُدُسَهُ. وَكَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا". (ق,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) അരുളി: "അല്ലാഹുവിന് ഏറ്റവും പ്രിയങ്കരമായ വ്രതം ദാവൂദ് നബി(അ)ന്റെതാണ്, അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ട നിസ്കാരവും ദാവൂദ് നബി(അ)യുടേതുതന്നെ. അദ്ദേഹം രാത്രിയുടെ പകുതി ഉറങ്ങുകയും, മൂന്നിലൊന്നു സമയം നിസ്കരിക്കുകയും ശേഷം ആറിലൊന്ന് സമയം ഉറങ്ങുകയും ചെയ്യുമായിരുന്നു. ഒരു ദിവസം വ്രതമെടുക്കുകയും ഒരു ദിവസം വ്രതമെടുക്കാതിരിക്കുകയും ചെയ്യും." (ബു,മു,ദ,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 81, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَنْكَحَنِي أَبِي امْرَأَةً ذَاتَ حَسَبٍ، فَكَانَ يَأْتِيهَا فَيَسْأَلُهَا عَنْ بَعْلِهَا، فَقَالَتْ: نِعْمَ الرَّجُلُ مِنْ رَجُلٍ، لَمْ يَطَأْ لَنَا فِرَاشًا وَلَمْ يُفَتِّشْ لَنَا كَنَفًا مُنْذُ أَتَيْنَاهُ. فَذَكَرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "ائْتِنِي بِهِ". فَأَتَيْتُهُ مَعَهُ فَقَالَ: "كَيْفَ تَصُومُ". قُلْتُ: كُلَّ يَوْمٍ. قَالَ: "صُمْ مِنْ كُلِّ جُمُعَةٍ ثَلَاثَةَ أَيَّامٍ". قُلْتُ: إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ. قَالَ: "صُمْ يَوْمَيْنِ وَأَفْطِرْ يَوْمًا". قَالَ: إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ. قَالَ: "صُمْ أَفْضَلَ الصِّيَامِ صِيَامَ دَاوُدَ عَلَيْهِ السَّلَامُ: صَوْمُ يَوْمٍ وَفِطْرُ يَوْمٍ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): എന്റെ പിതാവ് എനിക്ക് കുലീനയായ ഒരു വനിതയെ വിവാഹം ചെയ്തുതന്നു. പിതാവ് അവളുടെ അടുക്കൽ വന്ന് ഭർത്താവിനെക്കുറിച്ച് ചോദിക്കാറുണ്ടായിരുന്നു. അവൾ പറയും: നല്ല മനുഷ്യൻ, നമ്മുടെ വിരിപ്പിൽ ഇതുവരെ ബന്ധപ്പെട്ടിട്ടില്ല. അദ്ദേഹത്തിന്റെ പാർശ്വം എന്നോടിതുവരെ ചേർത്തുവച്ചിട്ടുമില്ല. അദ്ദേഹമത് റസൂൽ(സ)യെ അറിയിക്കുകയും ചെയ്തു. അവിടന്ന് പറഞ്ഞു: "അയാളെ എന്റെയടുത്തേക്ക് കൊണ്ടുവരിക." ഞാൻ അദ്ദേഹത്തോടൊപ്പം ചെന്നു. നബി(സ) ചോദിച്ചു: "നീ എങ്ങനെയാണു നോമ്പെടുക്കുന്നത്?" ഞാൻ പറഞ്ഞു: എല്ലാ ദിനവും. നബി(സ) അരുളി: "ആഴ്ചയിൽ മൂന്ന് ദിവസം നോമ്പെടുക്കുക." ഞാൻ പറഞ്ഞു: എനിക്കതിലേറെ കഴിയുമല്ലോ, നബിയേ. അവിടന്ന് പറഞ്ഞു: "രണ്ടുദിനം നോമ്പെടുക്കുക, ഒരു ദിനം നോമ്പ് മുറിക്കുക." ഞാൻ പറഞ്ഞു: എനിക്ക് അതിലേറെ കഴിയുമല്ലോ. തിരുമേനി(സ) അരുളി: "നീ ദാവൂദ് നബി(അ)ന്റെ ഉത്തമവ്രതം അനുഷ്ഠിക്കുക; അഥവാ, ഒരു ദിനം നോമ്പെടുക്കുക. അടുത്ത ദിനം നോമ്പുമുറിക്കുക." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 81, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: زَوَّجَنِي أَبِي امْرَأَةً فَجَاءَ يَزُورُهَا، فَقَالَ: كَيْفَ تَرَيْنَ بَعْلَكِ؟ فَقَالَتْ: نِعْمَ الرَّجُلُ مِنْ رَجُلٍ، لَا يَنَامُ اللَّيْلَ وَلَا يُفْطِرُ النَّهَارَ. فَوَقَعَ بِي وَقَالَ: زَوَّجْتُكَ امْرَأَةً مِنَ الْمُسْلِمِينَ فَعَضَلْتَهَا. قَالَ: فَجَعَلْتُ لَا أَلْتَفِتُ إِلَى قَوْلِهِ مِمَّا أَرَى عِنْدِي مِنَ الْقُوَّةِ وَالِاجْتِهَادِ، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لَكِنِّي أَنَا أَقُومُ وَأَنَامُ، وَأَصُومُ وَأُفْطِرُ. فَقُمْ وَنَمْ، وَصُمْ وَأَفْطِرْ". قَالَ: "صُمْ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ". فَقُلْتُ: أَنَا أَقْوَى مِنْ ذَلِكَ. قَالَ: "صُمْ صَوْمَ دَاوُدَ عَلَيْهِ السَّلَامُ: صُمْ يَوْمًا وَأَفْطِرْ يَوْمًا". قُلْتُ: أَنَا أَقْوَى مِنْ ذَلِكَ. قَالَ: "اقْرَأِ الْقُرْآنَ فِي كُلِّ شَهْرٍ". ثُمَّ انْتَهَى إِلَى خَمْسَ عَشْرَة، وَأَنَا أَقُولُ: أَنَا أَقْوَى مِنْ ذَلِكَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): എന്റെ പിതാവ് എനിക്കൊരു സ്ത്രീയെ വിവാഹം ചെയ്തുതന്നു. എന്നിട്ടദ്ദേഹം അവളെ സന്ദർശിക്കാനായി വന്നു. അവളോടു ചോദിച്ചു: എങ്ങനെയുണ്ട് നിന്റെ ഭർത്താവ്? അവൾ പറഞ്ഞു: വളരെ നല്ല മനുഷ്യൻ, രാത്രി ഉറങ്ങുകയോ പകൽ വ്രതം ഒഴിവാക്കുകയോ ചെയ്യില്ല. അദ്ദേഹം എന്നിലേക്കു തിരിഞ്ഞു പറഞ്ഞു: ഒരു മുസ്ലിം വനിതയെ നിനക്കു ഞാൻ വിവാഹം ചെയ്തുതന്നു. എന്നിട്ട് നീ അവളുമായി ദാമ്പത്യബന്ധത്തിലേർപ്പെട്ടില്ല. ശക്തിയും പരിശ്രമവും എനിക്കുണ്ടെന്നുള്ള ധാരണത്താൽ അദ്ദേഹത്തിന്റെ വാക്യം ഞാൻ ശ്രദ്ധിച്ചില്ല. അങ്ങനെയത് നബി(സ)യുടെ അടുത്തെത്തി. അവിടന്ന് പറഞ്ഞു: "ഞാൻ നിസ്കരിക്കുന്നു, ഉറങ്ങുന്നു, നോമ്പെടുക്കുന്നു, മുറിക്കുന്നു. അതുപോലെ നീ നിസ്കരിക്കുക, ഉറങ്ങുക, നോമ്പെടുക്കുക, മുറിക്കുകയും ചെയ്യുക. ഓരോ മാസവും മൂന്നുദിവസം നോമ്പെടുക്കുക." ഞാൻ പറഞ്ഞു: എനിക്കതിലേറെ കഴിയുമല്ലോ. അവിടന്ന് അരുളി: "ദാവൂദ്(അ)ന്റെ വ്രതമെടുക്കുക; ഒരു ദിവസം നോമ്പെടുക്കുക, അടുത്ത ദിവസം മുറിക്കുക." ഞാൻ പറഞ്ഞു: എനിക്കതിൽ കൂടുതൽ കഴിയുമല്ലോ. നബി(സ) പറഞ്ഞു: "എല്ലാ മാസവും ഖുർആൻ പാരായണം നടത്തുക." പിന്നെയത് പതിനഞ്ചു ദിവസമായി ചുരുങ്ങി. അതിലേറെ കഴിയുമെന്ന് ഞാൻ പറഞ്ഞുകൊണ്ടിരുന്നു. (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 81, 82, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُجْرَتِي فَقَالَ: "أَلَمْ أُخْبَرْ أَنَّكَ تَقُومُ اللَّيْلَ وَتَصُومُ النَّهَارَ". قَالَ: بَلَى. قَالَ: "فَلَا تَفْعَلَنَّ، نَمْ وَقُمْ، وَصُمْ وَأَفْطِرْ، فَإِنَّ لِعَيْنِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِجَسَدِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِزَوْجَتِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِضَيْفِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِصَدِيقِكَ عَلَيْكَ حَقًّا. وَإِنَّهُ عَسَى أَنْ يَطُولَ بِكَ عُمُرٌ، وَإِنَّهُ حَسْبُكَ أَنْ تَصُومَ مِنْ كُلِّ شَهْرٍ ثَلَاثًا، فَذَلِكَ صِيَامُ الدَّهْرِ كُلِّهِ، وَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا". قُلْتُ: إِنِّي أَجِدُ قُوَّةً، فَشَدَّدْتُ فَشُدِّدَ عَلَيَّ، قَالَ: "صُمْ مِنْ كُلِّ جُمُعَةٍ ثَلَاثَةَ أَيَّامٍ". قُلْتُ: إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ، فَشَدَّدْتُ فَشُدِّدَ عَلَيَّ، قَالَ: "صُمْ صَوْمَ نَبِيِّ اللَّهِ دَاوُدَ عَلَيْهِ السَّلَامُ". قُلْتُ: وَمَا كَانَ صَوْمُ دَاوُدَ؟ قَالَ: "نِصْفُ الدَّهْرِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) എന്റെ മുറിയിലേക്ക് വന്നു. എന്നിട്ട് പറഞ്ഞു: "നീ രാത്രി മുഴുവൻ നിസ്കരിക്കുകയും പകൽ നോമ്പനുഷ്ഠിക്കുകയും ചെയ്യുന്നുണ്ടെന്ന വിവരം എനിക്ക് ലഭിച്ചല്ലോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. അവിടന്ന് പറഞ്ഞു: "ഇനി അങ്ങനെ ചെയ്യരുത്. ഉറങ്ങുക, നിസ്കരിക്കുക, നോമ്പെടുക്കുക, ഒഴിവാക്കുക. നിന്റെ നേത്രങ്ങളോട് നിനക്ക് കടപ്പാടുണ്ട്. നിന്റെ ശരീരത്തോട് നിനക്ക് കടപ്പാടുണ്ട്, നിന്റെ ഭാര്യയോട് നിനക്ക് കടപ്പാടുണ്ട്, നിന്റെ അതിഥിയോട് നിനക്ക് കടപ്പാടുണ്ട്, നിന്റെ സുഹൃത്തിനോടും നിനക്ക് കടപ്പാടുണ്ട്; നിന്റെ ആയുസ്സ് ദൈർഘ്യമുള്ളതായിരിക്കാം, അതിനാൽ ഓരോ മാസവും മൂന്നു നോമ്പെടുത്താൽ മതി. അത് ഒരു കൊല്ലം മുഴുവനുള്ള നോമ്പുതന്നെയാണ്. നന്മ അതിന്റെ പത്തിരട്ടിയാണ്." ഞാൻ പറഞ്ഞു: എനിക്ക് ശക്തിയുണ്ട്, ഞാൻ ശക്തമാക്കിയപ്പോൾ എന്റെ മേൽ ശക്തമാക്കപ്പെട്ടു. നബി(സ) അരുളി: "എന്നാൽ നീ ആഴ്ചയിൽ മൂന്നുദിവസം നോമ്പെടുക്കുക." ഞാൻ പറഞ്ഞു: എനിക്കതിലേറെ കഴിയും. ഞാൻ ശക്തമാക്കിയപ്പോൾ എന്റെ മേൽ ശക്തമാക്കപ്പെട്ടു. അവിടന്ന് പറഞ്ഞു: "നീ അല്ലാഹുവിന്റെ പ്രവാചകൻ ദാവൂദ്(അ)മിന്റെ നോമ്പെടുക്കുക." ഞാൻ ചോദിച്ചു: എങ്ങനെയാണ് ദാവൂദ്(അ)മിന്റെ നോമ്പ്? അവിടന്ന് പറഞ്ഞു: "വർഷത്തിന്റെ പകുതി." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 82, 82, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: ذُكِرَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ يَقُولُ: لَأَقُومَنَّ اللَّيْلَ وَلَأَصُومَنَّ النَّهَارَ مَا عِشْتُ. فَقَالَ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنْتَ الَّذِي تَقُولُ ذَلِكَ". فَقُلْتُ لَهُ: قَدْ قُلْتُهُ يَا رَسُولَ اللَّهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَإِنَّكَ لَا تَسْتَطِيعُ ذَلِكَ، فَصُمْ وَأَفْطِرْ، وَنَمْ وَقُمْ، وَصُمْ مِنَ الشَّهْرِ ثَلَاثَةَ أَيَّامٍ، فَإِنَّ الْحَسَنَةَ بِعَشْرِ أَمْثَالِهَا، وَذَلِكَ مِثْلُ صِيَامِ الدَّهْرِ". قُلْتُ: فَإِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ؟ قَالَ: "صُمْ يَوْمًا وَأَفْطِرْ يَوْمَيْنِ". فَقُلْتُ: لِإِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ يَا رَسُولَ اللَّهِ؟ قَالَ: "فَصُمْ يَوْمًا وَأَفْطِرْ يَوْمًا، وَذَلِكَ صِيَامُ دَاوُدَ، وَهُوَ أَعْدَلُ الصِّيَامِ". قُلْتُ: فَإِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا أَفْضَلَ مِنْ ذَلِكَ". قَالَ عَبْدُ اللَّهِ بْنُ عَمْرو: لَأَنْ أَكُونَ قَبِلْتُ الثَّلَاثَةَ الْأَيَّامَ الَّتِي قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَبُّ إِلَيَّ مِنْ أَهْلِي وَمَالِي. (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ജീവിതകാലമത്രയും ഞാൻ രാത്രി മുഴുവൻ നിസ്കരിക്കുകയും പകൽ നോമ്പെടുക്കുകയും ചെയ്യുമെന്നു പറഞ്ഞത് റസൂൽ(സ)യോട് പറയപ്പെട്ടു. അപ്പോൾ അവിടന്ന് എന്നോട് ചോദിച്ചു: "നീ അങ്ങനെ പറഞ്ഞോ?" ഞാൻ പറഞ്ഞു: അതേ, തിരുദൂതരേ. നബി(സ) പറഞ്ഞു: "നിനക്കതിനാവില്ല. നീ നോമ്പെടുക്കുകയും ഒഴിവാക്കുകയും ചെയ്യുക. ഉറങ്ങുകയും നിസ്കരിക്കുകയും ചെയ്യുക. അതായത് മാസത്തിൽ മൂന്നുദിവസം നോമ്പെടുക്കുക. നന്മയുടെ പ്രതിഫലം പത്തിരട്ടിയാണ്. അത് ഒരു വർഷത്തെ നോമ്പുപോലെയാണ്." ഞാൻ പറഞ്ഞു: എനിക്കതിലേറെ കഴിയും. അവിടന്ന് പറഞ്ഞു: "ഒരു ദിവസം നോമ്പെടുക്കുക. രണ്ടുദിവസം മുറിക്കുക." ഞാൻ പറഞ്ഞു: എനിക്കതിലും കൂടുതൽ കഴിയുമല്ലോ തിരുദൂതരേ? അവിടന്നരുളി: "ഒരു ദിവസം നോമ്പെടുക്കുക, ഒരു ദിവസം ഒഴിവാക്കുകയും ചെയ്യുക. അതാണു ദാവൂദ്(അ)ന്റെ നോമ്പ്, അതാണ് ഏറ്റവും നല്ലത്." ഞാൻ പറഞ്ഞു: അതിലും ശ്രേഷ്ഠമായതെനിക്കു കഴിയുമല്ലോ? തിരുമേനി(സ) പറഞ്ഞു: "അതിലേറെ ശ്രേഷ്ഠതയുള്ളതായി മറ്റൊന്നുമില്ല." അബ്ദുല്ലാഹിബ്നു അംറ്(റ) പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞ മൂന്ന് ദിവസത്തെ സ്വീകരിക്കലായിരുന്നു എന്റെ കുടുംബത്തെക്കാളും സമ്പത്തിനേക്കാളും എനിക്കിഷ്ടമായത്. (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 82, 83, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ قَالَ: دَخَلْتُ عَلَى عَبْدِ اللَّهِ بْنِ عَمْرو رَضِيَ اللَّهُ عَنْهُمَا، قُلْتُ: أَيْ عَمِّ، حَدِّثْنِي عَمَّا قَالَ لَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: يَا ابْنَ أَخِي، إِنِّي قَدْ كُنْتُ أَجْمَعْتُ عَلَى أَنْ أَجْتَهِدَ اجْتِهَادًا شَدِيدًا، حَتَّى قُلْتُ: لَأَصُومَنَّ الدَّهْرَ، وَلَأَقْرَأَنَّ الْقُرْآنَ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ. فَسَمِعَ بِذَلِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَانِي حَتَّى دَخَلَ عَلَيَّ فِي دَارِي، فَقَالَ: "بَلَغَنِي أَنَّكَ قُلْتَ: لَأَصُومَنَّ الدَّهْرَ، وَلَأَقْرَأَنَّ الْقُرْآنَ". فَقُلْتُ: قَدْ قُلْتُ ذَلِكَ يَا رَسُولَ اللَّهِ. قَالَ: "فَلَا تَفْعَلْ، صُمْ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ". قُلْتُ: إِنِّي أَقْوَى عَلَى أَكْثَرَ مِنْ ذَلِكَ. قَالَ: "فَصُمْ مِنَ الْجُمُعَةِ يَوْمَيْنِ: الِاثْنَيْنِ وَالْخَمِيسَ". قُلْتُ: فَإِنِّي أَقْوَى عَلَى أَكْثَرَ مِنْ ذَلِكَ. قَالَ: "فَصُمْ صِيَامَ دَاوُدَ عَلَيْهِ السَّلَامُ، فَإِنَّهُ أَعْدَلُ الصِّيَامِ عِنْدَ اللَّهِ: يَوْمًا صَائِمًا وَيَوْمًا مُفْطِرًا، وَإِنَّهُ كَانَ إِذَا وَعَدَ لَمْ يُخْلِفْ، وَإِذَا لَاقَى لَمْ يَفِرَّ". (ن)', 'അബുസലമതുബ്നു അബ്ദുറഹ്മാൻ(റ): ഞാൻ അബ്ദുല്ലാഹിബ്നു അംറ്(റ)വിന്റെ അടുത്ത് ചെന്നു പറഞ്ഞു: പിതൃവ്യാ, റസൂൽ(സ) താങ്കൾക്കു പറഞ്ഞുതന്നത് എനിക്കു വിവരിച്ചു തന്നാലും. അദ്ദേഹം പറഞ്ഞു: സഹോദരപുത്രാ, ശക്തമായ പരിശ്രമം നടത്താൻ ഞാൻ തീരുമാനിച്ചു. അങ്ങനെ ഞാൻ പറഞ്ഞു: വർഷം മുഴുവൻ ഞാൻ വ്രതമെടുക്കും, എല്ലാ രാപ്പകലുകളിലും ഖുർആൻ പാരായണം ചെയ്യും. റസൂൽ(സ) ഇത് അറിയുകയും എന്റെ വീട്ടിൽ എത്തുകയും ചെയ്തു. തുടർന്ന് അവിടന്ന് പറഞ്ഞു: "നീ ഖുർആൻ ഓതുമെന്നും, നിത്യവ്രതം അനുഷ്ഠിക്കുമെന്നും പറഞ്ഞതായി ഞാൻ അറിഞ്ഞല്ലോ!" ഞാൻ പറഞ്ഞു: അതേ, ഞാനത് പറഞ്ഞിട്ടുണ്ട് പ്രവാചകരേ. അവിടന്നരുളി: "ഇനിയങ്ങനെ ചെയ്യരുത്. ഓരോ മാസവും മൂന്നുദിനം നീ നോമ്പെടുക്കുക." ഞാൻ പറഞ്ഞു: എനിക്കതിലേറെ കഴിയും. നബി(സ) പറഞ്ഞു: "എങ്കിൽ നീ ആഴ്ചയിൽ രണ്ടു നോമ്പെടുക്കുക; തിങ്കളാഴ്ചയും, വ്യാഴാഴ്ചയും." ഞാൻ പറഞ്ഞു: എനിക്കതിലേറെ കഴിയും. അവിടന്നരുളി: "നീ ദാവൂദ്(അ)ന്റെ വ്രതമെടുക്കുക. അതാണ് അല്ലാഹുവിന്റെയടുക്കൽ ഏറ്റവും മാന്യമായ നോമ്പ്. ഒരു ദിനം നോമ്പനുഷ്ഠിക്കുകയും അടുത്ത ദിവസം നോമ്പ് ഒഴിവാക്കുകയും ചെയ്യുക. നിശ്ചയം ദാവൂദ്(അ) കരാർ ചെയ്താൽ ലംഘിക്കുകയോ, (ശത്രുവിനെ) കണ്ടുമുട്ടിയാൽ തിരിഞ്ഞോടുകയോ ചെയ്തിട്ടില്ല." (ന)', 'أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ قَالَ', 'അബുസലമതുബ്നു അബ്ദുറഹ്മാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 83, 83, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ وَقَدْ سُئِلَ عَنْ صِيَامِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا كُنْتُ أُحِبُّ أَنْ أَرَاهُ مِنَ الشَّهْرِ صَائِمًا إِلَّا رَأَيْتُهُ، وَلَا مُفْطِرًا إِلَّا رَأَيْتُهُ، وَلَا مِنَ اللَّيْلِ قَائِمًا إِلَّا رَأَيْتُهُ، وَلَا نَائِمًا إِلَّا رَأَيْتُهُ، وَلَا مَسِسْتُ خَزَّةً وَلَا حَرِيرَةً أَلْيَنَ مِنْ كَفِّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَا شَمِمْتُ مِسْكَةً وَلَا عَبِيرَةً أَطْيَبَ رَائِحَةً مِنْ رَائِحَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'അനസ്(റ): നബി(സ)യുടെ നോമ്പിനെക്കുറിച്ച് ചോദിക്കപ്പെട്ടപ്പോൾ അനസ്(റ) പറഞ്ഞു: ഏതു മാസത്തിൽ നോമ്പുകാരനായി കാണാൻ ഞാനുദ്ദേശിച്ചാലും തിരുമേനി(സ)യെ ആ നിലക്കു ഞാൻ കാണാതിരുന്നിട്ടില്ല. തിരുമേനി(സ) നോമ്പുപേക്ഷിക്കുന്നതു കാണാൻ ഏതു മാസത്തിൽ ഞാനുദ്ദേശിച്ചാലും ഞാനതും കാണാതിരുന്നിട്ടില്ല. രാത്രി തിരുമേനി(സ) നിസ്കരിക്കുന്നത് കാണാനുദ്ദേശിച്ചാൽ അതും കാണാതിരിന്നിട്ടില്ല. ഉറങ്ങുന്നത് കാണാനുദ്ദേശിച്ചാൽ അതും കാണാതിരുന്നിട്ടില്ല. തിരുമേനി(സ)യുടെ കൈപ്പത്തിയേക്കാൾ മാർദ്ദവമേറിയ ഒരു പട്ടും ഞാൻ സ്പർശിച്ചിട്ടില്ല. റസൂൽ(സ)യേക്കാൾ സുഗന്ധമുള്ള ഒരു കസ്തൂരിയോ മറ്റു സുഗന്ധമോ ഞാൻ വാസനിച്ചിട്ടില്ല. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 84, 84, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ حَتَّى نَقُولَ لَا يُفْطِرُ، وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ. وَمَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَكْمَلَ صِيَامَ شَهْرٍ قَطُّ إِلَّا رَمَضَانَ، وَمَا رَأَيْتُهُ فِي شَهْرٍ أَكْثَرَ صِيَامًا مِنْهُ فِي شَعْبَانَ. (خ,د,ن,جه)', 'ആഇശ(റ): ഇനി നോമ്പുപേക്ഷിക്കില്ല എന്ന് ഞങ്ങൾ പറയുംവരെ റസൂൽ(സ) നോമ്പെടുക്കാറുണ്ടായിരുന്നു. ഇനി നോമ്പെടുക്കില്ല എന്ന് ഞങ്ങൾ പറയുംവരെ റസൂൽ(സ) നോമ്പ് ഒഴിവാക്കിയിരുന്നു. റമളാനിലൊഴികെ റസൂൽ(സ) ഒരു മാസം പൂർണമായും നോമ്പെടുക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല. ശഅ്ബാനിലേതിനേക്കാൾ കൂടുതലായി മറ്റൊരു മാസത്തിൽ റസൂൽ(സ) നോമ്പെടുക്കുന്നതും ഞാൻ കണ്ടിട്ടില്ല. (ബു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 84, 84, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يُفْطِرُ أَيَّامَ الْبِيضِ فِي حَضَرٍ وَلَا سَفَرٍ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): യാത്രയിലായാലും അല്ലെങ്കിലും ''അയ്യാമുൽ ബീള്'' (ചന്ദ്രമാസം 13, 14, 15) ദിവസങ്ങളിൽ റസൂൽ(സ) നോമ്പുപേക്ഷിക്കാറുണ്ടായിരുന്നില്ല. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 84, 84, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَا أَعْلَمُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ الْقُرْآنَ كُلَّهُ فِي لَيْلَةٍ، وَلَا قَامَ لَيْلَةً حَتَّى الصَّبَاحِ، وَلَا صَامَ شَهْرًا قَطُّ كَامِلًا غَيْرَ رَمَضَانَ. (ن)', 'ആഇശ(റ): റമളാനിലൊഴികെ നബി(സ) ഒരു മാസം പൂർണമായും നോമ്പെടുക്കുകയോ രാത്രി പ്രഭാതം വരെ നിസ്ക്കരിക്കുകയോ ഒറ്റ രാത്രിയിൽ ഖുർആൻ പൂർണമായും പാരായണം ചെയ്യുകയോ ചെയ്തതായി എനിക്കറിയില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 84, 84, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، وَقَدْ سُئِلَتْ عَنْ صِيَامِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: كَانَ يَصُومُ حَتَّى نَقُولَ قَدْ صَامَ، وَيُفْطِرُ حَتَّى نَقُولَ قَدْ أَفْطَرَ، وَمَا صَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَهْرًا كَامِلًا مُنْذُ قَدِمَ الْمَدِينَةَ إِلَّا رَمَضَانَ. (ن)', 'ആഇശ(റ): നബി(സ)യുടെ നോമ്പിനെകുറിച്ച് ചോദിക്കപ്പെട്ടപ്പോൾ അവർ പറഞ്ഞു: നബി(സ) നോമ്പെടുത്തിരിക്കുന്നു എന്ന് ഞങ്ങൾ പറയുന്നതുവരെ അവിടന്ന് നോമ്പെടുക്കുമായിരുന്നു. നോമ്പുപേക്ഷിച്ചിരിക്കുന്നു എന്നു ഞങ്ങൾ പറയുംവരെ നോമ്പുപേക്ഷിക്കുകയും ചെയ്യുമായിരുന്നു. മദീനയിൽ വന്നതുമുതൽ റമളാനിലല്ലാതെ ഒരു മാസം പൂർണമായും തിരുമേനി നോമ്പെടുത്തിട്ടില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 84, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ أَحَبَّ الشُّهُورِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَصُومَهُ شَعْبَانُ، بَلْ كَانَ يَصِلُهُ بِرَمَضَانَ. (ن)', 'ആഇശ(റ): റസൂൽ(സ)ക്ക് നോമ്പെടുക്കുന്നത് ഏറ്റവും ഇഷ്ടമുണ്ടായിരുന്ന മാസം ശഅ്ബാനായിരുന്നു. മാത്രമല്ല അതിനെ റമളാനിനോടു ചേർക്കാറുമുണ്ടായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 85, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَصُومُ شَهْرَيْنِ مُتَتَابِعَيْنِ إِلَّا شَعْبَانَ وَرَمَضَانَ. (ن)', 'ഉമ്മുസലമ(റ): ശഅ്ബാനിലും റമളാനിലുമല്ലാതെ വർഷത്തിൽ തുടർച്ചയായി രണ്ടുമാസം നബി(സ) നോമ്പെടുക്കുമായിരുന്നില്ല. (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 85, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِشَهْرٍ أَكْثَرَ صِيَامًا مِنْهُ لِشَعْبَانَ، كَانَ يَصُومُهُ أَوْ عَامَّتَهُ. وَفِي رِوَايَةٍ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ شَعْبَانَ إِلَّا قَلِيلًا. وَفِي رِوَايَةٍ قَالَتْ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَصُومُ شَعْبَانَ كُلَّهُ. (ن)', 'ആഇശ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) ശഅ്ബാനിൽ എടുത്തത്രയും നോമ്പ് മറ്റു മാസങ്ങളിൽ എടുത്തിട്ടില്ല. ശഅ്ബാനിൽ അവിടന്ന് നോമ്പെടുക്കാറുണ്ട്, അല്ലെങ്കിൽ പൂർണമായും നോമ്പ് എടുക്കാറുണ്ട്. മറ്റൊരു നിവേദനത്തിൽ: ശഅ്ബാനിൽ കുറഞ്ഞ ദിവസങ്ങളിലൊഴികെ റസൂൽ(സ) നോമ്പെടുത്തിരുന്നു. മറ്റൊരു നിവേദനത്തിൽ: ശഅ്ബാൻ പൂർണമായും നോമ്പെടുത്തിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 85, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=135), 1, 'وَفِي رِوَايَةٍ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ شَعْبَانَ إِلَّا قَلِيلًا.', 'മറ്റൊരു നിവേദനത്തിൽ: ശഅ്ബാനിൽ കുറഞ്ഞ ദിവസങ്ങളിലൊഴികെ റസൂൽ(സ) നോമ്പെടുത്തിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=135), 2, 'وَفِي رِوَايَةٍ قَالَتْ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَصُومُ شَعْبَانَ كُلَّهُ. (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: ശഅ്ബാൻ പൂർണമായും നോമ്പെടുത്തിരുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، لَمْ أَرَكَ تَصُومُ شَهْرًا مِنَ الشُّهُورِ مَا تَصُومُ مِنْ شَعْبَانَ؟ قَالَ: "ذَلِكَ شَهْرٌ يَغْفُلُ النَّاسُ عَنْهُ بَيْنَ رَجَبٍ وَرَمَضَانَ، وَهُوَ شَهْرٌ تُرْفَعُ فِيهِ الْأَعْمَالُ إِلَى رَبِّ الْعَالَمِينَ، فَأُحِبُّ أَنْ يُرْفَعَ عَمَلِي وَأَنَا صَائِمٌ". (ن)', 'ഉസാമതുബ്നു സൈദ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് ശഅ്ബാനിൽ എടുക്കുന്നത്ര നോമ്പ് മറ്റു മാസങ്ങളിൽ എടുക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല? അവിടന്ന് പറഞ്ഞു: "റമളാനിനും റജബിനും ഇടക്ക് ജനങ്ങൾ അശ്രദ്ധരാകുന്ന മാസമാണത്. ലോകരക്ഷിതാവിലേക്ക് കർമങ്ങൾ ഉയർത്തപ്പെടുന്ന മാസവുമാണത്. ഞാൻ നോമ്പുകാരനായിരിക്കെ എന്റെ കർമങ്ങൾ ഉയർത്തപ്പെടാൻ ഞാൻ ആഗ്രഹിക്കുന്നു." (ന)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 85, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّكَ تَصُومُ حَتَّى لَا تَكَادَ تُفْطِرَ، وَتُفْطِرُ حَتَّى لَا تَكَادَ أَنْ تَصُومَ، إِلَّا يَوْمَيْنِ: إِنْ دَخَلَا فِي صِيَامِكَ، وَإِلَّا صُمْتَهُمَا؟ قَالَ: "أَيُّ يَوْمَيْنِ". قُلْتُ: يَوْمَ الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ. قَالَ: "ذَانِكَ يَوْمَانِ تُعْرَضُ فِيهِمَا الْأَعْمَالُ عَلَى رَبِّ الْعَالَمِينَ، فَأُحِبُّ أَنْ يُعْرَضَ عَمَلِي وَأَنَا صَائِمٌ". (ن)', 'ഉസാമതുബ്നു സൈദ്(റ): ഞാൻ തിരുമേനി(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഇനി നോമ്പു മുറിക്കുകയില്ലെന്ന് വരുവോളം അങ്ങ് വ്രതമെടുക്കുന്നു. ഇനി നോമ്പ് അനുഷ്ഠിക്കുകയില്ലെന്ന് വരുവോളം നോമ്പ് അനുഷ്ഠിക്കാതിരിക്കുന്നു. രണ്ടുദിനങ്ങളൊഴികെ. അവ രണ്ടും അങ്ങ് നോമ്പെടുത്തിട്ടല്ലാതെ പ്രവേശിക്കുകയില്ല. അവിടന്ന് ചോദിച്ചു. "ഏതാണ് ആ ദിനങ്ങൾ?" ഞാൻ പറഞ്ഞു: തിങ്കളും വ്യാഴവും. അവിടന്ന് അരുളി: "ലോകരക്ഷിതാവിന് കർമങ്ങൾ സമർപ്പിക്കപ്പെടുന്ന രണ്ടു ദിനങ്ങളാണ് അവ. അതിനാൽ ഞാൻ നോമ്പുകാരനായിരിക്കേ എന്റെ കർമങ്ങൾ സമർപ്പിക്കപ്പെടുവാൻ ആഗ്രഹിക്കുന്നു." (ന)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 85, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَحَرَّى صِيَامَ الِاثْنَيْنِ وَالْخَمِيسِ. وَفِي رِوَايَةٍ: يَصُومُ الِاثْنَيْنِ وَالْخَمِيسَ. (ن)', 'ആഇശ(റ): റസൂൽ(സ) തിങ്കൾ, വ്യാഴം നോമ്പുകൾക്ക് അമിതപ്രാധാന്യം കൽപിക്കാറുണ്ടായിരുന്നു. മറ്റൊരു നിവേദനത്തിൽ: വ്യാഴവും തിങ്കളും നോമ്പെടുക്കാറുണ്ടായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 85, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=138), 1, 'وَفِي رِوَايَةٍ: يَصُومُ الِاثْنَيْنِ وَالْخَمِيسَ. (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: വ്യാഴവും തിങ്കളും നോമ്പെടുക്കാറുണ്ടായിരുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ: الِاثْنَيْنِ وَالْخَمِيسَ مِنْ هَذِهِ الْجُمُعَةِ، وَالِاثْنَيْنِ مِنَ الْمُقْبِلَةِ. (ن)', 'ഉമ്മുസലമ(റ): റസൂൽ(സ) ഓരോ മാസത്തിലും മൂന്ന് ദിവസം നോമ്പനുഷ്ഠിക്കുമായിരുന്നു. ഒരാഴ്ചയിലെ തിങ്കളാഴ്ചയും വ്യാഴായ്ചയും, പിന്നീടുള്ള ആഴ്ചയിൽ വരുന്ന തിങ്കളാഴ്ചയും. (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ حَفْصَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَخَذَ مَضْجَعَهُ جَعَلَ كَفَّهُ الْيُمْنَى تَحْتَ خَدِّهِ الْأَيْمَنِ، وَكَانَ يَصُومُ الِاثْنَيْنِ وَالْخَمِيسَ. (ن)', 'ഹഫ്സ(റ): റസൂൽ(സ) ഉറങ്ങാൻ കിടന്നാൽ തന്റെ വലതു കൈപ്പത്തി വലതു കവിളിനു താഴെ വെക്കുമായിരുന്നു. റസൂൽ(സ) തിങ്കളും വ്യാഴവും നോമ്പെടുക്കുകയും ചെയ്യുമായിരുന്നു. (ന)', 'حَفْصَةَ', 'ഹഫ്സ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ ثَلَاثَةَ أَيَّامٍ مِنْ غُرَّةِ كُلِّ شَهْرٍ، وَقَلَّمَا يُفْطِرُ يَوْمَ الْجُمُعَةِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): എല്ലാ മാസവും വെളുത്ത മൂന്നു ദിനങ്ങളിൽ (അയ്യാമുൽ ബീള്: 13, 14, 15) റസൂൽ(സ) നോമ്പെടുക്കാറുണ്ടായിരുന്നു. വെള്ളിയാഴ്ചയിൽ നോമ്പുപേക്ഷിക്കൽ വിരളമായിരുന്നു. (ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَكْعَتَيِ الضُّحَى، وَأَنْ لَا أَنَامَ إِلَّا عَلَى وِتْرٍ، وَصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنَ الشَّهْرِ. (ن)', 'അബൂഹുറൈറ(റ): രണ്ട് റക്അത് ളുഹാ നിസ്കരിക്കണമെന്നും വിത്ർ നിസ്കരിക്കാതെ ഉറങ്ങരുതെന്നും മാസത്തിൽ മൂന്നുദിവസം നോമ്പെടുക്കണമെന്നും റസൂൽ(സ) എന്നോട് കൽപിച്ചു. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، وَسُئِلَ عَنْ صِيَامِ عَاشُورَاءَ، قَالَ: مَا عَلِمْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَامَ يَوْمًا يَتَحَرَّى فَضْلَهُ عَلَى الْأَيَّامِ إِلَّا هَذَا الْيَوْمَ، يَعْنِي شَهْرَ رَمَضَانَ وَيَوْمَ عَاشُورَاءَ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ആശൂറാഅ് (മുഹർറം: 10) നോമ്പിനെക്കുറിച്ച് അദ്ദേഹം ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: ഈ ദിവസത്തിലല്ലാതെ, വളരെ പ്രാധാന്യത്തോടുകൂടി മറ്റു ദിനങ്ങളിൽ നോമ്പെടുക്കുന്നതായി നബി(സ)യെ ഞാൻ കണ്ടിട്ടില്ല. അതായത് റമളാൻ മാസവും ആശൂറാഅ് ദിനവും. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ مُعَاوِيَةَ رَضِيَ اللَّهُ عَنْهُ، قَالَ يَوْمَ عَاشُورَاءَ وَهُوَ عَلَى الْمِنْبَرِ: يَا أَهْلَ الْمَدِينَةِ، أَيْنَ عُلَمَاؤُكُمْ؟ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي هَذَا الْيَوْمِ: "إِنِّي صَائِمٌ، فَمَنْ شَاءَ أَنْ يَصُومَ فَلْيَصُمْ". (ن)', 'മുആവിയ(റ): ആശൂറാഅ് ദിനത്തിൽ മിമ്പറിൽനിന്ന് അദ്ദേഹം വിളിച്ചുപറഞ്ഞു: ഹേ, മദീനാ നിവാസികളേ, എവിടെയാണ് നിങ്ങളുടെ പണ്ഡിതന്മാർ? ഈ ദിനത്തിൽ റസൂൽ(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ഞാൻ ഇന്നു നോമ്പുകാരനാണ്; ആരെങ്കിലും നോമ്പെടുക്കാൻ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ നോമ്പെടുത്തുകൊള്ളട്ടെ." (ന)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَصُومُ يَوْمَ عَاشُورَاءَ، وَتِسْعًا مِنْ ذِي الْحِجَّةِ، وَثَلَاثَةَ أَيَّامٍ مِنَ الشَّهْرِ: أَوَّلَ اثْنَيْنِ مِنَ الشَّهْرِ وَخَمِيسَيْنِ. (ن)', 'ഉമ്മുസലമ(റ): ആശൂറാഅ് ദിനത്തിലും ദുൽഹജ്ജ് മാസത്തിലെ ആദ്യ ഒമ്പതു ദിനത്തിലും മാസത്തിൽ മൂന്നു ദിനത്തിലും അതായത് മാസത്തിൽ ആദ്യത്തെ തിങ്കളാഴ്ചയും രണ്ടു വ്യാഴാഴ്ചകളിലും തിരുമേനി( സ) നോമ്പനുഷ്ഠിക്കാറുണ്ടായിരുന്നു. (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 86, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "صَامَ نُوحٌ الدَّهْرَ، إِلَّا يَوْمَ الْفِطْرِ وَيَوْمَ الْأَضْحَى". [ز: في إسناده ضعيف] (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നൂഹ്(അ) ഈദുൽ അള്ഹായും (ബലിപെരുന്നാൾ ദിനം) ഈദുൽ ഫിത്വറും ഒഴികെ വർഷം മുഴുവൻ നോമ്പെടുത്തിരുന്നു." (ഇതിന്റെ പരമ്പരയിൽ ഒരു ദുർബലനുണ്ട്). (ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ഒരു ദുർബലനുണ്ട്', 87, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ- يَعْنِي مِنْ غُرَّةِ كُلِّ شَهْرٍ- ثَلَاثَةَ أَيَّامٍ. (د،ت،ن)', 'ഇബ്നുമസ്ഊദ്(റ): നബി(സ) മൂന്ന് ദിവസം - എല്ലാ മാസവും വെളുത്തവാവു ദിനങ്ങളിൽ - നോമ്പനുഷ്ഠിക്കാറുണ്ട്. (ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 87, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ مُعَاذَةَ الْعَدَوِيَّةِ أَنَّهَا قَالَتْ: سَأَلْتُ عَائِشَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ؟ قَالَتْ نَعَمْ، فَقُلْتُ لَهَا: مِنْ أَيِّ أَيَّامِ الشَّهْرِ كَانَ يَصُومُ؟ قَالَتْ: لَمْ يَكُنْ يُبَالِي مِنْ أَيِّ أَيَّامِ الشَّهْرِ يَصُومُ. (م،د،ت،ن،جه)', 'മുആദതുൽ അദവിയ്യ(റ): നബി(സ)യുടെ ഭാര്യയായ ആഇശ(റ)യോട് ഞാൻ ചോദിച്ചു. നബി(സ) എല്ലാ മാസവും മൂന്ന് ദിനങ്ങളിൽ നോമ്പനുഷ്ഠിക്കാറുണ്ടായിരുന്നോ? അവർ പറഞ്ഞു: അതെ. ഞാൻ ചോദിച്ചു: മാസത്തിലെ ഏതു ദിവസങ്ങളിലായിരുന്നു അവിടന്ന് നോമ്പനുഷ്ഠിക്കാറുണ്ടായിരുന്നത്? ആഇശ(റ) പറഞ്ഞു: മാസത്തിൽ ഏതു ദിവസമെന്നത് അവിടന്ന് അത്ര കാര്യമാക്കാറില്ല. (മു,ദ,തു,ന,ജ)', 'مُعَاذَةَ الْعَدَوِيَّةِ أَنَّهَا قَالَتْ', 'മുആദതുൽ അദവിയ്യ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 87, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ مِنَ الشَّهْرِ: السَّبْتَ وَالْأَحَدَ وَالِاثْنَيْنِ، وَمِنَ الشَّهْرِ الْآخَرِ: الثُّلَاثَاءَ وَالْأَرْبِعَاءَ وَالْخَمِيسَ. (ت)', 'ആഇശ(റ): റസൂൽ(സ) ഒരു മാസത്തിലെ ശനിയും, ഞായറും, തിങ്കളും ദിവസങ്ങളാണ് വ്രതമനുഷ്ഠിച്ചതെങ്കിൽ മറ്റൊരു മാസത്തിലെ ചൊവ്വ, ബുധൻ, വ്യാഴം എന്നീ ദിവസങ്ങളിലാവും വ്രതമനുഷ്ഠിക്കുക. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 87, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثَلَاثٍ: بِنَوْمٍ عَلَى وِتْرٍ، وَالْغُسْلِ يَوْمَ الْجُمُعَةِ، وَصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ. وَفِي رِوَايَةٍ: أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَكْعَتَيِ الضُّحَى، وَأَنْ لَا أَنَامَ إِلَّا عَلَى وِتْرٍ، وَصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ. (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) എന്നോട് മൂന്നു കാര്യങ്ങൾ കൽപിച്ചു: വിത്ർ നിസ്കരിച്ച് ഉറങ്ങുക, വെള്ളിയാഴ്ച ദിവസം കുളിക്കുക, മാസത്തിൽ മൂന്നുദിനം നോമ്പനുഷ്ഠിക്കുക. മറ്റൊരു നിവേദനം: എല്ലാ മാസവും മൂന്നു ദിവസം നോമ്പെടുക്കാനും വിത്റ് നിസ്കരിച്ചിട്ടല്ലാതെ ഉറങ്ങാതിരിക്കാനും ളുഹായുടെ രണ്ട് റക്അത് നിസ്കരിക്കാനും നബി(സ) എന്നോടു കൽപിച്ചു. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 87, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=150), 1, 'وَفِي رِوَايَةٍ: أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَكْعَتَيِ الضُّحَى، وَأَنْ لَا أَنَامَ إِلَّا عَلَى وِتْرٍ، وَصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ. (ن)', 'മറ്റൊരു നിവേദനം: എല്ലാ മാസവും മൂന്നു ദിവസം നോമ്പെടുക്കാനും വിത്റ് നിസ്കരിച്ചിട്ടല്ലാതെ ഉറങ്ങാതിരിക്കാനും ളുഹായുടെ രണ്ട് റക്അത് നിസ്കരിക്കാനും നബി(സ) എന്നോടു കൽപിച്ചു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَامَ ثَلَاثَةَ أَيَّامٍ مِنَ الشَّهْرِ فَقَدْ صَامَ الدَّهْرَ كُلَّهُ". ثُمَّ قَالَ: "صَدَقَ اللَّهُ فِي كِتَابِهِ: {مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا} [الأنعام: ١٦٠]". وَفِي رِوَايَةٍ: "فَقَدْ تَمَّ صَوْمُ الشَّهْرِ. أَوْ: فَلَهُ صَوْمُ الشَّهْرِ". (ت،جه)', 'അബൂദർറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും മാസം മൂന്നുദിവസം നോമ്പെടുത്താൽ അവൻ കൊല്ലം മുഴുക്കെ നോമ്പെടുത്തു." പിന്നെ നബി(സ) പറഞ്ഞു: " ''ആരെങ്കിലും ഒരു നന്മ ചെയ്താൽ അവന് അതിന്റെ പത്തിരട്ടിയുണ്ടെന്ന അല്ലാഹുവിന്റെ വചനം എത്ര സത്യമാണ്.'' " മറ്റൊരു നിവേദനം: "ഒരു മാസത്തെ വ്രതം പൂർത്തിയാക്കി." അല്ലെങ്കിൽ "അവന് ഒരു മാസത്തെ വ്രതമുണ്ട്." (തു,ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], 'الأنعام: ١٦٠', null, 88, 88, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=151), 1, 'وَفِي رِوَايَةٍ: "فَقَدْ تَمَّ صَوْمُ الشَّهْرِ. أَوْ: فَلَهُ صَوْمُ الشَّهْرِ". (ت،جه)', 'മറ്റൊരു നിവേദനം: "ഒരു മാസത്തെ വ്രതം പൂർത്തിയാക്കി." അല്ലെങ്കിൽ "അവന് ഒരു മാസത്തെ വ്രതമുണ്ട്." (തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ عَمْرِو بْنِ شُرَحْبِيلَ الْهَمْدَانِيِّ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قِيلَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَجُلٌ يَصُومُ الدَّهْرَ؟ قَالَ: "وَدِدْتُ أَنَّهُ لَمْ يَطْعَمِ الدَّهْرَ". قَالُوا: فَثُلُثَيْهِ؟ قَالَ: "أَكْثَرَ". قَالُوا: فَنِصْفَهُ؟ قَالَ: "أَكْثَرَ". ثُمَّ قَالَ: "أَلَا أُخْبِرُكُمْ بِمَا يُذْهِبُ وَحَرَ الصَّدْرِ؟ صَوْمُ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ". وَفِي رِوَايَةٍ: قَالَ: أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، مَا تَقُولُ فِي رَجُلٍ صَامَ الدَّهْرَ كُلَّهُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَدِدْتُ أَنَّهُ لَمْ يَطْعَمِ الدَّهْرَ شَيْئًا". قَالَ: فَثُلُثَيْهِ؟ قَالَ: "أَكْثَرَ". قَالَ: فَنِصْفَهُ؟ قَالَ: "أَكْثَرَ". قَالَ: "أَفَلَا أُخْبِرُكُمْ بِمَا يُذْهِبُ وَحَرَ الصَّدْرِ". قَالُوا: بَلَى. قَالَ: "صِيَامُ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ". (ن)', 'റസൂൽ(സ)യുടെ അനുചരരിൽപെട്ട ഒരാളിൽനിന്ന് അംറുബ്നു ശുറഹ്ബീലുൽ ഹമദാനി(റ): വർഷം മുഴുവൻ നോമ്പെടുക്കുന്ന ഒരാളെക്കുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അവിടന്ന് പറഞ്ഞു: "അവൻ വർഷത്തിൽ തീരേ ഭക്ഷിക്കുന്നില്ല എന്ന് ഞാൻ മനസ്സിലാക്കുന്നു." അവർ ചോദിച്ചു: വർഷത്തിൽ മൂന്നിൽ രണ്ടോ? അവിടന്നരുളി: "വളരെ കൂടുതലാണ്." അവർ ചോദിച്ചു: അതിന്റെ പകുതിയോ? അവിടന്ന് പറഞ്ഞു: "വളരെ കൂടുതലാണ്". എന്നിട്ട് തിരുമേനി(സ) അരുളി: "മനസ്സിന്റെ പക പോക്കിക്കളയുന്ന കാര്യം നിങ്ങൾക്കറിയിച്ചുതരട്ടെയോ? ഓരോ മാസത്തിലും മൂന്നു ദിവസം നോമ്പെടുക്കുക." മറ്റൊരു റിപ്പോർട്ട്: ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് കാലം മുഴുവൻ നോമ്പനുഷ്ഠിക്കുന്ന ഒരാളെക്കുറിച്ചു താങ്കളുടെ അഭിപ്രായമെന്താണ് റസൂലേ? എന്ന് ചോദിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അദ്ദേഹം അത്രയും കാലം ഭക്ഷണമൊന്നും കഴിച്ചില്ലെന്ന് ഞാൻ മനസ്സിലാക്കുന്നു." അവർ ചോദിച്ചു: വർഷത്തിൽ മൂന്നിൽ രണ്ട് ഭാഗമോ? നബി(സ) പറഞ്ഞു: "വളരെ കൂടുതലാണ്." അവർ ചോദിച്ചു: വർഷത്തിൽ പകുതിയോ? നബി(സ) പറഞ്ഞു: "വളരെ കൂടുതലാണ്." ശേഷം നബി(സ) പറഞ്ഞു: "മനസ്സിന്റെ ദേഷ്യം ഇല്ലാതാക്കിക്കളയുന്ന കാര്യം നിങ്ങൾക്കറിയിച്ചു തരട്ടെയോ?" അവർ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "മാസത്തിൽ മൂന്ന് ദിവസം നോമ്പനുഷ്ഠിക്കുക." (ന)', 'عَمْرِو بْنِ شُرَحْبِيلَ الْهَمْدَانِيِّ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ', 'റസൂൽ(സ)യുടെ അനുചരരിൽപെട്ട ഒരാളിൽനിന്ന് അംറുബ്നു ശുറഹ്ബീലുൽ ഹമദാനി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 88, 88, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=152), 1, 'وَفِي رِوَايَةٍ: قَالَ: أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، مَا تَقُولُ فِي رَجُلٍ صَامَ الدَّهْرَ كُلَّهُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَدِدْتُ أَنَّهُ لَمْ يَطْعَمِ الدَّهْرَ شَيْئًا". قَالَ: فَثُلُثَيْهِ؟ قَالَ: "أَكْثَرَ". قَالَ: فَنِصْفَهُ؟ قَالَ: "أَكْثَرَ". قَالَ: "أَفَلَا أُخْبِرُكُمْ بِمَا يُذْهِبُ وَحَرَ الصَّدْرِ". قَالُوا: بَلَى. قَالَ: "صِيَامُ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ". (ن)', 'മറ്റൊരു നിവേദന്: ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് കാലം മുഴുവൻ നോമ്പനുഷ്ഠിക്കുന്ന ഒരാളെക്കുറിച്ചു താങ്കളുടെ അഭിപ്രായമെന്താണ് റസൂലേ? എന്ന് ചോദിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അദ്ദേഹം അത്രയും കാലം ഭക്ഷണമൊന്നും കഴിച്ചില്ലെന്ന് ഞാൻ മനസ്സിലാക്കുന്നു." അവർ ചോദിച്ചു: വർഷത്തിൽ മൂന്നിൽ രണ്ട് ഭാഗമോ? നബി(സ) പറഞ്ഞു: "വളരെ കൂടുതലാണ്." അവർ ചോദിച്ചു: വർഷത്തിൽ പകുതിയോ? നബി(സ) പറഞ്ഞു: "വളരെ കൂടുതലാണ്." ശേഷം നബി(സ) പറഞ്ഞു: "മനസ്സിന്റെ ദേഷ്യം ഇല്ലാതാക്കിക്കളയുന്ന കാര്യം നിങ്ങൾക്കറിയിച്ചു തരട്ടെയോ?" അവർ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "മാസത്തിൽ മൂന്ന് ദിവസം നോമ്പനുഷ്ഠിക്കുക." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا عَبْدَ اللَّهِ بْنَ عَمْرٍو، إِنَّكَ تَصُومُ الدَّهْرَ وَتَقُومُ اللَّيْلَ، وَإِنَّكَ إِذَا فَعَلْتَ ذَلِكَ هَجَمَتِ الْعَيْنُ وَنَفِهَتْ لَهُ النَّفْسُ، لَا صَامَ مَنْ صَامَ الْأَبَدَ، صَوْمُ الدَّهْرِ ثَلَاثَةُ أَيَّامٍ مِنَ الشَّهْرِ، صَوْمُ الدَّهْرِ كُلِّهِ". قُلْتُ: إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ. قَالَ: "صُمْ صَوْمَ دَاوُدَ: كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا، وَلَا يَفِرُّ إِذَا لَاقَى". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): എന്നോട് റസൂൽ(സ) പറഞ്ഞു: "അബ്ദുല്ലാഹിബ്നു അംറേ, നീ നിത്യവും നോമ്പെടുക്കുകയും രാത്രി മുഴുവൻ നിസ്കരിക്കുകയും ചെയ്യുന്നു. അങ്ങനെ നീ ചെയ്താൽ നിന്റെ കണ്ണു കുഴിഞ്ഞുപോവുകയും ശരീരം ക്ഷീണിക്കുകയും ചെയ്യും. നിത്യനോമ്പെടുത്തവൻ നോമ്പെടുത്തിട്ടില്ല. ഒരു വർഷത്തെ നോമ്പെന്നാൽ ഓരോ മാസത്തിലെയും മൂന്നു ദിവസമാണ്. ആകാലം മൊത്തമുള്ള നോമ്പാണത്" ഞാൻ പറഞ്ഞു: എനിക്കതിലേറെ കഴിയും. അവിടന്നരുളി: "നീ ദാവൂദ്(അ)ന്റെ നോമ്പെടുക്കുക. അദ്ദേഹം ഒരു ദിനം നോമ്പെടുക്കും. അടുത്തദിനം നോമ്പുപേക്ഷിക്കുകയും ചെയ്യും. ശത്രുവിനെ കണ്ടുമുട്ടിയാൽ അദ്ദേഹം പിന്തിരിയുകയില്ല." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 88, 89, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذُكِرَ لَهُ صَوْمِي فَدَخَلَ عَلَيَّ، فَأَلْقَيْتُ لَهُ وِسَادَةَ أَدَمٍ رَبْعَةً، حَشْوُهَا لِيفٌ، فَجَلَسَ عَلَى الْأَرْضِ وَصَارَتِ الْوِسَادَةُ فِيمَا بَيْنِي وَبَيْنَهُ، قَالَ: "أَمَا يَكْفِيكَ مِنْ كُلِّ شَهْرٍ ثَلَاثَةُ أَيَّامٍ". قُلْتُ: يَا رَسُولَ اللَّهِ، قَالَ: "خَمْسًا". قُلْتُ: يَا رَسُولَ اللَّهِ، قَالَ: "سَبْعًا". قُلْتُ: يَا رَسُولَ اللَّهِ، قَالَ: "تِسْعًا". قُلْتُ: يَا رَسُولَ اللَّهِ، قَالَ: "إِحْدَى عَشْرَةَ". قُلْتُ: يَا رَسُولَ اللَّهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا صَوْمَ فَوْقَ صَوْمِ دَاوُدَ، شَطْرَ الدَّهْرِ: صِيَامُ يَوْمٍ وَفِطْرُ يَوْمٍ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ)യോട് എന്റെ നോമ്പിനെക്കുറിച്ച് ഉണർത്തപ്പെട്ടപ്പോൾ അവിടന്ന് എന്റെയടുത്തേക്കു വന്നു. തോലുകൊണ്ടുനിർമിച്ച മിതമായ വലിപ്പത്തിലുള്ള ഒരു തലയിണ ഞാൻ റസൂൽ(സ)ക്ക് നൽകി. അതിൽ നിറച്ചിരിക്കുന്നത് പനനാരാണ്. അവിടന്ന് തറയിലിരുന്നു. എന്റെയും അവിടത്തെയും ഇടയിലായിരുന്നു തലയിണ. അവിടന്ന് അരുളി: "ഓരോ മാസവും മൂന്ന് ദിവസം (നോമ്പ്) പോരേ നിങ്ങൾക്ക്." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ. അവിടന്ന് പറഞ്ഞു: "അഞ്ച്." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ. അവിടന്നരുളി: "ഏഴ്." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ. അവിടന്നരുളി: "ഒമ്പത്." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ. അവിടന്നരുളി: "പതിനൊന്ന്." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ. അപ്പോൾ അവിടന്നരുളി: "ദാവൂദ്(അ)ന്റെ നോമ്പിനപ്പുറം ഒരു നോമ്പില്ല. കൊല്ലത്തിന്റെ പകുതിയാണത്. അഥവാ ഒരു ദിവസം നോമ്പെടുക്കുക, അടുത്ത ദിവസം നോമ്പുപേക്ഷിക്കുക." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 89, 89, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "صِيَامٌ حَسَنٌ ثَلَاثَةُ أَيَّامٍ مِنَ الشَّهْرِ". (ن)', 'ഉസ്മാനുബ്നു അബിൽ ആസ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മാസത്തിലെ മൂന്നുദിവസത്തെ നോമ്പാണ് നല്ല നോമ്പ്." (ന)', 'عُثْمَانَ بْنِ أَبِي الْعَاصِ', 'ഉസ്മാനുബ്നു അബിൽ ആസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 89, 89, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَصُومُ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ: يَوْمَ الِاثْنَيْنِ مِنْ أَوَّلِ الشَّهْرِ، وَالْخَمِيسَ الَّذِي يَلِيهِ، ثُمَّ الْخَمِيسَ الَّذِي يَلِيهِ. (ن)', 'ഇബ്നുഉമർ(റ): എല്ലാ മാസവും മൂന്നു ദിവസം നബി(സ) നോമ്പെടുക്കാറുണ്ട്: മാസത്തിന്റെ ആദ്യത്തെ തിങ്കളാഴ്ച, തുടർന്നുവരുന്ന വ്യാഴാഴ്ച, പിന്നെ അതിനോടടുത്ത വ്യാഴാഴ്ചയും. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 89, 89, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ حَفْصَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أَرْبَعٌ لَمْ يَكُنْ يَدَعُهُنَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صِيَامَ عَاشُورَاءَ، وَالْعَشْرَ، وَثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَرَكْعَتَيْنِ قَبْلَ الْغَدَاةِ. (ن)', 'ഹഫ്സ(റ): നാലു കാര്യങ്ങൾ നബി(സ) ഉപേക്ഷിക്കാറില്ല. ആശൂറാഅ് നോമ്പ്, ദുൽഹജ്ജ് മാസത്തെ പത്ത് നോമ്പും, മാസത്തിലെ മൂന്ന് ദിവസത്തെ നോമ്പും, പ്രഭാതത്തിലെ സുബ്ഹിക്ക് മുമ്പുള്ള രണ്ടു റക്അത്തുകളും. (ന)', 'حَفْصَةَ', 'ഹഫ്സ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 89, 89, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَصُومُ تِسْعًا مِنْ ذِي الْحِجَّةِ، وَيَوْمَ عَاشُورَاءَ، وَثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ: أَوَّلَ اثْنَيْنِ مِنَ الشَّهْرِ، وَخَمِيسَيْنِ. وَفِي رِوَايَةٍ: قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ الْعَشْرَ، وَثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ: الِاثْنَيْنِ وَالْخَمِيسَ. وَفِي رِوَايَةٍ: قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُ بِصِيَامِ ثَلَاثَةِ أَيَّامٍ: أَوَّلِ خَمِيسٍ، وَالِاثْنَيْنِ، وَالِاثْنَيْنِ. (ن)', 'ഉമ്മുസലമ(റ): ദുൽഹജ്ജിലെ ഒമ്പതു ദിവസവും ആശൂറാഅ് ദിവസവും എല്ലാ മാസവും മൂന്നു ദിവസവും, അഥവാ മാസത്തിലെ ആദ്യ തിങ്കളാഴ്ചയും രണ്ടു വ്യാഴാഴ്ചകളും, നബി(സ) നോമ്പനുഷ്ഠിച്ചിരുന്നു. മറ്റൊരു നിവേദനം: ദുൽഹജ്ജ് പത്തും എല്ലാ മാസവും മൂന്നു ദിവസവും, അഥവാ തിങ്കളാഴ്ചയും വ്യാഴാഴ്ചയും, നബി(സ) നോമ്പെടുക്കാറുണ്ട്. മറ്റൊരു നിവേദനം: ആദ്യത്തെ വ്യാഴാഴ്ചയും തുടർന്ന് വരുന്ന രണ്ട് തിങ്കളാഴ്ചകളിലും നബി(സ) നോമ്പെടുക്കാൻ കൽപ്പിച്ചിരുന്നു. (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 89, 90, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=158), 1, 'وَفِي رِوَايَةٍ: قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ الْعَشْرَ، وَثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ: الِاثْنَيْنِ وَالْخَمِيسَ.', 'മറ്റൊരു നിവേദനം: ദുൽഹജ്ജ് പത്തും എല്ലാ മാസവും മൂന്നു ദിവസവും, അഥവാ തിങ്കളാഴ്ചയും വ്യാഴാഴ്ചയും, നബി(സ) നോമ്പെടുക്കാറുണ്ട്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=158), 2, 'وَفِي رِوَايَةٍ: قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُ بِصِيَامِ ثَلَاثَةِ أَيَّامٍ: أَوَّلِ خَمِيسٍ، وَالِاثْنَيْنِ، وَالِاثْنَيْنِ. (ن)', 'മറ്റൊരു നിവേദനം: ആദ്യത്തെ വ്യാഴാഴ്ചയും തുടർന്ന് വരുന്ന രണ്ട് തിങ്കളാഴ്ചകളിലും നബി(സ) നോമ്പെടുക്കാൻ കൽപ്പിച്ചിരുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ مُوسَى بْنِ طَلْحَةَ قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَرْنَبٍ قَدْ شَوَاهَا رَجُلٌ، فَلَمَّا قَدَّمَهَا إِلَيْهِ قَالَ: يَا رَسُولَ اللَّهِ، إِنِّي قَدْ رَأَيْتُ بِهَا دَمًا. فَتَرَكَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَأْكُلْهَا، وَقَالَ لِمَنْ عِنْدَهُ: "كُلُوا فَإِنِّي لَوِ اشْتَهَيْتُهَا أَكَلْتُهَا". وَرَجُلٌ جَالِسٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ادْنُ فَكُلْ مَعَ الْقَوْمِ". فَقَالَ: يَا رَسُولَ اللَّهِ إِنِّي صَائِمٌ. قَالَ: "فَهَلَّا صُمْتَ الْبِيضَ". قَالَ: وَمَا هُنَّ؟ قَالَ: ثَلَاثَ عَشْرَةَ وَأَرْبَعَ عَشْرَةَ وَخَمْسَ عَشْرَةَ. (ن)', 'മൂസബ്നു ത്വൽഹ(റ): വേവിച്ച മുയലുമായി ഒരാൾ നബി(സ)യുടെ അടുക്കൽ വന്നു. നബി(സ)ക്ക് അതു സമർപ്പിച്ചുകൊണ്ട് അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഇതിൽ അൽപം രക്തം ഞാൻ കണ്ടിട്ടുണ്ട്. അപ്പോൾ റസൂൽ(സ) അത് ഉപേക്ഷിച്ചു, ഭക്ഷിച്ചില്ല. കൂടെയുള്ളവരോട് നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഭക്ഷിച്ചു കൊള്ളുക, എനിക്കാഗ്രഹമുണ്ടെങ്കിൽ ഞാൻ തിന്നുമായിരുന്നു." അവിടെ ഇരിക്കുന്ന ഒരാളോട് നബി(സ) പറഞ്ഞു: "ഇവിടെ അടുത്ത് വന്ന് ഇവരോടൊപ്പം ഭക്ഷിക്കുക." അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ നോമ്പുകാരനാണ്. റസൂൽ(സ) പറഞ്ഞു: "വെളുത്തവാവു ദിനങ്ങളിൽ നോമ്പനുഷ്ഠിച്ചുകൂടായിരുന്നോ?" അദ്ദേഹം ചോദിച്ചു: അതേതാണ്? നബി(സ) പറഞ്ഞു: "പതിമൂന്ന്, പതിനാല്, പതിനഞ്ച്." (ന)', 'مُوسَى بْنِ طَلْحَةَ قَالَ', 'മൂസബ്നു ത്വൽഹ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 90, 90, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنِ الْمِنْهَالِ: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ يَأْمُرُ بِصِيَامِ الْبِيضِ: ثَلَاثَ عَشْرَةَ، وَأَرْبَعَ عَشْرَةَ، وَخَمْسَ عَشْرَةَ. وَيَقُولُ: "هُوَ كَصَوْمِ الدَّهْرِ. أَوْ: كَهَيْئَةِ صَوْمِ الدَّهْرِ". (د،ن،جه)', 'മിൻഹാൽ(റ): നബി(സ) മാസത്തിലെ പതിമൂന്ന്, പതിനാല്, പതിനഞ്ച് എന്നീ ദിനങ്ങളിൽ (വെളുത്ത വാവു ദിനങ്ങളിൽ) നോമ്പനുഷ്ഠിക്കാൻ കൽപ്പിച്ചിരുന്നു. നബി(സ) പറഞ്ഞു: "അത് കാലം മുഴുവൻ നോമ്പനുഷ്ഠിക്കുന്നത് പോലെയാണ്. അല്ലെങ്കിൽ അതേ രൂപത്തിലാണ്." (ദ,ന,ജ)', 'الْمِنْهَالِ', 'മിൻഹാൽ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 90, 90, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا ذَرٍّ، إِذَا صُمْتَ مِنَ الشَّهْرِ ثَلَاثَةَ أَيَّامٍ، فَصُمْ ثَلَاثَ عَشْرَةَ وَأَرْبَعَ عَشْرَةَ وَخَمْسَ عَشْرَةَ". حَسَنٌ. (م،ت)', 'അബൂദർറ് (റ): റസൂൽ(സ) പറഞ്ഞു: "അബൂദർറേ, നീ ഒരു മാസത്തിൽ മൂന്നു ദിവസം വ്രതമനുഷ്ഠിക്കുകയാണെങ്കിൽ പതിമൂന്ന്, പതിനാല്, പതിനഞ്ച് എന്നീ ദിവസങ്ങളിലായിക്കൊള്ളട്ടെ." (മു,തു)', 'أَبِي ذَرٍّ', 'അബൂദർറ് (റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 90, 90, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ أَرْنَبٌ قَدْ شَوَاهَا، وَخُبْزٌ، فَوَضَعَهَا بَيْنَ يَدَيِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: إِنِّي وَجَدْتُهَا تَدْمَى. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَصْحَابِهِ: "لَا يَضُرُّ، كُلُوا". وَقَالَ لِلْأَعْرَابِيِّ: "كُلْ". قَالَ: إِنِّي صَائِمٌ. قَالَ: "صَوْمُ مَاذَا". قَالَ: صَوْمُ ثَلَاثَةِ أَيَّامٍ مِنَ الشَّهْرِ. قَالَ: "إِنْ كُنْتَ صَائِمًا فَعَلَيْكَ بِالْغُرِّ الْبِيضِ: ثَلَاثَ عَشْرَةَ وَأَرْبَعَ عَشْرَةَ وَخَمْسَ عَشْرَةَ". (ن)', 'അബൂദർറ്(റ): ഒരു ഗ്രാമവാസി നബി(സ)യുടെ അടുക്കലേക്ക് വേവിച്ച മുയലിറച്ചിയും പത്തിരിയുമായെത്തി നബി(സ)യുടെ മുന്നിൽ സമർപ്പിച്ചു. എന്നിട്ട് പറഞ്ഞു: ഇത് രക്തം പുരണ്ട നിലയിലാണ് എനിക്ക് കിട്ടിയത്. അപ്പോൾ നബി(സ) അനുയായികളോട് പറഞ്ഞു: "നിങ്ങൾ ഭക്ഷിച്ചു കൊള്ളുക, പ്രശ്നമില്ല". ഗ്രാമവാസിയോട് പറഞ്ഞു: "നിങ്ങൾ ഭക്ഷിച്ചോളൂ." അയാൾ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. നബി(സ) ചോദിച്ചു: "ഏത് നോമ്പാണ്?" അയാൾ പറഞ്ഞു: മാസത്തിൽ അനുഷ്ഠിക്കുന്ന മൂന്ന് ദിവസത്തെ നോമ്പ്. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നോമ്പനുഷ്ഠിക്കുന്നുവെങ്കിൽ വെളുത്തവാവു ദിനങ്ങളായ പതിമൂന്ന്, പതിനാല്, പതിനഞ്ച് എന്നീ ദിനങ്ങളിൽ നോമ്പനുഷ്ഠിക്കുക". (ന)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 90, 91, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يُفْطِرُ أَيَّامَ الْبِيضِ فِي حَضَرٍ وَلَا سَفَرٍ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) യാത്ര വേളയിലും, അല്ലാത്തപ്പോഴും വെളുത്തവാവു ദിനങ്ങളിലെ നോമ്പ് ഉപേക്ഷിക്കാറില്ല. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 91, 91, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنْ صَوْمِ يَوْمِ الِاثْنَيْنِ، فَقَالَ: "فِيهِ وُلِدْتُ، وَفِيهِ أُنْزِلَ عَلَيَّ". (م)', 'അബൂഖതാദ(റ): തിങ്കളാഴ്ചയിലെ നോമ്പിനെപറ്റി നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അന്നാണു ഞാൻ ജനിച്ചത്. അന്നാണ് എനിക്കു ഖുർആൻ ഇറക്കപ്പെട്ടത്." (മു)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 91, 91, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ حَفْصَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ ثَلَاثَةَ أَيَّامٍ مِنَ الشَّهْرِ: الِاثْنَيْنِ وَالْخَمِيسَ، وَالِاثْنَيْنِ مِنَ الْجُمُعَةِ الْأُخْرَى. (د،ن)', 'ഹഫ്സ(റ): നബി(സ) മാസത്തിൽ മൂന്നു ദിവസം നോമ്പെടുക്കാറുണ്ട്; തിങ്കളാഴ്ചയും വ്യാഴാഴ്ചയും മറ്റൊരാഴ്ചയിലെ തിങ്കളാഴ്ചയും. (ദ,ന)', 'حَفْصَةَ', 'ഹഫ്സ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 91, 91, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ مَوْلَى أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ انْطَلَقَ مَعَ أُسَامَةَ إِلَى وَادِي الْقُرَى فِي طَلَبِ مَالٍ لَهُ، فَكَانَ يَصُومُ يَوْمَ الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ، فَقَالَ لَهُ مَوْلَاهُ: لِمَ تَصُومُ يَوْمَ الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ وَأَنْتَ شَيْخٌ كَبِيرٌ؟ فَقَالَ: إِنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَصُومُ يَوْمَ الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ، وَسُئِلَ عَنْ ذَلِكَ، فَقَالَ: "إِنَّ أَعْمَالَ الْعِبَادِ تُعْرَضُ يَوْمَ الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ". (د،ن)', 'ഉസാമതുബ്നു സൈദ്(റ)വിന്റെ അടിമയിൽനിന്ന് നിവേദനം: അദ്ദേഹം ഉസാമ(റ)യോട് കൂടെ വാദിൽ ഖുറായിലേക്ക് തന്റെ സമ്പത്തന്വേഷിച്ചു പോയി. ഉസാമ(റ) തിങ്കളാഴ്ചയും വ്യാഴാഴ്ചയും നോമ്പെടുക്കാറുണ്ടായിരുന്നു. തന്റെ അടിമ ഉസാമ(റ)യോട് ചോദിച്ചു: വൃദ്ധനായിട്ടും എന്തിനാണു വ്യാഴാഴ്ചയും തിങ്കളാഴ്ചയും നോമ്പെടുക്കുന്നത്? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) തിങ്കളാഴ്ചയും വ്യാഴാഴ്ചയും നോമ്പെടുക്കാറുണ്ട്. "വ്യാഴാഴ്ചയും തിങ്കളാഴ്ചയും അടിമകളുടെ പ്രവർത്തനങ്ങൾ വെളിവാക്കപ്പെടുന്നു"വെന്നാണ് നബി(സ) അതേപ്പറ്റി ചോദിക്കപ്പെട്ടപ്പോൾ പറഞ്ഞത്. (ദ,ന)', 'مَوْلَى أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 91, 91, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ هُنَيْدَةَ بْنِ خَالِدٍ الْخُزَاعِيِّ، عَنْ أُمِّهِ، قَالَتْ: دَخَلْتُ عَلَى أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا فَسَأَلْتُهَا عَنِ الصِّيَامِ، فَقَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُنِي أَنْ أَصُومَ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، أَوَّلُهَا الِاثْنَيْنِ وَالْخَمِيسِ. (د،ن)', 'ഹുനൈദ(റ) തന്റെ ഉമ്മയിൽ നിന്ന് നിവേദനം: ഞാൻ ഉമ്മുസലമ(റ)യുടെ അടുത്ത് കടന്നുചെന്ന് അവരോട് നോമ്പിനെ സംബന്ധിച്ചു ആരാഞ്ഞു. അവർ പറഞ്ഞു: ഓരോ മാസവും മൂന്നുവീതം നോമ്പനുഷ്ഠിക്കാൻ റസൂൽ(സ) എന്നോട് കൽപിക്കാറുണ്ടായിരുന്നു. അതിൽ ആദ്യത്തേത് തിങ്കളും വ്യാഴവുമായിരിക്കും. (ദ,ന)', 'هُنَيْدَةَ بْنِ خَالِدٍ الْخُزَاعِيِّ، عَنْ أُمِّهِ، قَالَتْ', 'ഹുനൈദ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 91, 92, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ شَعْبَانَ وَرَمَضَانَ، وَيَتَحَرَّى الِاثْنَيْنِ وَالْخَمِيسَ. (ت،ن،جه)', 'ആഇശ(റ): റമസാൻ, ശഅ്ബാൻ മാസങ്ങളിൽ റസൂൽ(സ) വ്രതമനുഷ്ഠിക്കുകയും തിങ്കൾ, വ്യാഴം ദിവസങ്ങളെ പ്രത്യേകം പരിഗണിക്കുകയും ചെയ്യുമായിരുന്നു. (തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 92, 92, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَصُومُ الِاثْنَيْنِ وَالْخَمِيسَ. فَقِيلَ: يَا رَسُولَ اللَّهِ، إِنَّكَ تَصُومُ الِاثْنَيْنِ وَالْخَمِيسَ؟ فَقَالَ: "إِنَّ يَوْمَ الِاثْنَيْنِ وَالْخَمِيسِ يَغْفِرُ اللَّهُ فِيهِمَا لِكُلِّ مُسْلِمٍ إِلَّا مُهْتَجِرَيْنِ، يَقُولُ: دَعْهُمَا حَتَّى يَصْطَلِحَا". (ت،جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) തിങ്കൾ, വ്യാഴം ദിവസങ്ങളിൽ നോമ്പനുഷ്ഠിക്കാറുണ്ടായിരുന്നു. ആരോ പ്രവാചകർ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടന്ന് തിങ്കൾ, വ്യാഴം ദിവസങ്ങളിൽ നോമ്പനുഷ്ഠിക്കുന്നുണ്ടല്ലോ? റസൂൽ(സ) പ്രതിവചിച്ചു: "തിങ്കൾ, വ്യാഴം ദിവസങ്ങളിൽ അല്ലാഹു എല്ലാ മുസ്‌ലിംകൾക്കും പൊറുത്തുകൊടുക്കും, പരസ്പരം തെറ്റിപ്പിരിഞ്ഞവർക്കൊഴികെ. അല്ലാഹു പറയും: അവർ അനുരഞ്ജനത്തിലെത്തുന്നതുവരെ അവരുടെ കാര്യമങ്ങു വിട്ടേക്കുക." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 92, 92, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ مُسْلِمٍ الْقُرَشِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ- أَوْ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صِيَامِ الدَّهْرِ، فَقَالَ: "إِنَّ لِأَهْلِكَ عَلَيْكَ حَقًّا". ثُمَّ قَالَ: "صُمْ رَمَضَانَ وَالَّذِي يَلِيهِ، وَكُلَّ أَرْبِعَاءَ وَخَمِيسٍ، فَإِذَا أَنْتَ قَدْ صُمْتَ الدَّهْرَ وَأَفْطَرْتَ". (د،ت،ن)', 'മുസ്‌ലിമുൽ ഖുറശീ(റ): നിത്യവ്രതത്തെ (വർഷം മുഴുവൻ) സംബന്ധിച്ച് ഞാൻ അല്ലെങ്കിൽ മറ്റാരോ തിരുദൂതർ(സ)യോടാരാഞ്ഞു. അവിടന്നരുളി: "നിന്റെ കുടുംബത്തോട് നിനക്ക് കടമകളുണ്ട്." ശേഷം പറഞ്ഞു: "അതിനാൽ റമസാനിലും അതിനോടടുത്ത ദിനങ്ങളിലും എല്ലാ ബുധൻ, വ്യാഴം ദിവസങ്ങളിലും വ്രതമനുഷ്ഠിക്കുക. എന്നാൽ, നീ കാലം മുഴുവൻ നോമ്പനുഷ്ഠിച്ചവനും നോമ്പു മുറിച്ചവനുമായി." (ദ,തു,ന)', 'مُسْلِمٍ الْقُرَشِيِّ', 'മുസ്‌ലിമുൽ ഖുറശീ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 92, 92, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدِمَ الْمَدِينَةَ، فَوَجَدَ الْيَهُودَ صِيَامًا يَوْمَ عَاشُورَاءَ، فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا هَذَا الْيَوْمُ الَّذِي تَصُومُونَهُ". قَالُوا: هَذَا يَوْمٌ عَظِيمٌ أَنْجَى اللَّهُ فِيهِ مُوسَى وَقَوْمَهُ، وَغَرَّقَ فِرْعَوْنَ وَقَوْمَهُ، فَصَامَهُ مُوسَى شُكْرًا، فَنَحْنُ نَصُومُهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَنَحْنُ أَحَقُّ وَأَوْلَى بِمُوسَى مِنْكُمْ". فَصَامَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَمَرَ بِصِيَامِهِ. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) മദീനയിലെത്തി. ആശൂറാ ദിനത്തിൽ ജൂതർ വ്രതമനുഷ്ഠിക്കുന്നതായി നബി(സ)ക്കറിയാൻ സാധിച്ചു. റസൂൽ(സ) അവരോടു ചോദിച്ചു: "നിങ്ങൾ വ്രതമനുഷ്ഠിക്കുന്ന ഈ ദിനത്തിന്റെ പ്രത്യേകതയെന്താണ്?" അവർ പറഞ്ഞു: മൂസാനബിയെയും ജനതയെയും അല്ലാഹു രക്ഷിക്കുകയും ഫറോവയെയും തന്റെയാളുകളെയും അല്ലാഹു മുക്കിക്കൊല്ലുകയും ചെയ്ത മഹത്തായ ദിനമാണിത്. മൂസാ(അ) ഈ ദിനത്തിൽ നന്ദിപൂർവം വ്രതമനുഷ്ഠിച്ചു. അതിനാൽ ഞങ്ങളും നോമ്പനുഷ്ഠിക്കുന്നു. റസൂൽ(സ) അരുളി: "മൂസ(അ)യോട് നിങ്ങളെക്കാൾ ബന്ധമുള്ളവർ ഞങ്ങളാണ്." അങ്ങനെ റസൂൽ(സ) അന്നു വ്രതമെടുക്കുകയും വ്രതമെടുക്കാൻ കൽപിക്കുകയും ചെയ്തു. (ബു,മു,ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 92, 93, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ عُبَيْدِ اللَّهِ بْنِ أَبِي يَزِيدَ: أَنَّهُ سَمِعَ ابْنَ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا وَسُئِلَ عَنْ صِيَامِ يَوْمِ عَاشُورَاءَ، فَقَالَ: مَا عَلِمْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَامَ يَوْمًا يَطْلُبُ فَضْلَهُ عَلَى الْأَيَّامِ إِلَّا هَذَا الْيَوْمَ، وَلَا شَهْرًا إِلَّا هَذَا الشَّهْرَ. يَعْنِي رَمَضَانَ. (م)', 'ഉബൈദുല്ലാഹിബ്നു അബീയസീദ്(റ): ആശൂറാ ദിനത്തിലെ നോമ്പിനെ സംബന്ധിച്ച് ഇബ്നുഅബ്ബാസ്(റ)വിനോടാരോ ചോദിച്ചപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നത് അദ്ദേഹം കേട്ടു: ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: മറ്റു ദിനങ്ങളെക്കാൾ കൂടുതൽ മഹത്വം തേടി ഈ ദിനമൊഴികെ മറ്റൊരു ദിനവും റസൂൽ(സ) നോമ്പനുഷ്ഠിച്ചതായി ഞാനറിഞ്ഞിട്ടില്ല. മറ്റു മാസങ്ങളേക്കാൾ കൂടുതൽ മഹത്വം തേടി ഈ മാസമൊഴികെ, അഥവാ റമളാനൊഴികെ, മറ്റൊരു മാസവും തിരുമേനി(സ) നോമ്പനുഷ്ഠിച്ചതായും ഞാനറിഞ്ഞിട്ടില്ല. (മു)', 'عُبَيْدِ اللَّهِ بْنِ أَبِي يَزِيدَ', 'ഉബൈദുല്ലാഹിബ്നു അബീയസീദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 93, 93, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذِ بْنِ عَفْرَاءَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أَرْسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَدَاةَ عَاشُورَاءَ إِلَى قُرَى الْأَنْصَارِ الَّتِي حَوْلَ الْمَدِينَةِ: "مَنْ كَانَ أَصْبَحَ صَائِمًا فَلْيُتِمَّ صَوْمَهُ، وَمَنْ كَانَ أَصْبَحَ مُفْطِرًا فَلْيُتِمَّ بَقِيَّةَ يَوْمِهِ". فَكُنَّا بَعْدَ ذَلِكَ نَصُومُهُ وَنُصَوِّمُ صِبْيَانَنَا الصِّغَارَ مِنْهُمْ إِنْ شَاءَ اللَّهُ تَعَالَى، وَنَذْهَبُ إِلَى الْمَسْجِدِ فَنَجْعَلُ لَهُمُ اللُّعْبَةَ مِنَ الْعِهْنِ، فَإِذَا بَكَى أَحَدُهُمْ عَلَى الطَّعَامِ أَعْطَيْنَاهَا إِيَّاهُ عِنْدَ الْإِفْطَارِ. (م)', 'റുബയ്യിഅ്(റ): ആശൂറാഅ് ദിനത്തിൽ മദീനക്കു ചുറ്റുമുള്ള അൻസാറുകളുടെ ഗ്രാമത്തിലേക്ക് ഇപ്രകാരം പറയാനായി റസൂൽ(സ) ആളെയയച്ചു: "പ്രഭാതത്തിൽ ആരെങ്കിലും നോമ്പുകാരനാണെങ്കിൽ അവൻ അത് പൂർത്തിയാക്കട്ടെ. നോമ്പുകാരനല്ലെങ്കിൽ ദിവസത്തിന്റെ ബാക്കിഭാഗം അവൻ പൂർത്തിയാക്കട്ടെ." പിന്നീടുള്ള ആശൂറാ ദിനത്തിൽ ഞങ്ങൾ നോമ്പനുഷ്ഠിക്കുകയും കുട്ടികളെ നോമ്പെടുപ്പിക്കുകയും ചെയ്യുക പതിവായിരുന്നു. ഞങ്ങൾ പള്ളിയിൽ പോകുമ്പോൾ കുട്ടികൾക്കു കമ്പിളിയുടെ കളിക്കോപ്പുകൾ നൽകും. ആരെങ്കിലും ഭക്ഷണത്തിനായി കരഞ്ഞാൽ നോമ്പുതുറക്കുന്നതുവരെ കളിക്കോപ്പുകളാണ് നൽകുക. (മു)', 'الرُّبَيِّعِ بِنْتِ مُعَوِّذِ بْنِ عَفْرَاءَ', 'റുബയ്യിഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 93, 93, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: حِينَ صَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ عَاشُورَاءَ وَأَمَرَنَا بِصِيَامِهِ قَالُوا: يَا رَسُولَ اللَّهِ، إِنَّهُ يَوْمٌ تُعَظِّمُهُ الْيَهُودُ وَالنَّصَارَى؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَإِذَا كَانَ الْعَامُ الْمُقْبِلُ صُمْنَا يَوْمَ التَّاسِعِ". فَلَمْ يَأْتِ الْعَامُ الْمُقْبِلُ حَتَّى تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م،د)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ആശൂറാദിനത്തിൽ നബിതിരുമേനി(സ) വ്രതമനുഷ്ഠിക്കുകയും അനുഷ്ഠിക്കാൻ ഞങ്ങളോട് കൽപിക്കുകയും ചെയ്തപ്പോൾ അനുചരർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഇത് ജൂതരും ക്രൈസ്തവരും ആദരിക്കുന്ന ദിനമല്ലേ? "എങ്കിൽ അടുത്ത വർഷം നമുക്ക് മുഹർറം ഒമ്പതിനും നോമ്പനുഷ്ഠിക്കാം" എന്ന് അവിടന്ന് പ്രതിവചിച്ചു. പക്ഷേ, അടുത്ത വർഷമായപ്പോഴേക്കും തിരുമേനി(സ) ഇഹലോകത്തോട് യാത്രപറഞ്ഞിരുന്നു. (മു,ദ)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 93, 93, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنِ الْحَكَمِ بْنِ الْأَعْرَجِ قَالَ: أَتَيْتُ ابْنَ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا وَهُوَ مُتَوَسِّدٌ رِدَاءَهُ فِي الْمَسْجِدِ الْحَرَامِ، فَسَأَلْتُهُ عَنْ صَوْمِ يَوْمِ عَاشُورَاءَ؟ فَقَالَ: إِذَا رَأَيْتَ هِلَالَ الْمُحَرَّمِ فَاعْدُدْ، فَإِذَا كَانَ يَوْمُ التَّاسِعِ فَأَصْبِحْ صَائِمًا. فَقُلْتُ: كَذَا كَانَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ؟ فَقَالَ: كَذَلِكَ كَانَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ. (م،د،ت،ن)', 'ഹകമുബ്നുൽ അഅ്റജ്(റ): ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ അരികെ ചെന്നു. മസ്ജിദുൽ ഹറാമിൽ തന്റെ മേൽവസ്ത്രം തലയണയാക്കിക്കിടക്കുകയായിരുന്നു അദ്ദേഹം. ആശൂറാ ദിനത്തിലെ നോമ്പിനെ സംബന്ധിച്ച് ഞാനദ്ദേഹത്തോടാരാഞ്ഞു. അദ്ദേഹം പറഞ്ഞു: മുഹർറത്തിന്റെ മാസപ്പിറവി ദർശിച്ചതു മുതൽ നീ ദിനങ്ങൾ എണ്ണുകയും ഒമ്പതാം ദിവസമെത്തിയാൽ പ്രഭാതം മുതൽ വ്രതമനുഷ്ഠിക്കുകയും ചെയ്യുക. ഞാൻ ചോദിച്ചു: മുഹമ്മദ്നബി(സ) ഇങ്ങനെയാണോ നോമ്പനുഷ്ഠിച്ചിരുന്നത്? അദ്ദേഹം പറഞ്ഞു: അതെ, ഇപ്രകാരമായിരുന്നു നബി(സ)യുടെ നോമ്പ്. (മു,ദ,തു,ന)', 'الْحَكَمِ بْنِ الْأَعْرَجِ قَالَ', 'ഹകമുബ്നുൽ അഅ്റജ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 93, 94, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ مَسْلَمَةَ، عَنْ عَمِّهِ: أَنَّ أَسْلَمَ أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "صُمْتُمْ يَوْمَكُمْ هَذَا". قَالُوا: لَا، قَالَ: "فَأَتِمُّوا بَقِيَّةَ يَوْمِكُمْ وَاقْضُوهُ". قَالَ أَبُو دَاوُدَ: يَعْنِي يَوْمَ عَاشُورَاءَ. (د،ن)', 'തന്റെ പിതൃവ്യനിൽനിന്ന് അബ്ദുറഹ്മാനുബ്നു മസ്‌ലമ(റ) നിവേദനം ചെയ്യുന്നു: അസ്‌ലമ ഗോത്രക്കാർ തിരുമേനി(സ)യുടെ അരികെ ചെന്നു. റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങളിന്നു വ്രതമെടുത്തിട്ടുണ്ടോ?" ഇല്ല എന്ന് അവർ മറുപടി പറഞ്ഞു. അവിടന്ന് പറഞ്ഞു: "ഈ ദിവസത്തെ ബാക്കിഭാഗം നിങ്ങൾ പൂർത്തിയാക്കുക. ശേഷമത് ഖളാഅ് വീട്ടുക." അബൂദാവൂദ്(റ) പറയുന്നു: ഇതുകൊണ്ടുദ്ദേശിക്കുന്നത് ആശൂറാ ദിനത്തിലെ വ്രതമാകുന്നു. (ദ,ന)', 'عَبْدِ الرَّحْمَنِ بْنِ مَسْلَمَةَ، عَنْ عَمِّهِ', 'തന്റെ പിതൃവ്യനിൽനിന്ന് അബ്ദുറഹ്മാനുബ്നു മസ്‌ലമ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 94, 94, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ يَوْمُ عَاشُورَاءَ تَصُومُهُ قُرَيْشٌ فِي الْجَاهِلِيَّةِ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُهُ، فَلَمَّا قَدِمَ الْمَدِينَةَ صَامَهُ، وَأَمَرَ بِصِيَامِهِ، فَلَمَّا فُرِضَ رَمَضَانُ، تَرَكَ يَوْمَ عَاشُورَاءَ، فَمَنْ شَاءَ صَامَهُ، وَمَنْ شَاءَ تَرَكَهُ. وَفِي رِوَايَةٍ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ شَاءَ فَلْيَصُمْهُ، وَمَنْ شَاءَ فَلْيُفْطِرْهُ". (ق،ت)', 'ആഇശ(റ): ഖുറൈശികൾ ജാഹിലിയ്യാ കാലത്ത് ആശൂറാ ദിനത്തിൽ നോമ്പനുഷ്ഠിക്കുമായിരുന്നു. നബി(സ)യും ആ ദിനത്തിൽ നോമ്പനുഷ്ഠിച്ചു കൊണ്ടിരുന്നു. അപ്രകാരം മദീനയിൽ വന്നപ്പോഴും നബി(സ) ആ നോമ്പനുഷ്ഠിക്കുകയും, ജനങ്ങളോട് അത് കൽപ്പിക്കുകയും ചെയ്തു. പിന്നീട് റമസാൻ വ്രതം നിർബന്ധമാക്കപ്പെട്ടപ്പോൾ ആശൂറാ ദിനത്തിലെ നോമ്പ് ഒഴിവാക്കുകയും ചെയ്തു. പിന്നീട് ഉദ്ദേശിച്ചവർ അനുഷ്ഠിക്കുകയും, ഉദ്ദേശ്യമുള്ളവർ ഒഴിവാക്കുകയും ചെയ്തു. മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "ഇഷ്ടമുള്ളവർ അന്ന് നോമ്പനുഷ്ഠിക്കുകയും ഇഷ്ടമുള്ളവർ മുറിക്കുകയും ചെയ്യട്ടെ." (ബു,മു,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 94, 94, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=177), 1, 'وَفِي رِوَايَةٍ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ شَاءَ فَلْيَصُمْهُ، وَمَنْ شَاءَ فَلْيُفْطِرْهُ". (ق،ت)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "ഇഷ്ടമുള്ളവർ അന്ന് നോമ്പനുഷ്ഠിക്കുകയും ഇഷ്ടമുള്ളവർ മുറിക്കുകയും ചെയ്യട്ടെ." (ബു,മു,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ عَاشُورَاءُ يَوْمًا نَصُومُهُ فِي الْجَاهِلِيَّةِ، فَلَمَّا نَزَلَ رَمَضَانُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَذَا يَوْمٌ مِنْ أَيَّامِ اللَّهِ، فَمَنْ شَاءَ صَامَهُ، وَمَنْ شَاءَ تَرَكَهُ". (خ،د)', 'ഇബ്നുഉമർ(റ): ആശൂറാ ദിനത്തിലെ നോമ്പ് ജാഹിലിയ്യാ കാലത്ത് ഞങ്ങളനുഷ്ഠിച്ചിരുന്നു. റമളാനിനെ സംബന്ധിച്ച കൽപ്പന വന്നപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇത് (ആശൂറാഅ്) അല്ലാഹുവിന്റെ വിശേഷദിനങ്ങളിൽപ്പെട്ട ഒരു ദിനമാണ്. ഉദ്ദേശിക്കുന്നവർ വ്രതമനുഷ്ഠിക്കട്ടെ, അല്ലാത്തവർ ഉപേക്ഷിക്കട്ടെ." (ബു,ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 94, 94, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صِيَامُ يَوْمِ عَاشُورَاءَ: إِنِّي أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ". (م،ت)', 'അബൂഖതാദ(റ): നബി(സ) പറഞ്ഞു: "ആശൂറാദിനത്തിലെ നോമ്പുകാരണം കഴിഞ്ഞ വർഷത്തെ ദോഷം മുഴുവൻ അല്ലാഹു പൊറുക്കുമെന്നു ഞാനാശിക്കുന്നു." (മു,തു)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 94, 94, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ مُحَمَّدِ بْنِ صَيْفِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ عَاشُورَاءَ: "مِنْكُمْ أَحَدٌ طَعِمَ الْيَوْمَ". قُلْنَا: مِنَّا طَعِمَ وَمِنَّا مَنْ لَمْ يَطْعَمْ. قَالَ: "فَأَتِمُّوا بَقِيَّةَ يَوْمِكُمْ، مَنْ كَانَ طَعِمَ وَمَنْ لَمْ يَطْعَمْ. فَأَرْسِلُوا إِلَى أَهْلِ الْعَرُوضِ فَلْيُتِمُّوا بَقِيَّةَ يَوْمِهِمْ". قَالَ: يَعْنِي أَهْلَ الْعَرُوضِ حَوْلَ الْمَدِينَةِ. (جه)', 'മുഹമ്മദ്ബ്നു സ്വൈഫിയ്യ്(റ): റസൂൽ(സ) ആശൂറാദിനത്തിൽ ഞങ്ങളോട് ചോദിച്ചു: "നിങ്ങളിലാരെങ്കിലും ഇന്ന് ഭക്ഷണം കഴിച്ചിട്ടുണ്ടോ?" ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങളിൽ ഭക്ഷിച്ചവരുമുണ്ട്, ഭക്ഷിക്കാത്തവരുമുണ്ട്. അപ്പോൾ തിരുമേനി(സ) അരുളി: "ഭക്ഷിച്ചവരും ഭക്ഷിക്കാത്തവരും ഇന്നു ബാക്കിസമയം പൂർത്തിയാക്കിക്കൊള്ളുക. ദിവസത്തിൽനിന്നു ശേഷിക്കുന്ന സമയം പൂർത്തിയാക്കാൻ പരിസരവാസികളോട് പറയാൻ ഒരാളെ അയക്കുകയും ചെയ്യുക." നിവേദകൻ പറഞ്ഞു: നബി(സ) ഉദ്ദേശിച്ചത് മദീനക്ക് ചുറ്റുമധിവസിക്കുന്നവരേയാണ്. (ജ)', 'مُحَمَّدِ بْنِ صَيْفِيٍّ', 'മുഹമ്മദ്ബ്നു സ്വൈഫിയ്യ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 94, 95, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَئِنْ بَقِيتُ إِلَى قَابِلٍ لَأَصُومَنَّ الْيَوْمَ التَّاسِعَ". فِي رِوَايَةٍ: مَخَافَةَ أَنْ يَفُوتَهُ عَاشُورَاءُ. (م،جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) അരുളി: "അടുത്തവർഷം ഞാൻ ജീവിച്ചിരിക്കുകയാണെങ്കിൽ (മുഹർറമിലെ) ഒമ്പതാം ദിവസവും ഞാൻ വ്രതമനുഷ്ഠിക്കും." മറ്റൊരു റിപ്പോർട്ട്: ആശൂറാ നോമ്പ് നഷ്ടപ്പെടുമോ എന്ന ഭയത്താലാണത്. (മു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 95, 95, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=181), 1, null, 'മറ്റൊരു നിവേദന്: ആശൂറാ നോമ്പ് നഷ്ടപ്പെടുമോ എന്ന ഭയത്താലാണത്. (മു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ ذُكِرَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمُ عَاشُورَاءَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَانَ يَوْمًا يَصُومُهُ أَهْلُ الْجَاهِلِيَّةِ، فَمَنْ أَحَبَّ مِنْكُمْ أَنْ يَصُومَهُ فَلْيَصُمْهُ، وَمَنْ كَرِهَهُ فَلْيَدَعْهُ". (م،جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ആശൂറാദിനത്തെപ്പറ്റി റസൂൽ(സ)യുടെ സന്നിധിയിൽ പരാമർശിക്കപ്പെട്ടു. അവിടന്ന് അരുളി. "അത് (ആശൂറാദിനം) ജാഹിലിയ്യാ കാലത്തെയാളുകൾ വ്രതമനുഷ്ഠിക്കുന്ന ദിനമായിരുന്നു. നിങ്ങളിലാരെങ്കിലും ആശൂറാ നോമ്പ് അനുഷ്ഠിക്കുന്നുവെങ്കിൽ അനുഷ്ഠിച്ചുകൊള്ളട്ടെ. വെറുക്കുന്നുവെങ്കിൽ ഉപേക്ഷിക്കട്ടെ." (മു,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 95, 95, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ: رَجُلٌ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: كَيْفَ تَصُومُ؟ فَغَضِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ قَوْلِهِ، فَلَمَّا رَأَى عُمَرُ رَضِيَ اللَّهُ عَنْهُ غَضَبَهُ قَالَ: رَضِينَا بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ نَبِيًّا، نَعُوذُ بِاللَّهِ مِنْ غَضَبِ اللَّهِ وَغَضَبِ رَسُولِهِ. فَجَعَلَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ يُرَدِّدُ هَذَا الْكَلَامَ حَتَّى سَكَنَ غَضَبُهُ، فَقَالَ عُمَرُ: يَا رَسُولَ اللَّهِ، كَيْفَ بِمَنْ يَصُومُ الدَّهْرَ كُلَّهُ؟ قَالَ: "لَا صَامَ وَلَا أَفْطَرَ" أَوْ قَالَ: "لَمْ يَصُمْ وَلَمْ يُفْطِرْ". قَالَ: كَيْفَ مَنْ يَصُومُ يَوْمَيْنِ وَيُفْطِرُ يَوْمًا؟ قَالَ: "وَيُطِيقُ ذَلِكَ أَحَدٌ". قَالَ: كَيْفَ مَنْ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا؟ قَالَ: "ذَاكَ صَوْمُ دَاوُدَ عَلَيْهِ السَّلَامُ". قَالَ: كَيْفَ مَنْ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمَيْنِ؟ قَالَ: "وَدِدْتُ أَنِّي طُوِّقْتُ ذَلِكَ". ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثٌ مِنْ كُلِّ شَهْرٍ، وَرَمَضَانُ إِلَى رَمَضَانَ، فَهَذَا صِيَامُ الدَّهْرِ كُلِّهِ. صِيَامُ يَوْمِ عَرَفَةَ: أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ وَالسَّنَةَ الَّتِي بَعْدَهُ، وَصِيَامُ يَوْمِ عَاشُورَاءَ: أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ". (م)', 'അബൂഖതാദ(റ): ഒരാൾ റസൂൽ(സ)യുടെ അടുത്തു ചെന്ന് ചോദിച്ചു: അങ്ങ് എങ്ങനെയാണ് വ്രതമെടുക്കാറുള്ളത്?" ചോദ്യം കേട്ട റസൂൽ(സ) കോപാകുലനായി. അവിടത്തെ കോപം കണ്ട ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവിനെ രക്ഷിതാവായും ഇസ്‌ലാമിനെ മതമായും മുഹമ്മദ്(സ)യെ പ്രവാചകരായും ഞങ്ങൾ തൃപ്തിപ്പെട്ടിരിക്കുന്നു. അല്ലാഹുവിന്റെയും അവന്റെ തിരുദൂതരുടെയും കോപത്തിൽനിന്ന് അല്ലാഹുവിനോട് ഞങ്ങൾ കാവൽ തേടുന്നു. തിരുമേനി(സ)യുടെ കോപമടങ്ങുന്നതുവരെ ഉമർ(റ) അതാവർത്തിച്ചു. തുടർന്ന് ഉമർ(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, നിത്യവ്രതമെടുക്കുന്നവനെ സംബന്ധിച്ച് അവിടത്തെ അഭിപ്രായമെ ന്താണ്? അവിടന്ന് പ്രതിവചിച്ചു: "അവൻ വ്രതമെടുത്തിട്ടില്ല; മുറിച്ചിട്ടുമില്ല." അല്ലെങ്കിൽ "അവൻ നോമ്പെടുക്കുന്നുമില്ല, മുറിക്കുന്നുമില്ല." ഉമർ(റ) ചോദിച്ചു: രണ്ടുദിവസം നോമ്പെടുത്ത് ഒരു ദിവസം നോമ്പെടുക്കാത്തവനെങ്ങനെയാണ്? അവിടന്ന് പറഞ്ഞു: "അതാർക്കെങ്കിലും കഴിയുമോ." ഒരു ദിവസം നോമ്പെടുക്കുകയും മറ്റൊരു ദിനം നോമ്പ് മുറിക്കുകയും ചെയ്യുന്നവനെപ്പറ്റി ഉമർ(റ) ചോദിച്ചു. "അതാണ് ദാവൂദ്നബി(അ)യുടെ നോമ്പ്" എന്നവിടന്ന് പ്രത്യുത്തരം നൽകി. ഉമർ(റ) ചോദിച്ചു: ഒരു ദിവസം നോമ്പെടുത്തു രണ്ടു ദിവസം നോമ്പു മുറിക്കുന്നവനെ സംബന്ധിച്ച് എന്താണ് അങ്ങയുടെ അഭിപ്രായം? നബി(സ) പറഞ്ഞു: "അതിനെനിക്കു കഴിഞ്ഞിരുന്നെങ്കിൽ എന്നു ഞാനാഗ്രഹിക്കുന്നു." പിന്നീടവിടന്നരുളി: "ഓരോ മാസത്തിലെ മൂന്നു ദിവസവും റമളാൻ മാസവും നോമ്പെടുക്കുകയാണെങ്കിൽ അത് എല്ലാ കാലത്തും നോമ്പെടുക്കുന്നതിനു തുല്യമാണ്. അറഫാദിനത്തിലെ വ്രതം കാരണമായി അല്ലാഹു കഴിഞ്ഞതും വരാനുള്ളതുമായ ഓരോ വർഷത്തെ ദോഷം പൊറുത്തുതരുമെന്ന് ഞാൻ ആശിക്കുന്നു. ആശൂറാ ദിനത്തിലെ നോമ്പ് കാരണമായി കഴിഞ്ഞ ഒരു വർഷത്തെ പാപം അല്ലാഹു പൊറുത്തുതരുമെന്ന് ഞാനാശിക്കുന്നു." (മു)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 95, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ: عَنْ قَتَادَةَ بْنِ النُّعْمَانِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ صَامَ يَوْمَ عَرَفَةَ: غُفِرَ لَهُ سَنَةٌ أَمَامَهُ وَسَنَةٌ بَعْدَهُ". (جه)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ) ഖതാദതുബ്നു നുഅ്മാൻ(റ)വിൽ നിന്ന് നിവേദനം: "ആരെങ്കിലും അറഫാദിനത്തിലെ നോമ്പനുഷ്ഠിച്ചാൽ കഴിഞ്ഞു പോയതും വരാനിരിക്കുന്നതുമായ ഓരോ വർഷങ്ങളിലെ പാപങ്ങൾ അവന് പൊറുക്കപ്പെടുമെ"ന്ന് റസൂൽ(സ) പറഞ്ഞതായി ഞാൻ കേട്ടു. (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 96, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ صَوْمِ يَوْمِ عَرَفَةَ بِعَرَفَةَ. (د،ن،جه)', 'അബൂഹുറൈറ(റ): അറഫയിൽവെച്ച് അറഫ നോമ്പനുഷ്ഠിക്കുന്നതിനെ റസൂൽ(സ) വിലക്കി. (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 96, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ أُمِّ الْفَضْلِ بِنْتِ الْحَارِثِ رَضِيَ اللَّهُ عَنْهَا: أَنَّ نَاسًا تَمَارَوْا عِنْدَهَا يَوْمَ عَرَفَةَ فِي صَوْمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ بَعْضُهُمْ: هُوَ صَائِمٌ، وَقَالَ بَعْضُهُمْ: لَيْسَ بِصَائِمٍ، فَأَرْسَلَتْ إِلَيْهِ بِقَدَحِ لَبَنٍ وَهُوَ وَاقِفٌ عَلَى بَعِيرِهِ بِعَرَفَةَ، فَشَرِبَ. (ق،د،ت،ن)', 'ഹാരിസിന്റെ പുത്രി ഉമ്മുൽഫള്ൽ(റ): അറഫാദിനത്തിൽ കുറച്ചാളുകൾ മഹതിയുടെ അടുക്കൽവന്ന് റസൂൽ(സ)യുടെ വ്രതത്തിന്റെ കാര്യത്തിൽ പരസ്പരം സംശയം പ്രകടിപ്പിച്ചു. ചിലർ പറഞ്ഞു: റസൂൽ(സ) നോമ്പുകാരനാണ്. ചിലർ പറഞ്ഞു: അല്ല. തൽസമയം മഹതി റസൂൽ(സ)ക്ക് ഒരു പാത്രം പാലുമായി ആളെ അയച്ചു. അവിടന്ന് അറഫയിൽ ഒരു ഒട്ടകത്തിന് സമീപം നിൽക്കുകയായിരുന്നു. തിരുമേനി(സ) ആ പാൽ കുടിച്ചു. (ബു,മു,ദ,തു,ന)', 'أُمِّ الْفَضْلِ بِنْتِ الْحَارِثِ', 'ഹാരിസിന്റെ പുത്രി ഉമ്മുൽഫള്ൽ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 96, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، وَقَدْ سُئِلَ عَنْ صَوْمِ يَوْمِ عَرَفَةَ بِعَرَفَةَ؟ فَقَالَ: حَجَجْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَصُمْهُ، وَمَعَ أَبِي بَكْرٍ فَلَمْ يَصُمْهُ، وَمَعَ عُمَرَ فَلَمْ يَصُمْهُ، وَمَعَ عُثْمَانَ فَلَمْ يَصُمْهُ. وَأَنَا لَا أَصُومُهُ، وَلَا آمُرُ بِهِ، وَلَا أَنْهَى عَنْهُ. حَسَنٌ. (ت)', 'ഇബ്നുഉമർ(റ): അറഫയിൽ വെച്ച് അറഫാ നോമ്പെടുക്കുന്നതു സംബന്ധിച്ച ചോദ്യത്തിന് അദ്ദേഹം ഇപ്രകാരം മറുപടി പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യോടൊപ്പം ഹജ്ജ് ചെയ്തു. പക്ഷേ, അവിടന്ന് അറഫാ നോമ്പനുഷ്ഠിച്ചില്ല. അബൂബകർ(റ)വിന്റെ കൂടെയും ഹജ്ജ് ചെയ്തു. അവരും അത് നോറ്റില്ല. ഉമർ(റ)വിന്റെ കൂടെയും ഹജ്ജ് ചെയ്തു. അവരുമത് നോറ്റിട്ടില്ല. ഉസ്മാൻ(റ)ന്റെ കൂടെയും ഞാൻ ഹജ്ജ് ചെയ്തു. പക്ഷേ, അവരും ആ നോമ്പനുഷ്ഠിച്ചില്ല. ഞാൻ ആ നോമ്പനുഷ്ഠിക്കുകയോ അത് കൽപിക്കുകയോ വിരോധിക്കുകയോ ചെയ്യില്ല. (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 96, 97, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ مُجِيبَةَ الْبَاهِلِيَّةِ، عَنْ أَبِيهَا أَوْ عَمِّهَا- رَضِيَ اللَّهُ عَنْهُمَا- أَنَّهُ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ انْطَلَقَ فَأَتَاهُ بَعْدَ سَنَةٍ وَقَدْ تَغَيَّرَتْ حَالُهُ وَهَيْئَتُهُ، فَقَالَ: يَا رَسُولَ اللَّهِ، أَمَا تَعْرِفُنِي؟ قَالَ: "مَنْ أَنْتَ". قَالَ: أَنَا الْبَاهِلِيُّ الَّذِي جِئْتُكَ عَامَ الْأَوَّلِ. قَالَ "فَمَا غَيَّرَكَ، وَقَدْ كُنْتَ حَسَنَ الْهَيْئَةِ". قَالَ: مَا أَكَلْتُ طَعَامًا إِلَّا بِلَيْلٍ مُنْذُ فَارَقْتُكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لِمَ عَذَّبْتَ نَفْسَكَ". ثُمَّ قَالَ: "صُمْ شَهْرَ الصَّبْرِ وَيَوْمًا مِنْ كُلِّ شَهْرٍ". قَالَ: زِدْنِي فَإِنَّ بِي قُوَّةً. قَالَ: "صُمْ يَوْمَيْنِ". قَالَ: زِدْنِي. قَالَ: "صُمْ ثَلَاثَةَ أَيَّامٍ". قَالَ: زِدْنِي. قَالَ: "صُمْ مِنَ الْحُرُمِ وَاتْرُكْ، صُمْ مِنَ الْحُرُمِ وَاتْرُكْ". وَقَالَ بِأَصَابِعِهِ الثَّلَاثَةِ فَضَمَّهَا ثُمَّ أَرْسَلَهَا. (د،ن،جه)', 'മുജീബതുൽബാഹിലി(റ) തന്റെ പിതാവിൽ നിന്ന് അല്ലെങ്കിൽ പിതൃസഹോദരിനിൽ നിന്ന്: അദ്ദേഹം (പിതാവോ പിതൃസഹോദരനോ) ഒരിക്കൽ റസൂൽ(സ)യുടെ അരികെ ചെന്നു. പിന്നീട് തിരിച്ചുപോയി ഒരു വർഷത്തിനുശേഷം വീണ്ടും തിരുമേനി(സ)യുടെ അടുത്ത്വന്നു. ആ സമയത്ത് അദ്ദേഹത്തിന്റെ രൂപഭാവങ്ങൾ വളരെ വ്യത്യാസപ്പെട്ടിരുന്നു. അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്നെ അറിയുമോ? നബി(സ) ചോദിച്ചു: "നിങ്ങൾ ആരാണ്." അദ്ദേഹം പറഞ്ഞു: കഴിഞ്ഞവർഷം അങ്ങയുടെ അരികെ വന്നിരുന്ന ബാഹിലി ഗോത്രക്കാരനാണു ഞാൻ. നബി(സ) ചോദിച്ചു: "വളരെ സുമുഖനായിരുന്ന നിന്നെ ഇത്ര മാറ്റം വരുത്തിയ കാര്യമെന്താണ്?" അദ്ദേഹം പറഞ്ഞു: അങ്ങയെ വിട്ടുപിരിഞ്ഞതുമുതൽ ഞാൻ രാത്രി മാത്രമേ ഭക്ഷണം കഴിക്കാറുള്ളൂ. നബി(സ) പറഞ്ഞു: "എന്തിനാണു നീ സ്വയം ശിക്ഷിക്കുന്നത്?" ശേഷം അവിടന്നരുളി: "ക്ഷമയുടെ മാസവും (റമസാൻ) എല്ലാ മാസത്തിൽനിന്നും ഒരു ദിവസവും വ്രതമെടുക്കുക." അദ്ദേഹം പറഞ്ഞു: ഇനിയും കൂടുതലാക്കിത്തരിക. കാരണം, എനിക്കതിനുള്ള ശേഷിയുണ്ട്. നബി(സ) പറഞ്ഞു: "എങ്കിൽ രണ്ടു ദിവസം വ്രതമെടുക്കുക." അദ്ദേഹം പറഞ്ഞു: എനിക്കു കൂടുതലാക്കിത്തരിക. നബി(സ) പറഞ്ഞു: "എങ്കിൽ മൂന്നുദിവസം വ്രതമനുഷ്ഠിക്കുക." അദ്ദേഹം പറഞ്ഞു: ഇനിയും എനിക്ക് ഏറ്റിത്തരിക. നബി(സ) പറഞ്ഞു: "വിശുദ്ധമാസത്തിൽ വ്രതമെടുത്തുകൊള്ളുക, വ്രതം മുറിക്കുകയും ചെയ്യുക, വിശുദ്ധമാസത്തിൽ വ്രതമെടുക്കുകയും മുറിക്കുകയും ചെയ്യുക. വിശുദ്ധമാസത്തിൽ വ്രതമെടുക്കുകയും മുറിക്കുകയും ചെയ്യുക." അപ്പോൾ തിരുമേനി(സ) മൂന്നു വിരലുകൾ കൂട്ടിപ്പിടിക്കുകയും പിന്നീട് അയച്ചുവിടുകയും ചെയ്തു. (ദ,ന,ജ)', 'مُجِيبَةَ الْبَاهِلِيَّةِ، عَنْ أَبِيهَا أَوْ عَمِّهَا-', 'മുജീബതുൽബാഹിലി(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 97, 97, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ أَبِي مُجِيبَةَ الْبَاهِلِيِّ، عَنْ أَبِيهِ أَوْ عَنْ عَمِّهِ- رَضِيَ اللَّهُ عَنْهُمَا- قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا نَبِيَّ اللَّهِ، أَنَا الرَّجُلُ الَّذِي أَتَيْتُكَ عَامَ الْأَوَّلِ. قَالَ: "فَمَا لِي أَرَى جِسْمَكَ نَاحِلًا". قَالَ: يَا رَسُولَ اللَّهِ، مَا أَكَلْتُ طَعَامًا بِالنَّهَارِ، مَا أَكَلْتُهُ إِلَّا بِاللَّيْلِ. قَالَ: "مَنْ أَمَرَكَ أَنْ تُعَذِّبَ نَفْسَكَ". قُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي أَقْوَى. قَالَ: "صُمْ شَهْرَ الصَّبْرِ وَيَوْمًا بَعْدَهُ". قُلْتُ: إِنِّي أَقْوَى. قَالَ: "صُمْ شَهْرَ الصَّبْرِ وَيَوْمَيْنِ بَعْدَهُ". قُلْتُ: إِنِّي أَقْوَى. قَالَ: "صُمْ شَهْرَ الصَّبْرِ وَثَلَاثَةَ أَيَّامٍ بَعْدَهُ، وَصُمْ أَشْهُرَ الْحُرُمِ". (د،جه)', 'അബുമുജീബതുൽ ബാഹിലി(റ): അദ്ദേഹത്തിന്റെ പിതാവ് അല്ലെങ്കിൽ പിതൃസഹോദരൻ പറഞ്ഞു: ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ കഴിഞ്ഞവർഷം അങ്ങയുടെയടുക്കൽ വന്നയാളാണ്. നബി(സ) ചോദിച്ചു: "നിന്റെ ശരീരം മെലിഞ്ഞു കാണുന്നല്ലോ?" അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ രാത്രിയിൽ കഴിക്കുന്ന ഭക്ഷണമൊഴിച്ചു പകലിൽ ഒന്നും കഴിക്കാറില്ല. നബി(സ) ചോദിച്ചു: "നിന്റെ ശരീരത്തെ ശിക്ഷിക്കാൻ ആരാണ് നിന്നോട് കൽപ്പിച്ചത്." അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ ശക്തനാണ്. നബി(സ) പറഞ്ഞു: "നീ ക്ഷമയുടെ മാസം (റമസാൻ) മുഴുവനും, ശേഷമുള്ള മാസത്തിൽ ഒരു നോമ്പും അനുഷ്ഠിക്കുക." അദ്ദേഹം പറഞ്ഞു: എനിക്കതിലേറെ സാധിക്കും, നബി(സ) പറഞ്ഞു: "റമളാൻ മുഴുവനും, ശേഷമുള്ള മാസങ്ങളിൽ രണ്ട് ദിവസവും നോമ്പനുഷ്ഠിക്കുക." അദ്ദേഹം പറഞ്ഞു: ഞാൻ ശക്തനാണ്. നബി(സ) പറഞ്ഞു: "റമസാൻ മുഴുവനും, ശേഷമുള്ള മാസങ്ങളിൽ മൂന്ന് വീതവും, പവിത്രമാക്കപ്പെട്ട മാസങ്ങളിലും നോമ്പനുഷ്ഠിക്കുക." (ദ,ജ)', 'أَبِي مُجِيبَةَ الْبَاهِلِيِّ، عَنْ أَبِيهِ أَوْ عَنْ عَمِّهِ-', 'അബുമുജീബതുൽ ബാഹിലി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 97, 98, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَفْضَلُ الصِّيَامِ بَعْدَ شَهْرِ رَمَضَانَ شَهْرُ اللَّهِ الْمُحَرَّمُ، وَإِنَّ أَفْضَلَ الصَّلَاةِ بَعْدَ الْمَفْرُوضَةِ صَلَاةٌ مِنَ اللَّيْلِ". (م،د،ت،ن،جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) അരുളി: "റമസാൻ മാസത്തിലെ നോമ്പ് കഴിഞ്ഞാൽ ഏറ്റവും മഹത്വമേറിയ നോമ്പ് മുഹർറം മാസത്തിലെ നോമ്പാണ്. ഫർള് നിസ്കാരങ്ങൾക്കുശേഷം ഏറ്റവും ശ്രേഷ്ഠമേറിയ നിസ്കാരം രാത്രി നിസ്കാരമാണ്." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 98, 98, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ، وَقَدْ سَأَلَهُ رَجُلٌ فَقَالَ: أَيُّ شَهْرٍ تَأْمُرُنِي أَنْ أَصُومَ بَعْدَ شَهْرِ رَمَضَانَ؟ قَالَ لَهُ: مَا سَمِعْتُ أَحَدًا يَسْأَلُ عَنْ هَذَا إِلَّا رَجُلًا سَمِعْتُهُ يَسْأَلُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَنَا قَاعِدٌ عِنْدَهُ، فَقَالَ: يَا رَسُولَ اللَّهِ، أَيُّ شَهْرٍ تَأْمُرُنِي أَنْ أَصُومَ بَعْدَ شَهْرِ رَمَضَانَ؟ قَالَ: "إِنْ كُنْتَ صَائِمًا بَعْدَ شَهْرِ رَمَضَانَ فَصُم الْمُحَرَّمَ، فَإِنَّهُ شَهْرُ اللَّهِ، فِيهِ يَوْمٌ تَابَ فِيهِ عَلَى قَوْمٍ، وَيَتُوبُ فِيهِ عَلَى قَوْمٍ آخَرِينَ". حَسَنٌ. (ت)', 'അലി(റ): ഒരാളവരോട് ചോദിച്ചു: റമളാനിലേതല്ലാത്ത ഏതു മാസത്തെ നോമ്പാണു നിങ്ങൾ എന്നോട് കൽപിക്കുന്നത്? അലി(റ) പറഞ്ഞു: ഇതിനെ സംബന്ധിച്ച് ചോദിക്കുന്ന ഒരാളെയല്ലാതെ ആരെയും ഞാൻ കേട്ടിട്ടില്ല, ഞാൻ അടുത്തുണ്ടായിരിക്കെ തിരുദൂതർ(സ)യോട് ഒരാൾ ചോദിക്കുന്നതായി ഞാൻ കേട്ടു. അല്ലാഹുവിന്റെ റസൂലേ, റമസാനല്ലാത്ത ഏതു മാസം ഞാൻ വ്രതമെടുക്കണമെന്നാണ് അവിടുന്നെന്നോട് കൽപിക്കുന്നത്? അവിടുന്നരുളി: "റമളാനല്ലാത്ത വല്ല മാസവും വ്രതമെടുക്കാൻ ഉദ്ദേശിക്കുന്നെങ്കിൽ അത് മുഹർറത്തിലായിക്കൊള്ളട്ടെ. കാരണം, അത് അല്ലാഹുവിന്റെ മാസമാണ്. ഒരു ജനതക്കാകെ അല്ലാഹു മാപ്പുകൊടുത്ത ദിനമുണ്ടതിൽ, ഇനിയും പല ജനതക്കുമവൻ അതിൽ മാപ്പരുളും." (തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 98, 98, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ سَعِيدِ بْنِ جُبَيْرٍ، وَسُئِلَ عَنْ صِيَامِ رَجَبٍ؟ فَقَالَ: أَخْبَرَنِي ابْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَصُومُ حَتَّى نَقُولَ: لَا يُفْطِرُ، وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ. (ق،د،ن،جه)', 'സഈദുബ്നു ജുബൈർ: റജബിലെ നോമ്പിനെ സംബന്ധിച്ച് ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഇബ്നുഅബ്ബാസ്(റ) എന്നോട് പറഞ്ഞു: റസൂൽ(സ) തീരേ നോമ്പുപേക്ഷിക്കുകയില്ല എന്ന് ഞങ്ങൾ പറയുവോളം റസൂൽ(സ) വ്രതമനുഷ്ഠിക്കുകയും, തീരേ വ്രതമനുഷ്ഠിക്കാറില്ല ഞങ്ങൾ എന്ന് പറയുവോളം വ്രതം ഉപേക്ഷിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ബു,മു,ദ,ന,ജ)', 'سَعِيدِ بْنِ جُبَيْرٍ، وَسُئِلَ عَنْ صِيَامِ رَجَبٍ؟ فَقَالَ', 'സഈദുബ്നു ജുബൈർ', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 98, 98, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ صِيَامِ رَجَبٍ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) റജബിലെ വ്രതം നിരോധിച്ചു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 98, 98, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ حَتَّى نَقُولَ لَا يُفْطِرُ، وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ فَمَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَكْمَلَ صِيَامَ شَهْرٍ إِلَّا رَمَضَانَ، وَمَا رَأَيْتُهُ أَكْثَرَ صِيَامًا مِنْهُ فِي شَعْبَانَ. (خ)', 'ആഇശ(റ): തീരേ നോമ്പ് മുറിക്കാറില്ല എന്ന് ഞങ്ങൾ ധരിക്കുവോളം റസൂൽ(സ) വ്രതമനുഷ്ഠിക്കുകയും തീരെ വ്രതമനുഷ്ഠിക്കാറില്ലെന്നു ധരിക്കുവോളം അവിടന്ന് വ്രതം ഉപേക്ഷിക്കാറുമുണ്ടായിരുന്നു. റമളാനല്ലാത്ത ഒരു മാസവും അവിടന്ന് പൂർണമായി വ്രതമനുഷ്ഠിക്കുന്നതായി ഞാൻ കണ്ടിട്ടില്ല. ശഅ്ബാനിലെ വ്രതത്തിന്റെയത്ര മറ്റൊരു സമയത്തും വ്രതമെടുക്കുന്നതായും റസൂൽ(സ)യെ ഞാൻ കണ്ടിട്ടില്ല. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 99, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ أَوْ لِآخَرَ: "أَصُمْتَ مِنْ سُرَرِ شَعْبَانَ". قَالَ: لَا. قَالَ: "فَإِذَا أَفْطَرْتَ فَصُمْ يَوْمَيْنِ". (م)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): റസൂൽ(സ) അദ്ദേഹത്തോട് അല്ലെങ്കിൽ വേറൊരാളോട് ചോദിച്ചു: "ശഅ്ബാന്റെ അന്ത്യത്തിൽ നീ നോമ്പനുഷ്ഠിച്ചുവോ?". ഇല്ല, എന്നായിരുന്നു മറുപടി. അവിടുന്നരുളി: "റമളാൻവ്രതം കഴിഞ്ഞശേഷം നീ രണ്ടുദിവസം വ്രതമെടുക്കുക." (മു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 99, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ أَحَبَّ الشُّهُورِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَصُومَهُ شَعْبَانُ، ثُمَّ يَصِلُهُ بِرَمَضَانَ. (د،ن)', 'ആഇശ(റ): വ്രതമെടുക്കാൻ തിരുമേനി(സ)ക്ക് ഏറ്റവും പ്രിയമുള്ള മാസം ശഅ്ബാനായിരുന്നു. പിന്നീട് ശഅ്ബാനിനെ റമളാനിനോട് ചേർക്കുകയും ചെയ്യും. (ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 99, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَحَفَّظُ مِنْ شَعْبَانَ مَا لَا يَتَحَفَّظُ مِنْ غَيْرِهِ، ثُمَّ يَصُومُ لِرُؤْيَةِ رَمَضَانَ، فَإِنْ غُمَّ عَلَيْهِ عَدَّ ثَلَاثِينَ يَوْمًا ثُمَّ صَامَ. (د)', 'ആഇശ(റ): റസൂൽ(സ) ''ശഅ്ബാൻ'' മാസത്തിൽ മറ്റുള്ള മാസങ്ങളേക്കാൾ സൂക്ഷ്മത പുലർത്തുമായിരുന്നു. പിന്നീടു ''റമളാൻ'' ചന്ദ്രിക കണ്ടാൽ വ്രതമനുഷ്ഠിക്കും. മേഘാവൃതമായതുമൂലം ദർശനം അസാധ്യമായാൽ മുപ്പതു ദിനങ്ങൾ എണ്ണുകയും ശേഷം നോമ്പനുഷ്ഠിക്കുകയും ചെയ്യും." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 99, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ شَهْرَيْنِ مُتَتَابِعَيْنِ إِلَّا أَنَّهُ كَانَ يَصِلُ شَعْبَانَ بِرَمَضَانَ. وفي رواية قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصِلُ شَعْبَانَ بِرَمَضَانَ. (ن)', 'ഉമ്മുസലമ(റ): തുടർച്ചയായ രണ്ടുമാസം റസൂൽ(സ) വ്രതമനുഷ്ഠിക്കുന്നതായി ഞാൻ കണ്ടിട്ടില്ല. എങ്കിലും റമളാനിലേക്കു ശഅ്ബാൻ മാസത്തെ ചേർത്തി വ്രതമനുഷ്ഠിക്കാറുണ്ടായിരുന്നു. മറ്റൊരു നിവേദനത്തിൽ: മഹതി പറഞ്ഞു: റസൂൽ(സ) ശഅ്ബാനിനെ റമളാനിനോട് ചേർക്കുമായിരുന്നു. (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 99, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=198), 1, 'وَفِي رِوَايَةٍ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصِلُ شَعْبَانَ بِرَمَضَانَ. (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: മഹതി പറഞ്ഞു: റസൂൽ(സ) ശഅ്ബാനിനെ റമളാനിനോട് ചേർക്കുമായിരുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَقَدْ كَانَتْ إِحْدَانَا تُفْطِرُ فِي رَمَضَانَ، فَمَا تَقْدِرُ عَلَى أَنْ تَقْضِيَ حَتَّى يَدْخُلَ شَعْبَانُ، وَمَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ فِي شَهْرٍ مَا يَصُومُ فِي شَعْبَانَ، كَانَ يَصُومُهُ كُلَّهُ إِلَّا قَلِيلًا، بَلْ كَانَ يَصُومُهُ كُلَّهُ. (ن)', 'ആഇശ(റ): ഞങ്ങളിൽ (സ്ത്രീകൾ) പലരും റമളാനിൽ നോമ്പു മുറിക്കാറുണ്ടായിരുന്നു. അങ്ങനെ ശഅ്ബാൻ വരുന്നതുവരെ അത് ഖളാഅ് വീട്ടാൻ പലപ്പോഴും കഴിയാറില്ല. റസൂൽ(സ) ശഅ്ബാനിൽ അനുഷ്ഠിക്കുന്നത്ര നോമ്പ് മറ്റൊരു മാസത്തിലും അനുഷ്ഠിക്കാറുണ്ടായിരുന്നില്ല. ചില ദിവസങ്ങളൊഴികെ ശഅ്ബാൻ മുഴുവനും വ്രതമനുഷ്ഠിക്കാറുണ്ടായിരുന്നു. അല്ല, മുഴുവൻ തന്നെയും അനുഷ്ഠിക്കാറുണ്ടായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 99, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَا أَعْلَمُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ الْقُرْآنَ كُلَّهُ فِي لَيْلَةٍ، وَلَا قَامَ لَيْلَةً حَتَّى الصَّبَاحِ، وَلَا صَامَ شَهْرًا كَامِلًا قَطُّ غَيْرَ رَمَضَانَ. (ن)', 'ആഇശ(റ): റസൂൽ(സ) രാത്രി മുഴുവൻ ഖുർആൻ പാരായണം ചെയ്യുന്നതായും പ്രഭാതം വരെ നിസ്കരിക്കുന്നതായും, റമളാനൊഴിച്ച് മറ്റു മാസങ്ങളിൽ പൂർണ്ണമായി നോമ്പനുഷ്ഠിക്കുന്നതായും ഞാൻ അറിഞ്ഞിട്ടില്ല.', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], '{}'::text[], null, null, 100, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ عَبْدِ اللَّهِ بْنِ شَقِيقٍ قَالَ: قُلْتُ لِعَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي صَلَاةَ الضُّحَى؟ قَالَتْ: لَا، إِلَّا أَنْ يَجِيءَ مِنْ مَغِيبِهِ. قُلْتُ: هَلْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ شَهْرًا كُلَّهُ؟ قَالَتْ: لَا، مَا عَلِمْتُ صَامَ شَهْرًا كُلَّهُ إِلَّا رَمَضَانَ، وَلَا أَفْطَرَ حَتَّى يَصُومَ مِنْهُ، حَتَّى مَضَى لِسَبِيلِهِ. وَفِي رِوَايَةٍ: قُلْتُ: هَلْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَهُ صَوْمٌ مَعْلُومٌ سِوَى رَمَضَانَ؟ قَالَتْ: وَاللَّهِ إِنْ صَامَ شَهْرًا مَعْلُومًا سِوَى رَمَضَانَ حَتَّى مَضَى لِوَجْهِهِ، وَلَا أَفْطَرَ حَتَّى يَصُومَ مِنْهُ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ശഖീഖ്(റ): ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചു: റസൂൽ(സ) ളുഹാ നിസ്ക്കാരം നിർവ്വഹിക്കാറുണ്ടോ? ആഇശ(റ) പറഞ്ഞു: യാത്രയിൽനിന്ന് തിരിച്ചുവരുന്ന സമയത്തല്ലാതെ നിർവഹിക്കാറില്ല. ഞാൻ ചോദിച്ചു: പൂർണമായ ഒരു മാസം അവിടന്ന് വ്രതമനുഷ്ഠിക്കാറുണ്ടോ? മഹതി പറഞ്ഞു: റസൂൽ(സ) വഫാത്താകുന്നത് വരെ റമളാനല്ലാത്ത ഒരു മാസം പരിപൂർണമായി വ്രതമനുഷ്ഠിച്ചതായി ഞാനറിഞ്ഞിട്ടില്ല. പരിപൂർണമായി വ്രതം ഒഴിവാക്കാറുമുണ്ടായിരുന്നില്ല.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=201), 1, 'وَفِي رِوَايَةٍ: قُلْتُ: هَلْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَهُ صَوْمٌ مَعْلُومٌ سِوَى رَمَضَانَ؟ قَالَتْ: وَاللَّهِ إِنْ صَامَ شَهْرًا مَعْلُومًا سِوَى رَمَضَانَ حَتَّى مَضَى لِوَجْهِهِ، وَلَا أَفْطَرَ حَتَّى يَصُومَ مِنْهُ. (ن)', 'മറ്റൊരു നിവേദന്: ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചു: റമസാനൊഴിച്ച് മറ്റെന്നെങ്കിലും സ്ഥിരമായി നബി(സ) നോമ്പനുഷ്ഠിക്കുന്നതായുണ്ടോ? ആഇശ(റ) പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, നബി(സ) വഫാത്താകും വരെ റമളാനൊഴിച്ച് പൂർണ്ണമായി നോമ്പനുഷ്ഠിച്ച ഒന്നും അറിയപ്പെട്ടിട്ടില്ല. മറ്റു മാസങ്ങളിൽ തീരെ അനുഷ്ഠിക്കാതിരുന്നിട്ടുമില്ല. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا بَقِيَ نِصْفٌ مِنْ شَعْبَانَ فَلَا تَصُومُوا". حَسَنٌ صَحِيحٌ. (د،ت)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) അരുളി: "ശഅ്ബാനിന്റെ പകുതിയായാൽ പിന്നെ നിങ്ങൾ വ്രതമനുഷ്ഠിക്കരുത്." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 100, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا انْتَصَفَ شَعْبَانُ فَلَا تَصُومُوا". (د،ت،جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) അരുളി: "ശഅ്ബാൻ പകുതിയായാൽ പിന്നീട് നിങ്ങൾ നോമ്പനുഷ്ഠിക്കരുത്." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 100, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا كَانَ النِّصْفُ مِنْ شَعْبَانَ فَلَا صَوْمَ حَتَّى يَجِيءَ رَمَضَانُ". (د،ت،جه)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ശഅ്ബാൻ പകുതിയായിക്കഴിഞ്ഞാൽ പിന്നെ റമളാൻ വരുന്നതു വരെ നോമ്പില്ല." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 100, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: فَقَدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً، فَخَرَجْتُ فَإِذَا هُوَ بِالْبَقِيعِ، فَقَالَ: "أَكُنْتِ تَخَافِينَ أَنْ يَحِيفَ اللَّهُ عَلَيْكِ وَرَسُولُهُ". قُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي ظَنَنْتُ أَنَّكَ أَتَيْتَ بَعْضَ نِسَائِكَ. فَقَالَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ يَنْزِلُ لَيْلَةَ النِّصْفِ مِنْ شَعْبَانَ إِلَى السَّمَاءِ الدُّنْيَا، فَيَغْفِرُ لِأَكْثَرَ مِنْ عَدَدِ شَعْرِ غَنَمِ كَلْبٍ". (ت،جه)', 'ആഇശ(റ): ഒരു രാത്രി ഞാൻ പ്രവാചകരെ(സ) കാണാതെയായി. അന്വേഷിച്ചുചെന്നപ്പോൾ റസൂൽ(സ) ജന്നത്തുൽ ബഖീഇൽ ഉണ്ടായിരുന്നു. അവിടന്ന് ചോദിച്ചു: "അല്ലാഹുവും അവന്റെ ദൂതരും നിന്നോട് അന്യായം കാണിക്കുമെന്ന് നീ ഭയപ്പെടുന്നോ?" ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ വിചാരിച്ചു അങ്ങ് ഏതെങ്കിലും ഭാര്യയുടെ അടുത്തുപോയതായിരിക്കുമെന്ന്. അപ്പോൾ അവിടന്നരുളി: "ശഅ്ബാൻ പകുതിയുടെ രാവിൽ ഒന്നാം ആകാശത്തേക്ക് അല്ലാഹു അവതരിക്കും. എന്നിട്ട് കലബ് ഗോത്രക്കാരുടെ ആടുകളുടെ രോമത്തിന്റെ എണ്ണത്തേക്കാൾ അധികമാളുകൾക്കവൻ പൊറുത്തുകൊടുക്കും." (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 101, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِرَجُلٍ: "هَلْ صُمْتَ مِنْ سَرَرِ شَعْبَانَ شَيْئًا". قَالَ: لَا، قَالَ: "فَإِذَا أَفْطَرْتَ فَصُمْ يَوْمًا". وَفِي رِوَايَةٍ: "يَوْمَيْنِ". (ق،د)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): റസൂൽ(സ) ഒരാളോടു ചോദിച്ചു. "നീ ശഅ്ബാന്റെ അവസാനത്തിൽ നോമ്പനുഷ്ഠിച്ചുവോ?" അദ്ദേഹം പറഞ്ഞു: "ഇല്ല." തിരുമേനി(സ) അരുളി: "നീ നോമ്പനുഷ്ഠിച്ചില്ലെങ്കിൽ ഒരു ദിവസം നോമ്പനുഷ്ഠിക്കുക." മറ്റൊരു റിപ്പോർട്ടനുസരിച്ച്: "രണ്ടു ദിവസം നോമ്പനുഷ്ഠിക്കുക." (ബു,മു,ദ)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 101, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=206), 1, 'وَفِي رِوَايَةٍ: "يَوْمَيْنِ". (ق،د)', 'മറ്റൊരു നിവേദനനുസരിച്ച്: "രണ്ടു ദിവസം നോമ്പനുഷ്ഠിക്കുക." (ബു,മു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنِ الْمُغِيرَةِ بْنِ فَرْوَةَ قَالَ: قَامَ مُعَاوِيَةُ فِي النَّاسِ بِدَيْرِ مِسْحَلٍ الَّذِي عَلَى بَابِ حِمْصَ، فَقَالَ: أَيُّهَا النَّاسُ، إِنَّا قَدْ رَأَيْنَا الْهِلَالَ يَوْمَ كَذَا وَكَذَا، وَأَنَا مُتَقَدِّمٌ بِالصِّيَامِ، فَمَنْ أَحَبَّ أَنْ يَفْعَلَهُ فَلْيَفْعَلْهُ. قَالَ: فَقَامَ إِلَيْهِ مَالِكُ بْنُ هُبَيْرَةَ السَّبَئِيُّ فَقَالَ: يَا مُعَاوِيَةُ، أَشَيْءٌ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَمْ شَيْءٌ مِنْ رَأْيِكَ؟ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "صُومُوا الشَّهْرَ وَسِرَّهُ". (د)', 'മുഗീറതുബ്നു ഫർവ(റ): ''ബാബു ഹിംസി''നടുത്തുള്ള ''ദൈർ മിസ്ഹൽ'' എന്ന സ്ഥലത്ത് വെച്ച് മുആവിയ(റ) ജനങ്ങളെ അഭിസംബോധന ചെയ്തു. അദ്ദേഹം പറഞ്ഞു: ജനങ്ങളേ, ഇന്ന ദിവസം നാം ചന്ദ്രപ്പിറവി കണ്ടിരിക്കുന്നു. തീർച്ചയായും ഞാൻ മുൻകൂട്ടി നോമ്പെടുക്കുകയാണ്. ആരെങ്കിലും അത് ഇഷ്ടപ്പെടുന്നുവെങ്കിൽ അവൻ അത് ചെയ്യട്ടെ. മുഗീറ(റ) പറയുന്നു: അപ്പോൾ മാലികുബ്നു ഹുബൈറതുസ്സബഇയ്യ് എഴുന്നേറ്റു അദ്ദേഹത്തോടു ചോദിച്ചു: മുആവിയാ, ഇതു പ്രവാചകരിൽനിന്നു താങ്കൾ കേട്ടതോ, അതോ താങ്കളുടെ അഭിപ്രായമോ?" മുആവിയ(റ) മറുപടി നൽകി: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "നിങ്ങൾ മാസത്തിന്റെ ആദ്യത്തിലും അവസാനത്തിലും നോമ്പനുഷ്ഠിക്കുക." (ദ)', 'الْمُغِيرَةِ بْنِ فَرْوَةَ قَالَ', 'മുഗീറതുബ്നു ഫർവ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 101, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ تَعْجِيلِ صَوْمِ يَوْمٍ قَبْلَ الرُّؤْيَةِ. [ز:في إسناده ضعيف]. (جه)', 'അബൂഹുറൈറ(റ): മാസപ്പിറവി ദർശനത്തിന് ഒരു ദിവസം മുമ്പ് നോമ്പ് തുടങ്ങുന്നത് റസൂൽ(സ) നിരോധിച്ചിട്ടുണ്ട്. (ഇതിന്റെ പരമ്പരയിൽ ഒരു ദുർബലനുണ്ട്). (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز:في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ഒരു ദുർബലനുണ്ട്', 101, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَحْصُوا هِلَالَ شَعْبَانَ لِرَمَضَانَ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "റമളാനിനുവേണ്ടി ശഅ്ബാൻ മാസചന്ദ്രികയെ നിങ്ങൾ ക്ലിപ്തമാക്കുക." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 102, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ لَمْ يَكُنْ يَصُومُ مِنَ السَّنَةِ شَهْرًا تَامًّا إِلَّا شَعْبَانَ، يَصِلُهُ بِرَمَضَانَ. (د،ت،ن،جه)', 'ഉമ്മുസലമ(റ): നബി(സ) വർഷത്തിൽ ശഅ്ബാൻ മാസത്തിലല്ലാതെ മാസം പൂർണ്ണമായും സുന്നത്ത് നോമ്പെടുക്കാറില്ല. ശഅ്ബാനിനെ നബി(സ) റമളാൻ മാസത്തോട് ചേർത്ത് അനുഷ്ഠിക്കുകയും ചെയ്യും. (ദ,തു,ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 102, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ، فَإِنْ حَالَ بَيْنَكُمْ وَبَيْنَهُ سَحَابَةٌ أَوْ ظُلْمَةٌ فَأَكْمِلُوا الْعِدَّةَ عِدَّةَ شَعْبَانَ، وَلَا تَسْتَقْبِلُوا الشَّهْرَ اسْتِقْبَالًا، وَلَا تَصِلُوا رَمَضَانَ بِيَوْمٍ مِنْ شَعْبَانَ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ മാസപ്പിറവി ദർശിച്ചാൽ നോമ്പനുഷ്ഠിക്കുക, അപ്രകാരം മാസപ്പിറവി ദർശിച്ചാൽ നോമ്പു മുറിക്കുക. കൂരിരുട്ടോ മേഘങ്ങളോ മാസം കാണുന്നതിന് നിങ്ങൾക്ക് തടസ്സമായാൽ ശഅബാൻ മാസത്തെ എണ്ണം കണക്കനുസരിച്ച് പൂർത്തീകരിക്കുക (മുപ്പത് പൂർത്തിയാക്കുക). റമളാനിനെ നോമ്പുകാരായി നിങ്ങൾ വരവേൽക്കരുത്. ശഅബാനിലെ ഒരു ദിനത്തെ റമളാനിനോട് കൂട്ടിച്ചേർക്കുകയും അരുത്". (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 102, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللَّهُ عَنْهُ، صَاحِبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ صَامَ رَمَضَانَ، ثُمَّ أَتْبَعَهُ بِسِتٍّ مِنْ شَوَّالٍ، فَكَأَنَّمَا صَامَ الدَّهْرَ". (م،د،ت،جه)', 'അബൂഅയ്യൂബ്(റ): നബി(സ) പറയുന്നു: "ആരെങ്കിലും റമളാൻ മാസം നോമ്പനുഷ്ഠിച്ച് അതോടൊപ്പം ശവ്വാലിലെ ആറു ദിവസം നോമ്പനുഷ്ഠിക്കുകയും ചെയ്താൽ നിശ്ചയം ഒരു വർഷം നോമ്പനുഷ്ഠിച്ചതുപോലെയായി." (മു,ദ,തു,ജ)', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 102, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ ثَوْبَانَ رَضِيَ اللَّهُ عَنْهُ، مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "مَنْ صَامَ سِتَّةَ أَيَّامٍ بَعْدَ الْفِطْرِ كَانَ تَمَامَ السَّنَةِ، مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا". (جه)', 'തിരുദൂതർ(സ)യുടെ മോചിതഅടിമ സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "ചെറിയ പെരുന്നാളിനുശേഷം ആറുദിവസത്തെ നോമ്പനുഷ്ഠിച്ചാൽ അതു വർഷം പൂർണമായി വ്രതമനുഷ്ഠിച്ചപോലെയാണ്. വല്ലവനും നന്മ ചെയ്താൽ അവന്നതിന്റെ പത്തിരട്ടിയാണു പ്രതിഫലം." (ജ)', 'ثَوْبَانَ', 'തിരുദൂതർ(സ)യുടെ മോചിതഅടിമ സൗബാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 103, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا: كَانَ يَصُومُ أَشْهُرَ الْحُرُمِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "صُمْ شَوَّالًا". فَتَرَكَ أَشْهُرَ الْحُرُمِ، ثُمَّ لَمْ يَزَلْ يَصُومُ شَوَّالًا حَتَّى مَاتَ. (جه)', 'ഉസാമതുബ്നു സൈദ്(റ): വിശുദ്ധമാസങ്ങൾ മുഴുവൻ വ്രതമനുഷ്ഠിച്ചിരുന്ന അദ്ദേഹത്തോട് റസൂൽ(സ) പറഞ്ഞു: "നീ ശവ്വാലിൽ വ്രതമനുഷ്ഠിക്കുക." പിന്നീടദ്ദേഹം വിശുദ്ധമാസങ്ങളിലെ നോമ്പുപേക്ഷിക്കുകയും ശവ്വാൽനോമ്പ് മരണംവരെ പതിവാക്കുകയും ചെയ്തിരുന്നു. (ജ)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 103, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ هُنَيْدَةَ بْنِ خَالِدٍ الْخُزَاعِيِّ، عَنِ امْرَأَتِهِ، عَنْ بَعْضِ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ تِسْعَ ذِي الْحِجَّةِ، وَيَوْمَ عَاشُورَاءَ، وَثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ: أَوَّلَ اثْنَيْنِ مِنَ الشَّهْرِ وَالْخَمِيسَ. (د،ن)', 'ഹുനൈദതുബ്നു ഖാലിദുൽ ഖസാഈ(റ) തന്റെ ഭാര്യയിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: റസൂൽ(സ)യുടെ ഭാര്യമാരിലൊരാൾ ഇപ്രകാരം പറഞ്ഞു: റസൂൽ(സ) ദുൽഹജ്ജ് മാസത്തിലെ ഒമ്പതു ദിവസവും, ആശൂറാഅ് ദിനവും ഓരോ മാസത്തിലും മൂന്നു വീതം ദിവസവും, മാസത്തിലെ ആദ്യത്തെ രണ്ട് തിങ്കളും വ്യാഴവും വ്രതമനുഷ്ഠിക്കാറുണ്ടായിരുന്നു. (ദ,ന)', 'هُنَيْدَةَ بْنِ خَالِدٍ الْخُزَاعِيِّ، عَنِ امْرَأَتِهِ، عَنْ بَعْضِ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ', 'ഹുനൈദതുബ്നു ഖാലിദുൽ ഖസാഈ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 103, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ أَيَّامٍ: الْعَمَلُ الصَّالِحُ فِيهَا أَحَبُّ إِلَى اللَّهِ مِنْ هَذِهِ الْأَيَّامِ" يَعْنِي أَيَّامَ الْعَشْرِ. قَالُوا: يَا رَسُولَ اللَّهِ، وَلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ؟ قَالَ: "وَلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ، إِلَّا رَجُلٌ خَرَجَ بِنَفْسِهِ وَمَالِهِ فَلَمْ يَرْجِعْ مِنْ ذَلِكَ بِشَيْءٍ". (خ،د،ت،جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) അരുളി: "ഈ ദിവസങ്ങളിൽ (ദുൽഹജ്ജിലെ പത്ത്) സൽക്കർമങ്ങൾ അല്ലാഹുവിന് പ്രിയങ്കരമായതിനേക്കാൾ പ്രിയങ്കരമായ മറ്റു ദിവസങ്ങളില്ല." അനുചരർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹുവിന്റെ മാർഗത്തിലെ ധർമ്മസമരവും അത്രത്തോളം വരില്ലേ? നബി(സ) പറഞ്ഞു: "ധർമ്മസമരവും അത്രത്തോളമെത്തില്ല, ഒരാളൊഴികെ. അയാൾ തന്റെ ശരീരവും സമ്പത്തുമായി യുദ്ധത്തിനിറങ്ങി, പക്ഷേ, ഒന്നും അയാൾക്ക് തിരിച്ചുലഭിച്ചില്ല." (ബു,ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 103, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ أَيَّامِ الدُّنْيَا أَيَّامٌ أَحَبُّ إِلَى اللَّهِ سُبْحَانَهُ أَنْ يُتَعَبَّدَ لَهُ فِيهَا مِنْ أَيَّامِ الْعَشْرِ، وَإِنَّ صِيَامَ يَوْمٍ فِيهَا لَيَعْدِلُ صِيَامَ سَنَةٍ، وَلَيْلَةٍ فِيهَا بِلَيْلَةِ الْقَدْرِ". (ت،جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ദുൽഹജ്ജിലെ പത്ത് ദിവസങ്ങളേക്കാൾ ആരാധനകൾ അല്ലാഹു ഇഷ്ടപ്പെടുന്ന ഒരു ദിവസവുമില്ല. അതിൽ ഒരു ദിവസം നോമ്പെടുക്കൽ ഒരു വർഷം നോമ്പെടുക്കുന്നതിനും അതിലെ ഒരു രാത്രി ഖദ്റിന്റെ രാത്രിക്കും തുല്യമാണ്." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 103, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَائِمًا فِي الْعَشْرِ قَطُّ. (م،د،ت،ن،جه)', 'ആഇശ(റ): ദുൽഹജ്ജ് പത്ത് ദിനങ്ങളിൽ നോമ്പനുഷ്ഠിച്ചതായി റസൂൽ(സ)യെ ഞാൻ തീരെ കണ്ടിട്ടില്ല. (മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ عَبْدِ اللَّهِ بن مَسْعُود رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ مِنْ غُرَّةِ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ، وَقَلَّمَا كَانَ يُفْطِرُ يَوْمَ الْجُمُعَةِ. حَسَنٌ. (د،ت،ن،جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) എല്ലാ മാസത്തിലെയും വെളുത്തവാവിന്റെ മൂന്നു ദിനങ്ങൾ നോമ്പനുഷ്ഠിക്കാറുണ്ട്. വെള്ളിയാഴ്ച ദിവസം വളരെകുറച്ചു മാത്രമാണ് നോമ്പെടുക്കാതിരുന്നത്. (ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بن مَسْعُود', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا سُئِلَتْ هَلْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْتَصُّ مِنَ الْأَيَّامِ شَيْئًا؟ قَالَتْ: لَا كَانَ عَمَلُهُ دِيمَةً وَأَيُّكُمْ يُطِيقُ مَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُطِيقُ. (خ)', 'ആഇശ(റ): അവർ ചോദിക്കപ്പെട്ടു: ഏതെങ്കിലും ദിവസത്തെ നബി(സ) പ്രത്യേകമാക്കാറുണ്ടോ? അവർ പറഞ്ഞു: ഇല്ല, അവിടത്തെ കർമ്മങ്ങളെല്ലാം പതിവു ക്രമത്തിലായിരുന്നു. റസൂൽ(സ)ക്കു കഴിയുന്നത് ആർക്കാണ് കഴിയുക? (ബു.)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنْ جُوَيْرِيَةَ بِنْتِ الْحَارِثِ رَضِيَ اللَّهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا يَوْمَ الْجُمُعَةِ وَهِيَ صَائِمَةٌ، فَقَالَ: أَصُمْتِ أَمْسِ؟ قَالَتْ: لَا، قَالَ: أَتُرِيدِينَ أَنْ تَصُومِي غَدًا؟ قَالَتْ: لَا، قَالَ: فَأَفْطِرِي. (خ،د)', 'ജുവൈരിയ ബിൻതുൽ ഹാരിസ്(റ): നബി(സ) ഒരു വെള്ളിയാഴ്ച അവരുടെ അടുത്ത്ചെന്നു. അവർ നോമ്പുകാരിയായിരുന്നു. നബി(സ) ചോദിച്ചു: "ഇന്നലെ നിങ്ങൾ നോമ്പെടുത്തിരുന്നോ?" അവർ പറഞ്ഞു: ഇല്ല. നബി(സ) ചോദിച്ചു: "നാളെ നോമ്പെടുക്കാൻ ഉദ്ദേശിക്കുന്നുണ്ടോ?" അവർ പറഞ്ഞു: ഇല്ല. നബി(സ) കൽപിച്ചു: "എന്നാൽ നോമ്പു മുറിക്കൂ." (ബു,ദ)', 'جُوَيْرِيَةَ بِنْتِ الْحَارِثِ', 'ജുവൈരിയ ബിൻതുൽ ഹാരിസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَخْتَصُّوا لَيْلَةَ الْجُمُعَةِ بِقِيَامٍ مِنْ بَيْنِ اللَّيَالِي، وَلَا تَخُصُّوا يَوْمَ الْجُمُعَةِ بِصِيَامٍ مِنْ بَيْنِ الْأَيَّامِ، إِلَّا أَنْ يَكُونَ فِي صَوْمٍ يَصُومُهُ أَحَدُكُمْ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നു: "രാത്രികളിൽനിന്ന് വെള്ളിയാഴ്ച രാത്രി നിസ്കാരംകൊണ്ട് നിങ്ങൾ പ്രത്യേകമാക്കരുത്. ദിവസങ്ങളിൽ വെള്ളിയാഴ്ച ദിനം നോമ്പുകൊണ്ടും പ്രത്യേകമാക്കരുത്. നിങ്ങൾ അനുഷ്ഠിച്ച് കൊണ്ടിരിക്കുന്നുവെങ്കിലൊഴികെ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَصُمْ أَحَدُكُمْ يَوْمَ الْجُمُعَةِ، إِلَّا أَنْ يَصُومَ قَبْلَهُ بِيَوْمٍ أَوْ بَعْدَهُ". (ق،د،ت،جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വെള്ളിയാഴ്ച ദിവസം നിങ്ങളാരും നോമ്പെടുക്കരുത്. അതിന് മുമ്പോ ശേഷമോ നോമ്പെടുത്താലല്ലാതെ." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 104, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ مُحَمَّدِ بْنِ عَبَّادِ بْنِ جَعْفَرٍ قَالَ: سَأَلْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ- رَضِيَ اللَّهُ عَنْهُمَا- وَأَنَا أَطُوفُ بِالْبَيْتِ: أَنَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صِيَامِ يَوْمِ الْجُمُعَةِ؟ قَالَ: نَعَمْ، وَرَبِّ هَذَا الْبَيْتِ. (ق،جه)', 'മുഹമ്മദുബ്നു അബ്ബാദുബ്നു ജഅ്ഫർ(റ): കഅ്ബയെ ത്വവാഫ് ചെയ്തുകൊണ്ടിരിക്കെ ഞാൻ ജാബിറുബ്നു അബ്ദില്ലാ(റ)വിനോട് ചോദിച്ചു: വെള്ളിയാഴ്ച ദിവസം നോമ്പനുഷ്ഠിക്കുന്നത് റസൂൽ(സ) വിലക്കിയിട്ടുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അതെ, ഈ കഅ്ബയുടെ നാഥനാണു സത്യം. (ബു,ജ)', 'مُحَمَّدِ بْنِ عَبَّادِ بْنِ جَعْفَرٍ قَالَ', 'മുഹമ്മദുബ്നു അബ്ബാദുബ്നു ജഅ്ഫർ(റ)', null, null, array['ق','جه']::text[], array['ബു','ജ']::text[], null, null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَصُومُوا يَوْمَ السَّبْتِ إِلَّا فِيمَا افْتُرِضَ عَلَيْكُمْ، فَإِنْ لَمْ يَجِدْ أَحَدُكُمْ إِلَّا عُودَ عِنَبٍ أَوْ لِحَاءَ شَجَرَةٍ فَلْيَمُصَّهُ". وفي رواية: عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ، عَنْ أُخْتِهِ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ .... فَذَكَرَ نَحْوَهُ. (د،ت،ن)', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് നിർബന്ധമാക്കപ്പെട്ടതല്ലാത്ത ഒരു നോമ്പും നിങ്ങൾ ശനിയാഴ്ച അനുഷ്ഠിക്കരുത്. നിങ്ങൾക്ക് മുന്തിരി വള്ളിയുടെ കൊള്ളിയോ, മറ്റേതെങ്കിലും വൃക്ഷത്തിന്റെ തൊലിയോ അല്ലാത്തത് കിട്ടാനില്ലെങ്കിൽ അതുപയോഗിച്ചെങ്കിലും നോമ്പു മുറിക്കുക."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=225), 1, 'وَفِي رِوَايَةٍ: عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ، عَنْ أُخْتِهِ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ .... فَذَكَرَ نَحْوَهُ. (د،ت،ن)', 'മറ്റൊരു നിവേദനത്തിൽ (തന്റെ സഹോദരിയിൽ നിന്ന്) അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ): നബി(സ) പറഞ്ഞു: എന്നിട്ട് മുന്നെ പറഞ്ഞ പോലെ അവർ പറഞ്ഞു. (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَخْرُجُ يَوْمَ الْفِطْرِ حَتَّى يَطْعَمَ تَمَرَاتٍ. (خ،جه)', 'അനസുബ്നുമാലിക്(റ): ഫിത്വ്റിന്റെ (ചെറിയപെരുന്നാൾ) ദിവസം നബി(സ) കാരക്ക ഭക്ഷിക്കാതെ പുറത്തിറങ്ങുമായിരുന്നില്ല. (ബു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَغْدُو يَوْمَ الْفِطْرِ حَتَّى يُغَدِّيَ أَصْحَابَهُ مِنْ صَدَقَةِ الْفِطْرِ. (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) ചെറിയ പെരുന്നാൾ ദിവസം അവിടത്തെ അനുചരരെ ഫിത്വ്റിന്റെ സ്വദഖയിൽ (ഫിത്വ്റ് സകാത്) നിന്ന് ഭക്ഷിപ്പിച്ചല്ലാതെ പ്രഭാതത്തിൽ പുറത്തിറങ്ങാറില്ല. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَخْرُجُ يَوْمَ الْفِطْرِ حَتَّى يَأْكُلَ، وَكَانَ لَا يَأْكُلُ يَوْمَ النَّحْرِ حَتَّى يَرْجِعَ. (ت،جه)', 'ബുറൈദ(റ): നബി(സ) ചെറിയപെരുന്നാൾദിനത്തിൽ ഭക്ഷിക്കാതെ പുറത്തിറങ്ങാറില്ല. എന്നാൽ ബലിപെരുന്നാളിന് പുറത്ത് പോയിവരുന്നത് വരെ ഒന്നും ഭക്ഷിക്കാറുണ്ടായിരുന്നില്ല. (തു,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 105, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صِيَامِ يَوْمَيْنِ: يَوْمِ الْفِطْرِ، وَيَوْمِ الْأَضْحَى. وَعَنْ لِبْسَتَيْنِ: الصَّمَّاءِ، وَأَنْ يَحْتَبِيَ الرَّجُلُ فِي الثَّوْبِ الْوَاحِدِ. وَعَنِ الصَّلَاةِ فِي سَاعَتَيْنِ: بَعْدَ الصُّبْحِ، وَبَعْدَ الْعَصْرِ. (ق،د،ت)', 'അബുസഈദിൽ ഖുദ്‌രി(റ): ഈദുൽഫിത്വ്ർ (ചെറിയ പെരുന്നാൾ), ഈദുൽഅള്ഹാ (ബലിപെരുന്നാൾ) എന്നീ രണ്ടുദിവസങ്ങളിൽ നോമ്പനുഷ്ഠിക്കുന്നത് റസൂൽ(സ) നിരോധിച്ചു. പിരടിയിലൂടെ വസ്ത്രം ധരിക്കൽ, ഒരൊറ്റ വസ്ത്രം കൊണ്ടു ചുറ്റിപ്പുതക്കൽ എന്നീ രണ്ട് വസ്ത്രധാരണാരീതിയും റസൂൽ(സ) വിലക്കി. സുബ്ഹ് നിസ്കാരത്തിന്റെ ശേഷം, അസ്ർ നിസ്കാരത്തിന്റെ ശേഷം എന്നിങ്ങനെ രണ്ടു നേരങ്ങളിൽ നിസ്കരിക്കുന്നതും റസൂൽ(സ) നിരോധിച്ചു. (ബു,മു,ദ,തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 106, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ أَبِي عُبَيْدٍ - مَوْلَى عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ رَضِيَ اللَّهُ عَنْهُ - قَالَ: شَهِدْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ فِي يَوْمِ النَّحْرِ بَدَأَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ، ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ صَوْمِ هَذَيْنِ الْيَوْمَيْنِ: "أَمَّا يَوْمُ الْفِطْرِ فَفِطْرُكُمْ مِنْ صَوْمِكُمْ وَعِيدٌ لِلْمُسْلِمِينَ، وَأَمَّا يَوْمُ الْأَضْحَى فَكُلُوا مِنْ لُحُومِ نُسُكِكُمْ". حَسَنٌ صَحِيحٌ. (ق،د،ت،ن،جه)', 'അബ്ദുർറഹ്മാൻ ബിൻ ഔഫ്(റ)വിന്റെ വിമോചിത അടിമ അബൂഉബൈദ(റ): അദ്ദേഹം പറയുന്നു: ഉമർ(റ)നോടൊത്ത് ഒരു ബലി പെരുന്നാൾ ദിവസം ഞാൻ പങ്കെടുത്തു. ഖുത്വ്ബയുടെ മുമ്പ് നിസ്കരിച്ചുകൊണ്ടാണദ്ദേഹം തുടങ്ങിയത്. തുടർന്നദ്ദേഹം പറഞ്ഞു: ഈ രണ്ടു ദിവസങ്ങളിൽ നോമ്പനുഷ്ഠിക്കുന്നത് റസൂൽ(സ) നിരോധിച്ചതായി ഞാൻ കേട്ടിട്ടുണ്ട്. "ഈദുൽഫിത്വ്ർ (ചെറിയപെരുന്നാൾ), നിങ്ങളുടെ റമളാൻനോമ്പിൽ നിന്ന് വരിമിക്കലും മുസ്ലിംകളുടെ ഉത്സവവുമാണ്. ബലിപെരുന്നാൾ, അന്നു നിങ്ങൾ ബലിയറുത്ത മൃഗങ്ങളുടെ മാംസം ഭക്ഷിച്ചുകൊള്ളുക." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي عُبَيْدٍ - مَوْلَى عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ', 'അബ്ദുർറഹ്മാൻ ബിൻ ഔഫ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 106, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنْ عَائِشَةَ وَابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُم قَالَا: لَمْ يُرَخَّصْ فِي أَيَّامِ التَّشْرِيقِ أَنْ يُصَمْنَ إِلَّا لِمَنْ لَمْ يَجِدِ الْهَدْيَ. (خ)', 'ആഇശ(റ), ഇബ്നുഉമർ(റ): ബലിമൃഗം കൈവശമില്ലാത്ത ഹാജിമാർക്കല്ലാതെ അയ്യാമുത്തശ്‌രീഖിൽ നോമ്പനുഷ്ഠിക്കാൻ തിരുമേനി(സ) അനുവാദം നൽകിയിരുന്നില്ല. (ബു.)', 'عَائِشَةَ وَابْنِ عُمَرَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 106, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنْ نُبَيْشَةَ الْهُذَلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيَّامُ التَّشْرِيقِ أَيَّامُ أَكْلٍ وَشُرْبٍ- وَفِي رِوَايَةٍ: وَذِكْرٍ لِلَّهِ". (م)', 'നുബൈശതുൽ ഹുദലി(റ): റസൂൽ(സ) പറഞ്ഞു: "അയ്യാമുത്തശ്‌രീഖ് തിന്നാനും കുടിക്കാനുമുള്ള ദിവസമാണ്." മറ്റൊരു നിവേദനം: "ദൈവികസ്മരണയുടേയും." (മു)', 'نُبَيْشَةَ الْهُذَلِيِّ', 'നുബൈശതുൽ ഹുദലി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 106, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=232), 1, 'وَفِي رِوَايَةٍ: وَذِكْرٍ لِلَّهِ". (م)', 'മറ്റൊരു നിവേദനം: "ദൈവികസ്മരണയുടേയും." (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ أَبِي مُرَّةَ مَوْلَى أُمِّ هَانِئٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ دَخَلَ مَعَ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا عَلَى أَبِيهِ عَمْرِو بْنِ الْعَاصِ فَقَرَّبَ إِلَيْهِمَا طَعَامًا، فَقَالَ: كُلْ، فَقَالَ: إِنِّي صَائِمٌ، فَقَالَ عَمْرٌو: كُلْ، فَهَذِهِ الْأَيَّامُ الَّتِي كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُنَا بِإِفْطَارِهَا وَيَنْهَانَا عَنْ صِيَامِهَا. قَالَ: وَهِيَ أَيَّامُ التَّشْرِيقِ. (د)', 'ഉമ്മുഹാനിഅ്(റ)യുടെ വിമോചിത അടിമ അബൂമുർറ(റ): അദ്ദേഹം അബ്ദുല്ലാഹിബിൻ അംറ്(റ)വിനോടൊപ്പം അദ്ദേഹത്തിന്റെ പിതാവ് അംറുബ്നുൽ ആസ്(റ)വിനെ സമീപിച്ചു. അദ്ദേഹം അവർക്കു ഭക്ഷണം നൽകി, തിന്നാൻ പറഞ്ഞു. അപ്പോൾ അബ്ദുല്ല പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. അന്നേരം അംറ്(റ) പറഞ്ഞു: കഴിക്കുക, റസൂൽ (സ) ഞങ്ങളോട് നോമ്പ് മുറിക്കാൻ കൽപിക്കുകയും നോമ്പനുഷ്ഠിക്കുന്നത് വിലക്കുകയും ചെയ്ത ദിവസങ്ങളാണിത്. നിവേദകൻ പറഞ്ഞു: അയ്യാമുത്തശ്‌രീഖ് ദിനങ്ങളായിരുന്നു അവ. (ദ)', 'أَبِي مُرَّةَ مَوْلَى أُمِّ هَانِئٍ', 'ഉമ്മുഹാനിഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 106, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَوْمُ عَرَفَةَ وَيَوْمُ النَّحْرِ وَأَيَّامُ التَّشْرِيقِ عِيدُنَا أَهْلَ الْإِسْلَامِ، وَهِيَ أَيَّامُ أَكْلٍ وَشُرْبٍ". (د،ت،ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അറഫാദിനം, പെരുന്നാൾദിനം, അയ്യാമുത്തശ്‌രീഖ് എന്നീ ദിവസങ്ങൾ നാം മുസ്ലിംകളുടെ ഉൽസവ ദിനങ്ങളാണ്. അത് തിന്നാനും കുടിക്കാനുമുള്ള ദിവസങ്ങളാണ്." (ദ,തു,ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 107, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيَّامُ مِنًى أَيَّامُ أَكْلٍ وَشُرْبٍ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "(ഹാജിമാർ) മിനയിൽ നിൽക്കുന്ന ദിവസങ്ങൾ തിന്നാനും കുടിക്കാനുമുള്ള ദിവസങ്ങളാണ്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 107, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنْ بِشْرِ بْنِ سُحَيْمٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَ أَيَّامَ التَّشْرِيقِ فَقَالَ: "لَا يَدْخُلُ الْجَنَّةَ إِلَّا نَفْسٌ مُسْلِمَةٌ، وَإِنَّ هَذِهِ الْأَيَّامَ أَيَّامُ أَكْلٍ وَشُرْبٍ". (جه)', 'ബിശ്റുബ്നു സുഹൈം(റ): റസൂൽ(സ) അയ്യാമുത്തശ്‌രീഖ് നാളിൽ നടത്തിയ പ്രഭാഷണത്തിൽ പറഞ്ഞു: "മുസ്ലിമായ വ്യക്തിക്ക് മാത്രമേ സ്വർഗപ്രവേശം സാധ്യമാവുകയുള്ളൂ. ഈ ദിനങ്ങൾ തിന്നാനും കുടിക്കാനുമുള്ള ദിവസങ്ങളാണ്." (ജ)', 'بِشْرِ بْنِ سُحَيْمٍ', 'ബിശ്റുബ്നു സുഹൈം(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 107, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِرَجُلٍ فِي ظِلِّ شَجَرَةٍ يُرَشُّ عَلَيْهِ الْمَاءُ، قَالَ: "مَا بَالُ صَاحِبِكُمْ هَذَا". قَالُوا: يَا رَسُولَ اللَّهِ، صَائِمٌ. قَالَ: "إِنَّهُ لَيْسَ مِنَ الْبِرِّ أَنْ تَصُومُوا فِي السَّفَرِ، وَعَلَيْكُمْ بِرُخْصَةِ اللَّهِ الَّتِي رَخَّصَ لَكُمْ، فَاقْبَلُوهَا". (ق،د،ن،جه))', 'ജാബിറുബ്നു അബ്ദില്ല(റ): മരത്തണലിൽ ഇരിക്കുന്ന ഒരാളുടെ അരികിലൂടെ റസൂൽ(സ) നടന്നുപോയി. അദ്ദേഹത്തിന്റെ മേൽ വെള്ളം തെളിക്കപ്പെടുന്നുണ്ടായിരുന്നു. അന്നേരം തിരുമേനി(സ) ചോദിച്ചു: "നിങ്ങളുടെ ഈ കൂട്ടുകാരനെന്തുപറ്റി?" അവർ പറഞ്ഞു: പ്രവാചകരേ അയാൾ നോമ്പുകാരനാണ്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "യാത്രയിൽ നിങ്ങൾ നോമ്പെടുക്കൽ പുണ്യകരമായ കാര്യമല്ല. നിങ്ങൾക്ക് അല്ലാഹു നൽകിയ ഇളവ് സ്വീകരിക്കുക. നിങ്ങളതനുവർത്തിക്കുക." (ബു,മു,ദ,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 107, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ حَمْزَةَ الْأَسْلَمِيَّ رَضِيَ اللَّهُ عَنْهُ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي رَجُلٌ أَسْرُدُ الصَّوْمَ، أَفَأَصُومُ فِي السَّفَرِ؟ قَالَ: "صُمْ إِنْ شِئْتَ، وَأَفْطِرْ إِنْ شِئْتَ". (ق،د،ت،ن،جه)', 'ആഇശ(റ): ഹംസതുൽഅസ്ലമി(റ) റസൂൽ(സ)യോട് ചോദിച്ചു: പ്രവാചകരേ, തുടർച്ചയായി നോമ്പനുഷ്ഠിക്കുന്ന ഒരാളാണ് ഞാൻ. അതിനാൽ, യാത്രാവേളയിൽ ഞാൻ നോമ്പ് എടുക്കട്ടെയോ? തിരുമേനി(സ) പറഞ്ഞു: "നീ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ നോമ്പെടുത്തുകൊള്ളുക. നീ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ ഒഴിവാക്കുകയും ചെയ്യുക." (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 107, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَافَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَامَ حَتَّى بَلَغَ عُسْفَانَ، ثُمَّ دَعَا بِإِنَاءٍ فَشَرِبَ نَهَارًا لِيَرَاهُ النَّاسُ، ثُمَّ أَفْطَرَ حَتَّى دَخَلَ مَكَّةَ، فَافْتَتَحَ مَكَّةَ فِي رَمَضَانَ. قَالَ ابْنُ عَبَّاسٍ: فَصَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السَّفَرِ وَأَفْطَرَ، فَمَنْ شَاءَ صَامَ وَمَنْ شَاءَ أَفْطَرَ. (ق،د،ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) (മക്കാ യാത്രാവേളയിൽ) ''ഉസ്ഫാൻ'' എന്ന സ്ഥലം എത്തുന്നതുവരെ നോമ്പെടുത്തുകൊണ്ട് യാത്ര ചെയ്തു. പിന്നെ ഒരു പാത്രം വെള്ളം ആവശ്യപ്പെട്ട് ജനങ്ങൾ കാൺകെ പകൽനേരത്ത് തന്നെ അത് കുടിച്ചു. (ഇത് റമളാൻ മാസത്തിലായിരുന്നു) അതിനുശേഷം മക്കയിൽ എത്തുന്നത്വരെ തിരുമേനി(സ) നോമ്പ് എടുത്തിരുന്നില്ല. അങ്ങനെ റമളാനിൽ മക്ക കീഴടക്കി. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: റസൂൽ(സ) യാത്രാവേളയിൽ നോമ്പ് എടുക്കുകയും ഒഴിവാക്കുകയും ചെയ്തിട്ടുണ്ട്. അതിനാൽ നോമ്പ് എടുക്കാനുദ്ദേശിക്കുന്നവർക്ക് നോമ്പ് എടുക്കുകയും നോമ്പ് ഒഴിവാക്കാനുദ്ദേശിക്കുന്നവർക്ക് ഒഴിവാക്കുകയും ചെയ്യാവുന്നതാണ്. (ബു,മു,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنْ حَمْزَةَ بْنِ عَمْرٍو الأسلمي رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: يَا رَسُولَ اللَّهِ، أَجِدُ بِي قُوَّةً عَلَى الصِّيَامِ فِي السَّفَرِ، فَهَلْ عَلَيَّ جُنَاحٌ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هِيَ رُخْصَةٌ مِنَ اللَّهِ عَزَّ وَجَلَّ، فَمَنْ أَخَذَ بِهَا فَحَسَنٌ، وَمَنْ أَحَبَّ أَنْ يَصُومَ فَلَا جُنَاحَ عَلَيْهِ". (م،ن)', 'ഹംസതുബ്നു അംറിൽ അസ്ലമി(റ): അദ്ദേഹം ചോദിച്ചു: പ്രവാചകരേ, യാത്രാവേളയിൽ നോമ്പെടുക്കാൻ എനിക്കു ശേഷിയുണ്ട്. അങ്ങനെ ചെയ്താൽ എന്റെ മേൽ കുറ്റമുണ്ടാകുമോ? തിരുമേനി(സ) പറഞ്ഞു: "അത് അല്ലാഹുവിൽനിന്നുള്ള ഒരു ഇളവാണ്. അത് സ്വീകരിച്ചാൽ അതാണു നല്ലത്. ഇനി ആരെങ്കിലും നോമ്പെടുക്കാൻ ആഗ്രഹിക്കുന്നുവെങ്കിൽ അതിന്റെ പേരിൽ അവനു കുറ്റമുണ്ടാവില്ല." (മു,ന)', 'حَمْزَةَ بْنِ عَمْرٍو الأسلمي', 'ഹംസതുബ്നു അംറിൽ അസ്ലമി(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَزَوْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِسِتٍّ عَشْرَةَ مَضَتْ مِنْ رَمَضَانَ، فَمِنَّا مَنْ صَامَ وَمِنَّا مَنْ أَفْطَرَ، فَلَمْ يَعِبِ الصَّائِمُ عَلَى الْمُفْطِرِ وَلَا الْمُفْطِرُ عَلَى الصَّائِمِ. (م)', 'അബുസഈദിൽ ഖുദ്‌രി(റ): റമളാൻ പതിനാറിന് ഞങ്ങൾ പ്രവാചകരോടൊപ്പം യുദ്ധം ചെയ്തു. അന്നേരം നോമ്പ് എടുത്തവരും എടുക്കാത്തവരും ഞങ്ങളുടെ കൂട്ടത്തിൽ ഉണ്ടായിരുന്നു. എന്നാൽ, നോമ്പ് എടുത്തവൻ എടുക്കാത്തവനെയോ നോമ്പ് എടുക്കാത്തവൻ തിരിച്ചോ ആക്ഷേപിച്ചിരുന്നില്ല. (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنْ حَمْزَةَ الْأَسْلَمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ يَا رَسُولَ اللَّهِ، إِنِّي صَاحِبُ ظَهْرٍ أُعَالِجُهُ: أُسَافِرُ عَلَيْهِ، وَأُكْرِيهِ، وَإِنَّهُ رُبَّمَا صَادَفَنِي هَذَا الشَّهْرُ - يَعْنِي رَمَضَانَ - وَأَنَا أَجِدُ الْقُوَّةَ، وَأَنَا شَابٌّ، وَأَجِدُ بِأَنْ أَصُومَ- يَا رَسُولَ اللَّهِ- أَهْوَنَ عَلَيَّ مِنْ أَنْ أُؤَخِّرَهُ فَيَكُونُ دَيْنًا، أَفَأَصُومُ يَا رَسُولَ اللَّهِ أَعْظَمُ لِأَجْرِي أَوْ أُفْطِرُ؟ قَالَ: "أَيَّ ذَلِكَ شِئْتَ يَا حَمْزَةُ". (م،د،ن)', 'ഹംസതുൽ അസ്ലമി(റ): ഞാൻ ചോദിച്ചു: പ്രവാചകരേ, ഞാൻ ഒരു വാഹനം കൈകാര്യം ചെയ്യുന്നവനാണ്. അതിന്മേൽ ഞാൻ യാത്ര ചെയ്യുകയും അതിനെ ഞാൻ വാടകയ്ക്കു കൊടുക്കുകയും ചെയ്യുന്നു. എന്റെ യാത്രക്കിടെ ഈ മാസം - റമളാൻ - കടന്നുവന്നേക്കാം. അത് അനുഷ്ഠിക്കുവാൻ എനിക്കു കഴിവുണ്ട്. ഞാനൊരു യുവാവാണ്. പ്രവാചകരേ, നോമ്പെടുക്കുന്നത്, അതിനെ ഒരുകടമായി പിന്തിക്കുന്നതിനേക്കാൾ എനിക്ക് നിസ്സാരമായി തോന്നുന്നു. അതിനാൽ പ്രവാചകരേ, ഞാനതു നോൽക്കുകയാണോ ഒഴിവാക്കുകയാണോ കൂടുതൽ പ്രതിഫലം ലഭ്യമാവാനുള്ള മാർഗം? തിരുമേനി(സ) പറഞ്ഞു: "ഹംസേ, നിനക്കിഷ്ടമുള്ളത് നീ പ്രവർത്തിച്ചോളൂ." (മു,ദ,ന)', 'حَمْزَةَ الْأَسْلَمِيِّ', 'ഹംസതുൽ അസ്ലമി(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا نُسَافِرُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمِنَّا الصَّائِمُ وَمِنَّا الْمُفْطِرِ، فَلَا يَجِدُ الْمُفْطِرُ عَلَى الصَّائِمِ وَلَا الصَّائِمُ عَلَى الْمُفْطِرِ. فَكَانُوا يَرَوْنَ أَنَّهُ مَنْ وَجَدَ قُوَّةً فَصَامَ فَحَسَنٌ، وَمَنْ وَجَدَ ضَعْفًا فَأَفْطَرَ فَحَسَنٌ. (م,ت)', 'അബൂസഈദ്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം യാത്രചെയ്യുമ്പോൾ നോമ്പുള്ളവരും ഇല്ലാത്തവരും ഞങ്ങളുടെ കൂട്ടത്തിലുണ്ടയിരുന്നു. എന്നാൽ നോമ്പുള്ളവർ ഇല്ലാത്തവരെയോ ഇല്ലാത്തവർ ഉള്ളവരെയോ ആക്ഷേപിച്ചില്ല. കഴിവുള്ളവർ അനുഷ്ഠിക്കുന്നതും ബലഹീനർ ഒഴിവാക്കുന്നതും നല്ലതായി അവർ കാണുമായിരുന്നു. (മു,തു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 108, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السَّفَرِ، فَمِنَّا الصَّائِمُ وَمِنَّا الْمُفْطِرُ، قَالَ: فَنَزَلْنَا مَنْزِلًا فِي يَوْمٍ حَارٍّ، أَكْثَرُنَا ظِلًّا صَاحِبُ الْكِسَاءِ، وَمِنَّا مَنْ يَتَّقِي الشَّمْسَ بِيَدِهِ، قَالَ: فَسَقَطَ الصُّوَّامُ وَقَامَ الْمُفْطِرُونَ، فَضَرَبُوا الْأَبْنِيَةَ وَسَقَوُا الرِّكَابَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ذَهَبَ الْمُفْطِرُونَ الْيَوْمَ بِالْأَجْرِ". (م)', 'അനസ്(റ): ഞങ്ങൾ പ്രവാചകർ(സ)യോടൊപ്പം ഒരു യാത്രയിലായിരുന്നു. ഞങ്ങളുടെ കൂട്ടത്തിൽ നോമ്പ് എടുത്തിരുന്നവരും നോമ്പ് ഒഴിവാക്കിയവരും ഉണ്ടായിരുന്നു. കഠിനചൂടുണ്ടായിരുന്ന ഒരു ദിവസം ഞങ്ങൾ ഒരു താവളത്തിൽ ഇറങ്ങി. കൂട്ടത്തിൽ പുതപ്പുണ്ടായിരുന്നവർക്കാണ് ഞങ്ങളുടെ ഇടയിൽ അധികം തണൽ ലഭിച്ചിരുന്നത്. കൈകൊണ്ടു വെയിൽ തടുത്തിരുന്നവരും ഉണ്ടായിരുന്നു. നോമ്പുണ്ടായിരുന്നവരെല്ലാം തളർന്നുവീണു. നോമ്പ് ഒഴിവാക്കിയിരുന്നവർ എഴുന്നേറ്റു തമ്പു കെട്ടുകയും വാഹനങ്ങൾക്ക് (മൃഗങ്ങൾ) വെള്ളം നൽകുകയും ചെയ്തു. അന്നേരം റസൂൽ(സ) പറഞ്ഞു: "ഇന്ന് നോമ്പ് അനുഷ്ഠിക്കാത്തവരാണ് പ്രതിഫലം കരസ്ഥമാക്കിയത്." (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنْ سَلَمَةَ بْنِ الْمُحَبَّقِ الْهُذَلِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَتْ لَهُ حَمُولَةٌ تَأْوِي إِلَى شِبَعٍ فَلْيَصُمْ رَمَضَانَ حَيْثُ أَدْرَكَهُ". وَفِي رِوَايَةٍ: "مَنْ أَدْرَكَهُ رَمَضَانُ فِي السَّفَرِ..." فَذَكَرَ مَعْنَاهُ. (د)', 'സലമതുബ്നുൽ മുഹബ്ബഖിൽ ഹുദലി(റ): റസൂൽ(സ) പറഞ്ഞു: "യാത്രാവേളയിൽ സുഖകരമായി യാത്ര ചെയ്യാവുന്ന വാഹനസൗകര്യമുള്ളവൻ, തന്റെ യാത്രയിൽ റമളാൻ ആഗതമായ സ്ഥലം മുതൽ നോമ്പ് എടുത്തുകൊള്ളട്ടെ." മറ്റൊരു നിവേദനത്തിൽ "യാത്രാവേളയിൽ റമളാൻ ആഗതമായാൽ...." എന്നാണുള്ളത്. (ദ)', 'سَلَمَةَ بْنِ الْمُحَبَّقِ الْهُذَلِيِّ', 'സലമതുബ്നുൽ മുഹബ്ബഖിൽ ഹുദലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=245), 1, 'وَفِي رِوَايَةٍ: "مَنْ أَدْرَكَهُ رَمَضَانُ فِي السَّفَرِ..." فَذَكَرَ مَعْنَاهُ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ "യാത്രാവേളയിൽ റമളാൻ ആഗതമായാൽ...." എന്നാണുള്ളത്. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ إِلَى مَكَّةَ عَامَ الْفَتْحِ، فَصَامَ حَتَّى بَلَغَ كُرَاعَ الْغَمِيمِ، وَصَامَ النَّاسُ مَعَهُ. فَقِيلَ لَهُ: إِنَّ النَّاسَ قَدْ شَقَّ عَلَيْهِمُ الصِّيَامُ، وَإِنَّ النَّاسَ يَنْظُرُونَ فِيمَا فَعَلْتَ. فَدَعَا بِقَدَحٍ مِنْ مَاءٍ بَعْدَ الْعَصْرِ فَشَرِبَ، وَالنَّاسُ يَنْظُرُونَ إِلَيْهِ. فَأَفْطَرَ بَعْضُهُمْ وَصَامَ بَعْضُهُمْ، فَبَلَغَهُ أَنَّ نَاسًا صَامُوا، فَقَالَ: "أُولَئِكَ الْعُصَاةُ". حَسَنٌ صَحِيحٌ. (م,ت,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) മക്കാവിജയത്തിന്റെ വർഷം മക്കയിലേക്ക് യാത്ര പുറപ്പെട്ടപ്പോൾ കുറാഉൽഗമീം എന്ന സ്ഥലത്ത് എത്തുന്നതുവരെ നോമ്പ് എടുത്തിരുന്നു. തിരുമേനി(സ)യോടൊപ്പം ജനങ്ങളും നോമ്പ് എടുത്തിരുന്നു. അവിടത്തോട് പറയപ്പെട്ടു: ജനങ്ങൾക്ക് നോമ്പ് വല്ലാതെ പ്രയാസകരമായിരിക്കുന്നു, അങ്ങ് എന്താണ് ചെയ്യുന്നതെന്ന് നോക്കുകയാണവർ. അപ്പോൾ തിരുമേനി(സ), അസ്വറിന് ശേഷം, ഒരു കോപ്പ വെള്ളം കൊണ്ടുവരാൻ ആവശ്യപ്പെടുകയും ജനങ്ങൾ കാൺകെതന്നെ അത് കുടിക്കുകയും ചെയ്തു. ഇതു കണ്ട ചിലർ നോമ്പുമുറിക്കുകയും എന്നാൽ മറ്റു ചിലർ നോമ്പ് മുറിക്കാതിരിക്കുകയും ചെയ്തു. ചിലയാളുകൾ നോമ്പ് എടുത്തിരിക്കുന്നുവെന്നു തിരുമേനി(സ) അറിഞ്ഞപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അവരാണ് എതിർ പ്രവർത്തിച്ചവർ." (മു,തു,ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِطَعَامٍ بِمَرِّ الظَّهْرَانِ، فَقَالَ لِأَبِي بَكْرٍ وَعُمَرَ "أَدْنِيَا فَكُلَا". فَقَالَا: إِنَّا صَائِمَانِ. فَقَالَ: "ارْحَلُوا لِصَاحِبَيْكُمْ، اعْمَلُوا لِصَاحِبَيْكُمْ". (ن)', 'അബൂഹുറൈറ(റ): ഒരു യാത്രയിൽ മർറുള്ളഹ്റാൻ എന്ന സ്ഥലത്ത് വെച്ച് പ്രവാചകൻ(സ)ക്ക് ഒരാൾ ഭക്ഷണം കൊണ്ടുവന്ന് കൊടുത്തു. അപ്പോൾ തിരുമേനി(സ) അബൂബക്കർ(റ), ഉമർ(റ) എന്നിവരോട് പറഞ്ഞു: "നിങ്ങൾ രണ്ടുപേരും അടുത്തേക്കിരുന്ന് ഭക്ഷണം കഴിക്കുക." അന്നേരം അവർ പറഞ്ഞു: ഞങ്ങൾ രണ്ടുപേരും നോമ്പുകാരാണ്. അപ്പോൾ തിരുമേനി(സ) (മറ്റു അനുചരരോട്) പറഞ്ഞു: "നിങ്ങളുടെ ഈ രണ്ടു കൂട്ടാളികളുടെ യാത്രയിൽ നിങ്ങൾ സഹായിക്കുക. നിങ്ങളുടെ ഈ രണ്ട് കൂട്ടുകാർക്കുവേണ്ടത് നിങ്ങൾ ചെയ്തുകൊടുക്കുക." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 109, 110, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ رَضِيَ اللهُ عَنْهُ قَالَ: يُقَالُ: الصِّيَامُ فِي السَّفَرِ كَالْإِفْطَارِ فِي الْحَضَرِ. وَفِي رِوَايَةٍ عَنْهُ قَالَ: الصَّائِمُ فِي السَّفَرِ كَالْمُفْطِرِ فِي الْحَضَرِ. (ن,جه)', 'അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ): യാത്രാവേളയിൽ നോമ്പനുഷ്ഠിക്കുകയെന്നത്, യാത്രയിലല്ലാത്തപ്പോൾ നോമ്പ് ഒഴിവാക്കുന്നതുപോലെയാണ് എന്ന് പറയപ്പെടുന്നു. അദ്ദേഹത്തിൽനിന്നുതന്നെയുള്ള മറ്റൊരു നിവേദനത്തിൽ: യാത്രാവേളയിൽ നോമ്പനുഷ്ഠിക്കുന്നവൻ, യാത്രയിലല്ലാത്തപ്പോൾ നോമ്പ് ഒഴിവാക്കുന്നവനെപ്പോലെയാണ്. (ന,ജ)', 'عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ', 'അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 110, 110, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=248), 1, 'وَفِي رِوَايَةٍ عَنْهُ قَالَ: الصَّائِمُ فِي السَّفَرِ كَالْمُفْطِرِ فِي الْحَضَرِ. (ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: യാത്രാവേളയിൽ നോമ്പനുഷ്ഠിക്കുന്നവൻ, യാത്രയിലല്ലാത്തപ്പോൾ നോമ്പ് ഒഴിവാക്കുന്നവനെപ്പോലെയാണ്. (ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ مُجَاهِدٍ، وَقَدْ سُئِلَ عَنِ الصَّوْمِ فِي السَّفَرِ؟ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ وَيُفْطِرُ. وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَامَ فِي شَهْرِ رَمَضَانَ وَأَفْطَرَ فِي السَّفَرِ. (ن)', 'മുജാഹിദ്(റ): യാത്രാവേളയിൽ നോമ്പ് എടുക്കുന്നതിനെക്കുറിച്ച് അദ്ദേഹത്തോട് ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) നോമ്പനുഷ്ഠിക്കുകയും ഒഴിവാക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. മറ്റൊരു നിവേദനം: റസൂൽ(സ) റമളാൻ മാസത്തിൽ നോമ്പനുഷ്ഠിക്കുകയും യാത്രാവേളയിൽ ഒഴിവാക്കുകയും ചെയ്തിരുന്നു. (ന)', 'مُجَاهِدٍ، وَقَدْ سُئِلَ عَنِ الصَّوْمِ فِي السَّفَرِ؟ قَالَ', 'മുജാഹിദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 110, 110, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=249), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَامَ فِي شَهْرِ رَمَضَانَ وَأَفْطَرَ فِي السَّفَرِ. (ن)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) റമളാൻ മാസത്തിൽ നോമ്പനുഷ്ഠിക്കുകയും യാത്രാവേളയിൽ ഒഴിവാക്കുകയും ചെയ്തിരുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ– رَجُلٌ مِنْ بَنِي عَبْدِ اللَّهِ بْنِ كَعْبٍ إِخْوَةِ بَنِي قُشَيْرٍ– قَالَ: أَغَارَتْ عَلَيْنَا خَيْلٌ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَانْتَهَيْتُ– أَوْ قَالَ: فَانْطَلَقْتُ– إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَأْكُلُ، فَقَالَ: "اجْلِسْ فَأَصِبْ مِنْ طَعَامِنَا هَذَا". فَقُلْتُ: إِنِّي صَائِمٌ، قَالَ: "اجْلِسْ أُحَدِّثْكَ عَنِ الصَّلَاةِ وَعَنِ الصِّيَامِ، إِنَّ اللَّهَ تَعَالَى وَضَعَ شَطْرَ الصَّلَاةِ– أَوْ نِصْفَ الصَّلَاةِ– وَالصَّوْمَ: عَنِ الْمُسَافِرِ، وَعَنِ الْمُرْضِعِ، أَوِ: الْحُبْلَى". وَاللَّهِ لَقَدْ قَالَهُمَا جَمِيعًا أَوْ أَحَدَهُمَا، قَالَ: فَتَلَهَّفَتْ نَفْسِي أَنْ لَا أَكُونَ أَكَلْتُ مِنْ طَعَامِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د,ت,ن,جه)', 'ബനൂഖുശൈറിന്റെ സഹോദരങ്ങളായ അബ്ദുല്ലാഹിബിൻ കഅ്ബിന്റെ സന്തതികളിലൊരാളായ അനസുബ്നു മാലിക്(റ): റസൂൽ(സ)യുടെ ഒരു കുതിരസംഘം അബദ്ധത്തിൽ ഞങ്ങൾക്കെതിരിൽ ആക്രമണം നടത്തി. അന്നേരം ഞാൻ പ്രവാചകരുടെ അടുത്തേക്ക്പോയി. തിരുമേനി(സ) അപ്പോൾ ഭക്ഷണം കഴിക്കുകയായിരുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "നീ ഇരുന്ന് ഞങ്ങളുടെ ഈ ഭക്ഷണം കഴിക്കൂ." അപ്പോൾ ഞാൻ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. തിരുമേനി(സ) പറഞ്ഞു: "നീ ഇരിക്കൂ, നിനക്ക് ഞാൻ നിസ്കാരത്തെയും നോമ്പിനേയും കുറിച്ച് പറഞ്ഞുതരാം. നിശ്ചയം അല്ലാഹുതആല, നിസ്കാരത്തിന്റെ പകുതിഭാഗവും നോമ്പും, യാത്രക്കാരൻ, മുലയൂട്ടുന്ന സ്ത്രീ അല്ലെങ്കിൽ ഗർഭിണി എന്നിവർക്ക് ഇളവ് നൽകിയിരിക്കുന്നു." മുലയൂട്ടുന്ന സ്ത്രീ, ഗർഭിണി ഇവർ രണ്ടുപേരെയും ഒരുമിച്ചോ അല്ലെങ്കിൽ ഇതിൽ ഏതെങ്കിലും ഒരാളേയോ ആണ് തിരുമേനി(സ) പ്രതിപാദിച്ചത്. നിവേദകൻ പറയുന്നു: റസൂൽ(സ)യുടെ ഭക്ഷണം ഞാൻ കഴിക്കാതിരുന്നതിൽ എനിക്കിപ്പോൾ ഖേദം തോന്നുന്നു. (ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', null, null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 110, 110, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنْ مُحَمَّدِ بْنِ كَعْبٍ أَنَّهُ قَالَ: أَتَيْتُ أَنَسَ بْنَ مَالِكٍ– رَضِيَ اللهُ عَنْهُ– فِي رَمَضَانَ وَهُوَ يُرِيدُ سَفَرًا، وَقَدْ رُحِلَتْ لَهُ رَاحِلَتُهُ وَلَبِسَ ثِيَابَ السَّفَرِ، فَدَعَا بِطَعَامٍ فَأَكَلَ، فَقُلْتُ لَهُ: سُنَّةٌ؟ قَالَ: سُنَّةٌ. ثُمَّ رَكِبَ. حَسَنٌ. (ت)', 'മുഹമ്മദുബ്നു കഅ്ബ്(റ): ഞാനൊരു റമളാനിൽ അനസുബ്നു മാലിക്(റ)വിന്റെ അടുത്ത് ചെന്നു. അദ്ദേഹമപ്പോൾ ഒരു യാത്രക്കുള്ള തയ്യാറെടുപ്പിലായിരുന്നു. അദ്ദേഹത്തിനായി തന്റെ വാഹനം തയ്യാറാക്കപ്പെടുകയും അദ്ദേഹം യാത്രാവസ്ത്രം ധരിക്കുകയും ചെയ്തിരുന്നു. അന്നേരം അദ്ദേഹം ഭക്ഷണം കൊണ്ടുവരാൻ ആവശ്യപ്പെടുകയും അതു കഴിക്കുകയും ചെയ്തു. അപ്പോൾ ഞാൻ ചോദിച്ചു: ഇതു സുന്നത്താണോ? അദ്ദേഹം പറഞ്ഞു: സുന്നത്താണ്. പിന്നെ അദ്ദേഹം വാഹനപ്പുറത്ത് കയറി. (തു)', 'مُحَمَّدِ بْنِ كَعْبٍ أَنَّهُ قَالَ', 'മുഹമ്മദുബ്നു കഅ്ബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 110, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنْ أَبِي قِلَابَةَ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ فِي سَفَرٍ، فَقَرَّبَ طَعَامًا، فَقَالَ لِرَجُلٍ: "ادْنُ فَاطْعَمْ". قَالَ: إِنِّي صَائِمٌ. قَالَ: "إِنَّ اللَّهَ وَضَعَ عَنِ الْمُسَافِرِ نِصْفَ الصَّلَاةِ وَالصِّيَامَ فِي السَّفَرِ، فَادْنُ فَاطْعَمْ". (ن)', 'അബൂഖിലാബ(റ): റസൂൽ(സ) ഒരു യാത്ര പുറപ്പെട്ടു. ആ യാത്രയിൽവെച്ച് തിരുമേനി(സ) ഭക്ഷണം അടുത്ത് വെച്ച് ഒരാളോടു പറഞ്ഞു: "നീ അടുത്തേക്കിരുന്ന് ഭക്ഷണം കഴിക്കൂ." അപ്പോൾ അയാൾ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അല്ലാഹു യാത്രക്കാരന് യാത്രാവേളയിൽ നിസ്കാരത്തിന്റെ പകുതിയും നോമ്പും ഇളവുനൽകിയിരിക്കുന്നു. അതുകൊണ്ട് നീ അടുത്തേക്കിരുന്ന് ഭക്ഷണം കഴിക്കൂ." (ന)', 'أَبِي قِلَابَةَ', 'അബൂഖിലാബ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 111, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنْ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ سَفَرٍ، فَقَالَ: "انْتَظِرِ– وَفِي رِوَايَةٍ: أَلَا تَنْتَظِرُ– الْغَدَاءَ يَا أَبَا أُمَيَّةَ". فَقُلْتُ: إِنِّي صَائِمٌ. فَقَالَ: "تَعَالَ ادْنُ مِنِّي حَتَّى أُخْبِرَكَ عَنِ الْمُسَافِرِ، إِنَّ اللَّهَ عَزَّ وَجَلَّ وَضَعَ عَنْهُ الصِّيَامَ وَنِصْفَ الصَّلَاةِ". (ن)', 'അംറുബ്നു ഉമയ്യതുള്ളംരി(റ): ഞാനൊരു യാത്രയിൽനിന്ന് മടങ്ങവേ റസൂൽ(സ)യുടെ അടുത്തേക്ക് ചെന്നു. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: "അബൂഉമയ്യാ, താങ്കൾ പ്രഭാതഭക്ഷണം പ്രതീക്ഷിക്കുക - മറ്റൊരു റിപ്പർട്ടിൽ: ഭക്ഷണം പ്രതീക്ഷിക്കുന്നില്ലേ?" ഞാൻ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നീ വരൂ എന്റെ അടുത്തേക്കിരിക്കൂ, യാത്രക്കാരനെക്കുറിച്ച് നിനക്കു ഞാൻ പറഞ്ഞുതരാം, യാത്രക്കാരന് അല്ലാഹു നോമ്പും നിസ്കാരത്തിന്റെ പകുതിയും ഇളവുചെയ്തിരിക്കുന്നു." (ന)', 'عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ', 'അംറുബ്നു ഉമയ്യതുള്ളംരി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 111, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=253), 1, 'وَفِي رِوَايَةٍ: أَلَا تَنْتَظِرُ– الْغَدَاءَ يَا أَبَا أُمَيَّةَ". فَقُلْتُ: إِنِّي صَائِمٌ. فَقَالَ: "تَعَالَ ادْنُ مِنِّي حَتَّى أُخْبِرَكَ عَنِ الْمُسَافِرِ، إِنَّ اللَّهَ عَزَّ وَجَلَّ وَضَعَ عَنْهُ الصِّيَامَ وَنِصْفَ الصَّلَاةِ". (ن)', 'മറ്റൊരു നിവേദനിൽ: ഭക്ഷണം പ്രതീക്ഷിക്കുന്നില്ലേ?" ഞാൻ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നീ വരൂ എന്റെ അടുത്തേക്കിരിക്കൂ, യാത്രക്കാരനെക്കുറിച്ച് നിനക്കു ഞാൻ പറഞ്ഞുതരാം, യാത്രക്കാരന് അല്ലാഹു നോമ്പും നിസ്കാരത്തിന്റെ പകുതിയും ഇളവുചെയ്തിരിക്കുന്നു." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنْ أَنَسِ بْنِ مَالِكٍ الْقُشَيْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ ذَهَبَ فِي إِبِلٍ لَهُ، فَانْتَهَى إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَأْكُلُ، أَوْ قَالَ: يَطْعَمُ، فَقَالَ: "ادْنُ فَكُلْ". أَوْ قَالَ: "ادْنُ فَاطْعَمْ". فَقُلْتُ: إِنِّي صَائِمٌ. فَقَالَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ وَضَعَ عَنِ الْمُسَافِرِ شَطْرَ الصَّلَاةِ وَالصِّيَامِ، وَعَنِ الْحَامِلِ وَالْمُرْضِعِ". وَفِي رِوَايَةٍ: قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي إِبِلٍ كَانَتْ لِي أُخِذَتْ، فَوَافَقْتُهُ وَهُوَ يَأْكُلُ، فَدَعَانِي إِلَى طَعَامِهِ، فَقُلْتُ: إِنِّي صَائِمٌ. فَقَالَ: "ادْنُ أُخْبِرْكَ عَنْ ذَلِكَ، إِنَّ اللَّهَ وَضَعَ عَنِ الْمُسَافِرِ الصَّوْمَ وَشَطْرَ الصَّلَاةِ". وَفِي رِوَايَةٍ: قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِحَاجَةٍ، فَإِذَا هُوَ يَتَغَدَّى، قَالَ: "هَلُمَّ إِلَى الْغَدَاءِ". فَقُلْتُ: إِنِّي صَائِمٌ. قَالَ: "هَلُمَّ أُخْبِرْكَ عَنِ الصَّوْمِ، إِنَّ اللَّهَ وَضَعَ عَنِ الْمُسَافِرِ نِصْفَ الصَّلَاةِ وَالصَّوْمَ، وَرَخَّصَ لِلْحُبْلَى وَالْمُرْضِعِ. (ن)', 'അനസ്ബിൻ മാലിക് അൽഖുശൈരി(റ): അദ്ദേഹം, തന്റെ ഒരു ഒട്ടകത്തിന്റെ കാര്യം സംസാരിക്കാൻ റസൂൽ(സ)യെ സമീപിച്ചു. തിരുമേനി(സ) അന്നേരം ഭക്ഷണം കഴിക്കുകയായിരുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "നീ അടുത്തേക്ക് ഇരുന്ന്, ഭക്ഷണം കഴിക്കൂ." അന്നേരം ഞാൻ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. അന്നേരം തിരുമേനി(സ) പറഞ്ഞു: "നിശ്ചയം അല്ലാഹുതആല, യാത്രക്കാരന് നിസ്കാരത്തിന്റെ പകുതിഭാഗവും നോമ്പും, ഗർഭിണിക്കും മുലയൂട്ടുന്ന സ്ത്രീക്കും നോമ്പും ഇളവുചെയ്തിരിക്കുന്നു." മറ്റൊരു നിവേദനം: പിടിക്കപ്പെട്ട എന്റെ ഒരു ഒട്ടകത്തിന്റെ കാര്യത്തിൽ സംസാരിക്കുന്നതിനുവേണ്ടി ഞാൻ പ്രവാചകർ(സ)യെ സമീപിച്ചു. ഞാൻ തിരുമേനി(സ)യെ കണ്ടനേരം തിരുമേനി(സ) ഭക്ഷണം കഴിക്കുകയായിരുന്നു. അവിടന്ന് എന്നെ ഭക്ഷണം കഴിക്കാൻ ക്ഷണിച്ചു. ഞാൻ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "താങ്കൾ അടുത്തേക്കുവരൂ, അതേക്കുറിച്ചു ഞാൻ പറഞ്ഞുതരാം. തീർച്ചയായും അല്ലാഹു യാത്രക്കാരന് നോമ്പും നിസ്കാരത്തിന്റെ പകുതിയും ഇളവുചെയ്തിരിക്കുന്നു." മറ്റൊരു നിവേദനം: എന്റെ ഒരു ആവശ്യത്തിന് വേണ്ടി ഞാൻ റസൂൽ(സ)യുടെ അടുത്തുചെന്നു. അന്നേരം, അവിടന്ന് പ്രഭാതഭക്ഷണം കഴിക്കുകയായിരുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "ഭക്ഷണം കഴിക്കൂ." ഞാൻ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "വരൂ, താങ്കൾക്കു ഞാൻ നോമ്പിനെപ്പറ്റി പറഞ്ഞുതരാം, നിശ്ചയം അല്ലാഹു യാത്രക്കാരന് നിസ്കാരത്തിന്റെ പകുതിയും നോമ്പും ഒഴിവാക്കിക്കൊടുക്കുകയും ഗർഭിണിക്കും മുലയൂട്ടുന്ന പെണ്ണിനും ഇളവുനൽകുകയും ചെയ്തിരിക്കുന്നു." (ന)', 'أَنَسِ بْنِ مَالِكٍ الْقُشَيْرِيِّ', 'അനസ്ബിൻ മാലിക് അൽഖുശൈരി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 111, 112, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=254), 1, 'وَفِي رِوَايَةٍ: قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي إِبِلٍ كَانَتْ لِي أُخِذَتْ، فَوَافَقْتُهُ وَهُوَ يَأْكُلُ، فَدَعَانِي إِلَى طَعَامِهِ، فَقُلْتُ: إِنِّي صَائِمٌ. فَقَالَ: "ادْنُ أُخْبِرْكَ عَنْ ذَلِكَ، إِنَّ اللَّهَ وَضَعَ عَنِ الْمُسَافِرِ الصَّوْمَ وَشَطْرَ الصَّلَاةِ".', 'മറ്റൊരു നിവേദനം: പിടിക്കപ്പെട്ട എന്റെ ഒരു ഒട്ടകത്തിന്റെ കാര്യത്തിൽ സംസാരിക്കുന്നതിനുവേണ്ടി ഞാൻ പ്രവാചകർ(സ)യെ സമീപിച്ചു. ഞാൻ തിരുമേനി(സ)യെ കണ്ടനേരം തിരുമേനി(സ) ഭക്ഷണം കഴിക്കുകയായിരുന്നു. അവിടന്ന് എന്നെ ഭക്ഷണം കഴിക്കാൻ ക്ഷണിച്ചു. ഞാൻ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "താങ്കൾ അടുത്തേക്കുവരൂ, അതേക്കുറിച്ചു ഞാൻ പറഞ്ഞുതരാം. തീർച്ചയായും അല്ലാഹു യാത്രക്കാരന് നോമ്പും നിസ്കാരത്തിന്റെ പകുതിയും ഇളവുചെയ്തിരിക്കുന്നു."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=254), 2, 'وَفِي رِوَايَةٍ: قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِحَاجَةٍ، فَإِذَا هُوَ يَتَغَدَّى، قَالَ: "هَلُمَّ إِلَى الْغَدَاءِ". فَقُلْتُ: إِنِّي صَائِمٌ. قَالَ: "هَلُمَّ أُخْبِرْكَ عَنِ الصَّوْمِ، إِنَّ اللَّهَ وَضَعَ عَنِ الْمُسَافِرِ نِصْفَ الصَّلَاةِ وَالصَّوْمَ، وَرَخَّصَ لِلْحُبْلَى وَالْمُرْضِعِ. (ن)', 'മറ്റൊരു നിവേദനം: എന്റെ ഒരു ആവശ്യത്തിന് വേണ്ടി ഞാൻ റസൂൽ(സ)യുടെ അടുത്തുചെന്നു. അന്നേരം, അവിടന്ന് പ്രഭാതഭക്ഷണം കഴിക്കുകയായിരുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "ഭക്ഷണം കഴിക്കൂ." ഞാൻ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "വരൂ, താങ്കൾക്കു ഞാൻ നോമ്പിനെപ്പറ്റി പറഞ്ഞുതരാം, നിശ്ചയം അല്ലാഹു യാത്രക്കാരന് നിസ്കാരത്തിന്റെ പകുതിയും നോമ്പും ഒഴിവാക്കിക്കൊടുക്കുകയും ഗർഭിണിക്കും മുലയൂട്ടുന്ന പെണ്ണിനും ഇളവുനൽകുകയും ചെയ്തിരിക്കുന്നു." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'عَنْ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مُسَافِرًا، فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا صَائِمٌ وَهُوَ يَأْكُلُ، قَالَ: "هَلُمَّ". قُلْتُ: إِنِّي صَائِمٌ. قَالَ: "تَعَالَ، أَلَمْ تَعْلَمْ مَا وَضَعَ اللَّهُ عَنِ الْمُسَافِرِ". قُلْتُ: وَمَا وَضَعَ عَنِ الْمُسَافِرِ؟ قَالَ: "الصَّوْمَ وَنِصْفَ الصَّلَاةِ". وَفِي رِوَايَةٍ قَالَ: كُنَّا نُسَافِرُ مَا شَاءَ اللَّهُ، فَأَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَطْعَمُ، فَقَالَ: "هَلُمَّ فَاطْعَمْ". فَقُلْتُ: إِنِّي صَائِمٌ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أُحَدِّثُكُمْ عَنِ الصِّيَامِ، إِنَّ اللَّهَ وَضَعَ عَنِ الْمُسَافِرِ الصَّوْمَ وَشَطْرَ الصَّلَاةِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു ശിഖ്ഖീർ(റ): ഞാനൊരു യാത്രക്കാരനായിരുന്നു. അങ്ങനെ ഞാൻ നോമ്പുകാരനായി പ്രവാചകർ(സ)യുടെ അടുത്തുചെന്നു. തിരുമേനി(സ) അപ്പോൾ ഭക്ഷണം കഴിക്കുകയായിരുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "വരൂ." ഞാൻ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "വരൂ, യാത്രക്കാരന് അല്ലാഹു ഇളവുനൽകിയതിനെപ്പറ്റി നീയറിഞ്ഞിട്ടില്ലേ?" ഞാൻ ചോദിച്ചു: യാത്രക്കാരന് എന്ത് ഇളവാണ് നൽകപ്പെട്ടിരിക്കുന്നത്? തിരുമേനി(സ) പറഞ്ഞു: "നോമ്പും പകുതി നിസ്കാരവും." മറ്റൊരു നിവേദനം: ഞങ്ങൾ എവിടേക്കോ യാത്ര ചെയ്യുകയായിരുന്നു. അങ്ങനെ, റസൂൽ(സ) ഭക്ഷണം കഴിക്കുന്നവേളയിൽ ഞങ്ങൾ തിരുമേനി(സ)യെ സമീപിച്ചു. അപ്പോൾ, തിരുമേനി(സ) പറഞ്ഞു: "വരൂ ഭക്ഷണം കഴിക്കൂ." ഞാൻ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നോമ്പിനെക്കുറിച്ച് നിങ്ങൾക്ക് ഞാൻ പറഞ്ഞുതരാം, അല്ലാഹു യാത്രക്കാരന് നോമ്പും പകുതി നിസ്കാരവും ഇളവുചെയ്തിരിക്കുന്നു." (ന)', 'عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ', 'അബ്ദുല്ലാഹിബ്നു ശിഖ്ഖീർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 112, 112, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=255), 1, 'وَفِي رِوَايَةٍ قَالَ: كُنَّا نُسَافِرُ مَا شَاءَ اللَّهُ، فَأَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَطْعَمُ، فَقَالَ: "هَلُمَّ فَاطْعَمْ". فَقُلْتُ: إِنِّي صَائِمٌ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أُحَدِّثُكُمْ عَنِ الصِّيَامِ، إِنَّ اللَّهَ وَضَعَ عَنِ الْمُسَافِرِ الصَّوْمَ وَشَطْرَ الصَّلَاةِ". (ن)', 'മറ്റൊരു നിവേദനം: ഞങ്ങൾ എവിടേക്കോ യാത്ര ചെയ്യുകയായിരുന്നു. അങ്ങനെ, റസൂൽ(സ) ഭക്ഷണം കഴിക്കുന്നവേളയിൽ ഞങ്ങൾ തിരുമേനി(സ)യെ സമീപിച്ചു. അപ്പോൾ, തിരുമേനി(സ) പറഞ്ഞു: "വരൂ ഭക്ഷണം കഴിക്കൂ." ഞാൻ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നോമ്പിനെക്കുറിച്ച് നിങ്ങൾക്ക് ഞാൻ പറഞ്ഞുതരാം, അല്ലാഹു യാത്രക്കാരന് നോമ്പും പകുതി നിസ്കാരവും ഇളവുചെയ്തിരിക്കുന്നു." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ إِلَى مَكَّةَ فِي رَمَضَانَ فَصَامَ حَتَّى بَلَغَ الْكَدِيدَ، أَفْطَرَ، فَأَفْطَرَ النَّاسُ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) റമളാനിൽ മക്കയിലേക്കു പുറപ്പെട്ടു. ''കദീദ്'' എന്ന സ്ഥലം എത്തുന്നതുവരെ തിരുമേനി(സ) നോമ്പെടുത്തു. അവിടെയെത്തിയപ്പോൾ നോമ്പ് ഒഴിവാക്കി. അപ്പോൾ ജനങ്ങളും നോമ്പ് ഒഴിവാക്കി. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 112, 112, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنْ عُبَيْدِ بْنِ جَبْرٍ قَالَ: كُنْتُ مَعَ أَبِي بَصْرَةَ الْغِفَارِيِّ رَضِيَ اللهُ عَنْهُ– صَاحِبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ– فِي سَفِينَةٍ مِنَ الْفُسْطَاطِ فِي رَمَضَانَ، فَرُفِعَ، ثُمَّ قُرِّبَ غَدَاؤُهُ، فَلَمْ يُجَاوِزِ الْبُيُوتَ حَتَّى دَعَا بِالسُّفْرَةِ، قَالَ: اقْتَرِبْ، قُلْتُ: أَلَسْتَ تَرَى الْبُيُوتَ؟ قَالَ أَبُو بَصْرَةَ: أَتَرْغَبُ عَنْ سُنَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَأَكَلَ. (د)', 'ഉബൈദുബ്നു ജബ്ർ(റ): ഞാൻ റസൂൽ(സ)യുടെ അനുചരൻ അബൂബസ്റതിൽ ഗിഫാരി(റ)യോടൊന്നിച്ച് ഒരു റമളാനിൽ ഫുസ്ഥാഥിൽനിന്നുള്ള ഒരു കപ്പലിലായിരുന്നു. കപ്പൽ യാത്രപുറപ്പെട്ടു, അപ്പോൾ ഭക്ഷണം കൊണ്ടുവരപ്പെട്ടു. വീടുകൾ വിട്ടുകടക്കുന്നതിനു (കാഴ്ചയിൽനിന്ന് മറയുന്നതിന്) മുമ്പുതന്നെ യാത്രാഭക്ഷണം കൊണ്ടുവരാൻ അദ്ദേഹം ആവശ്യപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: താങ്കൾ അടുത്തിരിക്കൂ. ഞാൻ ചോദിച്ചു: താങ്കൾ വീടുകൾ കാണുന്നില്ലേ?. അപ്പോൾ അബൂബസ്റ(റ) പറഞ്ഞു: താങ്കൾ പ്രവാചകചര്യക്കു വിരുദ്ധമാണോ ആഗ്രഹിക്കുന്നത്? എന്നിട്ടദ്ദേഹം ഭക്ഷണം കഴിച്ചു. (ദ)', 'عُبَيْدِ بْنِ جَبْرٍ قَالَ', 'ഉബൈദുബ്നു ജബ്ർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 112, 113, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنْ دِحْيَةَ بْنِ خَلِيفَةَ الْكَلْبِيِّ رَضِيَ اللهُ عَنْهُ: خَرَجَ مِنْ قَرْيَةٍ مِنْ دِمَشْقَ مَرَّةً إِلَى قَدْرِ قَرْيَةِ عُقْبَةَ مِنَ الْفُسْطَاطِ، وَذَلِكَ ثَلَاثَةُ أَمْيَالٍ، فِي رَمَضَانَ، ثُمَّ إِنَّهُ أَفْطَرَ وَأَفْطَرَ مَعَهُ نَاسٌ، وَكَرِهَ آخَرُونَ أَنْ يُفْطِرُوا، فَلَمَّا رَجَعَ إِلَى قَرْيَتِهِ قَالَ: وَاللَّهِ لَقَدْ رَأَيْتُ الْيَوْمَ أَمْرًا مَا كُنْتُ أَظُنُّ أَنِّي أَرَاهُ، إِنَّ قَوْمًا رَغِبُوا عَنْ هَدْيِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابِهِ. يَقُولُ ذَلِكَ لِلَّذِينَ صَامُوا، ثُمَّ قَالَ عِنْدَ ذَلِكَ: اللَّهُمَّ اقْبِضْنِي إِلَيْكَ. (د)', 'ദിഹ്യതുബിനു ഖലീഫതിൽകൽബി(റ): ഡമസ്കസിലെ ഒരു ഗ്രാമത്തിൽനിന്ന് ഫുസ്ത്വാതിലെ അഖബ ഗ്രാമത്തിന്റെ ദൂരപരിധിയിലേക്ക് റമളാനിൽ അദ്ദേഹം യാത്ര പുറപ്പെട്ടു. മൂന്നുമൈൽ ദൂരമായിരുന്നു അത്. അദ്ദേഹം നോമ്പ് ഒഴിവാക്കി. അദ്ദേഹത്തിന്റെ കൂടെ കുറച്ചുപേരും നോമ്പ് ഒഴിവാക്കി. എന്നാൽ മറ്റു ചിലർ നോമ്പ് ഒഴിവാക്കാൻ വിസമ്മതിച്ചു. തന്റെ ഗ്രാമത്തിലേക്കു മടങ്ങിയെത്തിയപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുതന്നെ സത്യം, ഞാൻ കാണേണ്ടിവരുമെന്ന് ഒരിക്കലും നിനക്കാത്ത ഒന്നാണ് ഇന്നു ഞാൻ കണ്ടത്. കുറച്ചുപേർ, പ്രവാചകർ(സ)യുടെയും സ്വഹാബത്തിന്റെയും ചര്യയ്ക്കു വിരുദ്ധമായി ആഗ്രഹിക്കുന്നു. നോമ്പനുഷ്ഠിച്ചവരോടാണ് അദ്ദേഹം ഇങ്ങനെ പറഞ്ഞത്. എന്നിട്ടദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവേ, എന്റെ റൂഹ് നിന്നിലേക്ക് എടുക്കേണമേ. (ദ)', 'دِحْيَةَ بْنِ خَلِيفَةَ الْكَلْبِيِّ', 'ദിഹ്യതുബിനു ഖലീഫതിൽകൽബി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 113, 113, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: كَانَ يَخْرُجُ إِلَى الْغَابَةِ، فَلَا يُفْطِرُ وَلَا يَقْصُرُ. (د)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം കാട്ടിലേക്കു പുറപ്പെടാറുണ്ടായിരുന്നു. പക്ഷേ, അപ്പോഴൊന്നുമദ്ദേഹം നോമ്പ് ഒഴിവാക്കുകയോ നിസ്കാരം ഖസ്വ്റ് ആക്കുകയോ ചെയ്യുമായിരുന്നില്ല. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 113, 113, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنِ ابْنِ عَبَّاسٍ قَالَ: خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْمَدِينَةِ إِلَى مَكَّةَ حَتَّى بَلَغَ عُسْفَانَ، ثُمَّ دَعَا بِإِنَاءٍ فَرَفَعَهُ إِلَى فِيهِ لِيُرِيَهُ النَّاسَ، وَذَلِكَ فِي رَمَضَانَ، فَكَانَ ابْنُ عَبَّاسٍ يَقُولُ: قَدْ صَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَفْطَرَ، فَمَنْ شَاءَ صَامَ، وَمَنْ شَاءَ أَفْطَرَ. (ق,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മദീനയിൽ നിന്നും മക്കയിലേക്ക് പുറപ്പെട്ടു. ''ഉസ്ഫാനി''ലെത്തിയപ്പോൾ ഒരുപാത്രം വെള്ളംകൊണ്ടുവരാൻ പറയുകയും ജനങ്ങൾ കാൺകെ ഉയർത്തി അവിടത്തെ വായിലേക്കൊഴിക്കുകയും ചെയ്തു. ഇത് റമളാനിലായിരുന്നു. ഇബ്നുഅബ്ബാസ്(റ) പറയുമായിരുന്നു: നബി(സ) നോമ്പനുഷ്ഠിക്കുകയും ഒഴിവാക്കുകയും ചെയ്തിട്ടുണ്ട്. അതിനാൽ ഉദ്ദേശിക്കുന്നവർ നോമ്പനുഷ്ഠിക്കുകയും ഉദ്ദേശിക്കുന്നവർ ഒഴിവാക്കുകയും ചെയ്തു കൊള്ളട്ടെ. (ബു,മു,ദ,ന)', 'ابْنِ عَبَّاسٍ قَالَ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 113, 113, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ فِي رَمَضَانَ، فَصَامَ– وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَامَ فِي السَّفَرِ – حَتَّى أَتَى قُدَيْدًا، ثُمَّ أُتِيَ– وَفِي رِوَايَةٍ: دَعَا– بِقَدَحٍ مِنْ لَبَنٍ فَشَرِبَ، وَأَفْطَرَ هُوَ وَأَصْحَابُهُ. وَفِي رِوَايَةٍ: صَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْمَدِينَةِ حَتَّى أَتَى قُدَيْدًا، ثُمَّ أَفْطَرَ حَتَّى أَتَى مَكَّةَ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഒരു റമളാനിൽ യാത്ര പുറപ്പെടുകയും നോമ്പെടുക്കുകയും ചെയ്തു. മറ്റൊരു നിവേദനത്തിൽ: റസൂൽ(സ) യാത്രയിൽ നോമ്പെടുത്തു. അങ്ങനെ ഖുദൈദ് എന്ന സ്ഥലത്തെത്തി. അവിടെ എത്തിയപ്പോൾ ഒരു കോപ്പ പാൽ കൊണ്ടുവന്നുകൊടുത്തു. മറ്റൊരു നിവേദനം: തിരുമേനി(സ) ഒരു കോപ്പ പാൽ കൊണ്ടുവരാൻ ആവശ്യപ്പെട്ടു. അതു കുടിച്ചു. തിരുമേനി(സ)യും തന്റെ അനുചരന്മാരും നോമ്പ് ഒഴിവാക്കുകയും ചെയ്തു. മറ്റൊരു നിവേദനം: റസൂൽ(സ) മദീനയിൽനിന്നു ഖദീദ് എന്ന സ്ഥലത്ത് എത്തുന്നതുവരെ നോമ്പെടുക്കുകയും പിന്നെ അവിടെനിന്ന് മക്കയിലെത്തുന്നതുവരെ നോമ്പൊഴിവാക്കുകയും ചെയ്തു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 113, 114, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=261), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَامَ فِي السَّفَرِ – حَتَّى أَتَى قُدَيْدًا، ثُمَّ أُتِيَ–', 'മറ്റൊരു നിവേദനത്തിൽ: റസൂൽ(സ) യാത്രയിൽ നോമ്പെടുത്തു. അങ്ങനെ ഖുദൈദ് എന്ന സ്ഥലത്തെത്തി. അവിടെ എത്തിയപ്പോൾ ഒരു കോപ്പ പാൽ കൊണ്ടുവന്നുകൊടുത്തു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=261), 2, 'وَفِي رِوَايَةٍ: دَعَا– بِقَدَحٍ مِنْ لَبَنٍ فَشَرِبَ، وَأَفْطَرَ هُوَ وَأَصْحَابُهُ.', 'മറ്റൊരു നിവേദനം: തിരുമേനി(സ) ഒരു കോപ്പ പാൽ കൊണ്ടുവരാൻ ആവശ്യപ്പെട്ടു. അതു കുടിച്ചു. തിരുമേനി(സ)യും തന്റെ അനുചരന്മാരും നോമ്പ് ഒഴിവാക്കുകയും ചെയ്തു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=261), 3, 'وَفِي رِوَايَةٍ: صَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْمَدِينَةِ حَتَّى أَتَى قُدَيْدًا، ثُمَّ أَفْطَرَ حَتَّى أَتَى مَكَّةَ. (ن)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) മദീനയിൽനിന്നു ഖദീദ് എന്ന സ്ഥലത്ത് എത്തുന്നതുവരെ നോമ്പെടുക്കുകയും പിന്നെ അവിടെനിന്ന് മക്കയിലെത്തുന്നതുവരെ നോമ്പൊഴിവാക്കുകയും ചെയ്തു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ– رَجُلٌ مِنْ بَنِي عَبْدِ الْأَشْهَلِ– قَالَ: أَغَارَتْ عَلَيْنَا خَيْلُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَتَغَدَّى، فَقَالَ: "ادْنُ فَكُلْ". قُلْتُ: إِنِّي صَائِمٌ. قَالَ: "اجْلِسْ أُحَدِّثْكَ عَنِ الصَّوْمِ. أَو: الصِّيَامِ. إِنَّ اللَّهَ عَزَّ وَجَلَّ وَضَعَ عَنِ الْمُسَافِرِ شَطْرَ الصَّلَاةِ، وَعَنِ الْمُسَافِرِ وَالْحَامِلِ وَالْمُرْضِعِ الصَّوْمَ. أَو: الصِّيَامَ". وَاللَّهِ لَقَدْ قَالَهُمَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كِلْتَاهُمَا أَوْ إِحْدَاهُمَا، فَيَا لَهْفَ نَفْسِي، فَهَلَّا كُنْتُ طَعِمْتُ مِنْ طَعَامِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د,ت,ن,جه)', 'ബനുഅബ്ദിൽ അശ്ഹലിൽ പെട്ട അനസുബ്നു മാലിക്(റ): ഞങ്ങളുടെ മേൽ നബി(സ)യുടെ കുതിര ആക്രമണം നടത്തി. ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നു. അപ്പോൾ നബി(സ) ഭക്ഷണം കഴിച്ച് കൊണ്ടിരിക്കുകയായിരുന്നു. എന്നോട് റസൂൽ(സ) പറഞ്ഞു: "അടുത്ത് വന്ന് ഭക്ഷിക്കൂ" ഞാൻ പറഞ്ഞു: എനിക്ക് നോമ്പാണ്. നബി(സ) പറഞ്ഞു: "താങ്കളിരിക്കൂ, ഞാൻ നോമ്പിനെക്കുറിച്ച് പറഞ്ഞു തരാം. നിശ്ചയം അല്ലാഹുതആല യാത്രക്കാരന് നിസ്കാരത്തിന്റെ പകുതിയും, യാത്രക്കാരൻ, ഗർഭിണി, മുലകൊടുക്കുന്ന സ്ത്രീ എന്നിവർക്ക് നോമ്പും ഇളവ് ചെയ്തിട്ടുണ്ട്." അദ്ദേഹം പറയുന്നു: അല്ലാഹുവാണെ, റസൂൽ(സ) രണ്ട് പേരെയും (ഗർഭണി, മുലയൂട്ടുന്നവൾ) ഒരുമിച്ചോ അല്ലെങ്കിൽ ഒരാളെ തനിച്ചോ ആണ് പറഞ്ഞത്. എന്റെ ദുഃഖമേ, നബി(സ)യുടെ ഭക്ഷണത്തിൽ നിന്ന് ഭക്ഷിച്ചിരുന്നെങ്കിലെന്ന് ഇപ്പോൾ എനിക്ക് തോന്നുന്നു. (ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'ബനുഅബ്ദിൽ അശ്ഹലിൽ പെട്ട അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 114, 114, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَخَّصَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْحُبْلَى الَّتِي تَخَافُ عَلَى نَفْسِهَا أَنْ تُفْطِرَ، وَلِلْمُرْضِعِ الَّتِي تَخَافُ عَلَى وَلَدِهَا. (جه)', 'അനസുബ്നു മാലിക്(റ): ശരീരത്തിന് അനാരോഗ്യം വരുമെന്നു ഭയപ്പെടുന്ന ഗർഭിണിക്കും കുഞ്ഞിന്റെ അനാരോഗ്യം ഭയക്കുന്ന മുലയൂട്ടുന്ന സ്ത്രീക്കും നോമ്പൊഴിവാക്കാൻ അല്ലാഹുവിന്റെ റസൂൽ(സ) ഇളവു നൽകിയിരിക്കുന്നു.¹ (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', '¹ നോമ്പനുഷ്ഠിക്കാൻ സാധിക്കാത്തവൻ അതൊഴിവാക്കിയാൽ അതാണുത്തമം എന്നാണ് അവർ അഭിപ്രായപ്പെട്ടിരുന്നത്.', null, array['جه']::text[], array['ജ']::text[], null, null, 114, 114, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَنْ مُعَاذَةَ الْعَدَوِيَّةِ: أَنَّ امْرَأَةً سَأَلَتْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَتَقْضِي الْحَائِضُ الصَّلَاةَ إِذَا طَهُرَتْ؟ قَالَتْ: أَحَرُورِيَّةٌ أَنْتِ؟ كُنَّا نَحِيضُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ نَطْهُرُ، فَيَأْمُرُنَا بِقَضَاءِ الصَّوْمِ وَلَا يَأْمُرُنَا بِقَضَاءِ الصَّلَاةِ. (ن)', 'മുആദതുൽ അദവിയ്യ(റ): ഒരു സ്ത്രീ ആഇശ(റ)യോട് ചോദിച്ചു: ആർത്തവകാരി ശുദ്ധിയായാൽ നിസ്കാരം ഖളാഅ് വീട്ടേണ്ടതുണ്ടോ? ആഇശ(റ) ചോദിച്ചു: നീ ഖവാരിജി² വാദക്കാരിയാണോ? റസൂൽ(സ)യുടെ കാലത്ത് ഞങ്ങൾ ആർത്തവത്തിൽനിന്നു വിമുക്തരായാൽ നോമ്പു ഖളാഅ് വീട്ടാൻ റസൂൽ(സ) കൽപ്പിക്കുമായിരുന്നു. എന്നാൽ, നിസ്കാരം ഖളാഅ് വീട്ടാൻ കൽപ്പിക്കാറില്ല. (ന)', 'مُعَاذَةَ الْعَدَوِيَّةِ', 'മുആദതുൽ അദവിയ്യ(റ)', '² ഹൈളിന്റെ കാര്യത്തിൽ കർക്കശ സ്വഭാവക്കാരായിരുന്നു ഖവാരിജുകൾ.', null, array['ن']::text[], array['ന']::text[], null, null, 114, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنْ كَانَ لَيَكُونُ عَلَيَّ الصِّيَامُ مِنْ رَمَضَانَ، فَمَا أَقْضِيهِ حَتَّى يَجِيءَ شَعْبَانُ. (ن)', 'ആഇശ (റ): റമളാനിലെ വല്ല നോമ്പും ഖളാഅ് വീട്ടാനുണ്ടെങ്കിൽ അടുത്ത ശഅ്ബാൻ വരെ ഞാൻ ആ നോമ്പു ഖളാഅ് വീട്ടാറുണ്ടായിരുന്നില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ (റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ نَزَلَ عَلَى قَوْمٍ فَلَا يَصُومَنَّ تَطَوُّعًا إِلَّا بِإِذْنِهِمْ". مُنْكَرٌ. (ت,جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു സമൂഹത്തിനടുത്ത് അതിഥിയായി ചെന്നാൽ അവരുടെ സമ്മതപ്രകാരമല്ലാതെ സുന്നത്ത് നോമ്പ് അനുഷ്ഠിക്കരുത്." (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ قَزَعَةَ قَالَ: أَتَيْتُ أَبَا سَعِيدٍ الْخُدْرِيَّ رَضِيَ اللهُ عَنْهُ وَهُوَ يُفْتِي النَّاسَ، وَهُمْ مُكِبُّونَ عَلَيْهِ، فَانْتَظَرْتُ خَلْوَتَهُ، فَلَمَّا خَلَا سَأَلْتُهُ عَنْ صِيَامِ رَمَضَانَ فِي السَّفَرِ؟ فَقَالَ: خَرَجْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَمَضَانَ عَامَ الْفَتْحِ، فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ وَنَصُومُ، حَتَّى بَلَغَ مَنْزِلًا مِنَ الْمَنَازِلِ، فَقَالَ: "إِنَّكُمْ قَدْ دَنَوْتُمْ مِنْ عَدُوِّكُمْ، وَالْفِطْرُ أَقْوَى لَكُمْ". فَأَصْبَحْنَا: مِنَّا الصَّائِمُ وَمِنَّا الْمُفْطِرُ، قَالَ: ثُمَّ سِرْنَا فَنَزَلْنَا مَنْزِلًا، فَقَالَ: "إِنَّكُمْ تُصَبِّحُونَ عَدُوَّكُمْ، وَالْفِطْرُ أَقْوَى لَكُمْ فَأَفْطِرُوا". فَكَانَتْ عَزِيمَةً مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ أَبُو سَعِيدٍ: ثُمَّ لَقَدْ رَأَيْتُنِي أَصُومُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبْلَ ذَلِكَ وَبَعْدَ ذَلِكَ. (م,د,ت,ن)', 'ഖസഅത്ത്(റ): ഞാൻ അബൂസഈദിൽ ഖുദ്രീ(റ)വിന്റെ അടുത്ത് ചെന്നപ്പോൾ അദ്ദേഹം ജനങ്ങൾക്ക് ഫത്വ നൽകുകയായിരുന്നു. ജനങ്ങൾ അദ്ദേഹത്തെ പൊതിഞ്ഞ് നിൽക്കുകയായിരുന്നു. അതുകൊണ്ട് അദ്ദേഹത്തെ ഒഴിഞ്ഞുകിട്ടാനായി ഞാൻ കാത്തിരുന്നു. ആളൊഴിഞ്ഞപ്പോൾ റമളാനിലെ യാത്ര വേളയിൽ നോമ്പനുഷ്ഠിക്കുന്നതിനെ കുറിച്ച് ഞാനദ്ദേഹത്തോട് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: മക്കാവിജയവർഷം റമളാനിൽ ഞങ്ങൾ നബി(സ)യോടൊപ്പം യാത്ര ചെയ്യവെ നബി(സ)യും ഞങ്ങളും നോമ്പനുഷ്ഠിച്ചിരുന്നു. ആ വേളയിൽ ഇറങ്ങേണ്ട ഒരു സ്ഥലത്തെത്തിയപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളുടെ ശത്രുവോട് അടുത്തിരിക്കുന്നതിനാൽ, നോമ്പൊഴിവാക്കലായിരിക്കും നിങ്ങൾക്ക് കൂടുതൽ ശക്തിപകരുക." ഞങ്ങളിൽ ചിലർ നോമ്പൊഴിവാക്കുകയും, ചിലർ അനുഷ്ഠിക്കുകയും ചെയ്തു. ഞങ്ങൾ യാത്ര തുടരുകയും, മറ്റൊരു സ്ഥലത്തിറങ്ങുകയും ചെയ്തപ്പോൾ നബി(സ) പറഞ്ഞു: "നിശ്ചയം നിങ്ങൾ നിങ്ങളുടെ ശത്രുവോടടുത്തിരിക്കുന്നതിനാൽ, നോമ്പൊഴിവാക്കലായിരിക്കും നിങ്ങൾക്ക് കൂടുതൽ ശക്തിപകരുക. അതുകൊണ്ട് നിങ്ങൾ നോമ്പൊഴിവാക്കുക." അത് റസൂൽ(സ)യുടെ ഉറച്ച തീരുമാനമായിരുന്നു. അബൂസഈദ്(റ) പറയുന്നു: നബി(സ)യോടൊപ്പം അതിനു മുമ്പും ശേഷവും ഞാൻ നോമ്പനുഷ്ഠിച്ചിട്ടുണ്ട്. (മു,ദ,തു,ന)', 'قَزَعَةَ قَالَ', 'ഖസഅത്ത്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 115, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: غَزَوْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَمَضَانَ غَزْوَتَيْنِ: يَوْمَ بَدْرٍ وَالْفَتْحِ، فَأَفْطَرْنَا فِيهِمَا. (ت)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): റമളാനിൽ റസൂൽ(സ)ക്കൊപ്പം ഞങ്ങൾ രണ്ട് യുദ്ധത്തിൽ പങ്കെടുത്തു; ബദ്ർ യുദ്ധത്തിലും മക്കാ വിജയദിനത്തിലും. അവ രണ്ടിലും ഞങ്ങൾ നോമ്പെടുത്തിരുന്നില്ല. (തു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 116, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنْ عَامِرِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْغَنِيمَةُ الْبَارِدَةُ الصَّوْمُ فِي الشِّتَاءِ". مُرْسَلٌ. (ت)', 'ആമിറുബ്നുമസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "തണുത്ത (പ്രയാസരഹിതമായ) യുദ്ധമുതൽ ശൈത്യകാലത്തെ നോമ്പാകുന്നു." (തു)', 'عَامِرِ بْنِ مَسْعُودٍ', 'ആമിറുബ്നുമസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 116, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أُمِّ سُلَيْمٍ فَأَتَتْهُ بِتَمْرٍ وَسَمْنٍ، قَالَ: "أَعِيدُوا سَمْنَكُمْ فِي سِقَائِهِ وَتَمْرَكُمْ فِي وِعَائِهِ فَإِنِّي صَائِمٌ". ثُمَّ قَامَ إِلَى نَاحِيَةٍ مِنَ الْبَيْتِ فَصَلَّى غَيْرَ الْمَكْتُوبَةِ فَدَعَا لِأُمِّ سُلَيْمٍ وَأَهْلِ بَيْتِهَا، فَقَالَتْ أُمُّ سُلَيْمٍ: يَا رَسُولَ اللَّهِ إِنَّ لِي خُوَيْصَّةً، قَالَ: "مَا هِيَ؟" قَالَتْ: خَادِمُكَ أَنَسٌ، فَمَا تَرَكَ خَيْرَ آخِرَةٍ وَلَا دُنْيَا إِلَّا دَعَا لِي بِهِ: "اللَّهُمَّ ارْزُقْهُ مَالًا وَوَلَدًا وَبَارِكْ لَهُ فِيهِ". فَإِنِّي لَمِنْ أَكْثَرِ الْأَنْصَارِ مَالًا. وَحَدَّثَتْنِي ابْنَتِي أُمَيْنَةُ أَنَّهُ دُفِنَ لِصُلْبِي مَقْدَمَ حَجَّاجٍ الْبَصْرَةَ بِضْعٌ وَعِشْرُونَ وَمِائَةٌ. (خ)', 'അനസ്(റ): നബി(സ) ഉമ്മുസുലൈം(റ)യുടെ അടുത്ത് ചെന്നു. ഉമ്മുസുലൈം(റ) അൽപം കാരക്കയും നെയ്യും റസൂൽ(സ)ക്ക് കൊണ്ടുവന്ന് കൊടുത്തു. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ കൊണ്ടുവന്ന നെയ്യും കാരക്കയും അവയുടെ പാത്രങ്ങളിൽതന്നെ വെക്കുക. കാരണം, ഞാൻ നോമ്പുകാരനാണ്." പിന്നീട് റസൂൽ(സ) മുറിയുടെ ഒരു ഭാഗത്ത് നിന്ന് സുന്നത്ത് നിസ്കാരം നിർവ്വഹിച്ചു. ശേഷം ഉമ്മുസുലൈം(റ)ക്കും കുടുംബത്തിനും വേണ്ടി പ്രാർത്ഥിച്ചു. അപ്പോൾ ഉമ്മുസുലൈം(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്കൊരു കുഞ്ഞുമോനുണ്ട്. റസൂൽ(സ) ചോദിച്ചു: "ആരാണത്?" ഉമ്മുസുലൈം(റ) പറഞ്ഞു: അങ്ങയുടെ സേവകൻ അനസ്. ഭൗതികവും പാരത്രികവുമായ എല്ലാ ഗുണങ്ങളെക്കൊണ്ടും റസൂൽ(സ) എനിക്കുവേണ്ടി പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ, അനസിനു നീ സമ്പത്തും സന്താനവും നൽകേണമേ! അവയിൽ ബറകതും നൽകേണമേ!" അക്കാരണത്താൽ ഞാൻ അൻസ്വാരികളിൽ ഏറ്റവും വലിയ സമ്പന്നരിൽപ്പെട്ടവനായി. ഹജ്ജാജ് ബസ്വറയിലെത്തിയപ്പോഴേക്കും എന്റെ സന്താന പരമ്പരയിൽ പെട്ട നൂറ്റിഇരുപതിലധികം പേർ മരിച്ചുപോയിരുന്നെന്ന് എന്റെ മകൾ ഉമൈന എന്നോടു പറഞ്ഞു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 116, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَرْسَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَدَاةَ عَاشُورَاءَ إِلَى قُرَى الْأَنْصَارِ: "مَنْ أَصْبَحَ مُفْطِرًا فَلْيُتِمَّ بَقِيَّةَ يَوْمِهِ، وَمَنْ أَصْبَحَ صَائِمًا فَلْيَصُمْ". قَالَتْ: فَكُنَّا نَصُومُهُ بَعْدُ وَنُصَوِّمُ صِبْيَانَنَا وَنَجْعَلُ لَهُمُ اللُّعْبَةَ مِنَ الْعِهْنِ فَإِذَا بَكَى أَحَدُهُمْ عَلَى الطَّعَامِ أَعْطَيْنَاهُ ذَلِكَ حَتَّى يَكُونَ عِنْدَ الْإِفْطَارِ. (خ)', 'മുഅവ്വിദിന്റെ മകൾ റുബയ്യിഅ്(റ): ആശൂറാഇന്റെ പ്രഭാതത്തിൽ അൻസ്വാരീ ഗ്രാമങ്ങളിലേക്ക് റസൂൽ(സ) ഇപ്രകാരം സന്ദേശമയച്ചു: "നോമ്പില്ലാത്തവൻ നോമ്പുകാരനായി ദിവസം പൂർത്തിയാക്കട്ടെ. നോമ്പുകാരനായി വല്ലവനും പ്രഭാതത്തിൽ എഴുന്നേറ്റാൽ അവൻ ആ നില തുടർന്നുപോവുകയും ചെയ്യട്ടെ." അതിനു ശേഷം ഞങ്ങൾ ആശൂറാ നോമ്പ് അനുഷ്ഠിക്കുകയും ഞങ്ങളുടെ കുട്ടികളെക്കൊണ്ട് അനുഷ്ഠിപ്പിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. അവർക്കു രോമം കൊണ്ട് കളിപ്പാട്ടങ്ങളുണ്ടാക്കിക്കൊടുക്കും. വല്ല കുട്ടിയും ഭക്ഷണത്തിന് കരഞ്ഞാൽ നോമ്പു തുറക്കാൻ സമയമാകും വരെ കളിപ്പാട്ടങ്ങൾ കൊടുത്ത് ഞങ്ങളവരെ കളിപ്പിക്കും. (ബു)', 'الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ', 'മുഅവ്വിദിന്റെ മകൾ റുബയ്യിഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 117, 117, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَتِ امْرَأَةٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ عِنْدَهُ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ زَوْجِي صَفْوَانَ بْنَ الْمُعَطَّلِ يَضْرِبُنِي إِذَا صَلَّيْتُ وَيُفَطِّرُنِي إِذَا صُمْتُ، وَلَا يُصَلِّي صَلَاةَ الْفَجْرِ حَتَّى تَطْلُعَ الشَّمْسُ؟ قَالَ: وَصَفْوَانُ عِنْدَهُ، قَالَ، فَسَأَلَهُ عَمَّا قَالَتْ: فَقَالَ: يَا رَسُولَ اللَّهِ، أَمَّا قَوْلُهَا: يَضْرِبُنِي إِذَا صَلَّيْتُ، فَإِنَّهَا تَقْرَأُ بِسُورَتَيْنِ وَقَدْ نَهَيْتُهَا. قَالَ: فَقَالَ: "لَوْ كَانَتْ سُورَةً وَاحِدَةً لَكَفَتِ النَّاسَ". وَأَمَّا قَوْلُهَا: يُفَطِّرُنِي، فَإِنَّهَا تَنْطَلِقُ فَتَصُومُ وَأَنَا رَجُلٌ شَابٌّ فَلَا أَصْبِرُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ: "لَا تَصُومُ امْرَأَةٌ إِلَّا بِإِذْنِ زَوْجِهَا". وَأَمَّا قَوْلُهَا: إِنِّي لَا أُصَلِّي حَتَّى تَطْلُعَ الشَّمْسُ، فَإِنَّا أَهْلُ بَيْتٍ قَدْ عُرِفَ لَنَا ذَاكَ، لَا نَكَادُ نَسْتَيْقِظُ حَتَّى تَطْلُعَ الشَّمْسُ. قَالَ: "فَإِذَا اسْتَيْقَظْتَ فَصَلِّ". (د)', 'അബൂസഈദ്(റ): ഒരു സ്ത്രീ പ്രവാചകസന്നിധിയിലെത്തി. ഞങ്ങളും അവിടെയുണ്ടായിരുന്നു. സ്ത്രീ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ ഭർത്താവ് സ്വഫ്വാനുബ്നുൽ മുഅഥൽ(റ) ഞാൻ നിസ്കരിച്ചാൽ എന്നെ അടിക്കുന്നു. ഞാൻ നോമ്പനുഷ്ഠിച്ചാൽ എന്നെ നോമ്പു മുറിപ്പിക്കുന്നു. സൂര്യനുദിക്കുംവരെ അദ്ദേഹം സുബ്ഹിനിസ്കാരം നിർവ്വഹിക്കാറുമില്ല. നിവേദകൻ പറയുന്നു: സ്വഫ്വാൻ പ്രവാചകരുടെ സമീപമുണ്ട്. സ്ത്രീയുടെ പരാതിയെക്കുറിച്ച് സ്വഫ്വാൻ(റ)വിനോടു റസൂൽ(സ) അന്വേഷിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, നിസ്കാരം നിർവ്വഹിച്ചാൽ ഞാൻ അടിക്കാൻ കാരണം, അവൾ നിസ്കാരത്തിൽ രണ്ടു സൂറത് ഓതുന്നതിനാലാണ്. അങ്ങനെ ഓതുന്നത് ഞാൻ വിലക്കിയതാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഒരു സൂറത് തന്നെ ജനങ്ങൾക്കു ധാരാളമാണ്." അവളുടെ നോമ്പു മുറിപ്പിക്കുന്നുവെന്ന് അവൾ പറയാൻ കാരണമിതാണ്; അവൾ പോയി നോമ്പു പിടിക്കുന്നു, ഞാനൊരു യുവാവല്ലേ. എനിക്ക് ക്ഷമിക്കാൻ കഴിയുന്നില്ല. തദവസരത്തിൽ റസൂൽ(സ) പറഞ്ഞു: "ഒരു സ്ത്രീയും ഭർതൃസമ്മതമില്ലാതെ നോമ്പനുഷ്ഠിക്കരുത്." സൂര്യനുദിക്കുവോളം ഞാൻ സുബ്ഹിനിസ്കാരം നിർവ്വഹിക്കില്ല എന്ന് പറഞ്ഞല്ലോ, അത് ഞങ്ങളുടെ പതിവ് അങ്ങനെയാണ്. സൂര്യനുദിക്കും വരെ ഞങ്ങൾ എഴുന്നേൽക്കാറില്ല. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ നീ ഉറക്കിൽനിന്നെണീറ്റാൽ നിസ്കരിക്കുക." (ദ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 117, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَصُومُ الْمَرْأَةُ وَبَعْلُهَا شَاهِدٌ إِلَّا بِإِذْنِهِ، غَيْرَ رَمَضَانَ. وَلَا تَأْذَنُ فِي بَيْتِهِ وَهُوَ شَاهِدٌ إِلَّا بِإِذْنِهِ". (ق,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഭർത്താവ് സ്ഥലത്തുണ്ടായിരിക്കെ ഒരു പെണ്ണും, റമളാൻ മാസത്തിലല്ലാതെ അവന്റെ സമ്മതമില്ലാതെ നോമ്പനുഷ്ഠിക്കരുത്. അവനുണ്ടായിരിക്കേ അവന്റെ സമ്മതപ്രകാരമല്ലാതെ വീട്ടിലേക്ക് ഒരാൾക്കും പ്രവേശനാനുവാദം നൽകുകയുമരുത്." (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ لَمْ يَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِهِ فَلَيْسَ لِلَّهِ حَاجَةٌ بِأَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ". حَسَنٌ صَحِيحٌ. (خ,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അനാവശ്യവാക്കുകളും അനാവശ്യ പ്രവൃത്തികളും ഒഴിവാക്കാത്ത നോമ്പുകാരൻ അന്ന-പാനീയങ്ങൾ ഒഴിവാക്കുന്നതിൽ അല്ലാഹുവിന് യാതൊരു താൽപര്യവുമില്ല." (ബു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "رُبَّ صَائِمٍ لَيْسَ لَهُ مِنْ صِيَامِهِ إِلَّا الْجُوعُ، وَرُبَّ قَائِمٍ لَيْسَ لَهُ مِنْ قِيَامِهِ إِلَّا السَّهَرُ". [ز: في إسناده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എത്ര നോമ്പുകാരുണ്ട്! അവരുടെ നോമ്പ് കൊണ്ട് അവർക്ക് വിശപ്പല്ലാതെ മറ്റൊന്നും തന്നെയില്ല. എത്ര നിസ്കാരക്കാരുണ്ട്! അവരുടെ രാത്രി നിസ്കാരം മൂലം അവർ ഉറക്കൊഴിച്ചതല്ലാതെ ഒരു ഫലവുമില്ല." (പരമ്പരയിൽ ദുർബലനുണ്ട്.) (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'പരമ്പരയിൽ ദുർബലനുണ്ട്.', 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلَا يَرْفُثْ وَلَا يَجْهَلْ، وَإِنْ جَهِلَ عَلَيْهِ أَحَدٌ فَلْيَقُلْ: إِنِّي امْرُؤٌ صَائِمٌ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നോമ്പുദിനത്തിൽ നിങ്ങളിലാരും തെറ്റായ പ്രവൃത്തികൾ ചെയ്യുകയോ അനാവശ്യ വാക്കുകൾ പറയുകയോ അരുത്. ഇനി വല്ലവനും അവനോട് അനാവശ്യം പറഞ്ഞാൽ ഞാൻ നോമ്പനുഷ്ഠിച്ച മനുഷ്യനാണെന്ന് പറഞ്ഞു കൊള്ളട്ടെ." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا نَحْنُ جُلُوسٌ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَهُ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ هَلَكْتُ، قَالَ: "مَا لَكَ؟". قَالَ: وَقَعْتُ عَلَى امْرَأَتِي فِي رَمَضَانَ وَأَنَا صَائِمٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ تَجِدُ رَقَبَةً تَعْتِقُهَا؟". قَالَ: لَا، قَالَ: "فَهَلْ تَسْتَطِيعُ أَنْ تَصُومَ شَهْرَيْنِ مُتَتَابِعَيْنِ؟". قَالَ: لَا، قَالَ: "فَهَلْ تَجِدُ إِطْعَامَ سِتِّينَ مِسْكِينًا؟". قَالَ: لَا، قَالَ: فَمَكَثَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَيْنَا نَحْنُ عَلي ذَلِكَ أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَرَقٍ فِيهِ تَمْرٌ، وَالْعَرَقُ: الْمِكْتَلُ، قَالَ: "أَيْنَ السَّائِلُ؟". فَقَالَ: أَنَا، قَالَ: "خُذْ هَذَا فَتَصَدَّقْ بِهِ". فَقَالَ لَهُ الرَّجُلُ: أَعَلَي أَفْقَرَ مِنِّي يَا رَسُولَ اللَّهِ؟ فَوَاللهِ مَا بَيْنَ لَابَتَيْهَا، يُرِيدُ الْحَرَّتَيْنِ، أَهْلُ بَيْتٍ أَفْقَرُ مِنْ أَهْلِ بَيْتِي، فَضَحِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَدَتْ أَنْيَابُهُ، ثُمَّ قَالَ: "أَطْعِمْهُ أَهْلَكَ". (ق,د,ت)', 'അബൂഹുറൈറ(റ): ഒരിക്കൽ ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരു മനുഷ്യൻ നബി(സ)യുടെ അടുക്കൽ വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ നശിച്ചു. തിരുമേനി(സ) ചോദിച്ചു: "നിനക്കെന്തുപറ്റി?" അദ്ദേഹം പറഞ്ഞു: ഞാൻ റമളാനിൽ (പകലിൽ) എന്റെ ഭാര്യയുമായി ബന്ധപ്പെട്ടു. തിരുമേനി(സ) ചോദിച്ചു: "നിനക്ക് ഒരു അടിമയെ മോചിപ്പിക്കാൻ സാധിക്കുമോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. തിരുമേനി(സ) ചോദിച്ചു: "തുടർച്ചയായി രണ്ടുമാസം നോമ്പ് അനുഷ്ഠിക്കുവാൻ നിനക്ക് സാധിക്കുമോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. തിരുമേനി(സ) ചോദിച്ചു: "അറുപത് ദരിദ്രന്മാർക്ക് ആഹാരം കൊടുക്കുവാൻ നിനക്ക് സാധിക്കുമോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. എന്നിട്ട് നിശബ്ദനായി പ്രവാചകരുടെ സമീപം നിന്നു. ഈ സമയം ഒരു കുട്ട കാരക്ക അവിടത്തെ സന്നിധിയിൽ കൊണ്ടുവരപ്പെട്ടു. "ആ ചോദ്യക്കാരൻ എവിടെ?" റസൂൽ(സ) അന്വേഷിച്ചു. ഞാൻ തന്നെ, ആഗതൻ പറഞ്ഞു. റസൂൽ(സ) പറഞ്ഞു: "നീ ഇതു കൊണ്ടുപോയി ദാനം ചെയ്യുക." ആഗതൻ പ്രവാചകർ(സ)യോട് ചോദിച്ചു: എന്നെക്കാൾ ദരിദ്രനായവന്നാണോ നൽകേണ്ടത്, പ്രവാചകരേ? അല്ലാഹുവാണ! ഈ മദീനയുടെ കറുത്ത രണ്ട് കൽപ്രദേശങ്ങൾക്കിടയിൽ (അതിർത്തിക്കുള്ളിൽ) ഞങ്ങളേക്കാൾ ദരിദ്രരായ ഒരു വീട്ടുകാരുമില്ല. റസൂൽ(സ) ഇതുകേട്ട് തന്റെ അണപ്പല്ലുകൾ വെളിവാകുംവിധം ചിരിക്കുകയും തുടർന്ന്, "നീ ഇതു കൊണ്ടുപോയി നിന്റെ വീട്ടുകാർക്കുതന്നെ കൊടുക്കുക" എന്ന് പറയുകയും ചെയ്തു. (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 118, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَتَى رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ فِي رَمَضَانَ، فَقَالَ: يَا رَسُولَ اللَّهِ، احْتَرَقْتُ، فَسَأَلَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا شَأْنُهُ؟ قَالَ: أَصَبْتُ أَهْلِي، قَالَ: "تَصَدَّقْ". قَالَ: وَاللَّهِ مَا لِي شَيْءٌ، وَلَا أَقْدِرُ عَلَيْهِ. قَالَ: "اجْلِسْ". فَجَلَسَ، فَبَيْنَمَا هُوَ عَلَى ذَلِكَ أَقْبَلَ رَجُلٌ يَسُوقُ حِمَارًا عَلَيْهِ طَعَامٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيْنَ الْمُحْتَرِقُ آنِفًا". فَقَامَ الرَّجُلُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَصَدَّقْ بِهَذَا". فَقَالَ: يَا رَسُولَ اللَّهِ، أَعَلَى غَيْرِنَا؟ فَوَاللَّهِ إِنَّا لَجِيَاعٌ، مَا لَنَا شَيْءٌ. قَالَ: "كُلُوهُ". وَفِي رِوَايَةٍ: فَأُتِيَ بِعَرَقٍ فِيهِ عِشْرُونَ صَاعًا. وَفِي رِوَايَةٍ: عَنِ الزُّهْرِيِّ، بِهَذَا الْحَدِيثِ بِمَعْنَاهُ، زَادَ: وَإِنَّمَا كَانَ هَذَا رُخْصَةً لَهُ خَاصَّةً، فَلَوْ أَنَّ رَجُلًا فَعَلَ ذَلِكَ– الْيَوْمَ– لَمْ يَكُنْ لَهُ بُدٌّ مِنَ التَّكْفِيرِ. وَفِي رِوَايَةٍ: أَنَّ رَجُلًا أَفْطَرَ فِي رَمَضَانَ، فَأَمَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُعْتِقَ رَقَبَةً، أَوْ يَصُومَ شَهْرَيْنِ مُتَتَابِعَيْنِ، أَوْ يُطْعِمَ سِتِّينَ مِسْكِينًا، قَالَ: لَا أَجِدُ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اجْلِسْ". فَأُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَرَقٍ فِيهِ تَمْرٌ، فَقَالَ: "خُذْ هَذَا فَتَصَدَّقْ بِهِ". فَقَالَ: يَا رَسُولَ اللَّهِ، مَا أَحَدٌ أَحْوَجُ مِنِّي. فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَدَتْ أَنْيَابُهُ وَقَالَ لَهُ: "كُلْهُ". وَفِي رِوَايَةٍ: "أَوْ تُعْتِقَ رَقَبَةً، أَوْ تَصُومَ شَهْرَيْنِ، أَوْ تُطْعِمَ سِتِّينَ مِسْكِينًا". وَفِي رِوَايَةٍ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَفْطَرَ فِي رَمَضَانَ، بِهَذَا الْحَدِيثِ، قَالَ: فَأُتِيَ بِعَرَقٍ فِيهِ تَمْرٌ قَدْرُ خَمْسَةَ عَشَرَ صَاعًا، وَقَالَ فِيهِ: "كُلْهُ أَنْتَ وَأَهْلُ بَيْتِكَ، وَصُمْ يَوْمًاوَاسْتَغْفِرِ اللَّهَ". (ق,د,ن)', 'ആഇശ(റ): റമളാനിൽ ഒരാൾ പള്ളിയിൽ വന്ന് പ്രവാചകരോട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ കത്തിക്കരിഞ്ഞുപോയിരിക്കുന്നു! എന്താണ് കാര്യമെന്ന് റസൂൽ(സ) അന്വേഷിച്ചു. ആഗതൻ പറഞ്ഞു: ഞാനെന്റെ ഭാര്യയുമായി ബന്ധപ്പെട്ടു നബിയേ. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ നീ വല്ലതും ദാനം ചെയ്യുക." അയാൾ പറഞ്ഞു: അല്ലാഹുവാണ! എന്റെ കയ്യിൽ ഒന്നുമില്ല. എനിക്കതിന്ന് കഴിയുകയുമില്ല. റസൂൽ(സ) അദ്ദേഹത്തോടിരിക്കാനാവശ്യപ്പെട്ടു. അയാൾ ഇരുന്നു. ആ അവസരം ഒരു മനുഷ്യൻ തന്റെ കഴുതപ്പുറത്ത് അൽപം ഭക്ഷണവുമായി വന്നു. റസൂൽ(സ) അന്വേഷിച്ചു: "എവിടെ ആ കത്തിക്കരിഞ്ഞ മനുഷ്യൻ?" അയാൾ എണീറ്റു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ ഇതു ദാനം ചെയ്യുക." അയാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ! മറ്റുള്ളവർക്കാണോ നൽകേണ്ടത്? അല്ലാഹുവാണ് സത്യം! ഞങ്ങൾ വളരെ പട്ടിണിയിലാണ്. ഞങ്ങളുടെ പക്കൽ ഒന്നുമില്ല. റസൂൽ(സ) അരുളി: "എങ്കിൽ നിങ്ങൾ തന്നെ ഭക്ഷിച്ചുകൊള്ളുക." മറ്റൊരു നിവേദനം: അപ്പോൾ ഒരു കുട്ടയിൽ ഇരുപത് സ്വാഅ് കാരക്ക കൊണ്ടുവരപ്പെട്ടു. മറ്റൊരു നിവേദനം: ഇമാം സുഹ്രീയിൽനിന്ന് ഇതേ ഹദീസിന്റെ ആശയം വന്നിട്ടുണ്ട്. അതിൽ കൂടുതലായി ഇപ്രകാരം കാണാം: നിശ്ചയം ഇത് അയാൾക്കുള്ള ഒരു പ്രത്യേകമായ ആനുകൂല്യമായിരുന്നു. ഇക്കാലത്ത് ആരെങ്കിലും അതു പ്രവർത്തിച്ചാൽ പ്രായശ്ചിത്തം (കഫ്ഫാറത്) അല്ലാതെ മറ്റൊരു മാർഗമില്ല. മറ്റൊരു നിവേദനം: ഒരു മനുഷ്യൻ റമളാനിൽ നോമ്പ് മുറിച്ചു. ഒരടിമയെ മോചിപ്പിക്കുവാൻ റസൂൽ(സ) അയാളോടു കൽപിച്ചു. അതിനു കഴിയില്ലെങ്കിൽ രണ്ടുമാസം തുടർച്ചയായി നോമ്പ് അനുഷ്ഠിക്കുവാനും അല്ലെങ്കിൽ പാവപ്പെട്ട അറുപതുപേർക്ക് ഭക്ഷണം നൽകാനും റസൂൽ(സ) അരുളി. എനിക്ക് കഴിയില്ലെന്ന് അയാൾ പ്രവാചകരെ അറിയിച്ചു. റസൂൽ(സ) അയാളോട് ഇരിക്കുവാനാവശ്യപ്പെട്ടു. അപ്പോൾ പ്രവാചകസന്നിധിയിൽ ഒരു കുട്ട കാരക്ക കൊണ്ടുവരപ്പെട്ടു. അതു ദാനം ചെയ്യുവാൻ റസൂൽ(സ) അയാളോട് കൽപിച്ചു. അയാൾ പറഞ്ഞു: എന്നെക്കാൾ അതിന് ആവശ്യമുള്ളവരുണ്ടാവില്ല. ഇതുകേട്ടു റസൂൽ(സ) അവിടത്തെ അണപ്പല്ലുകൾ വെളിവാകുമാർ ചിരിക്കുകയും അത് ഭക്ഷിച്ചുകൊള്ളാൻ അയാളോടു പറയുകയും ചെയ്തു. മറ്റൊരു നിവേദനം: "അല്ലെങ്കിൽ ഒരടിമയെ മോചിപ്പിക്കുക, അല്ലെങ്കിൽ രണ്ട് മാസം നോമ്പനുഷ്ഠിക്കുക, അതുമല്ലെങ്കിൽ പാവപ്പെട്ട അറുപത് പേർക്ക് ഭക്ഷണം നൽകുക." മറ്റൊരു നിവേദനം: റമളാനിൽ നോമ്പ്മുറിച്ച ഒരു വ്യക്തി റസൂൽ(സ)യുടെ സന്നിധിയിൽ വന്നു. പിന്നെ മേലുദ്ധരിച്ച അതേ ഹദീസ് തുടർന്നു പറയുന്നു: അപ്പോൾ ഒരു കുട്ടയിൽ പതിനഞ്ച് സ്വാഅ് കാരക്ക അവിടെ കൊണ്ടുവരപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "ഇത് നീയും നിന്റെ വീട്ടുകാരും ഭക്ഷിക്കുക. ഒരു ദിവസം നോമ്പനുഷ്ഠിക്കുകയും അല്ലാഹുവിനോടു പാപമോചനം തേടുകയും ചെയ്യുക." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن']::text[], array['ദ']::text[], null, null, 119, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=278), 1, 'وَفِي رِوَايَةٍ: فَأُتِيَ بِعَرَقٍ فِيهِ عِشْرُونَ صَاعًا.', 'മറ്റൊരു നിവേദനം: അപ്പോൾ ഒരു കുട്ടയിൽ ഇരുപത് സ്വാഅ് കാരക്ക കൊണ്ടുവരപ്പെട്ടു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=278), 2, 'وَفِي رِوَايَةٍ: عَنِ الزُّهْرِيِّ، بِهَذَا الْحَدِيثِ بِمَعْنَاهُ، زَادَ: وَإِنَّمَا كَانَ هَذَا رُخْصَةً لَهُ خَاصَّةً، فَلَوْ أَنَّ رَجُلًا فَعَلَ ذَلِكَ– الْيَوْمَ– لَمْ يَكُنْ لَهُ بُدٌّ مِنَ التَّكْفِيرِ.', 'മറ്റൊരു നിവേദനം: ഇമാം സുഹ്രീയിൽനിന്ന് ഇതേ ഹദീസിന്റെ ആശയം വന്നിട്ടുണ്ട്. അതിൽ കൂടുതലായി ഇപ്രകാരം കാണാം: നിശ്ചയം ഇത് അയാൾക്കുള്ള ഒരു പ്രത്യേകമായ ആനുകൂല്യമായിരുന്നു. ഇക്കാലത്ത് ആരെങ്കിലും അതു പ്രവർത്തിച്ചാൽ പ്രായശ്ചിത്തം (കഫ്ഫാറത്) അല്ലാതെ മറ്റൊരു മാർഗമില്ല.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=278), 3, 'وَفِي رِوَايَةٍ: أَنَّ رَجُلًا أَفْطَرَ فِي رَمَضَانَ، فَأَمَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُعْتِقَ رَقَبَةً، أَوْ يَصُومَ شَهْرَيْنِ مُتَتَابِعَيْنِ، أَوْ يُطْعِمَ سِتِّينَ مِسْكِينًا، قَالَ: لَا أَجِدُ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اجْلِسْ". فَأُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَرَقٍ فِيهِ تَمْرٌ، فَقَالَ: "خُذْ هَذَا فَتَصَدَّقْ بِهِ". فَقَالَ: يَا رَسُولَ اللَّهِ، مَا أَحَدٌ أَحْوَجُ مِنِّي. فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَدَتْ أَنْيَابُهُ وَقَالَ لَهُ: "كُلْهُ".', 'മറ്റൊരു നിവേദനം: ഒരു മനുഷ്യൻ റമളാനിൽ നോമ്പ് മുറിച്ചു. ഒരടിമയെ മോചിപ്പിക്കുവാൻ റസൂൽ(സ) അയാളോടു കൽപിച്ചു. അതിനു കഴിയില്ലെങ്കിൽ രണ്ടുമാസം തുടർച്ചയായി നോമ്പ് അനുഷ്ഠിക്കുവാനും അല്ലെങ്കിൽ പാവപ്പെട്ട അറുപതുപേർക്ക് ഭക്ഷണം നൽകാനും റസൂൽ(സ) അരുളി. എനിക്ക് കഴിയില്ലെന്ന് അയാൾ പ്രവാചകരെ അറിയിച്ചു. റസൂൽ(സ) അയാളോട് ഇരിക്കുവാനാവശ്യപ്പെട്ടു. അപ്പോൾ പ്രവാചകസന്നിധിയിൽ ഒരു കുട്ട കാരക്ക കൊണ്ടുവരപ്പെട്ടു. അതു ദാനം ചെയ്യുവാൻ റസൂൽ(സ) അയാളോട് കൽപിച്ചു. അയാൾ പറഞ്ഞു: എന്നെക്കാൾ അതിന് ആവശ്യമുള്ളവരുണ്ടാവില്ല. ഇതുകേട്ടു റസൂൽ(സ) അവിടത്തെ അണപ്പല്ലുകൾ വെളിവാകുമാർ ചിരിക്കുകയും അത് ഭക്ഷിച്ചുകൊള്ളാൻ അയാളോടു പറയുകയും ചെയ്തു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=278), 4, 'وَفِي رِوَايَةٍ: "أَوْ تُعْتِقَ رَقَبَةً، أَوْ تَصُومَ شَهْرَيْنِ، أَوْ تُطْعِمَ سِتِّينَ مِسْكِينًا".', 'മറ്റൊരു നിവേദനം: "അല്ലെങ്കിൽ ഒരടിമയെ മോചിപ്പിക്കുക, അല്ലെങ്കിൽ രണ്ട് മാസം നോമ്പനുഷ്ഠിക്കുക, അതുമല്ലെങ്കിൽ പാവപ്പെട്ട അറുപത് പേർക്ക് ഭക്ഷണം നൽകുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=278), 5, 'وَفِي رِوَايَةٍ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَفْطَرَ فِي رَمَضَانَ، بِهَذَا الْحَدِيثِ، قَالَ: فَأُتِيَ بِعَرَقٍ فِيهِ تَمْرٌ قَدْرُ خَمْسَةَ عَشَرَ صَاعًا، وَقَالَ فِيهِ: "كُلْهُ أَنْتَ وَأَهْلُ بَيْتِكَ، وَصُمْ يَوْمًاوَاسْتَغْفِرِ اللَّهَ". (ق,د,ن)', 'മറ്റൊരു നിവേദനം: റമളാനിൽ നോമ്പ്മുറിച്ച ഒരു വ്യക്തി റസൂൽ(സ)യുടെ സന്നിധിയിൽ വന്നു. പിന്നെ മേലുദ്ധരിച്ച അതേ ഹദീസ് തുടർന്നു പറയുന്നു: അപ്പോൾ ഒരു കുട്ടയിൽ പതിനഞ്ച് സ്വാഅ് കാരക്ക അവിടെ കൊണ്ടുവരപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "ഇത് നീയും നിന്റെ വീട്ടുകാരും ഭക്ഷിക്കുക. ഒരു ദിവസം നോമ്പനുഷ്ഠിക്കുകയും അല്ലാഹുവിനോടു പാപമോചനം തേടുകയും ചെയ്യുക." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: {وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ}. فَكَانَ مَنْ شَاءَ مِنْهُمْ أَنْ يَفْتَدِيَ بِطَعَامِ مِسْكِينٍ افْتَدَى، وَتَمَّ لَهُ صَوْمُهُ، فَقَالَ: {فَمَنْ تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَهُ وَأَنْ تَصُومُوا خَيْرٌ لَكُمْ} وَقَالَ: {فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ} [البقرة:١٨٤] (خ,د,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ''നോമ്പിന് സാധിക്കുന്നവർക്ക് അതിനുപകരമായി ഒരു പാവപ്പെട്ടവനുള്ള ഭക്ഷണം പ്രായശ്ചിത്തമായി നൽകേണ്ടതാണ്.'' (അൽബഖറ:183) എന്ന സൂക്തം ഇറങ്ങിയ സന്ദർഭം സഹാബാക്കളിൽ നോമ്പിനുപകരം പാവപ്പെട്ടവന് ഭക്ഷണംനൽകി പ്രായശ്ചിത്തം ചെയ്യാൻ ഉദ്ദേശിച്ചവർ അതു ചെയ്തു. അതോടെ അവരുടെ നോമ്പ് പൂർണമായിരുന്നു. ശേഷം ഇബ്നുഅബ്ബാസ്(റ) ഈ സൂക്തം ഓതി: ''എന്നാൽ ആരെങ്കിലും സ്വയംസന്നദ്ധനായി കൂടുതൽ നന്മ ചെയ്താൽ അതവനു ഗുണകരമാകുന്നു, നിങ്ങൾ നോമ്പനുഷ്ഠിക്കലാണ് നിങ്ങൾക്കേറ്റവുമുത്തമം.'' ഇബ്നുഅബ്ബാസ്(റ) തുടർന്നു: ''അതുകൊണ്ട് നിങ്ങളിൽ ആർ ആ മാസത്തിൽ സന്നിഹിതരാണോ അവർ ആ മാസം വ്രതമനുഷ്ഠിക്കേണ്ടതാണ്. ആരെങ്കിലും രോഗിയാവുകയോ യാത്രയിലാവുകയോ ചെയ്താൽ പകരം അത്രയും എണ്ണം നോമ്പെടുക്കേണ്ടതാണ്.'' (അൽബഖറ: 184) (ബു,ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], 'البقرة:١٨٤', null, 120, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَفْطَرَ يَوْمًا مِنْ رَمَضَانَ، مِنْ غَيْرِ رُخْصَةٍ، لَمْ يُجْزِهِ صِيَامُ الدَّهْرِ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "റമളാനിലെ ഒരു നോമ്പ് ഒരു കാരണവുമില്ലാതെ ആരെങ്കിലും മുറിച്ചാൽ കാലം മുഴുവൻ നോമ്പനുഷ്ഠിച്ചാലും അതിന് പകരമാവുകയില്ല." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 120, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أُثْبِتَتْ لِلْحُبْلَى وَالْمُرْضِعِ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): മേൽസൂക്തം ഗർഭിണികൾക്കും മുലയൂട്ടുന്ന സ്ത്രീകൾക്കുമുള്ള ആനുകൂല്യമാണ്. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 121, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: {وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ} قَالَ: كَانَتْ رُخْصَةً لِلشَّيْخِ الْكَبِيرِ وَالْمَرْأَةِ الْكَبِيرَةِ، وَهُمَا يُطِيقَانِ الصِّيَامَ: أَنْ يُفْطِرَا وَيُطْعِمَا مَكَانَ كُلِّ يَوْمٍ مِسْكِينًا، وَالْحُبْلَى وَالْمُرْضِعُ إِذَا خَافَتَا- يَعْنِي عَلَى أَوْلَادِهِمَا- أَفْطَرَتَا وَأَطْعَمَتَا. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''നോമ്പനുഷ്ഠിക്കാൻ സാധിക്കുന്നവർക്ക് അതിനുപകരമായി ഒരു പാവപ്പെട്ടവനു ഭക്ഷണം പ്രായശ്ചിത്തമായി നൽകേണ്ടതാണ്'' എന്ന സൂക്തത്തിലെ ആനുകൂല്യം പ്രായംചെന്ന വൃദ്ധന്മാർക്കും സ്ത്രീകൾക്കും ഉള്ളതാണ്. അവർക്കു നോമ്പ് അനുഷ്ഠിക്കാൻ കഴിയുമ്പോൾ തന്നെ നോമ്പു മുറിക്കാം. ഓരോ ദിവസത്തിനും പകരമായി അവർ ഒരു പാവപ്പെട്ടവന്ന് ഭക്ഷണം നൽകണം. ഗർഭിണിയും മുലയൂട്ടുന്ന സ്ത്രീയും വല്ല അപകടവും (നോമ്പ് മൂലം കുട്ടികളുടെ മേൽ ബാധിക്കാവുന്ന) ഭയന്നാൽ അവർക്കും നോമ്പ് മുറിക്കാം; ഭക്ഷണം നൽകിയാൽ മതി. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 121, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فِي قَوْلِهِ عَزَّ وَجَلَّ: {وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ} يُطِيقُونَهُ: يُكَلَّفُونَهُ. {فِدْيَةٌ طَعَامُ مِسْكِينٍ} وَاحِدٍ {فَمَنْ تَطَوَّعَ خَيْرًا} طَعَامُ مِسْكِينٍ آخَرَ، لَيْسَتْ بِمَنْسُوخَةٍ. {فَهُوَ خَيْرٌ لَهُ وَأَنْ تَصُومُوا خَيْرٌ لَكُمْ} لَا يُرَخَّصُ فِي هَذَا إِلَّا لِلَّذِي لَا يُطِيقُ الصِّيَامَ، أَوْ مَرِيضٍ لَا يُشْفَى. (ن)', 'മേൽസൂക്തത്തിന്റെ വിശദീകരണത്തിൽ ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ''യുത്വീഖൂനഹു'' എന്നാൽ ''പ്രയാസപ്പെടുക'' എന്നാണുദ്ദേശ്യം. ''മിസ്കീൻ'' എന്നതുകൊണ്ട് ''ഒരു പാവപ്പെട്ടവൻ'' എന്നാണ് വിവക്ഷ. ''സ്വയം സന്നദ്ധനായി കൂടുതൽ നന്മ ചെയ്യാൻ ഉദ്ദേശിച്ചാൽ'' എന്നതുകൊണ്ട് മറ്റൊരു പാവപ്പെട്ടവനും കൂടി ഭക്ഷണം നൽകുക എന്നാണുദ്ദേശ്യം. ആ സൂക്തം ദുർബലമാക്കപ്പെട്ടിട്ടില്ല. എന്നാൽ, ''നിങ്ങൾ നോമ്പനുഷ്ഠിക്കലാണ് നിങ്ങൾക്കു കൂടുതൽ ഗുണകരം''. ഇതിൽ നോമ്പനുഷ്ഠിക്കാൻ കഴിയാത്തവർക്കും മാറാരോഗികൾക്കുമല്ലാതെ ഈ ആനുകൂല്യം ബാധകമല്ല. (ന)', 'ابْنِ عَبَّاسٍ', 'മേൽസൂക്തത്തിന്റെ വിശദീകരണത്തിൽ ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 121, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَنَا وَحَفْصَةُ صَائِمَتَيْنِ، فَعُرِضَ لَنَا طَعَامٌ اشْتَهَيْنَاهُ، فَأَكَلْنَا مِنْهُ. فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَدَرَتْنِي إِلَيْهِ حَفْصَةُ، وَكَانَتِ ابْنَةَ أَبِيهَا، فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّا كُنَّا صَائِمَتَيْنِ، فَعُرِضَ لَنَا طَعَامٌ اشْتَهَيْنَاهُ فَأَكَلْنَا مِنْهُ؟ قَالَ: "اقْضِيَا يَوْمًا آخَرَ مَكَانَهُ". (د,ت)', 'ആഇശ(റ): ഞാനും ഹഫ്സ(സ)യും നോമ്പുകാരായിരുന്നു. അപ്പോൾ ഞങ്ങൾക്കിഷ്ടപ്പെട്ട ഒരു ഭക്ഷണം ഞങ്ങൾക്ക് കൊണ്ടുവരപ്പെട്ടു, അങ്ങനെ ഞങ്ങളതിൽനിന്നു ഭക്ഷിച്ചു. അപ്പോൾ റസൂൽ(സ) അവിടെ വന്നു, ഹഫ്സ എന്റെ മുമ്പേപോയി പ്രവാചകർ(സ)യോട് ഇക്കാര്യം അറിയിച്ചു. ഹഫ്സ(റ) പിതാവിന്റെ മകളായിരുന്നു. (തന്റെ പിതാവായ ഉമർ(റ)വിന്റെ അതേ സ്വഭാവക്കാരിയായിരുന്നു എന്നർത്ഥം) ഹഫ്സ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ ഇരുവരും നോമ്പുകാരായിരുന്നു. അങ്ങനെയിരിക്കെ ഞങ്ങൾക്കിഷ്ടപ്പെട്ട ഭക്ഷണം ലഭിച്ചപ്പോൾ ഞങ്ങൾ അതിൽനിന്നു ഭക്ഷിച്ചു. ഞങ്ങളെന്ത് ചെയ്യണം? റസൂൽ(സ) പറഞ്ഞു: "അതിന് പകരമായി നിങ്ങൾ മറ്റൊരു ദിവസം ഖളാഅ് വീട്ടുക." (ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 121, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا كُنْتُ أَقْضِي مَا يَكُونُ عَلَيَّ مِنْ رَمَضَانَ إِلَّا فِي شَعْبَانَ، حَتَّى تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ) വഫാതാകും വരെ, എനിക്ക് റമളാനിൽ ഒഴിവായ നോമ്പുകൾ അടുത്ത ശഅ്ബാനിലല്ലാതെ ഞാൻ വീട്ടാറുണ്ടായിരുന്നില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 122, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنَّا نَحِيضُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيَأْمُرُنَا بِقَضَاءِ الصَّوْمِ. (ت,جه)', 'ആഇശ(റ): നബി(സ)യോടൊപ്പം കഴിയവെ ഞങ്ങൾക്ക് ആർത്തവമുണ്ടാവുകയും നോമ്പു ഖളാഅ് വീട്ടാൻ ഞങ്ങളോട് നബി(സ) കൽപ്പിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 122, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 287, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ إِنَّ أُمِّي مَاتَتْ وَعَلَيْهَا صَوْمُ شَهْرٍ أَفَأَقْضِيهِ عَنْهَا؟ قَالَ: "نَعَمْ، فَدَيْنُ اللَّهِ أَحَقُّ أَنْ يُقْضَى". (ق,د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ പ്രവാചകസവിധത്തിൽ വന്നു പറഞ്ഞു: പ്രവാചകരേ, എന്റെ മാതാവ് മരണപ്പെട്ടു, അവർക്കു ഒരു മാസത്തെ നോമ്പു ഖളാഅ് വീട്ടാനുണ്ട്. ഉമ്മയുടെ നോമ്പ് അവർക്കുവേണ്ടി ഞാൻ ഖളാഅ്വീട്ടട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ, അല്ലാഹുവിനുള്ള കടംതന്നെയാണു വീട്ടാൻ കൂടുതൽ അർഹമായത്." (ബു,മു,ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 122, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 288, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَا أَنَا جَالِسٌ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ أَتَتْهُ امْرَأَةٌ فَقَالَتْ: إِنِّي تَصَدَّقْتُ عَلَى أُمِّي بِجَارِيَةٍ، وَإِنَّهَا مَاتَتْ، قَالَ: فَقَالَ: "وَجَبَ أَجْرُكِ، وَرَدَّهَا عَلَيْكِ الْمِيرَاثُ". قَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّهُ كَانَ عَلَيْهَا صَوْمُ شَهْرٍ، أَفَأَصُومُ عَنْهَا؟ قَالَ: "صُومِي عَنْهَا". قَالَتْ: إِنَّهَا لَمْ تَحُجَّ قَطُّ، أَفَأَحُجُّ عَنْهَا؟ قَالَ: "حُجِّي عَنْهَا". (م)', 'ബുറൈദ(റ): ഞാൻ റസൂൽ(സ)യുടെ സമീപം ഇരിക്കെ ഒരു സ്ത്രീ വന്ന്പറഞ്ഞു: ഞാൻ എന്റെ മരണപ്പെട്ടുപോയ ഉമ്മക്ക് വേണ്ടി ഒരു അടിമസ്ത്രീയെ ദാനം ചെയ്തിരിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "ദാനം ചെയ്തതിന്റെ പ്രതിഫലം നിനക്ക് തീർച്ചയായും ലഭിക്കുന്നതാണ്. അതിനു പുറമേ നീ ദാനം ചെയ്ത ആ അടിമസ്ത്രീ നിനക്ക് അനന്തരാവകാശമായി ലഭിക്കുകയും ചെയ്തു." അവൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ! എന്റെ മാതാവിന് ഒരു മാസത്തെ നോമ്പു കടമുണ്ട്. അവർക്കുവേണ്ടി ഞാൻ അത് നോറ്റുവീട്ടട്ടെയോ? തിരുമേനി(സ) അരുളി: "നീ അതു നോറ്റുവീട്ടുക." അവർ ചോദിച്ചു. എന്റെ മാതാവ് ഹജ്ജ് ചെയ്തിട്ടേയില്ല. ഞാൻ അവർക്കുവേണ്ടി ഹജ്ജ് ചെയ്യട്ടെയോ? തിരുമേനി(സ) അരുളി: "നീ അവർക്കുവേണ്ടി ഹജ്ജ് ചെയ്തുകൊള്ളുക." (മു)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 122, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 289, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ مَاتَ وَعَلَيْهِ صِيَامٌ، صَامَ عَنْهُ وَلِيُّهُ". (ق)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: നോമ്പ് വീട്ടേണ്ട ബാധ്യതയുണ്ടായിരിക്കെ ഒരാൾ മരിച്ചാൽ അയാളുടെ വലിയ്യ് (സംരക്ഷകൻ) അത് വീട്ടണം." (ബു,മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 122, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 290, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِذَا مَرِضَ الرَّجُلُ فِي رَمَضَانَ، ثُمَّ مَاتَ وَلَمْ يَصُمْ، أُطْعِمَ عَنْهُ وَلَمْ يَكُنْ عَلَيْهِ قَضَاءٌ، وَإِنْ كَانَ عَلَيْهِ نَذْرٌ قَضَى عَنْهُ وَلِيُّهُ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റമളാനിൽ ഒരാൾ രോഗബാധിതനാകുകയും നോമ്പനുഷ്ഠിക്കാതെ അവൻ മരണപ്പെടുകയും ചെയ്താൽ അവനുവേണ്ടി ഭക്ഷണം ദാനം ചെയ്തുകൊള്ളട്ടെ. അവന്ന് ഖളാഅ് വീട്ടൽ നിർബന്ധമില്ല. അവൻ നേർച്ചയാക്കിയ വല്ല നോമ്പും ഉണ്ടെങ്കിൽ അവനുവേണ്ടി അവന്റെ വലിയ്യ് (ഉത്തരവാദപ്പെട്ടവൻ) അത് നോറ്റുകൊള്ളട്ടെ. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 123, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 291, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ مَاتَ وَعَلَيْهِ صِيَامُ شَهْرٍ فَلْيُطْعَمْ عَنْهُ مَكَانَ كُلِّ يَوْمٍ مِسْكِينًا". قَالَ التِّرْمِذِيُّ: وَالصَّحِيحُ عَنِ ابْنِ عُمَرَ مَوْقُوفٌ قَوْلُهُ. (ت,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ഒരു മാസത്തെ നോമ്പ് ബാധ്യതയുണ്ടായിരിക്കെ ഒരാൾ മരണപ്പെട്ടാൽ അവനുവേണ്ടി ഓരോ ദിവസത്തിനും പകരം ഓരോ പാവപ്പെട്ടവന് ഭക്ഷണം കൊടുത്തുകൊള്ളട്ടെ." തുർമുദി പറയുന്നു: ഈ ഹദീസിലെ വാക്യങ്ങൾ ഇബ്നുഉമർ(റ)വിൽ നിന്നും ''മൗഖൂഫ്'' ആണെന്നാണ് പ്രബലാഭിപ്രായം. (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 123, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 292, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَتِ امْرَأَةٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ أُخْتِي مَاتَتْ وَعَلَيْهَا صِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ؟ قَالَ: "أَرَأَيْتِ لَوْ كَانَ عَلَى أُخْتِكِ دَيْنٌ أَكُنْتِ تَقْضِينَهُ". قَالَتْ: بَلَى. قَالَ: "فَحَقُّ اللَّهِ أَحَقُّ". (ق,د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു സ്ത്രീ പ്രവാചകസന്നിധിയിൽ വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ സഹോദരി മരണപ്പെട്ടു. അവൾക്ക് തുടർച്ചയായ രണ്ടുമാസത്തെ നോമ്പു നോറ്റുവീട്ടാനുണ്ട്. റസൂൽ(സ) പ്രതിവചിച്ചു: "നിന്റെ സഹോദരിക്ക് കടമുണ്ടെങ്കിൽ നീ അതു വീട്ടുമോ?" അവൾ പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "എന്നാൽ അല്ലാഹുവുമായുള്ള ബാധ്യതയാണ് വീട്ടുവാൻ ഏറ്റവും അർഹമായത്." (ബു,മു,ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 123, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 293, 'عَنْ أَبِي سَلَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ عَائِشَةَ رَضِيَ اللهُ عَنْهَا تَقُولُ: كَانَ يَكُونُ عَلَيَّ الصَّوْمُ مِنْ رَمَضَانَ، فَمَا أَسْتَطِيعُ أَنْ أَقْضِيَهُ إِلَّا فِي شَعْبَانَ، الشُّغْلُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَوْ: بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م)', 'അബൂസലമ(റ): ആഇശ(റ) പറയുന്നത് ഞാൻ കേട്ടു: റമളാനിലെ നോമ്പുകളെനിക്ക് ഖളാഅ് വീട്ടാനുണ്ടാകുമായിരുന്നു. ശഅ്ബാനിലല്ലാതെ അതിനെ ഖളാഅ് വീട്ടാൻ എനിക്ക് സാധിക്കാറില്ല. തിരുമേനിക്കുവേണ്ടിയുള്ള ചില പ്രവർത്തികളിൽ മുഴുകിയതായിരുന്നു കാരണം. അല്ലെങ്കിൽ, റസൂൽ(സ)യുടെ കാരണത്താൽ. (മു)', 'أَبِي سَلَمَةَ', 'അബൂസലമ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 123, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 294, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَفْطَرَ يَوْمًا مِنْ رَمَضَانَ، مِنْ غَيْرِ رُخْصَةٍ وَلَا مَرَضٍ، لَمْ يَقْضِ عَنْهُ صَوْمُ الدَّهْرِ كُلِّهِ وَإِنْ صَامَهُ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ ഇളവില്ലാതെയും, രോഗമില്ലാതെയും റമളാനിൽ നോമ്പൊഴിവാക്കിയാൽ പിന്നീടുള്ള കാലം മുഴുവൻ നോമ്പനുഷ്ഠിച്ചാലും അതിന് പകരമായി വീടുകയില്ല." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 124, 124, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 295, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي أَكَلْتُ وَشَرِبْتُ نَاسِيًا وَأَنَا صَائِمٌ؟ فَقَالَ: "اللَّهُ أَطْعَمَكَ وَسَقَاكَ". (ق,د,ت,ن)', 'അബൂഹുറൈറ(റ): ഒരാൾ റസൂൽ(സ)യുടെ അടുത്ത് വന്നുപറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, നോമ്പുകാരനായി ഞാൻ മറന്ന് ഭക്ഷണപാനീയങ്ങൾ കഴിച്ചു. റസൂൽ(സ) പ്രതിവചിച്ചു: "നിന്നെ ഭക്ഷിപ്പിച്ചവനും കുടിപ്പിച്ചവനും അല്ലാഹുവാണ്." (ബു,മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 124, 124, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 296, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَكَلَ أَوْ شَرِبَ نَاسِيًا فَلَا يُفْطِرْ، فَإِنَّمَا هُوَ رِزْقٌ رَزَقَهُ اللَّهُ" حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മറന്ന് ഭക്ഷിക്കുകയും കുടിക്കുകയും ചെയ്തവൻ നോമ്പ് മുറിക്കരുത്. നിശ്ചയം അല്ലാഹു അവനു നൽകിയ ഭക്ഷണമാണത്." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 124, 124, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 297, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: أَفْطَرْنَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي يَوْمِ غَيْمٍ، ثُمَّ طَلَعَتِ الشَّمْسُ. قُلْتُ لِهِشَامٍ: أُمِرُوا بِالْقَضَاءِ؟ قَالَ: فَلَا بُدَّ مِنْ ذَلِكَ. (خ,د,جه)', 'അസ്മാഅ്(റ): തിരുദൂതർ(സ)യുടെ കാലത്ത് മേഘാവൃതമായ ഒരു ദിനത്തിൽ ഞങ്ങൾ നോമ്പു തുറന്നു. ശേഷം സൂര്യൻ വെളിവായി. ഞാൻ ഹിശാമിനോട് ചോദിച്ചു: ഖളാഅ് വീട്ടാൻ അവർ കൽപിക്കപ്പെട്ടുവോ? ഹിശാം(റ) പറഞ്ഞു: അതുകൊണ്ട് കുഴപ്പമില്ല. (ബു,ദ,ജ)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഅ്(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 124, 124, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 298, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَبِّلُ وَهُوَ صَائِمٌ، وَيُبَاشِرُ وَهُوَ صَائِمٌ، وَلَكِنَّهُ كَانَ أَمْلَكَ لِإِرْبِهِ. (ق,د,ن,جه)', 'ആഇശ(റ): നബി(സ) നോമ്പുകാരനായിരിക്കെ ചുംബിക്കുകയും തൊട്ടുരുമ്മുകയും ചെയ്യാറുണ്ട്. നബി(സ) ഏറ്റവും കൂടുതൽ വികാരം നിയന്ത്രിക്കാൻ കഴിയുന്നവരായിരുന്നു. (ബു,മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 124, 124, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 299, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَبِّلُ فِي شَهْرِ الصَّوْمِ. (م,د,ت,جه)', 'ആഇശ(റ): നോമ്പുമാസത്തിൽ നബി(സ) ചുംബിക്കാറുണ്ടായിരുന്നു. (മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 124, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 300, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَبِّلُنِي وَهُوَ صَائِمٌ وَأَنَا صَائِمَةٌ. (د)', 'ആഇശ(റ): ഞാനും നബി(സ)യും നോമ്പുകാരായിരിക്കെ നബി(സ) എന്നെ ചുംബിക്കാറുണ്ടായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 125, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 301, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ: هَشَشْتُ فَقَبَّلْتُ وَأَنَا صَائِمٌ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، صَنَعْتُ الْيَوْمَ أَمْرًا عَظِيمًا، قَبَّلْتُ وَأَنَا صَائِمٌ؟ قَالَ: "أَرَأَيْتَ لَوْ مَضْمَضْتَ مِنَ الْمَاءِ وَأَنْتَ صَائِمٌ". قُلْتُ: لَا بَأْسَ بِهِ. قَالَ: "فَمَهْ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഉമറുബ്നുൽ ഖത്വാബ്(റ) പറഞ്ഞു: ഞാൻ നോമ്പുകാരനായിരിക്കെ വളരെയധികം വികാരോന്മത്തനാവുകയും ചുംബിക്കുകയും ചെയ്തു. എന്നിട്ടു ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാനിന്നു വളരെ ഗൗരവമേറിയ ഒരു കാര്യം ചെയ്തു. നോമ്പുകാരനായിരിക്കെ ഞാൻ ചുംബിച്ചു. റസൂൽ(സ) ചോദിച്ചു: "നീ നോമ്പുകാരനായിരിക്കെ വായിൽ വെള്ളം കൊപ്ലിച്ചാൽ എങ്ങനെയാവും" ഞാൻ പറഞ്ഞു: ഒരു പ്രശ്നവുമില്ല. റസൂൽ(സ) പറഞ്ഞു: "എന്നാൽ ഇതും പ്രശ്നമല്ല" (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 125, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 302, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُقَبِّلُهَا وَهُوَ صَائِمٌ، وَيَمُصُّ لِسَانَهَا. (د)', 'ആഇശ(റ): നബി(സ) നോമ്പുകാരനായിരിക്കെ മഹതിയെ ചുംബിക്കുകയും മഹതിയുടെ നാവ് ഊമ്പുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 125, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 303, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُبَاشَرَةِ لِلصَّائِمِ فَرَخَّصَ لَهُ، وَأَتَاهُ آخَرُ فَسَأَلَهُ فَنَهَاهُ، فَإِذَا الَّذِي رَخَّصَ لَهُ شَيْخٌ، وَالَّذِي نَهَاهُ شَابٌّ. (د)', 'അബൂഹുറൈറ(റ): ഒരാൾ നബി(സ)യോട് നോമ്പുകാരൻ ഭാര്യയുമായി തൊട്ടുരുമ്മുന്നതിനെപ്പറ്റി ചോദിച്ചു. നബി(സ) അയാൾക്ക് ഇളവു ചെയ്തു. മറ്റൊരാൾ വന്ന് നബിയോട് അതേ കാര്യത്തെപ്പറ്റി ചോദിച്ചു. അപ്പോൾ നബി(സ) അദ്ദേഹത്തെ വിലക്കി. റസൂൽ(സ) ഇളവു ചെയ്ത മനുഷ്യൻ വയസ്സനും, വിലക്കിയവൻ യുവാവുമായിരുന്നു. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 125, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 304, 'عَنْ مَيْمُونَةَ بِنْتِ سَعْدٍ رَضِيَ اللهُ عَنْهَا- مَوْلَاةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- قَالَتْ: سُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ رَجُلٍ قَبَّلَ امْرَأَتَهُ وَهُمَا صَائِمَانِ؟ قَالَ: "قَدْ أَفْطَرَا". [ز: في سنده ضعيف ومجهول] (جه)', 'നബി(സ)യുടെ അടിമയായിരുന്ന മൈമൂനബിൻത് സഅദ്(റ): നോമ്പുകാരനായനിലയിൽ തന്റെ ഭാര്യയെ ചുംബിച്ച ഒരുത്തനെക്കുറിച്ച് നബി(സ) ചോദിക്കപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "രണ്ടാളും നോമ്പു മുറിച്ചു." (നിവേദക പരമ്പരയിൽ ദുർബ്ബലനും അജ്ഞാതനുമുണ്ട്) (ജ)', 'مَيْمُونَةَ بِنْتِ سَعْدٍ', 'നബി(സ)യുടെ അടിമയായിരുന്ന മൈമൂനബിൻത് സഅദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف ومجهول', 'നിവേദക പരമ്പരയിൽ ദുർബ്ബലനും അജ്ഞാതനുമുണ്ട്', 125, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 305, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: رُخِّصَ لِلْكَبِيرِ الصَّائِمِ فِي الْمُبَاشَرَةِ، وَكُرِهَ لِلشَّابِّ. [ز: في سنده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): വയസ്സായ നോമ്പുകാരന് ഭാര്യയുമായി തൊട്ടുരുമ്മുന്നതിൽ ഇളവ് നൽകപ്പെട്ടു. യുവാവിനു കറാഹത്താക്കപ്പെട്ടു. (പരമ്പരയിൽ ദുർബലനുണ്ട്) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', 'പരമ്പരയിൽ ദുർബലനുണ്ട്', 125, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 306, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ أَصْحَابُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ الرَّجُلُ صَائِمًا فَحَضَرَ الْإِفْطَارُ فَنَامَ قَبْلَ أَنْ يُفْطِرَ لَمْ يَأْكُلْ لَيْلَتَهُ وَلَا يَوْمَهُ حَتَّى يُمْسِيَ، وَإِنَّ قَيْسَ بْنَ صِرْمَةَ الْأَنْصَارِيَّ كَانَ صَائِمًا فَلَمَّا حَضَرَ الْإِفْطَارُ أَتَى امْرَأَتَهُ فَقَالَ لَهَا: أَعِنْدَكِ طَعَامٌ؟ قَالَتْ: لَا، وَلَكِنْ أَنْطَلِقُ فَأَطْلُبُ لَكَ وَكَانَ يَوْمَهُ يَعْمَلُ فَغَلَبَتْهُ عَيْنَاهُ فَجَاءَتْهُ امْرَأَتُهُ، فَلَمَّا رَأَتْهُ قَالَتْ: خَيْبَةً لَكَ، فَلَمَّا انْتَصَفَ النَّهَارُ غُشِيَ عَلَيْهِ فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَزَلَتْ هَذِهِ الْآيَةُ: {أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَى نِسَائِكُمْ} فَفَرِحُوا بِهَا فَرَحًا شَدِيدًا، وَنَزَلَتْ: {وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ}. (خ)', 'ബറാഅ്(റ): മുഹമ്മദ്(സ)യുടെ അനുചരരിൽ ആരെങ്കിലും ഒരാൾ നോമ്പുനോൽക്കുകയും നോമ്പു മുറിക്കുന്ന സമയമെത്തുകയും എന്നാൽ നോമ്പുതുറക്കാതെ ഉറങ്ങുകയും ചെയ്താൽ (പിറ്റേ ദിവസം) വൈകുന്നേരമാവുന്നതുവരെ രാവും പകലും ഭക്ഷിക്കാറില്ല. ഖൈസുബ്നു സിർമതിൽ അൻസാരി(റ) ഒരിക്കൽ നോമ്പുനോറ്റു. നോമ്പു തുറക്കുന്ന സമയമായപ്പോൾ അദ്ദേഹം ഭാര്യയുടെ അടുത്തുപോയി ചോദിച്ചു. നിന്റെയടുക്കൽ ഭക്ഷണമുണ്ടോ? അവർ പറഞ്ഞു: ഇല്ല. പക്ഷേ ഞാൻ പോയി നിങ്ങൾക്കുവേണ്ടി അന്വേഷിച്ചുനോക്കാം. ഖൈസുബ്നു സിർമത്(റ) പകൽ ജോലിചെയ്യുന്നവരായിരുന്നു. അതുകാരണം അദ്ദേഹം ഉറങ്ങിപ്പോയി. ഭാര്യ തിരിച്ചുവന്നു അദ്ദേഹത്തെ കണ്ടപ്പോൾ പറഞ്ഞു: നിങ്ങളുടെ നിർഭാഗ്യം. ഉച്ചയായപ്പോൾ അദ്ദേഹം ബോധം കെട്ടു. വിവരം നബി(സ)യോടു പറഞ്ഞു. അപ്പോൾ ഈ ആയത് ഇറങ്ങി. ''നോമ്പിന്റെ രാത്രിയിൽ നിങ്ങൾക്കു നിങ്ങളുടെ സ്ത്രീകളുമായി സംയോഗം അനുവദിക്കപ്പെട്ടിരിക്കുന്നു.'' അപ്പോൾ അനുചരർ ഈ ആയത് കൊണ്ടു വളരെയധികം സന്തോഷിച്ചു. വീണ്ടും ആയത് ഇറങ്ങി. ''കറുത്ത നൂലിൽനിന്നു വെളുത്ത നൂൽ (ഫജ്റുസ്സ്വാദിഖ്) വെളിവാകുന്നതുവരെ നിങ്ങൾ തിന്നുകയും കുടിക്കുകയും ചെയത് കൊള്ളുക.'' (ബു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 126, 126, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 307, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَفْتِيهِ وَهِيَ تَسْمَعُ مِنْ وَرَاءِ الْبَابِ، فَقَالَ: يَا رَسُولَ اللَّهِ تُدْرِكُنِي الصَّلَاةُ وَأَنَا جُنُبٌ، أَفَأَصُومُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَأَنَا تُدْرِكُنِي الصَّلَاةُ وَأَنَا جُنُبٌ فَأَصُومُ". فَقَالَ: لَسْتَ مِثْلَنَا يَا رَسُولَ اللَّهِ، قَدْ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ. فَقَالَ: "وَاللَّهِ إِنِّي لَأَرْجُو أَنْ أَكُونَ أَخْشَاكُمْ لِلَّهِ، وَأَعْلَمَكُمْ بِمَا أَتَّقِي". (م)', 'ആഇശ(റ): റസൂൽ(സ)യുടെ അടുക്കൽ സംശയനിവാരണത്തിന് ഒരാൾ വന്നു. ആഇശ ബീവി(റ) വാതിലിനു പിന്നിൽനിന്നു കേൾക്കുന്നുണ്ട്. അയാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ ജനാബതുകാരനായിരിക്കെ സുബ്ഹി നിസ്കാരസമയം എത്തി. എനിക്കു നോമ്പു പറ്റുമോ? റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ജനാബതുകാരനായിരിക്കെ സുബ്ഹി നിസ്കാര സമയമാവുകയും ഞാൻ നോമ്പു നോൽക്കുകയും ചെയ്യുന്നു." അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടന്ന് ഞങ്ങളെപ്പോലെയല്ല. അങ്ങയുടെ കഴിഞ്ഞതും വരാനിരിക്കുന്നതുമായ പാപങ്ങൾ അല്ലാഹു പൊറുത്തിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുതന്നെയാണ് സത്യം, നിശ്ചയം നിങ്ങളെക്കാൾ അല്ലാഹുവിനെ ഭയപ്പെടുന്നവനും സൂക്ഷിക്കേണ്ട കാര്യങ്ങൾ അറിയുന്നവനും ഞാനാകണമെന്ന് ഞാൻ ആഗ്രഹിക്കുന്നു." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 126, 127, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 308, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَجُلًا قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ وَاقِفٌ عَلَى الْبَابِ: يَا رَسُولَ اللَّهِ، إِنِّي أُصْبِحُ جُنُبًا، وَأَنَا أُرِيدُ الصِّيَامَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَأَنَا أُصْبِحُ جُنُبًا وَأَنَا أُرِيدُ الصِّيَامَ، فَأَغْتَسِلُ وَأَصُومُ". فَقَالَ الرَّجُلُ: يَا رَسُولَ اللَّهِ، إِنَّكَ لَسْتَ مِثْلَنَا، قَدْ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ. فَغَضِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "وَاللَّهِ إِنِّي لَأَرْجُو أَنْ أَكُونَ أَخْشَاكُمْ لِلَّهِ وَأَعْلَمَكُمْ بِمَا أَتَّبِعُ". (م,د)', 'ആഇശ(റ): വാതിൽക്കൽ നിന്നു ഒരാൾ റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ ജനാബതുകാരനായി നേരം പുലരുന്നു, ഞാൻ നോമ്പ് ഉദ്ദേശിക്കുകയും ചെയ്യുന്നു? അപ്പോൾ അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "ഞാനും ജനാബതുകാരനായി നേരം പുലരുകയും, നോമ്പ് ഉദ്ദേശിക്കുകയും ചെയ്യാറുണ്ട്. ഞാൻ കുളിക്കും, നോമ്പു നോൽക്കും." അപ്പോൾ അയാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് ഞങ്ങളെപ്പോലെയല്ല. അങ്ങയുടെ മുൻകഴിഞ്ഞതും വരാനിരിക്കുന്നതുമായ പാപങ്ങൾ അല്ലാഹു അങ്ങേക്ക് പൊറുത്തുതന്നിട്ടുണ്ട്. അപ്പോൾ റസൂൽ(സ) ദേഷ്യത്തോടെ പറഞ്ഞു: "അല്ലാഹു തന്നെയാണ് സത്യം, നിങ്ങളേക്കാൾ ഞാൻ പിൻപറ്റുന്ന ഒന്നുകൊണ്ട് ഏറ്റവും അറിയുന്നവനും അല്ലാഹുവിനെ ഏറ്റവും ഭയപ്പെടുന്നവനും ആവണമെന്ന് ഞാൻ ആഗ്രഹിക്കുന്നു." (മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 127, 127, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 309, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَا وَرَبِّ الْكَعْبَةِ، مَا أَنَا قُلْتُ: "مَنْ أَصْبَحَ وَهُوَ جُنُبٌ فَلْيُفْطِرْ". مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَهُ. (جه)', 'അബൂഹുറൈറ(റ): കഅബയുടെ നാഥനാണ് സത്യം. "ആരെങ്കിലും ജനാബത്തുകാരനായി പ്രഭാതമായാൽ അവൻ നോമ്പു മുറിക്കണമെന്നു" ഞാൻ ഒരിക്കലും പറഞ്ഞിട്ടില്ല. മുഹമ്മദ് നബി(സ)യാണത് പറഞ്ഞത്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 127, 127, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 310, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَبِيتُ جُنُبًا، فَيَأْتِيهِ بِلَالٌ فَيُؤْذِنُهُ بِالصَّلَاةِ فَيَقُومُ فَيَغْتَسِلُ، فَأَنْظُرُ إِلَى تَحَدُّرِ الْمَاءِ مِنْ رَأْسِهِ، ثُمَّ يَخْرُجُ فَأَسْمَعُ صَوْتَهُ فِي صَلَاةِ الْفَجْرِ. قَالَ مُطَرِّفٌ: فَقُلْتُ لِعَامِرٍ: أَفِي رَمَضَانَ؟ قَالَ: رَمَضَانُ وَغَيْرُهُ سَوَاءٌ. (جه)', 'ആഇശ(റ): ജനാബതുകാരനായി നബി(സ) രാത്രി കഴിച്ചുകൂട്ടാറുണ്ട്. നബിയുടെ അടുക്കൽ ബിലാൽ(റ) വരുകയും നബി(സ)യെ സുബ്ഹി നിസ്കാരത്തിന്റെ സമയം അറിയിക്കുകയും ചെയ്യും. ഉടനെ റസൂൽ(സ) എഴുന്നേൽക്കുകയും കുളിക്കുകയും ചെയ്യും. അവിടത്തെ തലയിൽനിന്നു വെള്ളം ഒലിച്ചിറങ്ങുന്നത് ഞാൻ നോക്കിനില്ക്കും. പിന്നെ റസൂലുല്ലാഹി(സ) പുറപ്പെടും. അവിടത്തെ സുബ്ഹി നിസ്കാരത്തിലെ ശബ്ദം ഞാൻ കേൾക്കും. മുത്വർരിഫ് പറഞ്ഞു: ഞാൻ ആമിർ(റ)വിനോട് ചോദിച്ചു: അത് റമളാനിലാണോ? ആമിർ(റ) പറഞ്ഞു: റമളാനും അല്ലാത്തമാസവും സമമാണ്. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 127, 127, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 311, 'عَنْ نَافِعٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ أُمَّ سَلَمَةَ- رَضِيَ اللهُ عَنْهَا- عَنِ الرَّجُلِ يُصْبِحُ وَهُوَ جُنُبٌ، يُرِيدُ الصَّوْمَ؟ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصْبِحُ جُنُبًا مِنَ الْوِقَاعِ، لَا مِنِ احْتِلَامٍ، ثُمَّ يَغْتَسِلُ وَيُتِمُّ صَوْمَهُ. (جه)', 'നാഫിഅ്(റ): നോമ്പെടുക്കാൻ ഉദ്ദേശിക്കുന്ന, ജനാബത്തുകാരനായി പ്രഭാതമായ ഒരാളെപ്പറ്റി ഉമ്മുസലമ(റ)യോട് ഞാൻ ചോദിച്ചു. അവർ പറഞ്ഞു: റസൂൽ(സ) സ്വപ്നസ്ഖലനം കാരണത്താലല്ല, സംയോഗം കാരണമായി ജനാബത്തുകാരനായ നിലയിൽ പ്രഭാതമാകാറുണ്ട്. പിന്നെ അവിടന്ന് കുളിക്കുകയും നോമ്പു പൂർത്തിയാക്കുകയും ചെയ്യും. (ജ)', 'نَافِعٍ', 'നാഫിഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 127, 127, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 312, 'عَنْ عَامِرِ بْنِ رَبِيعَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَاكُ وَهُوَ صَائِمٌ، مَا لَا أَعُدُّ وَلَا أُحْصِي. (د,ت)', 'ആമിറുബ്നു റബീഅ(റ): എണ്ണിത്തിട്ടപ്പെടുത്താനും കണക്കാക്കാനും കഴിയാത്തത്ര തവണ റസൂൽ(സ) നോമ്പുകാരനായി പല്ലു ശുദ്ധിയാക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ദ,തു)', 'عَامِرِ بْنِ رَبِيعَةَ', 'ആമിറുബ്നു റബീഅ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 128, 128, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 313, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مِنْ خَيْرِ خِصَالِ الصَّائِمِ السِّوَاكُ". [ز: في إسناده ضعيف] (جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "പല്ലു ശുദ്ധിയാക്കൽ നോമ്പുകാരന്റെ നല്ല കാര്യങ്ങളിൽപെട്ടതാണ്." (പരമ്പരയിൽ ഒരു ദുർബലനുണ്ട്) (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'പരമ്പരയിൽ ഒരു ദുർബലനുണ്ട്', 128, 128, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 314, 'عَنْ أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ رَضِيَ اللهُ عَنْهَا، عَنْ بَعْضِ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ النَّاسَ فِي سَفَرِهِ عَامَ الْفَتْحِ بِالْفِطْرِ، وَقَالَ: "تَقَوَّوْا لِعَدُوِّكُمْ". وَصَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ أَبُو بَكْرٍ: قَالَ الَّذِي حَدَّثَنِي: لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْعَرْجِ يَصُبُّ عَلَى رَأْسِهِ الْمَاءَ وَهُوَ صَائِمٌ مِنَ الْعَطَشِ، أَوْ مِنَ الْحَرِّ. (د,ن)', 'നബി(സ)യുടെ ചില അനുചരരിൽനിന്ന് അബൂബക്റുബ്നു അബ്ദുറഹ്മാൻ(റ): മക്കാ വിജയവർഷം ഒരു യാത്രയിൽ റസൂൽ(സ) ജനങ്ങളോട് നോമ്പുമുറിക്കാൻ കൽപ്പിക്കുന്നതു ഞാൻ കണ്ടു. റസൂൽ(സ) പറഞ്ഞു: "ശത്രുക്കളെ നേരിടാൻ നിങ്ങൾ ശക്തി സംഭരിക്കുക." റസൂൽ(സ) നോമ്പു നോൽക്കുകയും ചെയ്തു. അബൂബക്കർ പറയുന്നു: എന്നോടു ഈ ഹദീസ് പറഞ്ഞയാൾ പറഞ്ഞു: നോമ്പുകാരനായ റസൂൽ(സ) ദാഹം കാരണം, അല്ലെങ്കിൽ ചൂടിന്റെ കാഠിന്യത്താൽ, അർജ് എന്ന സ്ഥലത്തുവെച്ചു അവിടത്തെ തലയിൽ വെള്ളം ഒഴിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ദ,ന)', 'أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ', 'നബി(സ)യുടെ ചില അനുചരരിൽനിന്ന് അബൂബക്റുബ്നു അബ്ദുറഹ്മാൻ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 128, 128, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 315, 'عَنْ لَقِيطِ بْنِ صَبِرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَخْبِرْنِي عَنِ الْوُضُوءِ؟ قَالَ: "أَسْبِغِ الْوُضُوءَ، وَخَلِّلْ بَيْنَ الْأَصَابِعِ، وَبَالِغْ فِي الِاسْتِنْشَاقِ إِلَّا أَنْ تَكُونَ صَائِمًا". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'ലഖീതുബ്നു സ്വബ്റത്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, വുളൂഇനെകുറിച്ച് എനിക്കു പറഞ്ഞുതരുമോ? നബി(സ) പറഞ്ഞു: "വുളൂഅ് നീ പൂർണ്ണമായ രീതിയിൽ ചെയ്യുക. വിരലുകൾക്കിടയിൽ നീ തിക്കകറ്റുക, നീ നോമ്പുകാരനല്ലെങ്കിൽ മൂക്കിൽ വെള്ളം കയറ്റുന്നതിൽ മികവു കാണിക്കുക." (ദ,തു,ന)', 'لَقِيطِ بْنِ صَبِرَةَ', 'ലഖീതുബ്നു സ്വബ്റത്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 128, 128, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 316, 'عَنْ مَعْبَدِ بْنِ هَوْذَةَ رَضِيَ اللهُ عَنْهُ، عَنْ أَبِيهِ عَنْ جَدِّهِ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ أَمَرَ بِالْإِثْمِدِ الْمُرَوَّحِ عِنْدَ النَّوْمِ، وَقَالَ: "لِيَتَّقِهِ الصَّائِمُ". (د)', 'തന്റെ വല്യുപ്പയിൽ നിന്ന് പിതാവ് വഴി മഅ്ബദുബ്നു ഹൗദത്ത്(റ): ഉറങ്ങാനൊരുങ്ങുമ്പോൾ കസ്തൂരി ഗന്ധം ചേർക്കപ്പെട്ട സുറുമയിടാൻ നബി(സ) കൽപിച്ചു. എന്നിട്ട് അവിടന്ന് പറഞ്ഞു: "നോമ്പുകാരൻ സൂക്ഷിച്ചു കൊള്ളട്ടെ." (ദ)', 'مَعْبَدِ بْنِ هَوْذَةَ', 'തന്റെ വല്യുപ്പയിൽ നിന്ന് പിതാവ് വഴി മഅ്ബദുബ്നു ഹൗദത്ത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 129, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 317, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ يَكْتَحِلُ وَهُوَ صَائِمٌ. (د)', 'അനസുബ്നു മാലിക്(റ): നോമ്പുകാരനായിരിക്കെ അദ്ദേഹം സുറുമ ഇടാറുണ്ടായിരുന്നു. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 129, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 318, 'عَنِ الْأَعْمَشِ قَالَ: مَا رَأَيْتُ أَحَدًا مِنْ أَصْحَابِنَا يَكْرَهُ الْكُحْلَ لِلصَّائِمِ، وَكَانَ إِبْرَاهِيمُ يُرَخِّصُ أَنْ يَكْتَحِلَ الصَّائِمُ بِالصَّبِرِ. (د)', 'അഅ്മശ്: നോമ്പുകാരൻ സുറുമ ഉപയോഗിക്കുന്നത് വെറുക്കുന്നവരായി നമ്മുടെ സഹചാരികളിൽ ആരുമുണ്ടായിരുന്നില്ല. നോമ്പുകാരൻ കറ്റുവാഴനീര് കൊണ്ടു സുറുമ ഇടുന്നതിനെ ഇബ്റാഹീം അനുവദിക്കുമായിരുന്നു. (ദ)', 'الْأَعْمَشِ قَالَ', 'അഅ്മശ്', null, null, array['د']::text[], array['ദ']::text[], null, null, 129, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 319, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: اشْتَكَتْ عَيْنِي، أَفَأَكْتَحِلُ وَأَنَا صَائِمٌ؟ قَالَ: "نَعَمْ". (ت)', 'അനസുബ്നു മാലിക്(റ): ഒരാൾ റസൂൽ(സ)യുടെ അരികിൽവന്നു പറഞ്ഞു: എന്റെ കണ്ണിനു രോഗം ബാധിച്ചിരിക്കുന്നു, നോമ്പുകാരനായിരിക്കെ എനിക്കു സുറുമ ഉപയോഗിക്കാൻ പറ്റുമോ? റസൂൽ(സ) പറഞ്ഞു: "അതേ." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 129, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 320, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: اكْتَحَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ صَائِمٌ. [ز: في سنده ضعيف] (جه)', 'ആഇശ(റ): നോമ്പുകാരനായിരിക്കെ റസൂൽ(സ) സുറുമ ഉപയോഗിച്ചിരുന്നു. (പരമ്പരയിൽ ദുർബലനുണ്ട്) (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', 'പരമ്പരയിൽ ദുർബലനുണ്ട്', 129, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 321, 'عَنْ شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ: بَيْنَمَا هُوَ يَمْشِي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ... فَذَكَرَ نَحْوَهُ. وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَى عَلَى رَجُلٍ بِالْبَقِيعِ، وَهُوَ يَحْتَجِمُ، وَهُوَ آخِذٌ بِيَدِي، لِثَمَانَ عَشْرَةَ خَلَتْ مِنْ رَمَضَانَ، فَقَالَ: "أَفْطَرَ الْحَاجِمُ وَالْمَحْجُومُ". (د,ت,ن,جه)', 'ശദ്ദാദുബ്നു ഔസ്(റ): അദ്ദേഹം പ്രവാചകർ(സ)യുടെ കൂടെ നടക്കുന്നതിനിടെ..... മുമ്പ് പറഞ്ഞ ഹദീസ് ഉദ്ധരിച്ചു. മറ്റൊരു നിവേദനം: റമളാനിന്റെ പതിനെട്ടാം ദിവസം റസൂൽ(സ) എന്റെ കരംപിടിച്ചു ബഖീഇലെ കൊമ്പുവെക്കുന്ന ഒരാളുടെ അടുക്കലേക്കു പോയി. എന്നിട്ട് പറഞ്ഞു: "കൊമ്പുവെച്ചവനും വെക്കപ്പെട്ടവനും വ്രതം മുറിച്ചു." (ദ,തു,ന,ജ)', 'شَدَّادِ بْنِ أَوْسٍ', 'ശദ്ദാദുബ്നു ഔസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 129, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=321), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَى عَلَى رَجُلٍ بِالْبَقِيعِ، وَهُوَ يَحْتَجِمُ، وَهُوَ آخِذٌ بِيَدِي، لِثَمَانَ عَشْرَةَ خَلَتْ مِنْ رَمَضَانَ، فَقَالَ: "أَفْطَرَ الْحَاجِمُ وَالْمَحْجُومُ". (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: റമളാനിന്റെ പതിനെട്ടാം ദിവസം റസൂൽ(സ) എന്റെ കരംപിടിച്ചു ബഖീഇലെ കൊമ്പുവെക്കുന്ന ഒരാളുടെ അടുക്കലേക്കു പോയി. എന്നിട്ട് പറഞ്ഞു: "കൊമ്പുവെച്ചവനും വെക്കപ്പെട്ടവനും വ്രതം മുറിച്ചു." (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 322, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَا كُنَّا نَدَعُ الْحِجَامَةَ لِلصَّائِمِ إِلَّا كَرَاهِيَةَ الْجَهْدِ. (خ,د)', 'അനസ്(റ): ബുദ്ധിമുട്ട് വെറുത്താലല്ലാതെ നോമ്പുകാരന് കൊമ്പുവെക്കുന്നതിനെ ഞങ്ങൾ ഉപേക്ഷിക്കാറില്ല. (ബു,ദ)*', 'أَنَسٍ', 'അനസ്(റ)', '*രോഗിക്ക് വിഷമമില്ലെങ്കിൽ കൊമ്പുവെക്കാവുന്നതാണ്', null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 129, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 323, 'عَنْ عَبْدِ الرَّحْمَنِ ابْنِ أَبِي لَيْلَى: حَدَّثَنِي رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْحِجَامَةِ وَالْمُوَاصَلَةِ وَلَمْ يُحَرِّمْهُمَا، إِبْقَاءً عَلَى أَصْحَابِهِ، فَقِيلَ لَهُ: يَا رَسُولَ اللَّهِ، إِنَّكَ تُوَاصِلُ إِلَى السَّحَرِ؟ فَقَالَ: "إِنِّي أُوَاصِلُ إِلَى السَّحَرِ، وَرَبِّي يُطْعِمُنِي وَيَسْقِينِي". (د)', 'അബ്ദുറഹ്മാനുബ്നു അബീലൈല(റ): റസൂൽ(സ)യുടെ ഒരു അനുചരൻ എന്നോട് പറഞ്ഞു: നബി(സ) കൊമ്പുവെക്കലും നോമ്പ് ചേർത്തനുഷ്ഠിക്കലും വിരോധിച്ചിട്ടുണ്ടെങ്കിലും അനുചരർ ചെയ്യാൻ പാടില്ലെന്ന രീതിയിൽ നിഷിദ്ധമാക്കിയിട്ടില്ല. നബി(സ) ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് അത്താഴം വരെ ചേർത്ത് നോൽക്കുന്നല്ലോ? നബി(സ) പറഞ്ഞു: "നിശ്ചയം ഞാൻ അത്താഴംവരെ ചേർത്തനുഷ്ഠിക്കുന്നു. എന്റെ രക്ഷിതാവെനിക്ക് ഭക്ഷണപാനീയങ്ങൾ നൽകുന്നു". (ദ)', 'عَبْدِ الرَّحْمَنِ ابْنِ أَبِي لَيْلَى', 'അബ്ദുറഹ്മാനുബ്നു അബീലൈല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 130, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 324, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: احْتَجَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- وَفِي رِوَايَةٍ: بَيْنَ مَكَّةَ وَالْمَدِينَةِ- وَهُوَ مُحْرِمٌ صَائِمٌ. وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ وَهُوَ صَائِمٌ. حَسَنٌ صَحِيحٌ. (خ,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നോമ്പുകാരനും ഇഹ്റാം ചെയ്തവരുമായിരിക്കെ - ഒരു നിവേദനത്തിൽ: മക്കയുടേയും മദീനയുടേയും മധ്യേ - റസൂൽ(സ) കൊമ്പുവെച്ചു. മറ്റൊരു നിവേദനം: നോമ്പുകാരനായിരിക്കെ നബി(സ) കൊമ്പുവെച്ചിരുന്നു. (ബു,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 130, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=324), 1, 'وَفِي رِوَايَةٍ: بَيْنَ مَكَّةَ وَالْمَدِينَةِ- وَهُوَ مُحْرِمٌ صَائِمٌ.', 'മറ്റൊരു നിവേദനം: നോമ്പുകാരനായിരിക്കെ നബി(സ) കൊമ്പുവെച്ചിരുന്നു. (ബു,തു)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=324), 2, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ وَهُوَ صَائِمٌ. حَسَنٌ صَحِيحٌ. (خ,ت)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 325, 'عَنْ مَعْدَانَ بْنِ طَلْحَةَ: أَنَّ أَبَا الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ حَدَّثَهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاءَ فَأَفْطَرَ، فَلَقِيتُ ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَسْجِدِ دِمَشْقَ، فَقُلْتُ: إِنَّ أَبَا الدَّرْدَاءِ حَدَّثَنِي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاءَ فَأَفْطَرَ؟ قَالَ: صَدَقَ، وَأَنَا صَبَبْتُ لَهُ وَضُوءَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د,ت)', 'മഅ്ദാനുബ്നു ത്വൽഹ(റ): അബുദ്ദർദാഅ്(റ) എനിക്ക് ഹദീസ് പറഞ്ഞുതന്നു: റസൂൽ(സ) ഛർദ്ദിച്ചപ്പോൾ നോമ്പു മുറിച്ചു. റസൂൽ(സ)യുടെ വിമോചിത അടിമയായ സൗബാൻ(റ)വിനെ ഡമസ്കസിലെ പള്ളിയിൽവെച്ച് കണ്ടപ്പോൾ അബുദ്ദർദാഅ്(റ) എനിക്കു പറഞ്ഞുതന്ന റസൂൽ(സ) ഛർദ്ദിച്ചപ്പോൾ നോമ്പുമുറിച്ചു എന്ന ഹദീസിനെകുറിച്ചു ഞാൻ ചോദിച്ചു. സൗബാൻ(റ) പറഞ്ഞു: സത്യമാണ്, ഞാനായിരുന്നു റസൂൽ(സ)ക്ക് വുളൂഇന്റെ വെള്ളം ഒഴിച്ചുകൊടുത്തിരുന്നത്. (ദ,തു)', 'مَعْدَانَ بْنِ طَلْحَةَ', 'മഅ്ദാനുബ്നു ത്വൽഹ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 130, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 326, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ ذَرَعَهُ الْقَيْءُ فَلَيْسَ عَلَيْهِ قَضَاءٌ، وَمَنِ اسْتَقَاءَ عَمْدًا فَلْيَقْضِ". (د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഛർദ്ദി ഉണ്ടായവൻ നോമ്പ് ഖളാഅ് വീട്ടേണ്ടതില്ല. എന്നാൽ, ഉണ്ടാക്കിഛർദ്ദിച്ചവൻ നോമ്പ് ഖളാഅ് വീട്ടേണ്ടതാണ്." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 130, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 327, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثٌ لَا يُفْطِرْنَ الصَّائِمَ: الْحِجَامَةُ وَالْقَيْءُ وَالِاحْتِلَامُ". (ت)', 'അബീസഈദിനിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറയുന്നു: "മൂന്നു കാര്യങ്ങൾ നോമ്പു മുറിക്കുകയില്ല; കൊമ്പുവെക്കലും ഛർദ്ദിയും സ്വപ്നസ്ഖലനവും". (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബീസഈദിനിൽ ഖുദ്രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 130, 131, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 328, 'عَنْ زَيْدِ بْنِ أَسْلَمَ الْعَدَوِيِّ، عَنْ رَجُلٍ مِنْ أَصْحَابِهِ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يُفْطِرُ مَنْ قَاءَ، وَلَا مَنِ احْتَلَمَ، وَلَا مَنِ احْتَجَمَ". (د,ت)', 'നബി(സ)യുടെ ഒരു അനുചരനിൽനിന്ന് തന്റെ സുഹൃത്ത് നിവേദനം ചെയ്യുന്നതായി സൈദുബ്നു അസ്ലമിൽ അദവീ(റ): റസൂൽ(സ) പറഞ്ഞു: "കൊമ്പുവെച്ചവനും, സ്വപ്നസ്ഖലനം ഉണ്ടായവനും, സ്വമേധയാ ഛർദ്ദി ഉണ്ടായവനും നോമ്പ് മുറിച്ചിട്ടില്ല". (ദ,തു)', 'زَيْدِ بْنِ أَسْلَمَ الْعَدَوِيِّ، عَنْ رَجُلٍ مِنْ أَصْحَابِهِ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ', null, null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 131, 131, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 329, 'عَنْ فَضَالَةَ بْنِ عُبَيْدٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ عَلَيْهِمْ فِي يَوْمٍ كَانَ يَصُومُهُ، فَدَعَا بِإِنَاءٍ فَشَرِبَ. فَقُلْنَا: يَا رَسُولَ اللَّهِ، إِنَّ هَذَا يَوْمٌ كُنْتَ تَصُومُهُ؟ قَالَ: "أَجَلْ، وَلَكِنِّي قِئْتُ". [ز: في سنده انقطاع، ومدلس عنعنه] (جه)', 'ഫളാലതുബ്നു ഉബൈദിൽ അൻസ്വാരി(റ): ഒരു ദിവസം റസൂൽ(സ) നോമ്പുനോറ്റ് അവരുടെ അടുത്തേക്ക് ചെന്നു. അപ്പോൾ ഒരു പാത്രം (വെള്ളം) കൊണ്ടുവരാൻ ആവശ്യപ്പെട്ടു. അതിൽനിന്ന് കുടിച്ചു. അപ്പോൾ ഞങ്ങൾ ചോദിച്ചു: തിരുദൂതരേ, തീർച്ചയായും ഈ ദിനത്തിൽ അങ്ങ് നോമ്പുകാരനായിരുന്നല്ലോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ, പക്ഷേ ഞാൻ ഛർദ്ദിച്ചു." ഇതിന്റെ പരമ്പരയിൽ നിവേദകർക്കിടയിൽ ഇടമുറിഞ്ഞിട്ടുണ്ട്. (ജ)', 'فَضَالَةَ بْنِ عُبَيْدٍ الْأَنْصَارِيِّ', 'ഫളാലതുബ്നു ഉബൈദിൽ അൻസ്വാരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده انقطاع، ومدلس عنعنه', null, 131, 131, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 330, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَامَ رَمَضَانَ وَقَامَهُ- إِيمَانًا وَاحْتِسَابًا- غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ. وَمَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". صَحِيحٌ. (ق,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും റമളാൻ മാസത്തിൽ പ്രതിഫലേച്ഛയോടെയും വിശ്വാസത്തോടെയും നിന്ന് നിസ്കരിക്കുകയും നോമ്പനുഷ്ഠിക്കുകയും ചെയ്താൽ അവന്റെ മുൻകഴിഞ്ഞ പാപങ്ങൾ പൊറുക്കപ്പെടും. വല്ലവനും ലൈലതുൽ ഖദ്റിൽ കൂലി ആഗ്രഹിച്ചും വിശ്വാസത്തോടെയും രാത്രി നിന്നു നിസ്കരിച്ചാൽ അവന്റെ മുൻകഴിഞ്ഞ പാപങ്ങളെല്ലാം പൊറുക്കപ്പെടും." (ബു,മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 131, 131, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 331, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ فِي جَوْفِ اللَّيْلِ يُصَلِّي فِي الْمَسْجِدِ، فَصَلَّى بِالنَّاسِ، قَالَتْ: فَكَانَ يُرَغِّبُهُمْ فِي قِيَامِ رَمَضَانَ مِنْ غَيْرِ أَنْ يَأْمُرَهُمْ بِعَزِيمَةٍ، وَيَقُولُ: "مَنْ قَامَ لَيْلَةَ الْقَدْرِ- وَفِي رِوَايَةٍ: مَنْ قَامَ رَمَضَانَ- إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". قَالَ: فَتُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْأَمْرُ عَلَى ذَلِكَ. (خ,ن)', 'ആഇശ(റ): റസൂൽ(സ) അർദ്ധരാത്രിയിൽ പള്ളിയിലേക്കു നിസ്കരിക്കാൻ പുറപ്പെട്ടു. സഹചാരികളൊത്ത് അവിടന്ന് നിസ്കാരം നിർവ്വഹിച്ചു. കണിശമായ കൽപനയില്ലാതെ റമളാനിലെ നിസ്കാരത്തിന് തിരുമേനി(സ) അവരെ പ്രേരിപ്പിക്കും. അവിടന്ന് പറഞ്ഞു: "ഖദ്റിന്റെ രാത്രിയിൽ - മറ്റൊരഭിപ്രായത്തിൽ റമളാനിൽ - പ്രതിഫലേച്ഛയോടെയും വിശ്വാസത്തോടെയും നിശാനിസ്കാരം നിർവ്വഹിച്ചാൽ മുൻകാലങ്ങളിൽ അവൻ ചെയ്ത പാപങ്ങൾ പൊറുക്കപ്പെടും." നിവേദകൻ പറയുന്നു: കാര്യം അപ്രകാരം ആയിരിക്കെയാണ് റസൂൽ(സ) വഫാത്തായത്. (ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 131, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=331), 1, 'وَفِي رِوَايَةٍ: مَنْ قَامَ رَمَضَانَ- إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". قَالَ: فَتُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْأَمْرُ عَلَى ذَلِكَ. (خ,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 332, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: صُمْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ يُصَلِّ بِنَا حَتَّى بَقِيَ سَبْعٌ مِنَ الشَّهْرِ، فَقَامَ بِنَا حَتَّى ذَهَبَ ثُلُثُ اللَّيْلِ، ثُمَّ لَمْ يَقُمْ بِنَا فِي السَّادِسَةِ وَقَامَ بِنَا فِي الْخَامِسَةِ حَتَّى ذَهَبَ شَطْرُ اللَّيْلِ، فَقُلْنَا لَهُ: يَا رَسُولَ اللَّهِ، لَوْ نَفَّلْتَنَا بَقِيَّةَ لَيْلَتِنَا هَذِهِ؟ فَقَالَ: "إِنَّهُ مَنْ قَامَ مَعَ الْإِمَامِ حَتَّى يَنْصَرِفَ كُتِبَ لَهُ قِيَامُ لَيْلَةٍ". (ت)', 'അബൂദർറ്(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ നോമ്പുനോറ്റു. മാസത്തിലെ ഏഴുദിവസം ബാക്കിയാകുവോളം അവിടന്ന് ഞങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചില്ല. അപ്പോൾ (23 കഴിഞ്ഞപ്പോൾ) അവിടന്ന് രാത്രിയുടെ മൂന്നിലൊന്നു കഴിയുവോളം നിസ്കരിച്ചു. പിന്നെ ആറാംദിനം നിസ്കരിച്ചില്ല. അഞ്ചാം ദിനം രാത്രിയുടെ പകുതി കഴിയുന്നതുവരെ നിസ്കരിച്ചു. അപ്പോൾ ഞങ്ങൾ അവിടത്തോട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഈ രാത്രിയിലെ ബാക്കി സമയം കൂടി താങ്കൾ ഞങ്ങൾക്കു വിട്ടുതന്നിരുന്നെങ്കിൽ. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "പിരിയുന്നതുവരെ ഇമാമിനോടൊപ്പം ഒരാൾ നിസ്കരിച്ചാൽ ഒരു രാത്രിയിലെ നിസ്കാരം മുഴുവൻ അവന് എഴുതപ്പെടുന്നതാണ്." (തു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 132, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 333, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُرَغِّبُ فِي قِيَامِ رَمَضَانَ مِنْ غَيْرِ أَنْ يَأْمُرَهُمْ بِعَزِيمَةٍ، وَيَقُولُ: "مَنْ قَامَ رَمَضَانَ- إِيمَانًا وَاحْتِسَابًا- غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". فَتُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْأَمْرُ عَلَى ذَلِكَ، ثُمَّ كَانَ الْأَمْرُ كَذَلِكَ فِي خِلَافَةِ أَبِي بَكْرٍ، وَصَدْرًا مِنْ خِلَافَةِ عُمَرَ عَلَى ذَلِكَ. حَسَنٌ صَحِيحٌ. (م,د,ت)', 'അബൂഹുറൈറ(റ): കണിശമായ കൽപനകൂടാതെ റമളാനിലെ നിസ്കാരത്തെ റസൂൽ(സ) പ്രേരിപ്പിച്ചിരുന്നു. "പ്രതിഫലേച്ഛയോടെയും വിശ്വാസത്തോടെയും റമളാനിലെ നിസ്കാരം നിർവ്വഹിച്ചവരുടെ മുൻപാപങ്ങൾ പൊറുക്കപ്പെട്ടു"മെന്നു തിരുമേനി(സ) പറഞ്ഞു. റസൂൽ(സ)യുടെ വഫാത്തിന്റെ സമയത്തും അബൂബക്കർ(റ)ന്റെ ഖിലാഫതിന്റെ കാലത്തും ഉമർ(റ)വിന്റെ ഖിലാഫത്തിന്റെ തുടക്കംവരെയും കാര്യം ഇപ്രകാരം തുടരുകയുണ്ടായി. (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 132, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 334, 'عَنِ النَّضْرِ بْنِ شَيْبَانَ: أَنَّهُ لَقِيَ أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ فَقَالَ لَهُ: حَدِّثْنِي بِأَفْضَلِ شَيْءٍ سَمِعْتَهُ يُذْكَرُ فِي شَهْرِ رَمَضَانَ. فَقَالَ أَبُو سَلَمَةَ: حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ ذَكَرَ شَهْرَ رَمَضَانَ فَفَضَّلَهُ عَلَى الشُّهُورِ، وَقَالَ: "مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا خَرَجَ مِنْ ذُنُوبِهِ كَيَوْمِ وَلَدَتْهُ أُمُّهُ". قَالَ النَّسَائِيُّ: هَذَا خَطَأٌ، وَالصَّوَابُ: أَبُو سَلَمَةَ عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ. (ن)', 'നള്റുബ്നു ശൈബാൻ(റ): അബൂസലമതുബ്നു അബ്ദുറഹ്മാൻ(റ)വിനെ അദ്ദേഹം കണ്ടുമുട്ടി. അദ്ദേഹത്തോട് പറഞ്ഞു: റമളാൻ മാസത്തെക്കുറിച്ച് നിങ്ങൾ കേട്ട ശ്രേഷ്ഠമായ കാര്യം അറിയിച്ചുതരിക. അബൂസലമ(റ) പ്രതിവചിച്ചു: റസൂൽ(സ) റമളാനിനെക്കുറിച്ച് പരാമർശിക്കുകയും റമളാൻ മാസം മറ്റു മാസങ്ങളേക്കാൾ ശ്രേഷ്ഠമാണെന്ന് പറയുകയും "ആരെങ്കിലും പ്രതിഫലേച്ഛയോടെയും വിശ്വാസത്തോടെയും റമളാനിലെ നിസ്കാരം നിർവ്വഹിച്ചാൽ, തന്നെ മാതാവ് പ്രസവിച്ച ദിവസത്തെപ്പോലെ, പാപങ്ങളിൽനിന്ന് അവൻ മുക്തനാകുന്നതാണ്." എന്ന് നബി(സ) പറയുകയും ചെയ്തുവെന്ന് അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) എന്നോട് പറഞ്ഞു. നസാഈ പറയുന്നു: ഇത് തെറ്റാണ്. അബുഹുറൈറ(റ)യിൽ നിന്ന് അബുസലമ(റ) റിപ്പോർട്ട് ചെയ്തു എന്നതാണ് ശരി. (ന)', 'النَّضْرِ بْنِ شَيْبَانَ', 'നള്റുബ്നു ശൈബാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 132, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 335, 'عَنِ النَّضْرِ بْنِ شَيْبَانَ قَالَ: قُلْتُ لِأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ: حَدِّثْنِي بِشَيْءٍ– سَمِعْتَهُ مِنْ أَبِيكَ، سَمِعَهُ أَبُوكَ مِنْ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، لَيْسَ بَيْنَ أَبِيكَ وَبَيْنَ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَحَدٌ– فِي شَهْرِ رَمَضَانَ. قَالَ: نَعَمْ، حَدَّثَنِي أَبِي قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى فَرَضَ صِيَامَ رَمَضَانَ عَلَيْكُمْ، وَسَنَنْتُ لَكُمْ قِيَامَهُ، فَمَنْ صَامَهُ وَقَامَهُ إِيمَانًا وَاحْتِسَابًا خَرَجَ مِنْ ذُنُوبِهِ كَيَوْمِ وَلَدَتْهُ أُمُّهُ". (ن)', 'നള്റ്ബ്നു ശൈബാൻ(റ): ഞാൻ അബുസലമതുബ്നു അബ്ദുൽ റഹ്മാൻ(റ)വിനോട് പറഞ്ഞു: റമളാൻ മാസത്തെക്കുറിച്ച് തിരുദൂതർ(സ)യിൽനിന്നു നിങ്ങളുടെ പിതാവും പിതാവിൽനിന്നു താങ്കളും കേട്ട, പ്രവാചകരുടെയും താങ്കളുടെ പിതാവിന്റെയും ഇടക്ക് ആരും തന്നെയില്ലാത്ത, ഒരു കാര്യം എനിക്ക് അറിയിച്ചുതരൂ. അബുസലമ(റ) പറഞ്ഞു: ശരി. എന്റെ പിതാവെന്നോട് പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം അല്ലാഹു അനുഗ്രഹപൂർണ്ണനും പ്രതാപമുടയവനുമത്രെ. അവൻ റമളാൻവ്രതം നിങ്ങൾക്കു നിർബന്ധമാക്കുകയും അതിലെ നിസ്കാരം ഞാൻ നിങ്ങൾക്ക് പുണ്യമാക്കുകയും ചെയ്തിരിക്കുന്നു. ആരെങ്കിലും അതിൽ പ്രതിഫലേച്ഛയോടെയും വിശ്വാസത്തോടെയും വ്രതമെടുക്കുകയും പ്രത്യേക നിസ്കാരം നിർവ്വഹിക്കുകയും ചെയ്താൽ ഉമ്മ പ്രസവിച്ച ദിനത്തിനു തുല്യമായി പാപങ്ങളിൽനിന്ന് അവൻ മുക്തനാകുന്നതാണ്." (ന)', 'النَّضْرِ بْنِ شَيْبَانَ قَالَ', 'നള്റ്ബ്നു ശൈബാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 133, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 336, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَجْوَدَ النَّاسِ، وَكَانَ أَجْوَدُ مَا يَكُونُ فِي رَمَضَانَ حِينَ يَلْقَاهُ جِبْرِيلُ، وَكَانَ جِبْرِيلُ يَلْقَاهُ فِي كُلِّ لَيْلَةٍ مِنْ شَهْرِ رَمَضَانَ فَيُدَارِسُهُ الْقُرْآنَ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ يَلْقَاهُ جِبْرِيلُ عَلَيْهِ السَّلَام أَجْوَدَ بِالْخَيْرِ مِنَ الرِّيحِ الْمُرْسَلَةِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): റസൂൽ(സ) വളരെയധികം ദാനം ചെയ്യുന്നവരായിരുന്നു. റമളാനിൽ ജിബ്രീലിനെ കാണുന്ന അവസരത്തിലായിരുന്നു അധികമായി ദാനം ചെയ്തിരുന്നത്. റമളാനിന്റെ എല്ലാ രാത്രികളിലും ഖുർആൻ പാരായണം ചെയ്തുകൊടുക്കാൻ ജിബ്രീൽ(അ) റസൂൽ(സ)യെ കാണുമായിരുന്നു. ജിബ്രീലിനെ കാണുന്ന അവസരത്തിൽ, അടിച്ചുവീശുന്ന കാറ്റിനെക്കാൾ നന്മകൊണ്ടു ധർമിഷ്ഠനായിരുന്നു റസൂൽ(സ). (ന)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 133, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 337, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا لَعَنَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ لَعْنَةٍ تُذْكَرُ، كَانَ إِذَا كَانَ قَرِيبَ عَهْدٍ بِجِبْرِيلَ عَلَيْهِ السَّلَام يُدَارِسُهُ كَانَ أَجْوَدَ بِالْخَيْرِ مِنَ الرِّيحِ الْمُرْسَلَةِ. (ن)', 'ആഇശ(റ): പറയപ്പെടാവുന്ന ഒരു ശാപവും റസൂൽ(സ) ശപിച്ചിട്ടില്ല. ഖുർആൻ പാരായണത്തിനായി ജിബ്രീൽ(അ) വരാനടുക്കുമ്പോൾ റസൂൽ(സ) അടിച്ചുവീശുന്ന കാറ്റിനെക്കാൾ നന്മകൊണ്ടു ദാനം ചെയ്തിരുന്നു. (ന.)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 133, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 338, 'عَنْ عَطِيَّةَ بْنِ سُفْيَانَ بْنِ عَبْدِ اللَّهِ بْنِ رَبِيعَةَ قَالَ: حَدَّثَنَا وَفْدُنَا الَّذِينَ قَدِمُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِإِسْلَامِ ثَقِيفٍ، قَالَ: وَقَدِمُوا عَلَيْهِ فِي رَمَضَانَ، فَضَرَبَ عَلَيْهِمْ قُبَّةً فِي الْمَسْجِدِ، فَلَمَّا أَسْلَمُوا صَامُوا مَا بَقِيَ عَلَيْهِمْ مِنَ الشَّهْرِ. [ز: فيه راو مجهول، ومدلس عنه] (جه)', 'അത്വിയ്യതുബ്നു സുഫ്യാനിബ്നി അബ്ദില്ലാഹിബ്നി റബീഅ(റ): സഖീഫുകാർ ഇസ്ലാമിലേക്കു വന്ന വാർത്തയുമായി റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന ഞങ്ങളുടെ സംഘം ഞങ്ങൾക്ക് പറഞ്ഞുതന്നു. നിവേദകൻ പറയുന്നു: റമളാനിലാണ് അവർ റസൂൽ(സ)യുടെ അടുത്തെത്തിയത്. അവിടന്ന് അവർക്കു പള്ളിയിൽ ഒരു കൂടാരമൊരുക്കി. അവർ ഇസ്ലാം സ്വീകരിച്ചപ്പോൾ റമളാനിൽ ബാക്കിയുള്ള ദിവസങ്ങൾ അവർ നോമ്പെടുത്തു. (നിവേദക പരമ്പര സംശയകരം) (ജ)', 'عَطِيَّةَ بْنِ سُفْيَانَ بْنِ عَبْدِ اللَّهِ بْنِ رَبِيعَةَ قَالَ', 'അത്വിയ്യതുബ്നു സുഫ്യാനിബ്നി അബ്ദില്ലാഹിബ്നി റബീഅ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فيه راو مجهول، ومدلس عنه', 'നിവേദക പരമ്പര സംശയകരം', 133, 134, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 339, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ الْعَشْرُ أَحْيَا اللَّيْلَ وَأَيْقَظَ أَهْلَهُ، وَجَدَّ، وَشَدَّ الْمِئْزَرَ. (م)', 'ആഇശ(റ): റമളാനിലെ അവസാനത്തെ പത്തായാൽ റസൂൽ(സ) രാത്രിയെ ആരാധനകളാൽ ജീവിപ്പിക്കുകയും വീട്ടുകാരെ വിളിച്ചുണർത്തുകയും അരയുടുപ്പ് മുറുക്കി ആരാധനക്ക് പരിശ്രമിക്കുകയും ചെയ്യുമായിരുന്നു. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 134, 134, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 340, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَجْتَهِدُ فِي الْعَشْرِ الْأَوَاخِرِ مَا لَا يَجْتَهِدُ فِي غَيْرِهِ. (جه)', 'ആഇശ(റ): മറ്റു ദിവസങ്ങളിലില്ലാത്ത പരിശ്രമം അവസാനത്തെ പത്തിൽ റസൂൽ(സ) പരിശ്രമിക്കാറുണ്ടായിരുന്നു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 134, 134, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 341, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّ رِجَالًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُرُوا لَيْلَةَ الْقَدْرِ فِي الْمَنَامِ فِي السَّبْعِ الْأَوَاخِرِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَرَى رُؤْيَاكُمْ قَدْ تَوَاطَأَتْ فِي السَّبْعِ الْأَوَاخِرِ فَمَنْ كَانَ مُتَحَرِّيهَا فَلْيَتَحَرَّهَا فِي السَّبْعِ الْأَوَاخِرِ". (خ)', 'ഇബ്നുഉമർ(റ): തിരുമേനി(സ)യുടെ അനുചരന്മാരിൽ അധികപേർക്കും ലൈലത്തുൽഖദ്ർ റമളാനിലെ അവസാന ആഴ്ചയിൽ വരുന്നതായി സ്വപ്നദർശനമുണ്ടായി. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങളുടെയെല്ലാം സ്വപ്നങ്ങൾ അവസാനത്തെ ഏഴുദിനങ്ങളിൽ ഒത്തുചേരുന്നതായാണു കാണുന്നത്. അതിനാൽ, ആരെങ്കിലും ഖദ്റിന്റെ രാത്രിയെ അന്വേഷിക്കുന്നുവെങ്കിൽ അവൻ റമളാനിന്റെ അവസാനത്തെ ആഴ്ചയിൽ അന്വേഷിക്കട്ടെ." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 134, 134, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 342, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: اعْتَكَفْنَا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعَشْرَ الْأَوْسَطَ مِنْ رَمَضَانَ فَخَرَجَ صَبِيحَةَ عِشْرِينَ فَخَطَبَنَا وَقَالَ: "إِنِّي أُرِيتُ لَيْلَةَ الْقَدْرِ ثُمَّ أُنْسِيتُهَا أَوْ نَسِيتُهَا فَالْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ فِي الْوَتْرِ، وَإِنِّي رَأَيْتُ أَنِّي أَسْجُدُ فِي مَاءٍ وَطِينٍ، فَمَنْ كَانَ اعْتَكَفَ مَعَ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلْيَرْجِعْ"، فَرَجَعْنَا وَمَا نَرَى فِي السَّمَاءِ قَزَعَةً، فَجَاءَتْ سَحَابَةٌ فَمَطَرَتْ حَتَّى سَالَ سَقْفُ الْمَسْجِدِ وَكَانَ مِنْ جَرِيدِ النَّخْلِ، وَأُقِيمَتِ الصَّلَاةُ، فَرَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَسْجُدُ فِي الْمَاءِ وَالطِّينِ، حَتَّى رَأَيْتُ أَثَرَ الطِّينِ فِي جَبْهَتِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'അബുസഈദ്(റ): റമളാനിന്റെ മധ്യത്തിലെ പത്തു ദിനങ്ങളിൽ തിരുമേനി(സ)യുടെ കൂടെ ഞങ്ങൾ ഇഅ്തികാഫിരുന്നു. റമളാൻ ഇരുപതിനു രാവിലെ തിരുമേനി(സ) പള്ളിയിൽനിന്നു പുറത്തുവന്ന് ഞങ്ങളോടു പറഞ്ഞു: "ലൈലത്തുൽ ഖദ്റിനെക്കുറിച്ച് എനിക്കു സ്വപ്നദർശനമുണ്ടായി. ശേഷം ഞാനതു മറന്നുപോയി. അവസാനത്തെ പത്തിലെ ഒറ്റയിട്ട ദിനങ്ങളിൽ നിങ്ങളതിനെ അന്വേഷിക്കുക. വെള്ളത്തിലും കളിമണ്ണിലും സുജൂദ് ചെയ്യുന്നതായും എനിക്കു സ്വപ്നദർശനമുണ്ടായി. അതിനാൽ പ്രവാചകനോടൊപ്പം ഇഅ്തികാഫ് ഇരുന്നവരൊക്കെ പള്ളിയിലേക്കുതന്നെ മടങ്ങുക." ഉടനെ ഞങ്ങൾ മടങ്ങി. അപ്പോൾ ആകാശത്തിൽ ഒരു മേഘപാളിപോലുമില്ലായിരുന്നു. പെട്ടെന്നു കാർമേഘങ്ങൾ വന്ന് മഴ വർഷിക്കാൻ തുടങ്ങി. മഴയുടെ ശക്തികാരണം ഈത്തപ്പന മട്ടലുകൊണ്ടുള്ള പള്ളിയുടെ മേൽക്കൂര ചോർന്നൊലിച്ചു. ശേഷം നിസ്കാരം നടന്നു. തിരുമേനി(സ) കളിമണ്ണിലും വെള്ളത്തിലും സുജൂദ് ചെയ്യുന്നത് ഞാൻ കണ്ടു. അവിടത്തെ തിരുനെറ്റിയിൽ കളിമണ്ണിന്റെ അവശിഷ്ടങ്ങളും ഞാൻ കണ്ടു. (ബു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 134, 135, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 343, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ لَيْلَةَ الْقَدْرِ فِي تَاسِعَةٍ تَبْقَى فِي سَابِعَةٍ تَبْقَى فِي خَامِسَةٍ تَبْقَى". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): തിരുമേനി(സ) പറഞ്ഞു: "ലൈലത്തുൽ ഖദ്റിനെ നിങ്ങൾ റമളാനിന്റെ ഒടുവിലെ പത്തിൽ, അതായത് റമളാനിൽ നിന്ന് ഒമ്പത് ദിവസം ബാക്കിനിൽക്കെ, ഏഴു ദിവസം ബാക്കിനിൽക്കെ, അഞ്ച് ദിവസം ബാക്കിനിൽക്കെ. റമളാൻ ഇരുപത്തൊമ്പതിലും ഇരുപത്തേഴിലും ഇരുപത്തഞ്ചിലും പ്രതീക്ഷിക്കുക." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 135, 135, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 344, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ– يَعْنِي لَيْلَةَ الْقَدْرِ– فَإِنْ ضَعُفَ أَحَدُكُمْ أَوْ عَجَزَ فَلَا يُغْلَبَنَّ عَلَى السَّبْعِ الْبَوَاقِي". (م)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അതിനെ - ലൈലതുൽ ഖദ്റിനെ - നിങ്ങൾ അവസാനത്തെ പത്തിൽ അന്വേഷിച്ചുകൊള്ളുക. ആർക്കെങ്കിലും അതിനു കഴിഞ്ഞില്ലെങ്കിൽ അവസാനത്തെ ഏഴു ദിവസങ്ങളിൽ അവൻ പരാജിതനാകരുത്." (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 135, 135, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 345, 'عَنْ عَبْدِ اللَّهِ بْنِ أُنَيْسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أُرِيتُ لَيْلَةَ الْقَدْرِ ثُمَّ أُنْسِيتُهَا، وَأَرَانِي صَبِيحَتَهَا أَسْجُدُ فِي مَاءٍ وَطِينٍ". قَالَ: فَمُطِرْنَا لَيْلَةَ ثَلَاثٍ وَعِشْرِينَ، فَصَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَانْصَرَفَ وَإِنَّ أَثَرَ الْمَاءِ وَالطِّينِ عَلَى جَبْهَتِهِ وَأَنْفِهِ. قَالَ: وَكَانَ عَبْدُ اللَّهِ بْنُ أُنَيْسٍ يَقُولُ: ثَلَاثٍ وَعِشْرِينَ. (م)', 'അബ്ദുല്ലാഹിബ്നു ഉനൈസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ലൈലതുൽ ഖദ്ർ എന്നാണെന്ന് എനിക്ക് അറിയിക്കപ്പെട്ടു. പിന്നീട് ഞാനതു മറന്നു. അന്നു രാവിലെ ഞാൻ വെള്ളത്തിലും ചെളിയിലും സുജൂദ് ചെയ്യുന്നത് എനിക്ക് കാണിക്കപ്പെട്ടു." അബ്ദുല്ല(റ) പറയുന്നു: ഇരുപത്തിമൂന്നിനു രാത്രി മഴപെയ്തു. നബി(സ) ഞങ്ങളോടൊപ്പം നിസ്കരിച്ചു തിരിച്ചുപോന്നു. നബിയുടെ മൂക്കിൻമേലും നെറ്റിയിലും വെള്ളവും ചെളിയുമുണ്ടായിരുന്നു. അബ്ദുല്ലാഹിബ്നു ഉനൈസ്(റ) പറയാറുണ്ടായിരുന്നു: ലൈലത്തുൽ ഖദ്ർ ഇരുപത്തിമൂന്നിനാകുന്നു. (മു)', 'عَبْدِ اللَّهِ بْنِ أُنَيْسٍ', 'അബ്ദുല്ലാഹിബ്നു ഉനൈസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 135, 135, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 346, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: اعْتَكَفَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعَشْرَ الْأَوْسَطَ مِنْ رَمَضَانَ، يَلْتَمِسُ لَيْلَةَ الْقَدْرِ قَبْلَ أَنْ تُبَانَ لَهُ، قَالَ: فَلَمَّا انْقَضَيْنَ أَمَرَ بِالْبِنَاءِ فَقُوِّضَ، ثُمَّ أُبِينَتْ لَهُ أَنَّهَا فِي الْعَشْرِ الْأَوَاخِرِ، فَأَمَرَ بِالْبِنَاءِ فَأُعِيدَ، ثُمَّ خَرَجَ عَلَى النَّاسِ فَقَالَ: "يَا أَيُّهَا النَّاسُ، إِنَّهَا كَانَتْ أُبِينَتْ لِي لَيْلَةُ الْقَدْرِ، وَإِنِّي خَرَجْتُ لِأُخْبِرَكُمْ بِهَا، فَجَاءَ رَجُلَانِ يَحْتَقَّانِ مَعَهُمَا الشَّيْطَانُ، فَنُسِّيتُهَا، فَالْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ، الْتَمِسُوهَا فِي التَّاسِعَةِ وَالسَّابِعَةِ وَالْخَامِسَةِ". قَالَ: قُلْتُ: يَا أَبَا سَعِيدٍ إِنَّكُمْ أَعْلَمُ بِالْعَدَدِ مِنَّا. قَالَ: أَجَلْ نَحْنُ أَحَقُّ بِذَلِكَ مِنْكُمْ. قَالَ: قُلْتُ: مَا التَّاسِعَةُ وَالسَّابِعَةُ وَالْخَامِسَةُ؟ قَالَ: إِذَا مَضَتْ وَاحِدَةٌ وَعِشْرُونَ فَالَّتِي تَلِيهَا ثِنْتَانِ وَعِشْرُونَ، فَهِيَ التَّاسِعَةُ. فَإِذَا مَضَتْ ثَلَاثٌ وَعِشْرُونَ فَالَّتِي تَلِيهَا السَّابِعَةُ، فَإِذَا مَضَى خَمْسٌ وَعِشْرُونَ فَالَّتِي تَلِيهَا الْخَامِسَةُ. (م)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ''ലൈലത്തുൽ ഖദ്ർ'' എന്നാണെന്ന് വ്യക്തമാക്കപ്പെടുന്നതിനു മുമ്പ് അതന്വേഷിച്ച് ഒരു റമളാൻ മാസത്തിലെ നടുവിലെ പത്തിൽ നബി(സ) ഇഅ്തികാഫിരുന്നു. നടുവിലെ പത്ത് അവസാനിച്ചപ്പോൾ അവിടത്തെ കൽപനപ്രകാരം തമ്പുകൾ പൊളിച്ചുമാറ്റപ്പെട്ടു. അനന്തരം അത് അവസാനത്തെ പത്തിലാണെന്ന് അവിടത്തേക്ക് വ്യക്തമാക്കപ്പെട്ടു. ഉടനെ തമ്പുകെട്ടാൻ കല്പിക്കുകയും അതു വീണ്ടും നിർമ്മിക്കുകയും ചെയ്തു. പിന്നെ നബി(സ) ജനങ്ങളുടെ അടുക്കലെത്തി. ഇങ്ങനെ പറഞ്ഞു: "ലൈലതുൽ ഖദ്ർ ഏതു രാത്രിയാണെന്ന് എനിക്കു വ്യക്തമാക്കപ്പെട്ടിരിക്കുന്നു. അതു നിങ്ങളെ അറിയിക്കാനാണ് ഞാൻ പുറത്തുവന്നത്. ആ സമയം തർക്കിക്കുന്ന രണ്ടുപേർ വന്നു. അവരോടുകൂടെ പിശാചുമുണ്ടായിരുന്നു. തന്നിമിത്തം ഞാനതു മറന്നുപോയി. അതുകൊണ്ട് നിങ്ങൾ റമളാനിലെ അവസാനത്തെ പത്തിൽ അതിനെ അന്വേഷിക്കുക. ഒമ്പതാം രാത്രിയും ഏഴാം രാത്രിയും അഞ്ചാം രാത്രിയും നിങ്ങൾ അതിനെ അന്വേഷിക്കുക." നിവേദകൻ പറയുന്നു: ഓ, അബൂസഈദ്, എണ്ണത്തെ സംബന്ധിച്ച് നിങ്ങൾക്കാണ് ഞങ്ങളേക്കാൾ അറിവുള്ളത്. അദ്ദേഹം പറഞ്ഞു: അതെ, നിങ്ങളെക്കാൾ അതിനർഹരായവർ ഞങ്ങൾ തന്നെയാണ്. നിവേദകൻ ചോദിച്ചു: ഒമ്പതാം രാവ്, ഏഴാം രാവ്, അഞ്ചാം രാവ് എന്നു പറഞ്ഞാൽ എന്താണ്? അബൂസഈദ്(റ) പറഞ്ഞു: ഇരുപത്തിയൊന്നു കഴിഞ്ഞാൽ അതിനടുത്ത് ഇരുപത്തിരണ്ടു വരും. അതാണ് ഒമ്പതാം രാവ്. ഇരുപത്തിമൂന്നു കഴിഞ്ഞാൽ അതിനോടടുത്ത് വരുന്നതാണ് ഏഴ്. ഇരുപത്തഞ്ച് കഴിഞ്ഞാൽ അതിനോടടുത്ത് വരുന്നതാണ് അഞ്ച്. (ഒമ്പതും, ഏഴും, അഞ്ചും രാവുകൾ അവശേഷിക്കുന്ന രാവുകളാണീ പറഞ്ഞത് കൊണ്ടുള്ള ഉദ്ദേശ്യം). (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 135, 136, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 347, 'عَنْ زِرِّ بْنِ حُبَيْشٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ أُبَيَّ بْنَ كَعْبٍ رَضِيَ اللهُ عَنْهُ فَقُلْتُ: إِنَّ أَخَاكَ ابْنَ مَسْعُودٍ يَقُولُ: مَنْ يَقُمِ الْحَوْلَ يُصِبْ لَيْلَةَ الْقَدْرِ، فَقَالَ: رَحِمَهُ اللَّهُ، أَرَادَ أَنْ لَا يَتَّكِلَ النَّاسُ، أَمَا إِنَّهُ قَدْ عَلِمَ أَنَّهَا فِي رَمَضَانَ، وَأَنَّهَا فِي الْعَشْرِ الْأَوَاخِرِ، وَأَنَّهَا لَيْلَةُ سَبْعٍ وَعِشْرِينَ. ثُمَّ حَلَفَ– لَا يَسْتَثْنِي– أَنَّهَا لَيْلَةُ سَبْعٍ وَعِشْرِينَ. فَقُلْتُ: بِأَيِّ شَيْءٍ تَقُولُ ذَلِكَ يَا أَبَا الْمُنْذِرِ؟ قَالَ: بِالْعَلَامَةِ– أَوْ بِالْآيَةِ– الَّتِي أَخْبَرَنَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا تَطْلُعُ يَوْمَئِذٍ لَا شُعَاعَ لَهَا. (م)', 'സിർറുബ്നു ഹുബൈശ്(റ): ഞാൻ ഉബയ്യുബ്നു കഅ്ബ്(റ)വിനോട് ചോദിച്ചു: നിങ്ങളുടെ സഹോദരൻ ഇബ്നുമസ്ഊദ്(റ) കൊല്ലം മുഴുവൻ രാത്രി നിസ്കരിക്കുന്നവനു ലൈലതുൽ ഖദ്റിന്റെ അനുഗ്രഹം കിട്ടുന്നതാണെന്ന് പറയുന്നു. അപ്പോൾ ഉബയ്യ്(റ) പറഞ്ഞു: അല്ലാഹു അദ്ദേഹത്തിന് കരുണ ചെയ്യട്ടെ. അദ്ദേഹം അങ്ങനെ പറയുന്നത് ജനങ്ങൾ ഒരു ദിവസം മാത്രം ആരാധനയിൽ മുഴുകി മറ്റു ദിവസങ്ങൾ ഉപേക്ഷിക്കാതിരിക്കാൻ വേണ്ടിയാണ്. അതു റമളാനിലെ അവസാനത്തെ പത്തിൽ ഇരുപത്തിയേഴാം രാവിലാണെന്ന് അദ്ദേഹത്തിന് അറിയാം. ശേഷം അതു റമളാൻ ഇരുപത്തിയേഴിനാണ് എന്ന് അദ്ദേഹം സത്യം ചെയ്തു പറഞ്ഞു. അപ്പോൾ ഞാൻ ചോദിച്ചു: നിങ്ങൾ എങ്ങനെയാണ് അത് ഉറപ്പിച്ചുപറയുന്നത്? അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഞങ്ങൾക്ക് അറിയിച്ചുതന്ന അടയാളങ്ങളും തെളിവുകളും അടിസ്ഥാനമാക്കിയാണ് ഞാൻ പറയുന്നത്. അന്ന് സൂര്യൻ കിരണങ്ങളില്ലാതെയാണ് ഉദിക്കുക. (മു)', 'زِرِّ بْنِ حُبَيْشٍ', 'സിർറുബ്നു ഹുബൈശ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 136, 136, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 348, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُجَاوِرُ فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ، وَيَقُولُ: "تَحَرَّوْا لَيْلَةَ الْقَدْرِ فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ". حَسَنٌ صَحِيحٌ. (ت)', 'ആഇശ(റ): നബി(സ) റമളാൻ അവസാനത്തെ പത്തിൽ ആരാധനക്കായി ഒഴിഞ്ഞുനിൽക്കുമായിരുന്നു. "റമളാൻ അവസാനത്തെ പത്തിൽ നിങ്ങൾ ലൈലതുൽ ഖദ്ർ പ്രതീക്ഷിക്കുവിൻ" എന്ന് നബി(സ) പറയാറുണ്ടായിരുന്നു. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 137, 137, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 349, 'عَنْ زِرِّ بْنِ حُبَيْشٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ لِأُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ: إِنِّي عَلِمْتُ– أَبَا الْمُنْذِرِ– أَنَّهَا لَيْلَةُ سَبْعٍ وَعِشْرِينَ؟ قَالَ: بَلَى، أَخْبَرَنَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنَّهَا لَيْلَةٌ، صَبِيحَتُهَا تَطْلُعُ الشَّمْسُ لَيْسَ لَهَا شُعَاعٌ". فَعَدَدْنَا وَحَفِظْنَا، وَاللَّهِ، لَقَدْ عَلِمَ ابْنُ مَسْعُودٍ أَنَّهَا فِي رَمَضَانَ، وَأَنَّهَا لَيْلَةُ سَبْعٍ وَعِشْرِينَ، وَلَكِنْ كَرِهَ أَنْ يُخْبِرَكُمْ فَتَتَّكِلُوا. حَسَنٌ صَحِيحٌ. (م,د,ت)', 'സിർറുബ്നു ഹുബൈശ്(റ): ഞാൻ ഉബയ്യുബ്നു കഅ്ബ്(റ)വിനോട് ചോദിച്ചു: അബുൽമുൻദിർ, ലൈലത്തുൽ ഖദ്ർ ഇരുപത്തിഏഴാം രാവിലല്ലേ? അദ്ദേഹം പറഞ്ഞു: അതെ, ഞങ്ങളോട് റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "ആ രാവിന്റെ പ്രഭാതത്തിലുദിക്കുന്ന സൂര്യന് കിരണങ്ങളുണ്ടാവില്ല." ആയതിനാൽ ഞങ്ങൾ ആ കാര്യം എണ്ണി നിശ്ചയിക്കുകയും സൂക്ഷ്മമായി മനസ്സിലാക്കുകയും ചെയ്തു. അദ്ദേഹം പറയുന്നു: അല്ലാഹുവാണ്, ഇബ്നുമസ്ഊദ്(റ) ഈ രാത്രി റമളാനിലാണെന്നും ഇരുപത്തിഏഴാം രാവിലാണെന്നും അറിഞ്ഞിട്ടുണ്ട്. എങ്കിലും നിങ്ങളോട് അതു തുറന്ന് പറയാൻ അദ്ദേഹം ഇഷ്ടപ്പെട്ടില്ല. കാരണം നിങ്ങൾ അങ്ങനെ മാത്രം കൈക്കൊള്ളാൻ സാധ്യതയുള്ളതിനാലാണ് അങ്ങനെ പറഞ്ഞത്. (മു,ദ,തു)', 'زِرِّ بْنِ حُبَيْشٍ', 'സിർറുബ്നു ഹുബൈശ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 137, 137, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 350, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ، وَذُكِرَتْ لَيْلَةُ الْقَدْرِ عِنْدَهُ، فَقَالَ: مَا أَنَا مُلْتَمِسُهَا– لِشَيْءٍ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ– إِلَّا فِي الْعَشْرِ الْأَوَاخِرِ، فَإِنِّي سَمِعْتُهُ يَقُولُ: "الْتَمِسُوهَا فِي تِسْعٍ يَبْقَيْنَ، أَوْ فِي سَبْعٍ يَبْقَيْنَ، أَوْ فِي خَمْسٍ يَبْقَيْنَ، أَوْ فِي ثَلَاثِ أَوَاخِرِ لَيْلَةٍ". قَالَ: وَكَانَ أَبُو بَكْرَةَ يُصَلِّي فِي الْعِشْرِينَ مِنْ رَمَضَانَ كَصَلَاتِهِ فِي سَائِرِ السَّنَةِ، فَإِذَا دَخَلَ الْعَشْرُ اجْتَهَدَ. حَسَنٌ صَحِيحٌ. (ت)', 'അബുബക്റത്(റ): ലൈലത്തുൽ ഖദ്റിനെപറ്റി പരാമർശിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)യിൽ നിന്നു കേട്ട ഒരുകാര്യം നിമിത്തമായി ഞാൻ അതിനെ അവസാനത്തെ പത്തിലല്ലാതെ പ്രതീക്ഷിക്കാറില്ല. നബി(സ) പറയുന്നതു ഞാൻ കേട്ടിട്ടുണ്ട്. "ലൈലത്തുൽ ഖദ്റിനെ നിങ്ങൾ അഞ്ചോ ഏഴോ ഒമ്പതോ ശേഷിക്കുന്ന അവസരങ്ങളിൽ പ്രതീക്ഷിക്കുക, (ഇരുപത്തി ഒന്നാം രാവിലോ, ഇരുപത്തിമൂന്നാം രാവിലേ, ഇരുപത്തിയഞ്ചാം രാവിലോ എന്നർത്ഥം.) അല്ലെങ്കിൽ അവസാനത്തെ മൂന്നു ദിവസങ്ങളിൽ പ്രതീക്ഷിച്ചുകൊള്ളുക." നിവേദകൻ പറയുന്നു: റമളാൻ ഇരുപതുവരെ കൊല്ലത്തിൽ മറ്റു ദിവസങ്ങളെപ്പോലെ അബൂബക്ർ(റ) നിസ്ക്കരിക്കും. എന്നാൽ അവസാനത്തെ പത്തായാൽ അദ്ദേഹം പരിശ്രമിക്കും. (തു)', 'أَبِي بَكْرَةَ', 'അബുബക്റത്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 137, 137, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 351, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَعْتَكِفُ الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ حَتَّى قَبَضَهُ اللَّهُ، ثُمَّ اعْتَكَفَ أَزْوَاجُهُ مِنْ بَعْدِهِ. (ق,د,ت)', 'ആഇശ(റ): തന്റെ വിയോഗം വരെ റമളാനിലെ അവസാനത്തെ പത്തിൽ നബി(സ) ഇഅ്തികാഫിരിക്കാറുണ്ട് (ഭജനമിരിക്കുക). അവിടത്തെ ശേഷം തന്റെ ഭാര്യമാരും ഇഅ്തികാഫിരിക്കാറുണ്ട്. (ബു,ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 137, 138, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 352, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَعْتَكِفُ الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ، فَلَمْ يَعْتَكِفْ عَامًا، فَلَمَّا كَانَ فِي الْعَامِ الْمُقْبِلِ اعْتَكَفَ عِشْرِينَ لَيْلَةً. (د,جه)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): നിശ്ചയം നബി(സ) റമളാനിലെ അവസാന പത്തു ദിനങ്ങളിൽ ഭജനമിരിക്കാറുണ്ട്. ഒരു വർഷം നബി(സ) ഭജനമിരുന്നില്ല. അങ്ങനെ അടുത്ത വർഷം അവിടന്ന് ഇരുപത് രാത്രികളിൽ ഭജനമിരുന്നു. (ദ,ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 138, 138, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 353, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعْتَكِفُ كُلَّ عَامٍ عَشْرَةَ أَيَّامٍ، فَلَمَّا كَانَ الْعَامُ الَّذِي قُبِضَ فِيهِ اعْتَكَفَ عِشْرِينَ يَوْمًا. وَكَانَ يُعْرَضُ عَلَيْهِ الْقُرْآنُ فِي كُلِّ عَامٍ مَرَّةً، فَلَمَّا كَانَ الْعَامُ الَّذِي قُبِضَ فِيهِ عُرِضَ عَلَيْهِ مَرَّتَيْنِ. (خ,د,جه)', 'അബൂഹുറൈറ(റ): എല്ലാ വർഷവും നബി(സ) പത്തുദിവസം ഇഅ്തികാഫിരിക്കും. അവിടത്തെ വഫാത്ത് നടന്ന കൊല്ലം അവിടന്ന് ഇരുപതു ദിവസം ഇഅ്തികാഫിരുന്നു. ഓരോ കൊല്ലത്തിലും ഒരു പ്രാവശ്യം നബി(സ)യ്ക്കു ഖുർആൻ വെളിവാക്കപ്പെടും. വിയോഗം നടന്ന വർഷത്തിൽ നബി(സ)ക്കു രണ്ട് തവണ ഖുർആൻ വെളിപ്പെടുത്തപ്പെടുകയുണ്ടായി. (ബു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 138, 138, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 354, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ أَنَّهُ سَأَلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُنْتُ نَذَرْتُ فِي الْجَاهِلِيَّةِ أَنْ أَعْتَكِفَ لَيْلَةً فِي الْمَسْجِدِ الْحَرَامِ؟ قَالَ: "فَأَوْفِ بِنَذْرِكَ". (ق,د,ت,ن,جه)', 'ഉമർ(റ): അദ്ദേഹം നബി(സ)യോടു ചോദിച്ചു: ഞാൻ ജാഹിലിയ്യാ കാലത്ത് മസ്ജിദുൽ ഹറാമിൽ ഒരു രാത്രി ഇഅ്തികാഫിരിക്കാൻ നേർച്ചയാക്കിയിരുന്നു? നബി(സ) പറഞ്ഞു: "നിന്റെ നേർച്ച വീട്ടിക്കൊള്ളുക." (ബു,മു,ദ,തു,ന,ജ)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 138, 138, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 355, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ أَنْ يَعْتَكِفَ صَلَّى الصُّبْحَ، ثُمَّ دَخَلَ الْمَكَانَ الَّذِي يُرِيدُ أَنْ يَعْتَكِفَ فِيهِ. فَأَرَادَ أَنْ يَعْتَكِفَ الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ، فَأَمَرَ، فَضُرِبَ لَهُ خِبَاءٌ، فَأَمَرَتْ عَائِشَةُ بِخِبَاءٍ فَضُرِبَ لَهَا، وَأَمَرَتْ حَفْصَةُ بِخِبَاءٍ فَضُرِبَ لَهَا، فَلَمَّا رَأَتْ زَيْنَبُ خِبَاءَهُمَا أَمَرَتْ بِخِبَاءٍ فَضُرِبَ لَهَا، فَلَمَّا رَأَى ذَلِكَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "آلْبِرَّ تُرِدْنَ". فَلَمْ يَعْتَكِفْ فِي رَمَضَانَ، وَاعْتَكَفَ عَشْرًا مِنْ شَوَّالٍ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ) ഇഅ്തികാഫിരിക്കാൻ ഉദ്ദേശിച്ചാൽ സുബ്ഹി നിസ്കരിച്ചു ഇഅ്തികാഫിരിക്കുന്നിടത്തേയ്ക്കു കടന്നിരിക്കുകയാണു ചെയ്തിരുന്നത്. അങ്ങനെ റമളാൻ അവസാനത്തെ പത്തിൽ നബി(സ) ഇഅ്തികാഫിരിക്കാൻ ഉദ്ദേശിച്ചപ്പോൾ കൽപ്പനയനുസരിച്ച് ഒരു തമ്പ് നിർമ്മിക്കപ്പെട്ടു. അപ്പോൾ ആഇശ(റ)യും ഒരു തമ്പു കെട്ടാൻ കൽപ്പിച്ചു. അതു നിർമ്മിക്കപ്പെടുകയും ചെയ്തു. ഹഫ്സ(റ)യും ഒരു തമ്പു കെട്ടിച്ചു. സൈനബ(റ) ഇതുകണ്ടപ്പോൾ തനിക്കും ഒരു തമ്പു കെട്ടിച്ചു. നബി(സ) ഇതു കണ്ടപ്പോൾ "ഗുണമാണോ ഇവരുദ്ദേശിക്കുന്നത്?" എന്നു ചോദിച്ചു. ആ റമളാനിൽ നബി(സ) ഇഅ്തികാഫിരുന്നില്ല. പിന്നെ ശവ്വാൽ പത്ത്ദിനങ്ങളിലാണ് നബി(സ) ഇഅ്തികാഫിരുന്നത്. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 138, 139, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 356, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعْتَكِفُ فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ، فَلَمْ يَعْتَكِفْ عَامًا، فَلَمَّا كَانَ فِي الْعَامِ الْمُقْبِلِ اعْتَكَفَ عِشْرِينَ. (ت)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) റമളാനിലെ അവസാന പത്തിൽ ഇഅ്തികാഫ് ഇരിക്കാറുണ്ട്. എന്നാൽ ഒരുവർഷം അപ്രകാരം ചെയ്തില്ല. അടുത്തവർഷം ഇരുപത് ദിവസം ഇഅ്തികാഫ് ഇരിക്കുകയുണ്ടായി. (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 139, 139, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 357, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اعْتَكَفَ الْعَشْرَ الْأَوَّلَ مِنْ رَمَضَانَ، ثُمَّ اعْتَكَفَ الْعَشْرَ الْأَوْسَطَ فِي قُبَّةٍ تُرْكِيَّةٍ عَلَى سُدَّتِهَا حَصِيرٌ. قَالَ: فَأَخَذَ الْحَصِيرَ بِيَدِهِ فَنَحَّاهَا فِي نَاحِيَةِ الْقُبَّةِ، ثُمَّ أَطْلَعَ رَأْسَهُ فَكَلَّمَ النَّاسَ فَدَنَوْا مِنْهُ، فَقَالَ: "إِنِّي اعْتَكَفْتُ الْعَشْرَ الْأَوَّلَ، أَلْتَمِسُ هَذِهِ اللَّيْلَةَ، ثُمَّ اعْتَكَفْتُ الْعَشْرَ الْأَوْسَطَ، ثُمَّ أُتِيتُ فَقِيلَ لِي: إِنَّهَا فِي الْعَشْرِ الْأَوَاخِرِ، فَمَنْ أَحَبَّ مِنْكُمْ أَنْ يَعْتَكِفَ، فَلْيَعْتَكِفْ". فَاعْتَكَفَ النَّاسُ مَعَهُ، قَالَ: "وَإِنِّي أُرِيتُهَا لَيْلَةَ وِتْرٍ، وَإِنِّي أَسْجُدُ صَبِيحَتَهَا فِي طِينٍ وَمَاءٍ". فَأَصْبَحَ مِنْ لَيْلَةِ إِحْدَى وَعِشْرِينَ، وَقَدْ قَامَ إِلَى الصُّبْحِ، فَمَطَرَتِ السَّمَاءُ، فَوَكَفَ الْمَسْجِدُ، فَأَبْصَرْتُ الطِّينَ وَالْمَاءَ، فَخَرَجَ حِينَ فَرَغَ مِنْ صَلَاةِ الصُّبْحِ، وَجَبِينُهُ وَرَوْثَةُ أَنْفِهِ فِيهِمَا الطِّينُ وَالْمَاءُ، وَإِذَا هِيَ لَيْلَةُ إِحْدَى وَعِشْرِينَ مِنَ الْعَشْرِ الْأَوَاخِرِ. (م)', 'അബൂസഈദുൽ ഖുദ്രി(റ): റമളാനിലെ ആദ്യപത്തിൽ നബി(സ) ഇഅ്തികാഫ് ഇരുന്നു. പിന്നെ നടുവിലെ പത്തിൽ ഒരു തുർക്കീഖുബ്ബയിൽ നബി (സ) ഇഅ്തികാഫ് ഇരുന്നു. അതിന്റെ വാതിലിൽ ഒരു പായയുണ്ടായിരുന്നു. നബി(സ) പായ കൈകൊണ്ടു എടുത്ത് ഖുബ്ബയുടെ ഒരു ഭാഗത്തേക്കു മാറ്റി പിന്നെ തല പുറത്തുകാട്ടി ജനങ്ങളോട് സംസാരിച്ചു. അപ്പോൾ അവർ നബി (സ)യുടെ അടുത്ത് വന്നു. അങ്ങനെ നബി(സ) പറഞ്ഞു: "ഈ രാത്രിയെ പ്രതീക്ഷിച്ച്, ഒന്നാം പത്തിൽ ഞാൻ ഇഅ്തികാഫ് ഇരുന്നു. പിന്നെ ഞാൻ നടുവിലെ പത്തിലും ഇഅ്തികാഫ് ഇരുന്നു. പിന്നെ എനിക്ക് അറിയിക്കപ്പെട്ടു: അത് അവസാന പത്തിലാണെന്ന്. അത്കൊണ്ട് നിങ്ങളിൽ ആരെങ്കിലും ഇഅ്തികാഫ് ഇരിക്കാൻ ഇഷ്ടപ്പെടുന്നെങ്കിൽ ഇഅ്തികാഫ് ഇരുന്നുകൊള്ളുക." അങ്ങനെ ജനങ്ങൾ നബി(സ)യോടൊപ്പം ഇഅ്തികാഫ് ഇരുന്നു. നബി(സ) പറഞ്ഞു: "ഒറ്റപ്പെട്ട രാത്രിയാണ് അതെന്ന് എനിക്കറിയിക്കപ്പെട്ടു. അതിന്റെ പ്രഭാതത്തിൽ ഞാൻ വെള്ളത്തിലും ചെളിയിലും സുജൂദ് ചെയ്യുമെന്നും." അങ്ങനെ ഇരുപത്തിയൊന്നാം രാവ് പുലർന്നു. നബി(സ) സുബ്ഹി നിസ്കരിക്കാൻ നിന്നു. അപ്പോൾ മഴ വർഷിച്ചു. പള്ളിയാകെ നിറഞ്ഞൊലിച്ചു. വെള്ളവും ചെളിയും കാണാൻ തുടങ്ങി. സുബ്ഹി കഴിഞ്ഞ ഉടനെ നബി(സ) പുറപ്പെട്ടു. അവിടത്തെ മൂക്കിൻമേലും നെറ്റിയിലും വെള്ളവും ചെളിയുമുണ്ടായിരുന്നു. അത് അവസാനത്തെ പത്തിലെ ഇരുപത്തിയൊന്നാം രാവിലായിരുന്നു. (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 139, 139, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 358, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَرَادَ أَنْ يَعْتَكِفَ، فَلَمَّا انْصَرَفَ إِلَى الْمَكَانِ الَّذِي أَرَادَ أَنْ يَعْتَكِفَ فِيهِ إِذَا أَخْبِيَةٌ، خِبَاءُ عَائِشَةَ، وَخِبَاءُ حَفْصَةَ، وَخِبَاءُ زَيْنَبَ، فَقَالَ: "أَالْبِرَّ تَقُولُونَ بِهِنَّ؟". ثُمَّ انْصَرَفَ فَلَمْ يَعْتَكِفْ حَتَّى اعْتَكَفَ عَشْرًا مِنْ شَوَّالٍ. (خ)', 'ആഇശ(റ): നബി(സ) ഇഅ്തികാഫിരിക്കാൻ ഉദ്ദേശിച്ചു. നബി(സ) ഇരിക്കാൻ ഉദ്ദേശിച്ച സ്ഥലത്തേക്ക് തിരിഞ്ഞപ്പോൾ അവിടങ്ങളിൽ ആഇശ(റ), ഹഫ്സ(റ), സൈനബ്(റ) എന്നിവരുടെ കൂടാരങ്ങളുണ്ട്. അന്നേരം നബി(സ) "ഈ കാര്യം നന്മയാണെന്ന് കരുതുന്നോ?" എന്ന് ചോദിച്ച് ഇഅ്തികാഫ് ഇരിക്കാതെ തിരിഞ്ഞു പോയി. പിന്നീട് ശവ്വാലിൽ പത്ത് ദിവസം ഇഅ്തികാഫിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 140, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 359, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَعْتَكِفُ الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ، قَالَ نَافِعٌ: وَقَدْ أَرَانِي عَبْدُ اللَّهِ الْمَكَانَ الَّذِي كَانَ يَعْتَكِفُ فِيهِ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ. (ق,د,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) റമളാനിലെ അവസാന പത്തിൽ ഇഅ്തികാഫിരിക്കാറുണ്ട്. നാഫിഅ് പറയുന്നു: അബ്ദുല്ല(റ) നബി(സ) ഇരുന്നിരുന്ന പള്ളിയിലെ സ്ഥലം എനിക്ക് കാണിച്ചു തന്നു. (ബു,മു,ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 140, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 360, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ إِذَا اعْتَكَفَ طُرِحَ لَهُ فِرَاشُهُ– أَوْ يُوضَعُ لَهُ سَرِيرُهُ– وَرَاءَ أُسْطُوَانَةِ التَّوْبَةِ. (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) ഇഅ്തികാഫ് ഇരുന്നാൽ ''തൗബ'' തൂണിന് പിന്നിൽ അവിടത്തെ വിരിപ്പ് വിരിക്കുകയോ അല്ലെങ്കിൽ അവിടത്തെ കട്ടിൽ അവിടെ കൊണ്ടിടുകയോ ചെയ്യാറുണ്ടായിരുന്നു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 140, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 361, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: وَإِنْ كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيُدْخِلُ عَلَيَّ رَأْسَهُ وَهُوَ فِي الْمَسْجِدِ فَأُرَجِّلُهُ، وَكَانَ لَا يَدْخُلُ الْبَيْتَ إِلَّا لِحَاجَةٍ إِذَا كَانَ مُعْتَكِفًا. (خ)', 'ആഇശ(റ): നബി(സ) പള്ളിയിലായിരിക്കെ എന്റെ അടുത്തേക്ക് തല നീട്ടിത്തരികയും ഞാൻ ചീകിക്കൊടുക്കുകയും ചെയ്യാറുണ്ട്. നബി(സ) ഇഅ്തികാഫിരിക്കുമ്പോൾ എന്തെങ്കിലും ആവശ്യത്തിനല്ലാതെ വീട്ടിലേക്ക് പ്രവേശിക്കാറില്ല. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 140, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 362, 'عَنْ صَفِيَّةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا جَاءَتْ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَزُورُهُ فِي اعْتِكَافِهِ فِي الْمَسْجِدِ فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ فَتَحَدَّثَتْ عِنْدَهُ سَاعَةً، ثُمَّ قَامَتْ تَنْقَلِبُ، فَقَامَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَعَهَا يَقْلِبُهَا، حَتَّى إِذَا بَلَغَتْ بَابَ الْمَسْجِدِ عِنْدَ بَابِ أُمِّ سَلَمَةَ، مَرَّ رَجُلَانِ مِنَ الْأَنْصَارِ فَسَلَّمَا عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُمَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَى رِسْلِكُمَا إِنَّمَا هِيَ صَفِيَّةُ بِنْتُ حُيَيٍّ"، فَقَالَا: سُبْحَانَ اللَّهِ يَا رَسُولَ اللَّهِ وَكَبُرَ عَلَيْهِمَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الشَّيْطَانَ يَبْلُغُ مِنَ الْإِنْسَانِ مَبْلَغَ الدَّمِ وَإِنِّي خَشِيتُ أَنْ يَقْذِفَ فِي قُلُوبِكُمَا شَيْئًا". (ق,د,جه)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=362), 1, 'وَفِي رِوَايَةٍ لِابْنِ مَاجَه: وَكَانَ مَسْكَنُهَا (حَفْصَةَ رَضِيَ اللهُ عَنْهَا) فِي دَارِ أُسَامَةَ بْنِ زَيْدٍ. (جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 363, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا اعْتَكَفَ يُدْنِي إِلَيَّ رَأْسَهُ فَأُرَجِّلُهُ، وَكَانَ لَا يَدْخُلُ الْبَيْتَ إِلَّا لِحَاجَةِ الْإِنْسَانِ. وَفِي رِوَايَةٍ: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَكُونُ مُعْتَكِفًا فِي الْمَسْجِدِ، فَيُنَاوِلُنِي رَأْسَهُ مِنْ خَلَلِ الْحُجْرَةِ فَأَغْسِلُ رَأْسَهُ، وَفِي رِوَايَةٍ: فَأُرَجِّلُهُ، وَأَنَا حَائِضٌ. (ق,د,ن,جه)', 'ആഇശ(റ): നബി(സ) ഇഅ്തികാഫിരുന്നാൽ എന്റെയടുത്തേയ്ക്കു തല നീട്ടി വെക്കുകയും ഞാൻ നബി(സ)യുടെ മുടി ചീകിക്കൊടുക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. പ്രാഥമിക കാര്യങ്ങൾക്കു മാത്രമേ നബി(സ) വീട്ടിൽ പ്രവേശിക്കാറുണ്ടായിരുന്നുള്ളു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=363), 1, 'وَفِي رِوَايَةٍ: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَكُونُ مُعْتَكِفًا فِي الْمَسْجِدِ، فَيُنَاوِلُنِي رَأْسَهُ مِنْ خَلَلِ الْحُجْرَةِ فَأَغْسِلُ رَأْسَهُ،', 'മറ്റൊരു നിവേദനം: നബി(സ) പള്ളിയിൽ ഇഅ്തികാഫിരിക്കുകയായിരിക്കും. നബി(സ) തന്റെ തല മുറിയുടെ ഒരു വിടവിലൂടെ നീട്ടിത്തരുകയും ഞാൻ തല കഴുകിക്കൊടുക്കുകയും ചെയ്യുമായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=363), 2, 'وَفِي رِوَايَةٍ: فَأُرَجِّلُهُ، وَأَنَا حَائِضٌ. (ق,د,ن,جه)', 'മറ്റൊരു നിവേദനം: ഞാൻ ആർത്തവകാരിയായിരിക്കെ മുടി ചീകിക്കൊടുക്കുമായിരുന്നു. (ബു,മു,ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 364, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اعْتَكَفَ فِي قُبَّةٍ تُرْكِيَّةٍ، عَلَى سُدَّتِهَا قِطْعَةُ حَصِيرٍ. قَالَ: فَأَخَذَ الْحَصِيرَ بِيَدِهِ فَنَحَّاهَا فِي نَاحِيَةِ الْقُبَّةِ، ثُمَّ أَطْلَعَ رَأْسَهُ فَكَلَّمَ النَّاسَ. (جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഒരു തുർക്കി ഖുബ്ബയിൽ നബി(സ) ഇഅ്തികാഫിരുന്നു. അതിന്റെ വാതിലിൽ ഒരു പായക്കഷണമുണ്ടായിരുന്നു. അദ്ദേഹം പറയുന്നു: നബി(സ) പായയെടുത്ത് ഖുബ്ബയുടെ ഒരു ഭാഗത്തേക്കു മാറ്റിവെച്ചു. എന്നിട്ട് തല പുറത്തുകാട്ടി ജനങ്ങളോടു സംസാരിച്ചു. (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 141, 141, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 365, 'عَنْ صَفِيَّةَ بِنْتِ حُيَيٍّ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهَا جَاءَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَزُورُهُ، وَهُوَ مُعْتَكِفٌ فِي الْمَسْجِدِ، فِي الْعَشْرِ الْأَوَاخِرِ مِنْ شَهْرِ رَمَضَانَ. فَتَحَدَّثَتْ عِنْدَهُ سَاعَةً مِنَ الْعِشَاءِ، ثُمَّ قَامَتْ تَنْقَلِبُ، فَقَامَ مَعَهَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْلِبُهَا، حَتَّى إِذَا بَلَغَتْ بَابَ الْمَسْجِدِ الَّذِي كَانَ عِنْدَ مَسْكَنِ أُمِّ سَلَمَةَ، زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَمَرَّ بِهِمَا رَجُلَانِ مِنَ الْأَنْصَارِ، فَسَلَّمَا عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ نَفَذَا، فَقَالَ لَهُمَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَى رِسْلِكُمَا، إِنَّهَا صَفِيَّةُ بِنْتُ حُيَيٍّ". قَالَا: سُبْحَانَ اللَّهِ يَا رَسُولَ اللَّهِ. وَكَبُرَ عَلَيْهِمَا ذَلِكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الشَّيْطَانَ يَجْرِي مِنِ ابْنِ آدَمَ مَجْرَى الدَّمِ، وَإِنِّي خَشِيتُ أَنْ يَقْذِفَ فِي قُلُوبِكُمَا شَيْئًا". (ق,د,جه)', 'നബി(സ)യുടെ ഭാര്യ സ്വഫിയ്യബിൻത് ഹുയയ്യ്(റ): റസൂൽ(സ) റമസാൻ മാസം അവസാനത്തെ പത്തിൽ പള്ളിയിൽ ഇഅ്തികാഫിരിക്കുമ്പോൾ അവർ നബി(സ)യെ കാണാൻ ചെന്നു. ഇശാ സമയം ഒത്തിരി നേരം നബി(സ)യോട് സംസാരിച്ചിട്ട് അവർ പോകാൻ എണീറ്റു. പറഞ്ഞയക്കാൻ നബി(സ) അവരോടൊപ്പം വന്നു. നബി(സ)യുടെ മറ്റൊരു ഭാര്യയായ ഉമ്മുസലമ(റ)യുടെ വീടിനടുത്തുള്ള, പള്ളിയുടെ വാതിലുവരെ അവർ എത്തി. അപ്പോൾ അൻസാരികളിൽ പെട്ട രണ്ടുപേർ ആ വഴിവന്നു. അവരിരുപേരും നബി(സ)യോട് സലാം ചൊല്ലി വേഗം കടന്നുപോവുകയായിരുന്നു. അപ്പോൾ നബി(സ) അവരെ വിളിച്ചു പറഞ്ഞു: "ഏയ് നിൽക്കൂ, ഇതു ഹുയയ്യിന്റെ മകൾ സ്വഫിയ്യ(റ)യാണ്". അവരിരുവരും പറഞ്ഞു: സുബ്ഹാനല്ലാഹ്! അല്ലാഹുവിന്റെ റസൂലെ. നബി(സ) പറഞ്ഞത് അവരെ വിഷമിപ്പിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "പിശാച് മനുഷ്യ ശരീരത്തിൽ രക്തം നടക്കുന്നിടത്തൊക്കെ നടക്കും. നിങ്ങളുടെ ഹൃദയങ്ങളിൽ അവനെന്തെങ്കിലും തോന്നിപ്പിക്കുമോയെന്ന് ഞാൻ പേടിച്ചു". (ബു,മു,ദ,ജ)', 'صَفِيَّةَ بِنْتِ حُيَيٍّ', 'നബി(സ)യുടെ ഭാര്യ സ്വഫിയ്യബിൻത് ഹുയയ്യ്(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 141, 142, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 366, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَمُرُّ بِالْمَرِيضِ وَهُوَ مُعْتَكِفٌ، فَيَمُرُّ كَمَا هُوَ، وَلَا يُعَرِّجُ، يَسْأَلُ عَنْهُ. وَفِي رِوَايَةٍ: قَالَتْ: إِنْ كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُ الْمَرِيضَ وَهُوَ مُعْتَكِفٌ. (د)', 'ആഇശ(റ): ഇഅ്തികാഫിരിക്കെ നബി(സ) രോഗിയുടെ അടുത്തുകൂടെ നടന്നുപോകും. തിരുമേനി(സ) അതുപോലെ തന്നെ നടക്കും. രോഗിയെക്കുറിച്ച് അന്വേഷിക്കാൻ അവിടെ നിൽക്കില്ല. മറ്റൊരു റിപ്പോർട്ട്: ഇഅ്തികാഫിരിക്കെ നബി(സ) രോഗികളെ സന്ദർശിക്കാറുണ്ട്. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 142, 142, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=366), 1, 'وَفِي رِوَايَةٍ: قَالَتْ: إِنْ كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُ الْمَرِيضَ وَهُوَ مُعْتَكِفٌ. (د)', 'മറ്റൊരു നിവേദന്: ഇഅ്തികാഫിരിക്കെ നബി(സ) രോഗികളെ സന്ദർശിക്കാറുണ്ട്. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 367, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: السُّنَّةُ عَلَى الْمُعْتَكِفِ أَنْ لَا يَعُودَ مَرِيضًا، وَلَا يَشْهَدَ جَنَازَةً، وَلَا يَمَسَّ امْرَأَةً وَلَا يُبَاشِرَهَا، وَلَا يَخْرُجَ لِحَاجَةٍ إِلَّا لِمَا لَا بُدَّ مِنْهُ، وَلَا اعْتِكَافَ إِلَّا بِصَوْمٍ، وَلَا اعْتِكَافَ إِلَّا فِي مَسْجِدٍ جَامِعٍ. (د,ن)', 'ആഇശ(റ): അത്യാവശ്യ കാര്യങ്ങൾക്കല്ലാതെ പുറത്തുപോകാതിരിക്കലും സ്ത്രീയെ തൊടാതിരിക്കലും സുഖാനുഭൂതിയിലേർപ്പെടാതിരിക്കലും ജനാസയിൽ പങ്കെടുക്കാതിരിക്കലും രോഗിയെ സന്ദർശിക്കാതിരിക്കലുമാണ് ഇഅ്തികാഫ് ഇരിക്കുന്നവന് സുന്നത്ത്. നോമ്പുകൊണ്ടല്ലാതെ ഇഅ്തികാഫ് ഇല്ല. ജുമുഅ നടത്തപ്പെടുന്ന പള്ളിയിലല്ലാതെ ഇഅ്തികാഫും ഇല്ല. (ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 142, 142, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 368, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ عُمَرَ رَضِيَ اللهُ عَنْهُ جَعَلَ عَلَيْهِ أَنْ يَعْتَكِفَ فِي الْجَاهِلِيَّةِ لَيْلَةً– أَوْ يَوْمًا– عِنْدَ الْكَعْبَةِ، فَسَأَلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "اعْتَكِفْ وَصُمْ". وَفِي رِوَايَةٍ: فَبَيْنَمَا هُوَ مُعْتَكِفٌ إِذْ كَبَّرَ النَّاسُ فَقَالَ: مَا هَذَا يَا عَبْدَ اللَّهِ؟ قَالَ: سَبْيُ هَوَازِنَ، أَعْتَقَهُمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ: وَتِلْكَ الْجَارِيَةُ، فَأَرْسَلَهَا مَعَهُمْ. (ق,د,ت,ن)', 'ഇബ്നുഉമർ(റ): ജാഹിലിയ്യാകാലത്ത്, ഒരു രാത്രി അല്ലെങ്കിൽ ഒരു പകൽ കഅ്ബക്കരികെ ഇഅ്തികാഫിരിക്കാൻ ഉമർ(റ) നേർച്ചയാക്കിയിരുന്നു. ഇതേക്കുറിച്ചദ്ദേഹം പ്രവാചകരോടു ചോദിച്ചപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "താങ്കൾ നോമ്പെടുക്കുകയും ഭജനമിരിക്കുകയും ചെയ്യുക."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=2 and h.hadith_no=368), 1, 'وَفِي رِوَايَةٍ: فَبَيْنَمَا هُوَ مُعْتَكِفٌ إِذْ كَبَّرَ النَّاسُ فَقَالَ: مَا هَذَا يَا عَبْدَ اللَّهِ؟ قَالَ: سَبْيُ هَوَازِنَ، أَعْتَقَهُمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ: وَتِلْكَ الْجَارِيَةُ، فَأَرْسَلَهَا مَعَهُمْ. (ق,د,ت,ن)', 'മറ്റൊരു നിവേദനം: ഉമർ(റ) ഇഅ്തികാഫ് ഇരിക്കെ ജനങ്ങൾ ഉച്ചത്തിൽ തക്ബീർ ചൊല്ലി. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: അബ്ദുല്ലാ, ഇതെന്താണ്? ഇബ്നുഉമർ(റ) പറഞ്ഞു: പ്രവാചകർ(സ) മോചിപ്പിച്ച ''ഹവാസിൻ'' ഗോത്രത്തിലെ അടിമകളാണിവർ. ഉമർ(റ) പറഞ്ഞു: എന്നാൽ ഈ അടിമപ്പെൺകുട്ടിയും അങ്ങനെയിരിക്കട്ടെ (ഹവാസിനിലെ ഒരു പെൺകുട്ടി ഉമർ(റ)വിന്റെ അടിമയായിരുന്നു). അങ്ങനെ ഉമർ(റ) ആ പെൺകുട്ടിയെ അവരോടൊപ്പം പറഞ്ഞയച്ചു. (ബു,മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 369, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنْ كُنْتُ لَأَدْخُلُ الْبَيْتَ لِلْحَاجَةِ، وَالْمَرِيضُ فِيهِ، فَمَا أَسْأَلُ عَنْهُ إِلَّا وَأَنَا مَارَّةٌ. قَالَتْ: وَكَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يَدْخُلُ الْبَيْتَ إِلَّا لِحَاجَةٍ، إِذَا كَانُوا مُعْتَكِفِينَ. (ق,د,ت,جه)', 'ആഇശ(റ): ഞാനെന്തെങ്കിലും ആവശ്യത്തിന് വീട്ടിൽ പ്രവേശിക്കാറില്ല. അവിടെ ഒരു രോഗിയുണ്ടായാൽ, ഞാൻ നടന്നിട്ടല്ലാതെ രോഗിയെക്കുറിച്ച് അന്വേഷിക്കാറില്ല. മഹതി പറയുന്നു: നബി(സ) ഭജനമിരിക്കുന്നതിനിടയിൽ അവിടന്ന് ആവശ്യത്തിനല്ലാതെ വീട്ടിൽ പ്രവേശിക്കാറില്ല. (ബു,മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 143, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 370, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمُعْتَكِفُ يَتْبَعُ الْجِنَازَةَ، وَيَعُودُ الْمَرِيضَ". [ز: إِسْنَادُهُ ضَعِيفٌ، وَمُخَالِفٌ لِمَا رَوَاهُ الثِّقَاتُ] (جه)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇഅ്തികാഫിരിക്കുന്നവൻ ജനാസയെ പിന്തുടരാം. രോഗികളെ സന്ദർശിക്കുകയും ചെയ്യാം." (പരമ്പരയിൽ ദൗർബല്യമുണ്ട്, മാത്രമല്ല വിശ്വസ്ഥർ നിവേദനം ചെയ്ത ഹദീസുമായി ഇത് എതിരാണ്.) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: إِسْنَادُهُ ضَعِيفٌ، وَمُخَالِفٌ لِمَا رَوَاهُ الثِّقَاتُ', null, 143, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 371, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُدْنِي إِلَيَّ رَأْسَهُ وَهُوَ مُجَاوِرٌ، فَأَغْسِلُهُ وَأُرَجِّلُهُ وَأَنَا فِي حُجْرَتِي، وَأَنَا حَائِضٌ، وَهُوَ فِي الْمَسْجِدِ. (جه)', 'ആഇശ(റ): ആർത്തവമുള്ള നിലയിൽ ഞാനെന്റെ റൂമിലിരിക്കുമ്പോൾ പള്ളിയിൽ ഇരിക്കുന്ന നബി(സ) എന്നിലേക്ക് തലനീട്ടിത്തരികയും ഞാൻ മുടി കഴുകുകയും ചീകിക്കൊടുക്കുകയും ചെയ്യാറുണ്ട്. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 143, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 372, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: اعْتَكَفَتْ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ امْرَأَةٌ مِنْ أَزْوَاجِهِ، فَكَانَتْ تَرَى الصُّفْرَةَ وَالْحُمْرَةَ، فَرُبَّمَا وَضَعْنَا الطَّسْتَ تَحْتَهَا وَهِيَ تُصَلِّي. (خ,د,جه)', 'ആഇശ(റ): നബി(സ)യുടെ കൂടെ തന്റെ ഭാര്യമാരിലൊരാൾ ഇഅ്തികാഫ് ഇരുന്നു. അവർക്കു രക്തം വരുന്നുണ്ടായിരുന്നു. അവർ നിസ്കരിക്കുമ്പോൾ പലപ്പോഴും ഞങ്ങൾ കോളാമ്പി താഴെവെച്ചുകൊടുക്കുമായിരുന്നു. (ബു,ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 143, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 373, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي الْمُعْتَكِفِ: "هُوَ يَعْكِفُ الذُّنُوبَ، وَيُجْرَى لَهُ مِنَ الْحَسَنَاتِ كَعَامِلِ الْحَسَنَاتِ كُلِّهَا". [ز: في إسناده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഇഅ്തികാഫിരിക്കുന്നവരെക്കുറിച്ച് നബി(സ) പറഞ്ഞു: "ഇഅ്തികാഫിരിക്കുന്നവൻ പാപങ്ങളെ തടഞ്ഞുവെച്ചവനാണ്. നന്മകൾ മുഴുവൻ ചെയ്തവനെപ്പോലെ അവനു പ്രതിഫലം നൽകപ്പെടും." (സനദിൽ ദുർബലനുണ്ട്) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'സനദിൽ ദുർബലനുണ്ട്', 144, 144, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 374, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَامَ لَيْلَتَيِ الْعِيدَيْنِ، مُحْتَسِبًا لِلَّهِ، لَمْ يَمُتْ قَلْبُهُ يَوْمَ تَمُوتُ الْقُلُوبُ". (جه)', 'അബൂഉമാമ(റ): പ്രവാചകർ(സ) പറഞ്ഞു: "അല്ലാഹുവിൽ നിന്നും പ്രതിഫലമാഗ്രഹിച്ച് രണ്ട് പെരുന്നാൾ രാവുകളിലും ആരെങ്കിലും ആരാധനാ കർമ്മങ്ങളനുഷ്ഠിച്ചാൽ ഹൃദയങ്ങൾ മരിക്കുന്ന ദിനം അവരുടെ ഹൃദയം മരിക്കില്ല." (ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 144, 144, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=2 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
